INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_104', 'Unit 104', 'Unit 104 on the first floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"east": "zone_meridian_floor_1"}', '{"is_interior": true}', NULL, 1782898109, 'map_int_meridian', 'zone_meridian_floor_1', -1, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_clone_facility_z-1_1782276270002', 'Coldwater Clone Facility Basement', 'Basement of Coldwater Clone Facility.', 'safe', 0, 0, 0, '[]', '{"up": "zone_start"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null}', '8063162d-964d-4bbb-ad88-eb932f8ec495', 1782278037, 'map_int_1782352518150', NULL, 0, 0, -1, NULL, NULL, '#4bb36a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_marquee', 'The Marquee', 'The Marquee was a theater district before the Collapse and never entirely stopped pretending. A dead cinema marquee juts over the intersection, its plastic letters half-looted so the last feature reads simply NO ONE. Rain-slick asphalt throws back the pink and cyan of a dozen bar signs still drawing power from god-knows-where. Foot traffic here is the closest thing the basin has to a nightlife, and everyone walks like they''re being watched, because they are.', 'safe', 0, 0, 1, '["A bar door swings open somewhere, leaking bass and warm air, then thuds shut.", "The dead marquee buzzes and drops another letter onto the pavement.", "A cluster of people laugh too loudly and move on fast.", "Neon reflection ripples across a puddle as a bike whines past."]', '{"in": "zone_mq_pigeon_bar", "east": "zone_mq_battery", "west": "zone_velk_exterior", "north": "zone_mq_cathode", "south": "zone_mq_ember"}', '{"scavenging_table_id": null}', NULL, 1783123847, 'map_world', NULL, 3, 0, 0, 'MQ', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
