INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_203', 'Unit 203', 'Unit 203 on the second floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"north": "zone_meridian_floor_2"}', '{"is_interior": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_2', 0, 1, 2, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_grocery_util', 'Ration Nine — Utility Room', 'A tight service room behind the walk-in freezer, throbbing with compressor drone. Frost creeps up the pipework, and the junction box sits bolted to the one dry wall, breakers labelled in fading grease-pencil for coolers long since scavenged. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_mq_grocery_stock"}', '{"is_building": false, "is_interior": true}', NULL, 1783023538, 'map_int_mq_grocery', 'zone_mq_grocery_stock', 0, -2, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_floor_4', 'The Meridian — Floor 4 Hallway', 'Floor 4 of The Meridian. A narrow corridor stretches between four unit doors — numbers 401, 402, 403, 404 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_floor_5", "down": "zone_meridian_floor_3", "east": "zone_meridian_unit_402", "west": "zone_meridian_unit_404", "north": "zone_meridian_unit_401", "south": "zone_meridian_unit_403"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783112382, 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 4, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
