INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_amp_util', 'Ampersand Electronics — Utility Room', 'A repair bench buried under cannibalised boards, ribbon cable, and dead handsets harvested for parts. The shop''s junction box has been rewired with suspicious, loving care — bypass jumpers and a bootleg meter spliced across the mains. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_mq_amp_shop"}', '{"is_building": false, "is_interior": true}', NULL, 1783023539, 'map_int_mq_amp', 'zone_mq_amp_shop', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_12', 'Unit 3D', 'Number 3D, last door on the top floor. Half the light fixtures are gone, wires capped and hanging, but a portable lamp does the job. A wide bed under the window, a wardrobe with a mirror gone black at the edges, and a strange, welcome quiet — you''re as far from the bar as the building gets. The kind of room you disappear into.', 'safe', 0, 0, 0, '["The black-edged wardrobe mirror catches a movement that isn''t there."]', '{"east": "zone_embassy_floor3"}', '{"is_building": false, "is_interior": false, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null}', NULL, 1783045464, 'map_interior_zone_residential_lobby', 'zone_embassy_floor3', -1, 0, 2, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_city_east', 'The Loading Bay', 'A vast warehouse complex The Franchise uses as a distribution hub. Forklifts move between shelves stacked to the ceiling. Everything here has a SKU.', 'safe', 0, 0, 1, '["An autonomous forklift nearly runs you over. It has a smiley face sticker.", "\"CUSTOMER SATISFACTION IS OUR PRIORITY,\" the speakers insist, less and less convincingly."]', '{"east": "zone_city_north", "west": "zone_warehouse", "north": "zone_powerplantnew", "south": "zone_city_west"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123847, 'map_world', NULL, -1, -1, 0, 'LW', '#111111', '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_velk_shop', 'Velk''s Pre-Owned Furnishings', 'The shop is improbably full — every surface covered, every corner claimed. Chairs stacked on tables, lamps draped with fabric samples, shelves bowing under the weight of picture frames, drawer units, and objects with no obvious purpose but clear previous lives. It smells like oil soap and old wood. Somehow, it all feels livable.', 'safe', 0, 0, 1, '["Something in a pile shifts and settles with a creak.", "A lamp flickers, steadies, then flickers again.", "A drawer slides open an inch on its own. The shop is just settling, probably.", "The scent of lemon oil drifts through the crowded aisles.", "A price tag twirls slowly on a hanging lamp."]', '{"out": "zone_velk_exterior", "down": "zone_velk_basement"}', '{"is_interior": true}', NULL, 1782918446, 'map_int_velk', 'zone_velk_exterior', 0, 0, 0, NULL, NULL, '#e08a4a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_clone_facility_bathroom', 'Coldwater Clone Facility - Bathroom', 'A sterile, brightly lit washroom lined with smooth composite walls and seamless flooring. The air smells faintly of antiseptic and ozone, while quiet ventilation hums overhead. Hairline drainage channels and spotless surfaces give the unsettling impression that every trace of biological material is meant to disappear without a trace.', 'safe', 0, 0, 1, '[]', '{"west": "zone_start"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null}', NULL, 1782354298, 'map_int_1782352518150', NULL, 1, 0, 0, NULL, NULL, '#4bb36a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_badland_sw_outer', 'The Static Wood', 'What used to be a municipal park, gone feral over long neglect. The trees have grown in crooked and close, roots buckling the old footpaths, and a swing-set rusts on its chains where no child has played in a lifetime.', 'low', 1, 0, 1, '["A branch creaks overhead, though there is barely wind to move it.", "A swing chain ticks back and forth, slow and rusty.", "Something small rustles off through the undergrowth and is gone."]', '{"west": "zone_deep_waste", "north": "zone_outskirts"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123847, 'map_world', NULL, -2, 1, 0, 'SW', '#eeeeee', '#53565c', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_503', 'Unit 503', 'Unit 503 on the fifth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"north": "zone_meridian_floor_5"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_5', 0, 1, 5, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_504', 'Unit 504', 'Unit 504 on the fifth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"east": "zone_meridian_floor_5"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898111, 'map_int_meridian', 'zone_meridian_floor_5', -1, 0, 5, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_601', 'Unit 601', 'Unit 601 on the sixth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"south": "zone_meridian_floor_6"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898111, 'map_int_meridian', 'zone_meridian_floor_6', 0, -1, 6, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_floor_2', 'The Meridian — Floor 2 Hallway', 'Floor 2 of The Meridian. A narrow corridor stretches between four unit doors — numbers 201, 202, 203, 204 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_floor_3", "down": "zone_meridian_floor_1", "east": "zone_meridian_unit_202", "west": "zone_meridian_unit_204", "north": "zone_meridian_unit_201", "south": "zone_meridian_unit_203"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783112116, 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 2, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_101', 'Unit 101', 'Unit 101 on the first floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"south": "zone_meridian_floor_1"}', '{"is_interior": true}', NULL, 1782898109, 'map_int_meridian', 'zone_meridian_floor_1', 0, -1, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_badland_w_gate', 'The Rust Quarter West', 'The processing yards peter out here into a maze of collapsed sheds and rusted-shut gantries. Everything worth stripping was stripped generations ago; what remains is too big or too broken to carry. The quiet has the particular weight of a place people simply stopped coming to.', 'low', 1, 0, 0, '["The ruins groan somewhere behind you. Structural settling, probably.", "A long-dead cable sways and taps against a gantry.", "Grit hisses across the cracked concrete and pools in the old wheel-ruts."]', '{"east": "zone_outskirts", "west": "zone_ruins", "north": "zone_civ_sortation", "south": "zone_deep_waste"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, -3, 0, 0, 'QW', '#eeeeee', '#53565c', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_weighbridge', 'The Weighbridge', 'A truck weighbridge where every load in and out of the Yards is tallied by a scale that hasn''t been calibrated since the Handoff and a clerk who rounds in the company''s favour.', 'low', 0, 0, 1, '["The weighbridge groans as a laden hauler creeps onto the plate.", "The clerk squints at the dial, writes down a different number, and waves the truck on."]', '{"west": "zone_yard_dray", "north": "zone_yard_reefer", "south": "zone_yard_forklift"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 8, 0, 0, 'WB', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_city_north', 'Threshold Plaza North', 'A cracked concrete plaza ringed by dead streetlights still standing at attention. This is the northern gate into Coldwater proper — the LED departure boards here flicker through routes that no longer run anywhere.', 'safe', 0, 0, 1, '["A drone hums overhead, chassis stenciled with a faded corporate logo.", "The departure board flickers: COLDWATER → DENVER → [SIGNAL LOST]."]', '{"east": "zone_city_ne", "west": "zone_city_east", "north": "zone_ext_1782953094650", "south": "zone_threshold"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', NULL, 1783123848, 'map_world', NULL, 0, -1, 0, 'TN', '#111111', '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_pigeon_bar', 'The Dead Pigeon', 'A long, low bar named for the taxidermied pigeon nailed over the register, wings spread in permanent, moth-eaten glory. The counter is a slab of reclaimed door on oil drums; the stools don''t match and neither do the glasses. String lights and the blue flicker of a muted screen do all the lighting the place can afford. It smells of spilled synth-beer, cigarettes, and the particular warmth of a room where nobody is going to ask what you did today.', 'safe', 0, 0, 1, '["The taxidermied pigeon sheds a single feather onto the register.", "Someone racks up a game in the corner; balls scatter with a crack.", "The muted screen cuts to a test pattern and nobody notices.", "A stool scrapes as a regular finds the exact spot they always sit."]', '{"out": "zone_mq_marquee", "down": "zone_mq_pigeon_back"}', '{"is_building": true, "is_interior": true, "building_name": "The Dead Pigeon", "building_type": "bar", "world_exit_zone": "zone_mq_marquee"}', NULL, 1782964407, 'map_int_mq_pigeon', 'zone_mq_marquee', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_602', 'Unit 602', 'Unit 602 on the sixth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"west": "zone_meridian_floor_6"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898111, 'map_int_meridian', 'zone_meridian_floor_6', 1, 0, 6, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_velk_basement', 'Velk''s — Utility Room', 'A low-ceilinged basement room that smells of damp concrete and old cabling. A junction box occupies most of one wall, its panel door held shut with a twist of wire. Exposed conduit runs along the ceiling toward the shop above. A single bulb dangles from a cord, doing its best.', 'safe', 0, 0, 1, '[]', '{"up": "zone_velk_shop", "down": "zone_util_zone_velk_basement"}', '{"is_interior": true}', NULL, 1782918447, 'map_int_velk', 'zone_velk_exterior', 0, 0, -1, NULL, NULL, '#e08a4a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_drum_basement', 'Second Skin — Utility Room', 'A cramped basement room packed with bolts of fabric stored upright along one wall — Cassius''s off-season overflow. The junction box on the opposite wall has been labelled in marker: LIGHTS, SIGN, MISC. A tangle of extension cords snakes toward a power strip that is doing entirely too much work.', 'safe', 0, 0, 1, '[]', '{"up": "zone_drum_shop", "down": "zone_util_zone_drum_basement"}', '{"is_interior": true}', NULL, 1783059649, 'map_int_drum', 'zone_drum_exterior', 0, 0, -1, NULL, NULL, '#e08a4a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_start', 'Coldwater Clone Facility', 'Aseptic white tile floor that has long since gone grey at the grout lines. Vat chambers run along both walls — human-sized cylinders of cloudy fluid, most occupied, all humming at a frequency just below the threshold of comfort. Overhead fluorescents pulse with slow, clinical regularity. Somewhere in the walls, a machine breathes. This is where you come from. Every time.', 'safe', 0, 0, 1, '["A vat releases a slow bubble. Something shifts inside.", "The reconstitution system cycles — a low harmonic you feel more than hear.", "A printer somewhere spits out a receipt. Nobody comes to collect it."]', '{"out": "zone_city_west", "down": "zone_clone_facility_z-1_1782276270002", "east": "zone_clone_facility_bathroom"}', '{"is_building": true, "is_interior": true, "is_apartment": false, "building_name": "Coldwater Clone Facility", "building_type": null, "world_exit_zone": "zone_city_west", "scavenging_table_id": "scav_roadside_junk"}', NULL, 1782495256, 'map_int_1782352518150', NULL, 0, 0, 0, NULL, NULL, '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_304', 'Unit 304', 'Unit 304 on the third floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"east": "zone_meridian_floor_3"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_3', -1, 0, 3, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_util', 'Chrome Court — Basement Utility', 'The tower''s guts: a low concrete basement of riser conduits, a dead boiler, and a floor drain choked with grit. The main junction box dominates one wall, a slab of breakers and humming busbars feeding every unit above. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"up": "zone_mq_chrome_lobby"}', '{"is_building": false, "is_interior": true}', NULL, 1783023542, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cage', 'Tin Lane', 'A dogleg of a service lane roofed in corrugated tin that drums like gunfire whenever it rains, which is always. Every ground-floor window wears its own cage of rebar and welded mesh; commerce here is conducted through slots. The Cage anchors the lane — steel screen floor to ceiling, a clerk somewhere behind it, a shotgun somewhere behind the clerk. A hand-lettered sign promises OPEN and, unusually, means it.', 'low', 0, 0, 1, '[]', '{"in": "zone_mq_cage_shop", "east": "zone_yard_chassis", "west": "zone_mq_overpass", "north": "zone_mq_precinct", "south": "zone_meat_slaughter"}', '{"is_building": true, "is_interior": false, "is_apartment": false, "building_name": "The Cage", "building_type": "shop", "world_exit_zone": "zone_mq_overpass", "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 5, 1, 0, 'CG', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_chassis', 'Chassis Row', 'A row of stripped truck chassis up on blocks, cannibalised for parts one bolt at a time. Grease-black mechanics work under them, visible only as boots and the occasional curse.', 'low', 0, 0, 1, '["A wrench clatters under a chassis, followed by a considered obscenity.", "A mechanic rolls out from under a truck, looks at you, and rolls back."]', '{"east": "zone_yard_transfer", "west": "zone_mq_cage", "north": "zone_yard_loadout", "south": "zone_yard_bonded"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 6, 1, 0, 'Ch', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_precinct', 'Muster Yard', 'A hard-standing of cracked concrete and painted lines nobody parks between anymore. Floodlights — real, working ones — wash the whole yard in interrogation white, so there is nowhere to stand that isn''t seen. Precinct 9 fronts the yard behind a caged sally-port, its charter placard swapped so many times the old bolt holes have merged into one long scar. A departmental drone idles on its pad, optics tracking anything that moves too fast.', 'safe', 0, 0, 1, '[]', '{"in": "zone_mq_precinct_lobby", "east": "zone_yard_loadout", "west": "zone_mq_battery", "north": "zone_yard_depot", "south": "zone_mq_cage"}', '{"is_building": true, "is_interior": false, "is_apartment": false, "building_name": "Precinct 9", "building_type": "police", "world_exit_zone": "zone_mq_battery", "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 5, 0, 0, 'P9', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cherry_office', 'The Cherry Pit — Back Office', 'The office where the Cherry''s money is counted and its problems are solved. A metal desk, a safe bolted through the floor, and a wall of monitors cycling grainy feeds of every corner of the club. A cot in the corner says the manager either lives here or has nowhere better to hide. The air is stale with old smoke and the ozone tang of overworked electronics.', 'low', 0, 0, 0, '["A monitor rolls to static, then snaps back to the floor.", "The bolted safe ticks as it cools, or as something inside settles.", "Somewhere a phone rings twice and is silenced mid-tone."]', '{"up": "zone_mq_cherry_floor", "north": "zone_mq_cherry_util"}', '{"is_interior": true}', NULL, 1783020039, 'map_int_mq_cherry', 'zone_mq_cherry_floor', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_pigeon_back', 'The Dead Pigeon — Back Booth', 'A curtained booth down a short flight of steps, where the deals that keep the Dead Pigeon solvent actually happen. One table, four chairs, a lamp with a scarf thrown over it for mood or for darkness, depending on your business. The walls are soft with old soundproofing foam, so whatever is said here stays a rumor at most.', 'low', 0, 0, 0, '["Muffled bass thuds down through the ceiling from the bar above.", "The scarf over the lamp smells faintly of scorching.", "A chair creaks under someone who isn''t there anymore."]', '{"up": "zone_mq_pigeon_bar", "north": "zone_mq_pigeon_util"}', '{"is_interior": true}', NULL, 1782964407, 'map_int_mq_pigeon', 'zone_mq_pigeon_bar', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cherry_vip', 'The Cherry Pit — VIP', 'A curtained-off nook the club calls VIP with a straight face. A curved couch, a low table ringed with the ghosts of glasses, and a rope that only pretends to be velvet. The privacy is real enough if you''ve paid for it, and the stains suggest a great many people have. A camera dome in the corner watches the room, which rather defeats the point.', 'low', 0, 0, 0, '["The camera dome tracks you with a soft, deliberate whir.", "The privacy curtain sways though there''s no draft.", "Muffled club noise presses against the little room like water."]', '{"south": "zone_mq_cherry_floor"}', '{"mis_ok": true, "is_interior": true}', NULL, 1783020038, 'map_int_mq_cherry', 'zone_mq_cherry_floor', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_city_west', 'Franchise Strip', 'Pre-Handoff retail storefronts, repurposed and argued over for years. Big box skeletons and drive-through lanes now used as livestock pens, retrofitted for survival.', 'safe', 0, 0, 1, '["A vendor shouts: \"AUTHENTIC PRE-HANDOFF CANNED GOODS. ONLY SLIGHTLY EXPIRED.\"", "Two people argue about whether the Architect controls the weather."]', '{"in": ["zone_start", "zone_residential_lobby"], "east": "zone_threshold", "west": "zone_outskirts", "north": "zone_city_east"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_consumer_trash"}', NULL, 1783123848, 'map_world', NULL, -1, 0, 0, 'FS', '#111111', '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_302', 'Unit 302', 'Unit 302 on the third floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"west": "zone_meridian_floor_3"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_3', 1, 0, 3, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_container', 'Container Row', 'Stacked containers march away in canyons four high, their doors chalked with destinations and their contents a matter of faith. The wind between the stacks never stops.', 'low', 0, 0, 1, '["A container door bangs somewhere in the canyon and echoes and echoes.", "Wind funnels between the stacks with a moan you feel in your sternum."]', '{"east": "zone_yard_freightworks", "west": "zone_corp_boardroom", "north": "zone_waste_oxide", "south": "zone_yard_sidings"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 6, -3, 0, 'Cn', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_furniture_store', 'Dead Space Interiors', 'A decommissioned industrial unit repurposed as a furniture showroom. Exposed concrete, neon tube lighting that flickers on a deliberate schedule. The pieces are arranged in vignettes separated by strips of blue painter''s tape on the floor. Price tags are handwritten on recycled cardboard. The air smells of outgassing polymer and burnt coffee from a percolator no one will admit to owning.', 'safe', 0, 0, 0, '[]', '{"out": "zone_thresholdeast", "north": "zone_furniture_util"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1782933540, 'map_int_furniture', 'zone_thresholdeast', 0, 0, 0, NULL, NULL, '#e08a4a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_corp_investor', 'Investor''s Walk', 'A colonnade where freight futures are traded on the strength of ships that may or may not exist. Fortunes are made and unmade here on cargo that is still, technically, at sea.', 'safe', 0, 0, 1, '["Someone on the Walk sells a shipment they''ve never seen to someone who never will.", "A futures board flickers, and three people on the Walk quietly stop smiling."]', '{"east": "zone_yard_sidings", "west": "zone_up_chrome", "north": "zone_corp_boardroom", "south": "zone_yard_depot"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase8-build', 1783123886, 'map_world', NULL, 5, -2, 0, 'Iv', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_outskirts', 'The Rust Quarter', 'The industrial edge of the basin, decades past its last shift. Enormous processing facilities stand half-collapsed, their sheet-metal walls streaked orange with rust and peeling off the frames. Weeds have prised up the loading aprons; nothing here has drawn power in a very long time.', 'low', 1, 0, 1, '["Loose sheet metal bangs somewhere in the wind, slow and hollow.", "You find a paycheck stub from a company that no longer exists.", "A pigeon clatters up out of a dead ventilation stack."]', '{"east": "zone_city_west", "west": "zone_badland_w_gate", "south": "zone_badland_sw_outer"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, -2, 0, 0, 'RQ', '#eeeeee', '#53565c', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_sump_cellar', 'Sump — Cellar', 'A brick cellar that predates everything above it, stacked with kegs, crates, and the accumulated evidence of a bar that never throws anything away. A bare bulb on a cord. Damp that has soaked so deep into the mortar the walls sweat. The drain from upstairs terminates somewhere down here, and you''d rather not learn exactly where.', 'low', 0, 0, 0, '["The bare bulb sways on its cord, though nothing touched it.", "A keg settles in the stack with a hollow, ringing knock.", "Water drips somewhere in the dark with metronomic patience."]', '{"up": "zone_mq_sump_bar", "north": "zone_mq_sump_util"}', '{"is_interior": true}', NULL, 1782964407, 'map_int_mq_sump', 'zone_mq_sump_bar', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_city_se', 'The Clinic Block', 'One of the only reliably staffed medical points in the basin. People are polite here. Nobody wants to be the reason it closes.', 'safe', 0, 0, 1, '["A line forms outside, orderly, almost eerily so.", "Someone hums a tune that might be older than the Handoff."]', '{"east": "zone_drum_exterior", "west": "zone_city_south", "north": "zone_thresholdeast"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', NULL, 1783123848, 'map_world', NULL, 1, 1, 0, 'CB', '#111111', '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_city_sw', 'The Under Entrance', 'A guarded stairwell down into the old subway tunnels. The Archivists'' real vault is below, but this entrance is calm, watched, safe.', 'safe', 0, 0, 1, '["A train horn sounds in the distance. There are no trains.", "Cold air rises from the stairwell, smelling of paper and rust."]', '{"east": "zone_city_south"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, -1, 1, 0, 'UE', '#111111', '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_forklift', 'Forklift Flat', 'A concrete apron where the yard''s forklifts are parked, charged, and fought over each shift. Tyre-black scuffs map a hundred near-misses across the slab.', 'low', 0, 0, 1, '["A forklift alarm beeps its slow reverse into the flat and cuts out.", "Two drivers argue over a charging cable with real, tired heat."]', '{"west": "zone_yard_transfer", "north": "zone_yard_weighbridge", "south": "zone_yard_railhead"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 8, 1, 0, 'FK', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_tunnels', 'The Under', 'Pre-Handoff subway tunnels, now home to the Archivists. Emergency lighting casts everything amber. The walls are dense with salvaged text — newspaper fragments, printed articles, handwritten notes.', 'medium', 0, 0, 1, '["Someone is typing, fast, somewhere in the dark.", "A train horn sounds in the distance. There are no trains.", "Scratched into the wall, half-legible: \"when the static’s bad, ask the shadows.\""]', '{"up": "zone_slums"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1781980620, 'map_world', NULL, 0, 2, -1, NULL, NULL, '#cf6a2e', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_grocery', 'Ration Nine', 'A grocery in the loosest post-Collapse sense: three aisles of dented cans, vac-packed protein bricks, and produce grown under lamps somewhere and trucked in still faintly warm. RATION NINE, the sign says, though there is no Ration One through Eight that anyone can name. Fluorescent tubes hum over shelves stocked with the grim staples of survival and, incongruously, a rack of gum by the register. A camera and a clerk track your hands with equal suspicion.', 'safe', 0, 0, 1, '["A fluorescent tube stutters over aisle two and gives up.", "The cooler compressor kicks on with a shudder that rattles the cans.", "A can rolls off a shelf somewhere and wobbles to a stop.", "The register beeps, unprompted, and the clerk swears at it."]', '{"out": "zone_mq_battery", "north": "zone_mq_grocery_stock"}', '{"is_building": true, "is_interior": true, "building_name": "Ration Nine", "building_type": "grocery", "world_exit_zone": "zone_mq_battery"}', NULL, 1782964407, 'map_int_mq_grocery', 'zone_mq_battery', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_403', 'Unit 403', 'Unit 403 on the fourth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"north": "zone_meridian_floor_4"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_4', 0, 1, 4, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_weapons_exterior', 'Rebar Cut', 'A shipping container grafted onto the alley wall, its roll-door cut down to a service hatch and barred with rebar. A stencilled sign — a rifle crossed with a wrench — hangs over the entrance. Somebody has scratched PRICES ARE FIRM into the paint, then, beneath it, SO AM I.', 'low', 0, 0, 1, '[]', '{"east": "zone_meat_ashpit", "west": "zone_deep_gutter", "north": "zone_mq_ember"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": "zone_deep_waste", "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 3, 2, 0, 'QS', '#111111', '#e08a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_warrens', 'The Warrens', 'Where the Sprawl''s foundations rot into a warren of lean-tos and tarp-roofed stalls. Everything here is for sale, and most of it is stolen off someone still warm.', 'medium', 1, 0, 1, '["A hawker rattles a tin of unlabelled pills at you and melts back into the tarps.", "Two figures argue over a mattress in a doorway, then over a knife."]', '{"east": "zone_deep_cardboard", "west": "zone_deep_tarpit", "south": "zone_deep_rotrow"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123848, 'map_world', NULL, -2, 2, 0, 'WR', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_city_south', 'The Sprawl Gate', 'Where the dense vertical Sprawl tapers into the rest of the city. Laundry lines and extension cords crisscross overhead like a second sky.', 'safe', 0, 0, 1, '["Something crashes several floors above. Then laughter.", "A wall screen loops a corporate conflict-resolution training video, forever."]', '{"east": "zone_city_se", "west": "zone_city_sw", "north": "zone_threshold", "south": "zone_slums"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, 0, 1, 0, 'SG', '#111111', '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_warehouse', 'The Loading Bay West', 'A vast warehouse complex that The Franchise faction uses as a distribution hub. Everything here has a SKU. Everything here is for sale.', 'low', 0, 0, 1, '["\"CUSTOMER SATISFACTION IS OUR PRIORITY\" plays from overhead speakers. The voice sounds increasingly uncertain."]', '{"east": "zone_city_east", "west": "zone_civ_sortation", "north": "zone_up_aid"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, -2, -1, 0, 'LW', '#eeeeee', '#347b49', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_bonded', 'The Bonded Store', 'A caged bonded warehouse for goods that are in the country but not yet, legally, anywhere. The padlocks are new; the paperwork authorising them is not.', 'low', 0, 0, 1, '["A guard rattles the bonded cage, confirms the locks, and moves on.", "Something inside the bonded store is ticking. Nobody has volunteered to check."]', '{"east": "zone_yard_tare", "west": "zone_meat_slaughter", "north": "zone_yard_chassis", "south": "zone_yard_skid"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 6, 2, 0, 'BD', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_tare', 'Tare Row', 'Where empty containers are weighed and stacked, their tare marked in chalk on the steel. The stacks climb four high and lean in ways that keep the insurers awake.', 'low', 0, 0, 1, '["A container stack settles with a boom that you feel in your teeth.", "Chalk figures on a container smear in the damp, no longer adding up."]', '{"east": "zone_yard_railhead", "west": "zone_yard_bonded", "north": "zone_yard_transfer", "south": "zone_yard_interchange"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 7, 2, 0, 'Ta', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_precinct_lobby', 'Precinct 9 — Lobby', 'A bulletproof-glass lobby that manages to feel both fortified and abandoned. A duty officer sits behind the glass beneath a corporate charter seal and a laminated list of fees for services that used to be free. Bolted plastic chairs face a wall-screen scrolling WANTED faces and civic reminders. The floor is the specific institutional grey of a place designed to wear you down before you ever reach a desk. It is, however, warm, and no one gets murdered in here, which counts.', 'safe', 0, 0, 1, '["The duty officer''s terminal chimes and is ignored.", "A WANTED face scrolls up the wall-screen, lingers, scrolls on.", "The door buzzer sounds; the mag-lock clunks; no one comes in.", "Somewhere past the glass, a phone rings in the empty bureaucratic dark."]', '{"out": "zone_mq_precinct", "down": "zone_mq_precinct_holding", "north": "zone_mq_precinct_bullpen"}', '{"is_building": true, "is_interior": true, "building_name": "Precinct 9", "building_type": "police", "world_exit_zone": "zone_mq_precinct"}', NULL, 1782964407, 'map_int_mq_precinct', 'zone_mq_precinct', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cage_shop', 'The Cage', 'Inside, the store is exactly as advertised: aisles of hard goods behind floor-to-ceiling steel mesh, and the clerk sealed in a welded cage at the center like the last honest man in a bad neighborhood, which he may be. You point, he retrieves, money goes through the slot. The stock is a magpie''s hoard — batteries, blades, bandages, bad liquor, worse cigarettes — everything a person needs to get through one more week and nothing they''d want to be caught enjoying.', 'safe', 0, 0, 1, '["The clerk racks the shotgun''s action once, for no reason, for every reason.", "A battery display buzzes behind the mesh, testing itself.", "The vending machine out front thunks and dispenses to no one.", "Steel mesh sings faintly as the cooler fan pushes air through it."]', '{"out": "zone_mq_cage", "north": "zone_mq_cage_util"}', '{"is_building": true, "is_interior": true, "building_name": "The Cage", "building_type": "shop", "world_exit_zone": "zone_mq_cage"}', NULL, 1782964407, 'map_int_mq_cage', 'zone_mq_cage', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_precinct_holding', 'Precinct 9 — Holding', 'Two cages of painted bar-steel in a concrete basement, a drain in the floor, and a bench bolted to each wall for the overnight guests. The paint on the bars is chipped down to raw metal exactly at hand height, all the way around, by every pair of hands that ever gripped them waiting to be processed or forgotten. It smells of disinfectant losing a war against everything else.', 'low', 0, 0, 0, '["A cage door, unlatched, swings a slow inch on its hinge and stops.", "The floor drain exhales a cold, sour breath.", "Bootsteps cross the ceiling overhead and recede.", "The overnight fluorescent buzzes at a pitch engineered to prevent sleep."]', '{"up": "zone_mq_precinct_lobby"}', '{"is_interior": true}', NULL, 1782964408, 'map_int_mq_precinct', 'zone_mq_precinct_lobby', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_amp_shop', 'Ampersand Electronics', 'A stall built into the overpass footing, every inch of it strung with salvaged tech: coils of cable, cracked slates, drones with their guts hanging out, and a wall of chargers for devices no one makes anymore. The proprietor works at a bench under a magnifier lamp, soldering iron never quite set down. Everything is priced by argument. A hand-lettered sign warns NO REFUNDS, NO EXCEPTIONS, NO EXORCISMS, the last apparently learned the hard way.', 'safe', 0, 0, 1, '["The soldering iron hisses as it meets flux; a thread of smoke curls up.", "A salvaged drone on the shelf twitches one rotor and goes still.", "Something on the tech wall emits a single mournful boot-chime.", "A charger indicator blinks green, red, green, deciding nothing."]', '{"out": "zone_mq_overpass", "north": "zone_mq_amp_util"}', '{"is_building": true, "is_interior": true, "building_name": "Ampersand Electronics", "building_type": "shop", "world_exit_zone": "zone_mq_overpass"}', NULL, 1782964407, 'map_int_mq_amp', 'zone_mq_overpass', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_thresholdeast', 'The Threshold East', 'The boulevard continues east as the buildings grow taller and crowd closer together, casting long shadows over the broken pavement. Collapsed skybridges hang between aging towers, their twisted steel frames silhouetted against flickering neon in the distance. Scattered barricades and burned-out vehicles narrow the roadway into a winding path through decades of neglect. Weathered signs advertise businesses that haven''t existed in a generation, while loose cables sway overhead with a faint electrical buzz. Somewhere farther ahead, the city''s heartbeat feels stronger, though whether it promises opportunity or danger is impossible to tell.', 'safe', 0, 0, 1, '[]', '{"in": "zone_furniture_store", "east": "zone_velk_exterior", "west": "zone_threshold", "south": "zone_city_se"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, 1, 0, 0, 'TE', '#111111', '#4bb36a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_401', 'Unit 401', 'Unit 401 on the fourth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"south": "zone_meridian_floor_4"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_4', 0, -1, 4, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_502', 'Unit 502', 'Unit 502 on the fifth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"west": "zone_meridian_floor_5"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_5', 1, 0, 5, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
