INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_coldwater_turbine_hall', 'Coldwater Power Plant — Turbine Hall', 'A cavernous hall of throbbing turbines and grimy conduit. The city plant squats at the centre, roaring, its casing scabbed with warning decals and oil. The whole room shudders with the low churn of megawatts.', 'low', 0, 0, 0, '[]', '{"out": "zone_powerplantnew"}', '{"is_building": true, "is_interior": true, "world_exit_zone": "zone_powerplantnew"}', NULL, 1782940278, 'map_int_coldwater_power', 'zone_powerplantnew', 0, 0, 0, NULL, NULL, '#9a8a4f', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_101', 'Unit 101', 'A single room with a bed frame, a hot plate, and a window that frames a brick wall four feet away. The lock works. That is the entire pitch, and around here it closes the sale.', 'safe', 0, 0, 1, '["Pipes knock somewhere in the walls. The building is old but it holds."]', '{"south": "zone_mq_chrome_f1"}', '{"is_apartment": true}', NULL, 1782964408, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, -1, 1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_unit_301', 'Unit 301', 'Unit 301 on the third floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]', '{"south": "zone_meridian_floor_3"}', '{"is_interior": true, "is_apartment": true}', NULL, 1782898110, 'map_int_meridian', 'zone_meridian_floor_3', 0, -1, 3, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_104', 'Unit 104', 'A corner unit, which here means two windows instead of one and a draft to match. A bed, a footlocker, a sink that runs brown for a ten-count before it clears. The door is steel. The door is the point.', 'safe', 0, 0, 1, '["Pipes knock somewhere in the walls. The building is old but it holds."]', '{"east": "zone_mq_chrome_f1"}', '{"is_apartment": true}', NULL, 1782964408, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', -1, 0, 1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
