INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_roof', 'Chrome Court — Roof', 'The tar-and-gravel roof of Chrome Court, guarded by a knee-high parapet and the honor system. Someone hauled up a couple of ruined armchairs and a firepit made from a washing-machine drum; the ashes are days old but the intent is neighborly. From here the whole Marquee spreads out below in a grid of pink and cyan, the dead cinema marquee winking, the precinct floodlights sweeping. The wind up here has come a long way and has opinions.', 'safe', 0, 0, 1, '["The wind combs across the gravel and lifts a spiral of old ash.", "A pink neon glow pulses up from the street, painting the parapet.", "Something flaps loose on an HVAC unit and slaps, slaps, slaps.", "Far off, the precinct floodlight swings across the rooftops and moves on."]', '{"down": "zone_mq_chrome_f3"}', '{"open_sky": true}', NULL, 1782964410, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, 4, NULL, NULL, '#e85aa0', 'outdoors', '{}', NULL);
