INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_204', 'Unit 204', 'A corner unit, which here means two windows instead of one and a draft to match. A bed, a footlocker, a sink that runs brown for a ten-count before it clears. The door is steel. The door is the point.', 'safe', 0, 0, 1, '["Pipes knock somewhere in the walls. The building is old but it holds."]', '{"east": "zone_mq_chrome_f2"}', '{"is_apartment": true}', NULL, 1782964409, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', -1, 0, 2, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_bulk', 'Bulk Yard', 'An open bulk yard heaped with aggregate, scrap, and materials too cheap to steal but too useful to bin. A grab-crane picks at the heaps with idiot patience.', 'low', 0, 0, 1, '["The grab-crane drops a jawful of scrap and swings back for more.", "A heap of aggregate slides with a long grinding sigh and resettles lower."]', '{"west": "zone_yard_interchange", "north": "zone_yard_railhead"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 8, 3, 0, 'BK', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_skid', 'Skid Row', 'A lane of skids and dunnage where the truly unwanted freight ends up — water-damaged, mislabelled, or simply forgotten until it becomes salvage by default.', 'low', 0, 0, 1, '["A skid of ruined cargo sags in the wet and gives up another inch.", "A picker works down Skid Row, tapping crates, listening for anything worth the crowbar."]', '{"east": "zone_yard_interchange", "west": "zone_meat_carrion", "north": "zone_yard_bonded"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 6, 3, 0, 'Sk', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_interchange', 'The Interchange', 'The road-and-rail interchange at the Yards'' back gate, a snarl of level crossings and truck lanes where everything meets and nothing has right of way.', 'low', 0, 0, 1, '["A crossing bell rings for a train that takes four full minutes to not arrive.", "A truck and a flatcar reach the interchange at once and simply... negotiate."]', '{"east": "zone_yard_bulk", "west": "zone_yard_skid", "north": "zone_yard_tare"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 7, 3, 0, 'IX', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_residential_lobby', 'Embassy Hotel & Bar — Lobby', 'A converted hotel lobby, marble floors gone dull under a permanent film of dust, repurposed into the basin''s closest thing to real estate. A corkboard by the door — bolted over what used to be the concierge desk — is covered in handwritten unit listings, half of them crossed out. Along one wall, a bar still operates under a brass sign reading THE EMBASSY LOUNGE — a half-dozen cracked vinyl stools lined up at the counter, free to sit if you don''t mind the wobble. Lowry stands behind it, polishing a glass that was already clean. The building still has working locks upstairs, which around here makes it valuable.', 'safe', 0, 0, 1, '["Someone argues with the building''s old intercom system, which only ever says \"PLEASE HOLD.\"", "A hand-written sign reads: UNITS AVAILABLE. ASK ABOUT OUR LOCKS."]', '{"up": "zone_embassy_floor2", "out": "zone_city_west", "down": "zone_residential_lobby_z-1_1782105292491", "east": "zone_apt_3", "west": "zone_apt_4", "north": "zone_apt_1", "south": "zone_apt_2"}', '{"is_building": true, "is_interior": true, "is_apartment": false, "building_name": "Embassy Hotel & Bar", "building_type": "hotel", "world_exit_zone": "zone_city_west"}', NULL, 1782356877, 'map_interior_zone_residential_lobby', NULL, 0, 0, 0, 'FS', NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meat_ashpit', 'Ashpit', 'A soot-black yard behind the market where the day''s unsold and unsellable meat goes to the fire. The smoke is greasy and the smell gets into everything you own.', 'medium', 1, 0, 1, '["The ashpit fire flares as something wet goes in, and the smoke thickens.", "A stray dog is driven off from the ashpit''s edge, and comes straight back."]', '{"east": "zone_meat_slaughter", "west": "zone_weapons_exterior", "north": "zone_mq_overpass", "south": "zone_meat_offal"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 4, 2, 0, 'Ap', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_open', 'The Open Bay', 'The end of the last jetty, where the pilings give out and the grey water of Coldwater Bay just goes on. Something big moves out there, unhurried, patient.', 'low', 0, 0, 1, '["Far out on the bay, a wake rises, crosses, and sinks without a source.", "The jetty ends here in splintered wood and open, indifferent water."]', '{"east": "zone_bay_fog", "west": "zone_bay_sound", "north": "zone_bay_mid", "south": "zone_bay_shallows"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123848, 'map_world', NULL, 2, -5, 0, 'OB', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_ember', 'Ember Alley', 'Where the Marquee''s neon can''t quite reach, the district goes to seed. Ember Alley is a slot of a street lit orange by a single working sodium lamp and the coal-glow of cigarettes in doorways. A dive bar exhales stale beer and old grease into the cold. The walls wear decades of paste-over posters, and somewhere behind them, the brick. People here mind their own business with a dedication that is itself a kind of threat.', 'low', 0, 0, 1, '["Glass breaks in the alley behind you, followed by a tired curse.", "The sodium lamp gutters, drowning the street in ember-red, then steadies.", "Someone is being sick, thoroughly, out of sight.", "A cat the size of a raccoon regards you from a dumpster lid and does not blink."]', '{"in": "zone_mq_sump_bar", "east": "zone_mq_overpass", "west": "zone_drum_exterior", "north": "zone_mq_marquee", "south": "zone_weapons_exterior"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 3, 1, 0, 'EM', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_sump_bar', 'Sump', 'The kind of bar that doesn''t need a name over the door because if you''re here, you already knew where you were going. SUMP is scratched into the paint anyway. It is one narrow room, a plank bar, and a floor that slopes toward a literal drain in the center — hence the name, and hence the smell. The regulars are fixtures, welded to their stools by decades of gravity and grievance. Drinks are cheap, strong, and served without conversation.', 'safe', 0, 0, 1, '["Something unspeakable gurgles down the floor drain and is not discussed.", "A regular knocks the bar twice; the bartender pours without looking.", "The single TV shows horse racing from a track that no longer exists.", "A fly, impossibly, in this cold, orbits the room in slow figure-eights."]', '{"out": "zone_mq_ember", "down": "zone_mq_sump_cellar"}', '{"is_building": true, "is_interior": true, "building_name": "Sump", "building_type": "bar", "world_exit_zone": "zone_mq_ember"}', NULL, 1782964407, 'map_int_mq_sump', 'zone_mq_ember', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_ext_1782953094650', 'Limelight Lot', 'A fenced service yard behind the broadcast blocks, floodlit at all hours by lights nobody remembers installing. Coax and power run overhead in fat looms, stapled to anything that will hold them, humming faintly in the wet. KSAB-TV''s stage door sits under a dead awning, its ON AIR bulb burned out mid-word so it reads only ON. A satellite dish the size of a paddling pool tilts drunkenly on the roofline, still tracking a bird that stopped answering years ago.', 'safe', 0, 0, 1, '[]', '{"in": "zone_studio_1782953094650", "west": "zone_powerplantnew", "north": "zone_media_plaza", "south": "zone_city_north"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 0, -2, 0, 'KS', '#111111', '#f5e642', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_fog', 'The Fog Bank', 'A permanent bank of cold fog sits over this stretch of the bay, thick enough to lose a boat in. Sound comes strangely here — near things far, far things near.', 'low', 0, 0, 1, '["A foghorn sounds, impossibly close, from a boat you cannot see.", "The fog closes behind you as you move, sealing the way back to a rumour."]', '{"east": "zone_bay_breakwater", "west": "zone_bay_open", "north": "zone_bay_deep", "south": "zone_bay_barges"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123848, 'map_world', NULL, 3, -5, 0, 'FB', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_furniture_util', 'Dead Space Interiors — Utility Room', 'The showroom''s backroom: plastic-shrouded sofas stacked to the ceiling, a graveyard of flat-pack and packing foam. Wedged between two wardrobes, the building''s junction box hums, warm to the touch, its cabinet door held shut with a bungee cord. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_furniture_store"}', '{"is_building": false, "is_interior": true}', NULL, 1783023537, 'map_int_furniture', 'zone_furniture_store', 0, -1, 0, NULL, NULL, '#e08a4a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_grocery_stock', 'Ration Nine — Stockroom', 'A cramped stockroom walled with wire shelving and stacked pallets, the cold-store humming behind a heavy insulated door. Inventory sheets curl on a clipboard nobody has updated in weeks. It smells of cardboard, cold, and the sweetish edge of something in the back that turned before it sold. A fire exit is chained shut in flagrant violation of several dead safety codes.', 'low', 0, 0, 0, '["The cold-store door seals shut with a sucking thud.", "A pallet of cans ticks and shifts under its own weight.", "The chained fire exit rattles as wind finds the gap beneath it."]', '{"north": "zone_mq_grocery_util", "south": "zone_mq_grocery"}', '{"is_interior": true}', NULL, 1782964407, 'map_int_mq_grocery', 'zone_mq_grocery', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_precinct_util', 'Precinct 9 — Electrical Room', 'A municipal-grey utility room off the bullpen, breaker panel plastered with faded safety notices and one evidence tag nobody ever filed. This box backs the holding cells and the front desk both — a fact stencilled in stern red beside a hacking port sealed below the latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_mq_precinct_bullpen"}', '{"is_building": false, "is_interior": true}', NULL, 1783023541, 'map_int_mq_precinct', 'zone_mq_precinct_bullpen', 0, -2, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_sump_util', 'Sump — Utility Nook', 'A dank corner of the cellar where the floor never dries. A sump pump gurgles somewhere below, and a rust-streaked junction cabinet drips condensation down its breaker faces, sparks of corrosion blooming at every bolt. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_mq_sump_cellar"}', '{"is_building": false, "is_interior": true}', NULL, 1783023536, 'map_int_mq_sump', 'zone_mq_sump_cellar', 0, -1, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cage_util', 'The Cage — Utility Room', 'A steel-walled back room stinking of gun oil and solvent. The junction box hangs behind a padlocked expanded-metal grille, as caged as everything else in this shop, its breakers throwing a faint amber glow across racked ammo tins. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_mq_cage_shop"}', '{"is_building": false, "is_interior": true}', NULL, 1783023540, 'map_int_mq_cage', 'zone_mq_cage_shop', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_pigeon_util', 'The Dead Pigeon — Utility Closet', 'A cramped closet off the back booth, walls furred with condensation and old beer-line runs. A grey junction cabinet hums between a stack of empty kegs and a mop bucket, breathing warm ozone into the smell of stale hops. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_mq_pigeon_back"}', '{"is_building": false, "is_interior": true}', NULL, 1783023534, 'map_int_mq_pigeon', 'zone_mq_pigeon_back', 0, -1, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cherry_util', 'The Cherry Pit — Utility Room', 'Past a beaded curtain behind the office, a windowless room of dead neon tubes, a cracked mirror-ball, and coils of stage cable. The building''s junction box hums against the far wall, its indicator lights winking through the sticky dark like the club never really closes. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]', '{"south": "zone_mq_cherry_office"}', '{"is_building": false, "is_interior": true}', NULL, 1783023535, 'map_int_mq_cherry', 'zone_mq_cherry_office', 0, -1, -1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cherry_floor', 'The Cherry Pit', 'A strip club that leans hard on the one gimmick it can afford: a single working spotlight and a stage of scuffed acrylic lit cherry-red from beneath. Vinyl banquettes ring the room in various states of split and repair. The music is a heartbeat of bass you feel in your fillings. Dancers work the pole with the flat professionalism of people counting the minutes, and the bar sells watered drinks at armed-robbery prices. Everyone is watching everyone, and pretending not to.', 'safe', 0, 0, 1, '["The bass drops and the spotlight swings to catch the stage.", "A bouncer folds his arms in the doorway and studies you without warmth.", "Someone tucks a bill into a garter without making eye contact.", "The cherry underlight flickers, tinting the whole room arterial red."]', '{"out": "zone_mq_cathode", "down": "zone_mq_cherry_office", "north": "zone_mq_cherry_vip"}', '{"is_building": true, "is_interior": true, "building_name": "The Cherry Pit", "building_type": "club", "world_exit_zone": "zone_mq_cathode"}', NULL, 1783019924, 'map_int_mq_cherry', 'zone_mq_cathode', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_floor_6', 'The Meridian — Floor 6 Hallway', 'Floor 6 of The Meridian. A narrow corridor stretches between four unit doors — numbers 601, 602, 603, 604 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_roof", "down": "zone_meridian_floor_5", "east": "zone_meridian_unit_602", "west": "zone_meridian_unit_604", "north": "zone_meridian_unit_601", "south": "zone_meridian_unit_603"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783112081, 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 6, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meat_offal', 'Offal Lane', 'Where the parts nobody names are sold to people who don''t ask — a lane of trestle tables under a low awning, the trade brisk and the eye-contact minimal.', 'medium', 1, 0, 1, '["A vendor slaps down a tray of something and looks away before you can.", "Cats mass at the mouth of Offal Lane, waiting for the inevitable."]', '{"east": "zone_meat_carrion", "west": "zone_deep_deepmaw", "north": "zone_meat_ashpit"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 4, 3, 0, 'Of', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_lobby', 'Chrome Court — Lobby', 'The ground-floor lobby of Chrome Court: a bank of tenant mailboxes, most jimmied, and an elevator with a hand-lettered OUT OF ORDER SINCE sign where the date has been scratched out and re-guessed by successive residents. A stairwell climbs into the amber gloom of the upper floors behind a fire door that no longer latches. A resident''s bicycle is chained to the radiator with more security than the front door offers. It is quiet, and locked, and warm, and that is enough.', 'safe', 0, 0, 1, '["The stairwell fire door drifts open an inch and settles.", "A mailbox door hangs open, ticking against its frame in the draft.", "Somewhere above, a TV murmurs through a floor.", "The dead elevator''s call button glows, hopeful and useless."]', '{"up": "zone_mq_chrome_f1", "out": "zone_mq_chrome_court", "down": "zone_mq_chrome_util"}', '{"is_building": true, "is_interior": true, "building_name": "Chrome Court", "building_type": "apartment", "world_exit_zone": "zone_mq_chrome_court"}', NULL, 1782964408, 'map_int_mq_chrome', 'zone_mq_chrome_court', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_floor_3', 'The Meridian — Floor 3 Hallway', 'Floor 3 of The Meridian. A narrow corridor stretches between four unit doors — numbers 301, 302, 303, 304 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_floor_4", "down": "zone_meridian_floor_2", "east": "zone_meridian_unit_302", "west": "zone_meridian_unit_304", "north": "zone_meridian_unit_301", "south": "zone_meridian_unit_303"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783112361, 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 3, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meat_carrion', 'Carrion Way', 'The far end of the market, where the meat is cheapest and the questions fewest. A dead-end way, which the scavengers and the desperate both find convenient for different reasons.', 'medium', 1, 0, 1, '["Something changes hands fast at the end of Carrion Way, and both parties leave quickly.", "A crow the size of a cat works at a scrap in the gutter, unbothered by you."]', '{"east": "zone_yard_skid", "west": "zone_meat_offal", "north": "zone_meat_slaughter"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 5, 3, 0, 'Cy', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian', 'Halcyon Walk', 'A stretch of cracked pavement the city has forgotten to condemn. Water-stained precast towers lean over it on both sides, their ground floors a monotony of steel-framed glass — most of it dark, a few doors still lit from within. The Meridian''s lobby throws a wedge of sick fluorescent light across the walk here, doorman long gone, intercom panel hanging by its wires. Somewhere overhead a window unit drips onto its sill in a slow, patient rhythm.', 'safe', 0, 0, 1, '[]', '{"in": "zone_meridian_lobby", "east": "zone_mq_cathode", "west": "zone_city_ne", "north": "zone_up_approach", "south": "zone_velk_exterior"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": "zone_city_ne", "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 2, -1, 0, NULL, '#eeeeee', '#347b49', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_8', 'Unit 2D', 'Unit 2D, narrow as a coffin and about as bright. The previous tenant left in a hurry: a chair on its side, a ring of candle stubs on the floor, initials keyed into the doorframe. There''s a real bed, though, and a deadbolt, and the walls are thick enough that the neighbours'' business stays theirs.', 'safe', 0, 0, 0, '["The overturned chair settles with a faint creak."]', '{"east": "zone_embassy_floor2"}', '{"is_building": false, "is_interior": true, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783111686, 'map_interior_zone_residential_lobby', NULL, -1, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_7', 'Unit 2C', 'Number 2C. Someone painted this one, once — a hopeful yellow now gone the colour of a smoker''s teeth, peeling in long tongues off the plaster. A kitchenette with two working burners, a fold-down table, and a bathtub in the main room because the plumbing never reached the back. The window looks onto a brick wall an arm''s length away.', 'safe', 0, 0, 0, '["A tongue of old paint peels a little further from the wall."]', '{"west": "zone_embassy_floor2"}', '{"is_building": false, "is_interior": true, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783111686, 'map_interior_zone_residential_lobby', NULL, 1, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_6', 'Unit 2B', 'Unit 2B, tucked at the back over the alley. It smells of the dumpsters three floors down and whatever the last tenant fried. A single bulb on a string, a closet with its door removed to serve as a shelf, and a radiator that either roars or freezes — never anything between. Cheap, and it shows, but the door bolts from the inside.', 'safe', 0, 0, 0, '["The radiator bangs twice and falls silent."]', '{"north": "zone_embassy_floor2"}', '{"is_building": false, "is_interior": true, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783111686, 'map_interior_zone_residential_lobby', NULL, 0, 1, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_5', 'Unit 2A', 'A corner unit, Number 2A, riding the front of the building. Two windows face the street, one boarded, one still glassed and grimy enough to filter the neon into a permanent bruise-purple. A mattress on a bent steel frame, a hotplate wired straight into the wall, and a water stain on the ceiling shaped uncannily like a hanged man. The lock, at least, is real.', 'safe', 0, 0, 0, '["Neon light through the grimy window pulses, dims, holds."]', '{"south": "zone_embassy_floor2"}', '{"is_building": false, "is_interior": true, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783111686, 'map_interior_zone_residential_lobby', NULL, 0, -1, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_f2', 'Chrome Court — Floor 2', 'The second-floor hallway of Chrome Court, a tunnel of amber emergency light and doors painted so many times the numbers are just suggestions. The carpet is worn to jute down the center where every tenant walks the identical line. Four units open off the hall. A window at the end looks out over the district''s neon, which from up here almost looks like a city that works.', 'safe', 0, 0, 1, '["A door down the hall closes with the finality of a lock turning.", "The amber emergency light hums and dims by a shade.", "Something is cooking behind one of the doors; the smell almost reaches you.", "The end-of-hall window rattles as the wind leans on it."]', '{"up": "zone_mq_chrome_f3", "down": "zone_mq_chrome_f1", "east": "zone_mq_chrome_202", "west": "zone_mq_chrome_204", "north": "zone_mq_chrome_201", "south": "zone_mq_chrome_203"}', '{"is_interior": true}', NULL, 1782964408, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, 2, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_drum_exterior', 'Bobbin Cut', 'A slim pedestrian cut that somehow keeps its dignity in a city this far gone — swept, even, the puddles smaller here than they have any right to be. Storefront glass runs its length, most of it soaped over, one window still dressed and lit. Drum''s Fits shows two mannequins in loud, layered outfits that dare you to walk past without looking, a neon thread-spool buzzing pink above the door. The rest of the frontage waits for tenants who aren''t coming.', 'low', 0, 0, 1, '[]', '{"in": "zone_drum_shop", "east": "zone_mq_ember", "west": "zone_city_se", "north": "zone_velk_exterior"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": "zone_deep_waste", "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 2, 1, 0, 'Cl', '#eeeeee', '#347b49', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_10', 'Unit 3B', 'Number 3B, back corner under the roof. The ceiling slopes where the building''s cornice cuts in, low enough to crack your skull if you sit up wrong in the night. A camp bed, a footlocker, a hole in the plaster patched with a road sign. When it rains, the stain on the landing ceiling isn''t the only one — you''ll hear it here first, tapping the bucket someone thoughtfully left behind.', 'safe', 0, 0, 0, '["A single drip finds the bucket with a flat metallic tap."]', '{"north": "zone_embassy_floor3"}', '{"is_building": false, "is_interior": false, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null}', NULL, 1783045464, 'map_interior_zone_residential_lobby', 'zone_embassy_floor3', 0, 1, 2, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_9', 'Unit 3A', 'Unit 3A, top floor, street-facing. Best light in the building up here — what little the smog lets through comes in clean and level through a window that actually opens. A proper bed, a desk someone bolted to the wall, and a hook in the ceiling that used to hold a fan and now holds nothing, turning slowly in the draft. Quiet. Expensive-feeling, for the Embassy.', 'safe', 0, 0, 0, '["The empty ceiling hook turns a slow half-circle in the draft."]', '{"south": "zone_embassy_floor3"}', '{"is_building": false, "is_interior": false, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null}', NULL, 1783045464, 'map_interior_zone_residential_lobby', 'zone_embassy_floor3', 0, -1, 2, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_apt_11', 'Unit 3C', 'Unit 3C. The realtor — the corkboard downstairs, really — calls this one ''cozy.'' It''s small. A single room with a curtained-off toilet, a sink that runs rust for a minute before it runs clear, and a window painted shut and then painted again. But the lock is new, the floor is solid, and nobody up here asks questions.', 'safe', 0, 0, 0, '["Behind the curtain, the sink drips rust-brown, then stops."]', '{"west": "zone_embassy_floor3"}', '{"is_building": false, "is_interior": false, "is_apartment": true, "building_name": null, "building_type": null, "world_exit_zone": null}', NULL, 1783045464, 'map_interior_zone_residential_lobby', 'zone_embassy_floor3', 1, 0, 2, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_court', 'Foundry Cut', 'A short cut between two boom-era towers, narrow enough that the wind funnels through hard enough to sting. Brushed-metal cladding sheets the walls, half of it peeled back to the rust beneath. Chrome Court''s entrance stands at the far end — steel letters over the doors, three fallen and re-inked on cardboard — beside a solid brick of painted-over intercoms. The gutter runs with something that was recently oil.', 'safe', 0, 0, 1, '[]', '{"in": "zone_mq_chrome_lobby", "east": "zone_yard_depot", "west": "zone_mq_cathode", "north": "zone_up_chrome", "south": "zone_mq_battery"}', '{"is_building": true, "is_interior": false, "is_apartment": false, "building_name": "Chrome Court", "building_type": "apartment", "world_exit_zone": "zone_mq_cathode", "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 4, -1, 0, 'CC', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_overpass', 'The Overpass', 'A stub of collapsed elevated roadway roofs this block in permanent shadow, its underside a cathedral of rebar and pigeon filth. Someone strung work-lights along the girders and called it commerce. An electronics stall glows under the deck; a stairwell drops into a basement lit by a single sign. Water finds its way down through the concrete no matter the weather, ticking into puddles that never dry.', 'low', 0, 0, 1, '["Water ticks down from the overpass and finds the back of your collar.", "Pigeons erupt off a girder in a slapping panic, then resettle.", "A work-light swings on its cord, throwing the shadows into motion.", "Something heavy passes on the road above; the whole deck shivers dust."]', '{"in": "zone_mq_amp_shop", "east": "zone_mq_cage", "west": "zone_mq_ember", "north": "zone_mq_battery", "south": "zone_meat_ashpit"}', '{"scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 4, 1, 0, 'OP', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_catalyst', 'Catalyst Row', 'A row of distillation towers, each one cracked open like a spent shell casing. The catalyst beds inside have gone to a fine iridescent grit that hangs in the air and glitters when it catches the light. It is very pretty, and very bad for you.', 'medium', 1, 0, 0, '["The grit in the air fluoresces faintly, painting everything a sick green for a heartbeat.", "A tower groans as the wind leans on it, shedding a slow curtain of rust."]', '{"east": "zone_waste_sinter", "west": "zone_slag_flarestack", "north": "zone_waste_fumealley", "south": "zone_slag_yard"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_industrial_salvage"}', NULL, 1783123848, 'map_world', NULL, -9, -1, 0, 'CR', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_sump', 'The Effluent Sump', 'Settling ponds step down the slope, their surfaces skinned over in oily rainbows that don''t move even when the wind does. Whatever the works couldn''t burn, it dumped here. The smell gets into your clothes and stays for days.', 'medium', 1, 0, 0, '["A bubble the size of your head rises through the sludge and pops with a flat, wet cough.", "Something breaks the surface of the far pond, then thinks better of it."]', '{"east": "zone_waste_reek", "west": "zone_slag_drums", "north": "zone_slag_yard", "south": "zone_waste_ashencut"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_irradiated_salvage"}', NULL, 1783123848, 'map_world', NULL, -9, 1, 0, 'ES', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_ashway_ashfall', 'Ashfall Mile', 'The road gives up and the flats take over — a grey plain of settled ash that swallows your bootprints and hands them back to the wind. Somewhere upwind a stack is still venting; the sky here is the colour of an old bruise.', 'low', 1, 0, 0, '["Ash sifts down like dirty snow and coats your lips with the taste of burnt plastic.", "The wind drops for a moment, and the silence has a weight to it."]', '{"east": "zone_ashway_road", "west": "zone_ashway_wash", "north": "zone_waste_palings", "south": "zone_waste_deadflat"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, -6, 0, 0, 'AF', '#111111', '#8b9097', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_precinct_bullpen', 'Precinct 9 — Bullpen', 'A room of mismatched desks shoved together, each buried under case files no one will close and coffee cups fossilizing into archaeology. A corkboard maps the district''s gangs in red string that has long since become its own conspiracy. Half the overhead lights are dead and no one has requisitioned bulbs. The officers who work here have the specific exhaustion of people paid to hold a line that moved years ago.', 'safe', 0, 0, 1, '["A desk phone rings four times and kicks to a full voicemail box.", "Red string sags off the corkboard and dangles, tracing nothing.", "A dead overhead light ticks as it tries and fails to warm up.", "Someone''s coffee has grown a skin; it wrinkles as the AC breathes on it."]', '{"north": "zone_mq_precinct_util", "south": "zone_mq_precinct_lobby"}', '{"is_interior": true}', NULL, 1782964407, 'map_int_mq_precinct', 'zone_mq_precinct_lobby', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_ashway_wash', 'The Dry Wash', 'A concrete drainage channel cuts across the flats, its floor crazed and stained the rust-black of old runoff. A collapsed checkpoint booth leans over the lip, its boom gate frozen halfway down like it''s still trying to stop you.', 'low', 1, 0, 0, '["Something skitters along the channel floor and is gone before you can place it.", "Water you can''t see drips steadily from the culvert mouth, each drop echoing."]', '{"east": "zone_ashway_ashfall", "west": "zone_slag_gate", "north": "zone_waste_rustmarsh", "south": "zone_waste_ashenverge"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123848, 'map_world', NULL, -7, 0, 0, 'DW', '#111111', '#8b9097', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_gate', 'Slagworks Gate', 'Chain-link and razor wire sag around a gatehouse with every window punched out. A faded sign still bolts to the fence: COLDWATER RECLAMATION — AUTHORISED PERSONNEL ONLY. Past it, the silhouettes of cracking towers rake at the sky.', 'low', 1, 0, 0, '["The gate chain swings against the post with a slow, patient clang.", "A security floodlight buzzes, dies, and buzzes again, powered by nothing you can find."]', '{"east": "zone_ashway_wash", "west": "zone_slag_yard", "north": "zone_waste_sinter", "south": "zone_waste_reek"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_industrial_salvage"}', NULL, 1783123848, 'map_world', NULL, -8, 0, 0, 'SG', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_f3', 'Chrome Court — Floor 3', 'The third-floor hallway of Chrome Court, a tunnel of amber emergency light and doors painted so many times the numbers are just suggestions. The carpet is worn to jute down the center where every tenant walks the identical line. Four units open off the hall. A window at the end looks out over the district''s neon, which from up here almost looks like a city that works.', 'safe', 0, 0, 1, '["A door down the hall closes with the finality of a lock turning.", "The amber emergency light hums and dims by a shade.", "Something is cooking behind one of the doors; the smell almost reaches you.", "The end-of-hall window rattles as the wind leans on it."]', '{"up": "zone_mq_chrome_roof", "down": "zone_mq_chrome_f2", "east": "zone_mq_chrome_302", "west": "zone_mq_chrome_304", "north": "zone_mq_chrome_301", "south": "zone_mq_chrome_303"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783111944, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, 3, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_flarestack', 'Flarestack Field', 'A field of flare stacks stands dead against the sky, each tipped with a burner that hasn''t lit in a lifetime. The ground between them is glassed in patches where the flares used to rain fire, and the glass is full of things that got caught when it cooled.', 'low', 1, 0, 0, '["The wind moans across the mouth of a dead flare stack like breath over a bottle.", "Underfoot the glassed ground crunches, and something small and fused stares up at you."]', '{"east": "zone_slag_catalyst", "west": "zone_red_dreadfurnace", "north": "zone_waste_cokeyard", "south": "zone_slag_rail"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_industrial_salvage"}', NULL, 1783123848, 'map_world', NULL, -10, -1, 0, 'FF', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_ashway_road', 'The Haul Road', 'Six lanes of freight road run west out of Old Coldwater, expansion joints heaved into knee-high ridges by decades of frost. Dead haulers sit nose-to-tail in the breakdown lane, cabs stripped to the frame, waiting on a shift change that never came.', 'low', 1, 0, 0, '["A tanker''s air-brake lets go somewhere down the line with a hiss, though nothing has moved here in years.", "Grit pings off the guardrail in a gust, then goes still."]', '{"east": "zone_ruins", "west": "zone_ashway_ashfall", "north": "zone_waste_slake", "south": "zone_waste_verge"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123846, 'map_world', NULL, -5, 0, 0, 'HR', '#111111', '#8b9097', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_reclaimer', 'The Reclaimer', 'At the works'' dead centre squats the reclaimer — a rotary furnace the size of a city block, its maw a black tunnel the wind pours into and never seems to come back out of. The richest salvage sits here, in the ash beds nobody sane will reach. The air hums, low, in your teeth.', 'medium', 1, 0, 0, '["The reclaimer''s drum shifts on its bearings with a groan you feel in the fillings of your teeth.", "For just a second the hum stops, and the silence is so total you can hear your own blood."]', '{"east": "zone_slag_rail", "north": "zone_red_dreadfurnace", "south": "zone_waste_coldslag"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_irradiated_salvage"}', NULL, 1783123848, 'map_world', NULL, -11, 0, 0, 'RC', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_corp_argent', 'Argent Row', 'A silver-fronted terrace of freight-finance offices overlooking the Yards, where the people who own the cargo watch it move without once touching it. The view is of money becoming more money.', 'safe', 0, 0, 1, '["A ticker crawls silver figures across a frontage, up, always up.", "A financier watches a container swing across the yard and mentally spends it twice."]', '{"west": "zone_waste_downwind", "north": "zone_nc_chancery", "south": "zone_yard_gantry"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase8-build', 1783123846, 'map_world', NULL, 8, -4, 0, 'Ar', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_ruins', 'Old Coldwater', 'What remains of the actual city. Glass and rebar and the occasional wall of a building that still looks like it meant something once. At the center, the old city hall stands largely untouched — the Architect''s infrastructure runs through its foundation.', 'medium', 1, 0, 0, '["The city hall''s windows glow faint blue. They always do. Nobody goes in.", "A dog watches you from a pile of rubble. It doesn''t seem scared. That''s somehow worse."]', '{"east": "zone_badland_w_gate", "west": "zone_ashway_road", "north": "zone_waste_endcut", "south": "zone_waste_grit"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123846, 'map_world', NULL, -4, 0, 0, 'OC', '#eeeeee', '#53565c', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_sound', 'The Sound', 'A sheltered sound between the wreck and the cold-store pilings, calm enough that the fishing skiffs tie up here. It is the last friendly water before the bay stops pretending.', 'low', 0, 0, 1, '["A moored skiff knocks gently against a piling, over and over.", "A fisher hauls a net over the sound''s edge, sees the catch, and swears."]', '{"east": "zone_bay_open", "west": "zone_nc_spindle", "north": "zone_bay_wreck", "south": "zone_dock_coldstore"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 1, -5, 0, 'SD', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_rail', 'The Rail Throat', 'A rail siding chokes on its own collapse here — tanker cars derailed and stacked, spines snapped, spilling decades-dry chemical crust across the ballast. The rolling stock is a mountain of salvage nobody''s been desperate enough to climb. Yet.', 'low', 1, 0, 0, '["Metal contracts somewhere in the wreck with a bang that rolls off flat across the flats.", "A tanker car settles a half-inch with a groan and a shower of rust."]', '{"east": "zone_slag_yard", "west": "zone_slag_reclaimer", "north": "zone_slag_flarestack", "south": "zone_slag_drums"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_industrial_salvage"}', NULL, 1783123848, 'map_world', NULL, -10, 0, 0, 'RT', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_bonepicker', 'Bonepicker''s End', 'A dead-end court where the scavengers sort their hauls — piles of picked-clean chassis and, now and then, picked-clean people.', 'medium', 1, 0, 1, '["A picker weighs a fistful of teeth on a hanging scale.", "Someone whistles a warning and the whole court goes still."]', '{"east": "zone_deep_gasp", "west": "zone_deep_maw", "north": "zone_deep_scab"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, 1, 3, 0, 'BP', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_gasp', 'Gasp Hollow', 'A sunken hollow where the air goes thin and chemical. Regulars breathe through rags; newcomers cough up their welcome.', 'high', 1, 0, 1, '["Your throat closes for a second on a lungful of something sweet and wrong.", "A regular offers you a rag for a price, already knowing you''ll pay it."]', '{"east": "zone_deep_deepmaw", "west": "zone_deep_bonepicker", "north": "zone_deep_gutter"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, 2, 3, 0, 'GH', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_deepmaw', 'The Deep Maw', 'The bottom of the bottom. Past here the Sprawl stops pretending to be a city and starts being a wound.', 'high', 1, 0, 1, '["Far below, something large shifts its weight and settles.", "The dark down here has a grain to it, like it''s watching back."]', '{"east": "zone_meat_offal", "west": "zone_deep_gasp"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, 3, 3, 0, 'DM', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_up_gate', 'Uptown Gate', 'The clean edge of the city. A corporate checkpoint of brushed steel and polite menace sorts the paying customers from the rest. Cameras track the way you walk.', 'safe', 0, 0, 1, '["A turnstile chimes approval for someone who is not you.", "A recorded voice thanks you for your continued compliance."]', '{"east": "zone_up_approach", "north": "zone_dock_wharf", "south": "zone_city_ne"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase1-build', 1783123846, 'map_world', NULL, 1, -2, 0, 'UG', '#eeeeee', '#347b49', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_gutter', 'Gutter Market', 'Trestle tables of salvaged meat, bruised pills, and dead men''s boots. The vendors don''t make eye contact and neither should you.', 'medium', 1, 0, 1, '["A butcher slaps down a cut you decide not to identify.", "A vendor sweeps a tarp over her table the instant a patrol light sweeps the row."]', '{"east": "zone_weapons_exterior", "west": "zone_deep_scab", "south": "zone_deep_gasp"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, 2, 2, 0, 'GM', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_maw', 'The Maw', 'The Sprawl opens its throat here: a downward-sloping plaza where the Undermarket swallows anyone with nothing left to trade but themselves.', 'medium', 1, 0, 1, '["The crowd parts around something on the ground and closes again without looking.", "A busker plays a gutted keyboard, three keys, over and over."]', '{"east": "zone_deep_bonepicker", "west": "zone_deep_wormtown", "north": "zone_slums"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, 0, 3, 0, 'MW', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_scab', 'Scab Alley', 'A knife-narrow cut between tenements, the floor slick with things best not named. Deals happen fast here, and so does everything else.', 'medium', 1, 0, 1, '["A deal goes wrong two doorways down. Then very quiet.", "Fresh graffiti drips over old graffiti over older blood."]', '{"east": "zone_deep_gutter", "west": "zone_slums", "south": "zone_deep_bonepicker"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, 1, 2, 0, 'SC', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_drum_shop', 'Second Skin', 'The shop is narrow but makes good use of vertical space — racks of clothing climb toward the ceiling, organized by some colour-logic that only Cassius understands. The walls are covered in polaroid-style printouts of outfits, annotated in marker. A tailoring station dominates one corner: cutting mat, shears, a half-dressed mannequin with pins in unfortunate places.', 'safe', 0, 0, 1, '["Fabric rustles softly on a rack as air moves through the shop.", "The spool-shaped sign outside buzzes faintly through the wall.", "A mannequin slowly loses a pin to gravity. It hits the floor without drama.", "The squeak of a hanger being slid along a rail.", "Scissors catch the light from somewhere in the back."]', '{"out": "zone_drum_exterior", "down": "zone_drum_basement"}', '{"is_interior": true}', NULL, 1783059649, 'map_int_drum', 'zone_drum_exterior', 0, 0, 0, NULL, NULL, '#e08a4a', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_rotrow', 'Rot Row', 'The smell arrives before you do — a terrace of failed refrigeration and the produce it couldn''t save. Flies the size of thumbnails work the air.', 'medium', 1, 0, 1, '["A drift of flies lifts, resettles, lifts again.", "Something drips steadily from an awning that has no business being wet."]', '{"east": "zone_deep_wormtown", "west": "zone_deep_sink", "north": "zone_deep_warrens"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, -2, 3, 0, 'RR', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_wormtown', 'Wormtown', 'Tunnelled into a collapsed parkade, Wormtown is all dripping concrete and squatter-cant scrawled on every pillar.', 'medium', 1, 0, 1, '["A squatter recites directions to nowhere in a sing-song cant.", "Water finds a new path through the concrete overhead and chooses your collar."]', '{"east": "zone_deep_maw", "west": "zone_deep_rotrow", "north": "zone_deep_cardboard"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123846, 'map_world', NULL, -1, 3, 0, 'WT', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_up_chrome', 'Chrome Heights', 'Mirror-glass frontages and valet drones. The Heights look down on the Marquee''s neon like it''s a stain they''ve already hired someone to remove.', 'safe', 0, 0, 1, '["A valet drone waits by a car you could never afford to breathe on.", "Your reflection follows you across a dozen panes, each a little more judged."]', '{"east": "zone_corp_investor", "west": "zone_up_skyway", "north": "zone_dock_slip", "south": "zone_mq_chrome_court"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase1-build', 1783123846, 'map_world', NULL, 4, -2, 0, 'CH', '#eeeeee', '#347b49', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_civ_commons', 'The Commons', 'A cracked plaza the city forgot to demolish. A breadline shuffles past a dead fountain, and a hand-painted banner insists that WE ARE ALL SHAREHOLDERS.', 'safe', 0, 0, 1, '["The breadline shuffles forward a step for reasons no one can identify.", "A pigeon lands on the dead fountain''s rim and judges the crowd."]', '{"east": "zone_civ_ledger", "west": "zone_waste_windrow", "north": "zone_waste_emberwaste", "south": "zone_civ_meltwater"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase2-build', 1783123846, 'map_world', NULL, -3, -3, 0, 'CO', '#111111', '#4bb36a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_gravel', 'Gravel Throat', 'A choked culvert of crushed concrete and rebar, funnelling the wind into a low continuous growl. Footing is bad and getting worse.', 'low', 0, 0, 1, '["A slab shifts underfoot and settles with a stony grunt.", "The throat exhales a gust that carries the smell of old rain and rust."]', '{"east": "zone_civ_meltwater", "west": "zone_waste_smoulder", "north": "zone_waste_windrow", "south": "zone_waste_endcut"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123846, 'map_world', NULL, -4, -2, 0, 'GV', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_util_zone_meridian_lobby', 'The Meridian - Lobby — Utility Room', 'A cramped below-grade utility room: bare concrete, sweating pipes, and the building junction box humming in its steel cabinet.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_lobby"}', '{"is_interior": true, "utility_room": true, "world_exit_zone": "zone_meridian"}', NULL, 1783116355, 'map_int_meridian', NULL, 0, 0, -1, NULL, NULL, '#8e6fd0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_up_skyway', 'Skyway Landing', 'Where an elevated skyway touches down among planters of engineered ferns. The air is filtered; you can tell because it tastes like nothing at all.', 'safe', 0, 0, 1, '["A skyway car sighs past overhead, full of faces that don''t look down.", "A planter mists itself on a schedule indifferent to the weather."]', '{"east": "zone_up_chrome", "west": "zone_up_approach", "north": "zone_dock_fishmarket", "south": "zone_mq_cathode"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase1-build', 1783123846, 'map_world', NULL, 3, -2, 0, 'SK', '#eeeeee', '#347b49', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_util_zone_velk_basement', 'Velk''s — Utility Room — Utility Room', 'A cramped below-grade utility room: bare concrete, sweating pipes, and the building junction box humming in its steel cabinet.', 'safe', 0, 0, 0, '[]', '{"up": "zone_velk_basement"}', '{"is_interior": true, "utility_room": true, "world_exit_zone": "zone_velk_exterior"}', NULL, 1783116357, 'map_int_velk', 'zone_velk_exterior', 0, 0, -2, NULL, NULL, '#8e6fd0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_civ_sortation', 'Sortation Yard', 'A dead-letter depot where a sorting belt still crawls, shuffling parcels to addresses that burned down years ago. The bot at the end never stops stamping.', 'low', 0, 0, 1, '["The belt delivers a parcel addressed to a building that is now a crater.", "The sorting bot stamps RETURN TO SENDER on a rat and moves on."]', '{"east": "zone_warehouse", "west": "zone_waste_endcut", "north": "zone_civ_meltwater", "south": "zone_badland_w_gate"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase2-build', 1783123846, 'map_world', NULL, -3, -1, 0, 'SY', '#111111', '#4bb36a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_cardboard', 'Cardboard Row', 'A gutter of flattened appliance boxes and pallet-wood shanties. Cook-fires gutter in oil drums and the greasy smoke never quite clears.', 'medium', 1, 0, 1, '["A child watches you from a refrigerator-box doorway and does not blink.", "Something in an oil drum pops and sends up a gout of blue flame."]', '{"east": "zone_slums", "west": "zone_deep_warrens", "south": "zone_deep_wormtown"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase1-build', 1783123885, 'map_world', NULL, -1, 2, 0, 'CD', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_up_aid', 'Aid Station', 'A pre-Handoff triage kiosk someone keeps running out of pure spite and expired supplies. A medibot with one working arm sorts the walking wounded by who can pay.', 'safe', 0, 0, 1, '["The medibot''s good arm gestures NEXT to no one in particular.", "A vending machine offers bandages, saline, and, inexplicably, cologne."]', '{"east": "zone_powerplantnew", "west": "zone_civ_meltwater", "north": "zone_civ_ledger", "south": "zone_warehouse"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase1-build', 1783123885, 'map_world', NULL, -2, -2, 0, 'AD', '#eeeeee', '#347b49', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_civ_steps', 'Civic Steps', 'A broad municipal stair that once led somewhere that mattered. Now it just connects the records office to the water, and the pigeons have claimed the landings.', 'safe', 0, 0, 1, '["A gull and a pigeon dispute a chip wrapper on the steps.", "Wind off the bay carries the smell of salt and diesel up the stair."]', '{"east": "zone_media_plaza", "west": "zone_civ_ledger", "north": "zone_up_vellum", "south": "zone_powerplantnew"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase3-build', 1783123885, 'map_world', NULL, -1, -3, 0, 'ST', '#111111', '#4bb36a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_grit', 'Grit Row', 'A row of half-buried machine shells, their guts long picked over, their shadows the only shade for a mile. Something dens in the biggest of them.', 'medium', 0, 0, 1, '["Metal groans inside a machine shell, then thinks better of it.", "A grit-devil spins up, wanders the row, and collapses."]', '{"east": "zone_deep_waste", "west": "zone_waste_verge", "north": "zone_ruins", "south": "zone_waste_nadir"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -4, 1, 0, 'GT', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_verge', 'The Verge', 'The lip of the wastes proper, where the Haul Road''s shoulder crumbles into scree. Beyond, the grey goes on longer than seems fair.', 'low', 0, 0, 1, '["Scree hisses down the verge, dislodged by nothing you can see.", "A haul truck''s ghost-glare sweeps the road above and is gone."]', '{"east": "zone_waste_grit", "west": "zone_waste_deadflat", "north": "zone_ashway_road", "south": "zone_waste_coalsack"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -5, 1, 0, 'VG', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_nadir', 'The Nadir', 'The low point of the whole basin, where every runoff eventually arrives. A crust of dried chemistry cracks under your boots in bright, wrong colours.', 'medium', 0, 1, 1, '["The crust cracks in a colour that has no honest name.", "Something half-dissolved twitches in a puddle and goes still."]', '{"east": "zone_deep_tarpit", "west": "zone_waste_coalsack", "north": "zone_waste_grit", "south": "zone_waste_bailey"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -4, 2, 0, 'ND', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_tarpit', 'Tarpit Edge', 'Where the Undermarket''s runoff meets the wastes — a black seep of tar and worse, worked by pickers who answer to the gangs uphill.', 'medium', 1, 0, 1, '["A picker sinks a pole into the seep and hauls up something that drips.", "A gang tag, still wet, claims the tarpit for the week."]', '{"east": "zone_deep_warrens", "west": "zone_waste_nadir", "north": "zone_deep_waste", "south": "zone_deep_sink"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase2-build', 1783123885, 'map_world', NULL, -3, 2, 0, 'TP', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_windrow', 'The Windrow', 'Wind has heaped the district''s garbage into a long grey dune here, a windrow of ash and packaging that shifts and mutters.', 'low', 0, 0, 1, '["The windrow slumps with a sigh and buries something that was showing.", "Grit ticks against your teeth on a gust off the dune."]', '{"east": "zone_civ_commons", "west": "zone_waste_molten", "north": "zone_waste_slaghollow", "south": "zone_waste_gravel"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -4, -3, 0, 'WD', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_bailey', 'The Bailey', 'The broken ring-wall of some old containment yard, its bailey now a killing-floor of blind corners and drifted ash. Things nest in the wall.', 'medium', 0, 1, 1, '["Ash sifts from a murder-hole overhead in a thin grey thread.", "Down a blind corner, something exhales and waits to see if you follow."]', '{"east": "zone_deep_sink", "west": "zone_waste_grime", "north": "zone_waste_nadir"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -4, 3, 0, 'BY', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_coalsack', 'Coalsack', 'A slag pit gone black and glassy, so dark it drinks the light. The counter on anything you carry ticks a little faster here.', 'medium', 0, 1, 1, '["The black glass underfoot crunches like frozen tar.", "A dry heat rises off the pit though there is nothing burning."]', '{"east": "zone_waste_nadir", "west": "zone_waste_tipple", "north": "zone_waste_verge", "south": "zone_waste_grime"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -5, 2, 0, 'CK', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_sink', 'The Sink', 'The lowest drain of the Sprawl, where everything the Undermarket can''t sell finally settles. The smell has a shape you can lean on.', 'medium', 1, 0, 1, '["The sink glugs, swallows, and belches up a shoe.", "A rat the size of a loaf regards you, unimpressed, and dog-paddles on."]', '{"east": "zone_deep_rotrow", "west": "zone_waste_bailey", "north": "zone_deep_tarpit"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase2-build', 1783123885, 'map_world', NULL, -3, 3, 0, 'SK', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_rebar', 'Rebar Field', 'A cleared lot bristling with the rebar stubs of buildings that never got past their foundations. The bay wind whistles through the iron like a bad flute.', 'low', 0, 0, 1, '["Wind draws a low tuneless note from a forest of rebar.", "Rust flakes drift off the iron and settle on everything, including you."]', '{"east": "zone_dock_coldstore", "west": "zone_up_vellum", "north": "zone_nc_spindle", "south": "zone_media_plaza"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase3-build', 1783123885, 'map_world', NULL, 0, -4, 0, 'RF', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_dock_wharf', 'The Wharf', 'The working face of Coldwater Docks: bollards worn smooth, cargo nets stiff with salt, and the whole thing groaning gently on its pilings with the swell.', 'low', 0, 0, 1, '["A crane somewhere lowers a pallet with a shriek of unoiled cable.", "The wharf shifts underfoot as a swell rolls in, and settles."]', '{"east": "zone_dock_quays", "west": "zone_media_plaza", "north": "zone_dock_coldstore", "south": "zone_up_gate"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase3-build', 1783123885, 'map_world', NULL, 1, -3, 0, 'WH', '#111111', '#1fb5aa', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_grime', 'Grime Row', 'A sunken lane filmed in decades of industrial grime, every surface tacky to the touch. The husks out here don''t rust so much as fester.', 'medium', 0, 1, 1, '["A husk in the grime shifts its weight with a wet, deliberate creak.", "Your handprint stays on the wall behind you, glistening."]', '{"east": "zone_waste_bailey", "west": "zone_waste_runoff", "north": "zone_waste_coalsack"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -5, 3, 0, 'GR', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_up_vellum', 'Vellum Court', 'A pocket of would-be gentility at the water''s edge — planters, a dry ornamental basin, and frontages that face away from the docks as if embarrassed by them.', 'safe', 0, 0, 1, '["A planter mists itself and the ornamental basin, uselessly.", "A resident hurries through, not looking at the water."]', '{"east": "zone_waste_rebar", "west": "zone_waste_cull", "north": "zone_nc_datum", "south": "zone_civ_steps"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase3-build', 1783123885, 'map_world', NULL, -1, -4, 0, 'VL', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_dock_boatyard', 'The Boat Yard', 'A slipway of half-built and half-scrapped hulls, propped on stands, ribs bared to the weather. A shipwright works one of them with a heat-gun and a grudge.', 'low', 0, 0, 1, '["A hull rings like a bell as the shipwright drives a rivet home.", "A skeletal boat on its stand casts a cage of shadow across the yard."]', '{"east": "zone_nc_manifold", "west": "zone_bay_barges", "north": "zone_bay_breakwater", "south": "zone_dock_slip"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123885, 'map_world', NULL, 4, -4, 0, 'BY', '#111111', '#1fb5aa', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_dock_quays', 'The Quays', 'A run of stone quays where the fishing boats tie up and the cargo dhows unload after dark. Everything smells of tar, brine, and old fish.', 'low', 0, 0, 1, '["A mooring line creaks taut, then slack, then taut.", "A stevedore spits into the water and watches it a while."]', '{"east": "zone_dock_fishmarket", "west": "zone_dock_wharf", "north": "zone_bay_shallows", "south": "zone_up_approach"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase3-build', 1783123885, 'map_world', NULL, 2, -3, 0, 'QY', '#111111', '#1fb5aa', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_dock_coldstore', 'Cold Storage', 'A refrigerated warehouse still running on stolen power, its doors breathing fog. Inside, racks of catch and less legal cargo hang in the cold dark.', 'low', 0, 0, 1, '["A cold-store door sighs open, exhaling fog, and no one comes out.", "Something shifts on a hook deeper in the cold, then stills."]', '{"east": "zone_bay_shallows", "west": "zone_waste_rebar", "north": "zone_bay_sound", "south": "zone_dock_wharf"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123885, 'map_world', NULL, 1, -4, 0, 'CS', '#111111', '#1fb5aa', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_shallows', 'The Shallows', 'A boardwalk on rotting pilings runs out over the shallows, where the bay goes brown and thick with runoff. You can see shapes moving under the skin of the water.', 'low', 0, 0, 1, '["Something breaks the surface of the shallows, then is gone.", "The boardwalk gives a soft rotten groan and holds. Just."]', '{"east": "zone_bay_barges", "west": "zone_dock_coldstore", "north": "zone_bay_open", "south": "zone_dock_quays"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123885, 'map_world', NULL, 2, -4, 0, 'SH', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_barges', 'Moored Barges', 'A raft of dead barges lashed together into a floating slum-annex, rising and falling as one. You cross the harbour here by stepping from deck to swaying deck.', 'low', 0, 0, 1, '["A barge deck tilts under your weight and rights itself, unbothered.", "Washing strung between two barges drips into the black water below."]', '{"east": "zone_dock_boatyard", "west": "zone_bay_shallows", "north": "zone_bay_fog", "south": "zone_dock_fishmarket"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123885, 'map_world', NULL, 3, -4, 0, 'MB', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_cindersteps', 'Cinder Steps', 'A flight of fused-cinder terraces climbs the spoil-heap, each step a strata of a different bad decade. Your boots grind glass with every stride.', 'low', 0, 0, 1, '["A terrace edge crumbles to cinder-glass and slides away downslope.", "Ash lifts off the steps in a low sheet and resettles behind you."]', '{"east": "zone_waste_dross", "west": "zone_waste_blight", "north": "zone_waste_overburden", "south": "zone_waste_rustmarsh"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -7, -2, 0, 'CN', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_rustmarsh', 'Rust Marsh', 'Runoff has pooled into a shallow marsh the colour of old blood, reeds of rebar standing in water that stains everything it touches. Something big moves in the deeper channels.', 'medium', 0, 0, 1, '["A wake crosses the rust-marsh between the rebar reeds and is gone.", "Orange water laps at your boots and leaves a tidemark that won''t wash out."]', '{"east": "zone_waste_palings", "west": "zone_waste_sinter", "north": "zone_waste_cindersteps", "south": "zone_ashway_wash"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -7, -1, 0, 'RM', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_dross', 'Dross Flat', 'An open flat carpeted in dross — the skimmed scum of a thousand melts, light as pumice and sharp as spite. It crunches, endlessly, wherever you step.', 'low', 0, 0, 1, '["The dross crunches underfoot in a way that carries too far.", "A dust-devil of grey skim spins up, wanders the flat, and dies."]', '{"east": "zone_waste_smoulder", "west": "zone_waste_cindersteps", "north": "zone_waste_tarseep", "south": "zone_waste_palings"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -6, -2, 0, 'DR', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_smoulder', 'The Smoulder', 'A seam of buried refuse that has been smouldering underground for years, venting thin acrid smoke through cracks in the crust. The ground is warm and wrong.', 'low', 0, 0, 1, '["Warm smoke threads up through a crack and coils around your ankles.", "The crust flexes underfoot, warm as a living thing, and settles."]', '{"east": "zone_waste_gravel", "west": "zone_waste_dross", "north": "zone_waste_molten", "south": "zone_waste_slake"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -5, -2, 0, 'SM', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_civ_ledger', 'Ledger Hall', 'A municipal records office running on one flickering terminal and a clerk who outlived the department. Filing cabinets tower into the dark, alphabetised by a system since lost.', 'safe', 0, 0, 1, '["A cabinet drawer rolls open on its own and hangs there, accusing.", "The lone terminal chirps, prints a single blank slip, and sleeps again."]', '{"east": "zone_civ_steps", "west": "zone_civ_commons", "north": "zone_waste_cull", "south": "zone_up_aid"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase2-build', 1783123885, 'map_world', NULL, -2, -3, 0, 'LG', '#111111', '#4bb36a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_util_zone_drum_basement', 'Second Skin — Utility Room — Utility Room', 'A cramped below-grade utility room: bare concrete, sweating pipes, and the building junction box humming in its steel cabinet.', 'safe', 0, 0, 0, '[]', '{"up": "zone_drum_basement"}', '{"is_interior": true, "utility_room": true, "world_exit_zone": "zone_drum_exterior"}', NULL, 1783116358, 'map_int_drum', 'zone_drum_exterior', 0, 0, -2, NULL, NULL, '#8e6fd0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_up_approach', 'Spire Approach', 'A manicured processional toward the Halcyon spire — reflecting pools, engineered calm, and signage in a font that costs more than you do.', 'safe', 0, 0, 1, '["A groundskeeper drone skims a leaf from a pool that has never held a leaf.", "The signage subtly rearranges to face whoever is richest."]', '{"east": "zone_up_skyway", "west": "zone_up_gate", "north": "zone_dock_quays", "south": "zone_meridian"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase1-build', 1783123885, 'map_world', NULL, 2, -2, 0, 'SA', '#eeeeee', '#347b49', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_media_plaza', 'Mediaform Plaza', 'A hard-surfaced plaza dominated by a three-storey media wall that loops harbour-safety propaganda to an audience of nobody. A camera drone tracks anything that moves.', 'safe', 0, 0, 1, '["The media wall cheerfully reminds you that DROWNING IS PREVENTABLE.", "A camera drone swivels, fixes on you, loses interest."]', '{"east": "zone_dock_wharf", "west": "zone_civ_steps", "north": "zone_waste_rebar", "south": "zone_ext_1782953094650"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase3-build', 1783123885, 'map_world', NULL, 0, -3, 0, 'MP', '#111111', '#f5e642', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_molten', 'Molten Row', 'A row of tapped-out smelter troughs, the slag in them cooled to glassy rope decades ago. Heat-ghosts still shimmer off the metal on the worst afternoons.', 'low', 0, 0, 1, '["Cooled slag ticks and settles in a trough as if remembering being poured.", "A heat-shimmer rises off dead metal though there is nothing to make it."]', '{"east": "zone_waste_windrow", "west": "zone_waste_tarseep", "north": "zone_waste_sootbank", "south": "zone_waste_smoulder"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -5, -3, 0, 'MR', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_cinderway', 'Cinderway', 'An old haul-road paved in packed cinder runs south into nothing, edged with the burnt-out shells of the trucks that used it. The way is clear; the reasons to take it are not.', 'medium', 0, 0, 1, '["A truck shell ticks as the day''s heat leaves it, settling on flat tyres.", "The cinderway stretches south into a grey haze that never quite resolves."]', '{"east": "zone_waste_runoff", "west": "zone_waste_hopper", "north": "zone_waste_ferro"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -7, 3, 0, 'CW', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_dock_fishmarket', 'Fishmarket Dock', 'Trestle slabs of pale bay catch under a sagging awning, worked by fishmongers who gut and call and gut without pause. The runoff makes the boards treacherous.', 'low', 0, 0, 1, '["A fishmonger splits something long and pale with a single wet stroke.", "Cats gather at the edge of the market, patient as debt collectors."]', '{"east": "zone_dock_slip", "west": "zone_dock_quays", "north": "zone_bay_barges", "south": "zone_up_skyway"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "fishing_table_id": "fish_coldwater_bay", "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123885, 'map_world', NULL, 3, -3, 0, 'FM', '#111111', '#1fb5aa', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_gantry', 'Gantry Yard', 'A forest of gantry cranes straddles the tracks here, lifting and placing with slow enormous care. Standing beneath them is a trust exercise the Yards runs on you daily.', 'low', 0, 0, 1, '["A gantry crane passes overhead, its shadow crossing you like a slow eclipse.", "A load hangs, sways, and is set down a hand''s breadth from where you stand."]', '{"west": "zone_yard_freightworks", "north": "zone_corp_argent", "south": "zone_yard_crane"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 8, -3, 0, 'GY', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_ferro', 'Ferro Flat', 'A field so saturated with iron oxide that a dropped blade rusts to lace by morning. The whole flat sings a faint magnetic whine that sets your fillings buzzing.', 'medium', 0, 0, 1, '["A thin magnetic whine rises, sets your teeth on edge, and fades.", "Rust blooms visibly across a scrap you pass, like a wound opening."]', '{"east": "zone_waste_tipple", "west": "zone_waste_drossworks", "north": "zone_waste_ashenverge", "south": "zone_waste_cinderway"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -7, 2, 0, 'FF', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_endcut', 'The Endcut', 'Where the paved city simply ends — a ragged cut of exposed foundations and severed pipes bleeding rust down onto the wastes below.', 'low', 0, 0, 1, '["A severed pipe releases a slow brown weep that never quite stops.", "Somewhere below, a foundation ticks as it cools into the evening."]', '{"east": "zone_civ_sortation", "west": "zone_waste_slake", "north": "zone_waste_gravel", "south": "zone_ruins"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase2-build', 1783123885, 'map_world', NULL, -4, -1, 0, 'EC', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_hopper', 'The Hopper', 'A collapsed loading hopper forms a steel-walled sinkhole here, its throat choked with drifted ash and the odd picked-clean bone. Things climb out of it at night.', 'medium', 0, 0, 1, '["Ash hisses down the hopper''s throat into a dark that never fills.", "A bone, picked white, rolls up out of the hopper''s mouth and stops at your feet."]', '{"east": "zone_waste_cinderway", "west": "zone_waste_dustreach", "north": "zone_waste_drossworks"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -8, 3, 0, 'HP', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_tipple', 'The Tipple', 'The skeleton of an ore tipple leans over the flat, its chutes long empty, its gantries a roost for things with too many legs. Rust rains down whenever the wind leans on it.', 'medium', 0, 0, 1, '["A gantry sheds a slow rain of rust as the wind leans on the tipple.", "Something with too many legs adjusts its grip on a chute overhead."]', '{"east": "zone_waste_coalsack", "west": "zone_waste_ferro", "north": "zone_waste_deadflat", "south": "zone_waste_runoff"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -6, 2, 0, 'TT', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_runoff', 'The Runoff', 'Where the flats drain, a sludge-choked culvert carries the day''s worst chemistry down into the dark. The smell has teeth. Something upstream keeps it fed.', 'medium', 0, 0, 1, '["The runoff glugs and shifts as something upstream lets more through.", "A slick of colours that shouldn''t exist together slides past and is gone."]', '{"east": "zone_waste_grime", "west": "zone_waste_cinderway", "north": "zone_waste_tipple"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -6, 3, 0, 'RO', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_deadflat', 'Dead Flat', 'A hardpan so lifeless the scavengers use it as a boundary: past here, nothing grows, nothing dens, nothing bothers. Which is its own kind of warning.', 'low', 0, 0, 1, '["Nothing moves on the dead flat. Nothing at all. It''s unnerving.", "Your own footsteps come back off the hardpan a half-beat late."]', '{"east": "zone_waste_verge", "west": "zone_waste_ashenverge", "north": "zone_ashway_ashfall", "south": "zone_waste_tipple"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -6, 1, 0, 'DF', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_deadwater', 'Dead Water', 'A becalmed pocket of the bay where nothing moves and sound goes flat. Boats avoid it; the ones that didn''t are still here, mostly under.', 'low', 0, 0, 1, '["The dead water swallows the sound of your own footsteps.", "A mast tilts up out of the flat water, marking a boat that stayed too long."]', '{"east": "zone_bay_reach", "west": "zone_bay_slick", "south": "zone_bay_mid"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 2, -7, 0, 'DW', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_slick', 'The Slick', 'A permanent rainbow slick of spilled fuel lies flat on the water here, too still to be healthy. Walk the lashed pontoons and try not to breathe deep.', 'low', 0, 0, 1, '["The fuel-slick parts around a pontoon and closes again, seamless.", "A dead gull rotates slowly on the slick, wings spread as if still gliding."]', '{"east": "zone_bay_deadwater", "west": "zone_nc_sable", "south": "zone_bay_wreck"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 1, -7, 0, 'SL', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_skyline', 'Skyline Walk', 'A glass promenade cantilevered out over the drop, the whole grey city and greyer bay laid out beneath your feet through the floor. Vertigo is included in the rent.', 'safe', 0, 0, 1, '["The glass floor creaks reassuringly and shows you the long way down.", "A resident jogs past on the skyline walk, eyes forward, seeing none of it."]', '{"east": "zone_bay_buoy", "west": "zone_gov_vantage", "north": "zone_nc_halcyon", "south": "zone_nc_datum"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase5-build', 1783123885, 'map_world', NULL, -1, -6, 0, 'SK', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_narrows', 'The Narrows', 'Where the breakwater''s arm nearly meets the far spit, the bay pinches to a churning narrows. The current here has taken stronger swimmers than you and shows no signs of being full.', 'medium', 0, 0, 1, '["The narrows churns white against the last blocks of the breakwater.", "The current tugs at the pontoon and, briefly, at you."]', '{"east": "zone_nc_concordat", "west": "zone_bay_reach", "south": "zone_bay_floes"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 4, -7, 0, 'NR', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_wreck', 'The Wreck', 'A freighter died here decades ago and never fully sank, its rusted flank a cliff of riveted iron you can board at low swell. Deep in the flooded holds, things have made a home.', 'medium', 0, 0, 1, '["The wreck groans as the swell works at it, shedding a rain of rust.", "Something large shifts deep in the flooded hold, and the whole hull shivers."]', '{"east": "zone_bay_mid", "west": "zone_bay_buoy", "north": "zone_bay_slick", "south": "zone_bay_sound"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 1, -6, 0, 'WR', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_buoy', 'Iron Buoy', 'A great rusted channel-buoy lists here, its bell long silenced, chained to a mooring that no longer connects to anything. Squatters have built a precarious perch on top.', 'low', 0, 0, 1, '["The dead buoy''s bell shifts in the swell but does not quite ring.", "A squatter waves from the buoy''s perch, or possibly warns you off."]', '{"east": "zone_bay_wreck", "west": "zone_nc_skyline", "north": "zone_nc_sable", "south": "zone_nc_spindle"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 0, -6, 0, 'IB', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_sable', 'Sable Court', 'A black-marble court ringed by frontages so exclusive they have no signage at all. If you have to ask what''s sold here, a discreet security detail will ask you to leave.', 'safe', 0, 0, 1, '["A frosted door opens, exhales climate-controlled air, and closes on nothing.", "Two security operators clock you, confer without words, and keep watching."]', '{"east": "zone_bay_slick", "west": "zone_nc_halcyon", "south": "zone_bay_buoy"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase5-build', 1783123885, 'map_world', NULL, 0, -7, 0, 'SB', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_spindle', 'The Spindle', 'The base of a slender comms spindle that climbs out of sight, humming with the whole district''s data. Standing near it makes your teeth ache and your deck light up with things it shouldn''t.', 'safe', 0, 0, 1, '["The spindle''s hum steps up a semitone, then settles.", "Your gear chirps at signals it has no business receiving."]', '{"east": "zone_bay_sound", "west": "zone_nc_datum", "north": "zone_bay_buoy", "south": "zone_waste_rebar"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase5-build', 1783123885, 'map_world', NULL, 0, -5, 0, 'SP', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_reach', 'The Reach', 'The long open reach toward the bay mouth, where the fog thins and the swell finally has room to build. The far shore is a rumour on the worst days and invisible on the rest.', 'low', 0, 0, 1, '["The swell lifts the pontoon-walk and sets it down with a sigh.", "Something surfaces far out on the reach, considers the distance, and sinks."]', '{"east": "zone_bay_narrows", "west": "zone_bay_deadwater", "south": "zone_bay_deep"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 3, -7, 0, 'RE', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_prefect', 'Prefect Plaza', 'The plaza fronting the Prefecture, where the queue for permits, papers, and pardons wraps twice around a dry fountain. The Prefecture issues all three, at a price and a delay.', 'safe', 0, 0, 1, '["The permit queue advances one place and a small cheer goes up.", "A prefecture clerk stamps a document, considers it, and stamps it again."]', '{"east": "zone_nc_halcyon", "west": "zone_gov_assembly", "south": "zone_gov_vantage"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -2, -7, 0, 'PF', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_registry', 'Registry Hall', 'The central registry of citizens, most of them dead, missing, or invented. Archivists move between the stacks with the reverence of priests tending a god that has stopped answering.', 'safe', 0, 0, 1, '["An archivist reshelves a citizen file with elaborate, pointless care.", "A drawer of records rolls open, exhales dust, and offers up a name no one claims."]', '{"east": "zone_gov_cobalt", "west": "zone_waste_scald", "north": "zone_gov_ministry", "south": "zone_waste_ashensteppe"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -4, -6, 0, 'RG', '#eeeeee', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_floes', 'The Floes', 'Runoff and cold have crusted this corner of the bay with rafts of grey ice that grind together and apart. You cross by timing the floes, which is exactly as advisable as it sounds.', 'low', 0, 0, 1, '["Two ice floes grind together with a sound like a slow scream.", "A floe tips under your weight, rights itself, and drifts on, unbothered."]', '{"east": "zone_bay_basin", "west": "zone_bay_deep", "north": "zone_bay_narrows", "south": "zone_bay_breakwater"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 4, -6, 0, 'FL', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_ministry', 'Ministry Row', 'A colonnade of ministries that administer nothing, their brass plates polished daily by staff who have not been paid in a decade and turn up anyway. The doors are always open onto empty marble halls.', 'safe', 0, 0, 1, '["A clerk crosses Ministry Row with a stack of forms and a look of terrible purpose.", "A ministry door stands open on a hall of empty desks, all of them expectant."]', '{"east": "zone_gov_assembly", "west": "zone_waste_rusthollow", "south": "zone_gov_registry"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -4, -7, 0, 'MN', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_cobalt', 'Cobalt Court', 'A court of law tiled in cobalt, where cases are heard, adjourned, and inherited by the children of the original plaintiffs. Justice here is less blind than simply very, very slow.', 'safe', 0, 0, 1, '["A bailiff calls a case number that has not been reached in nine years.", "Two advocates argue amicably over a docket neither expects to resolve."]', '{"east": "zone_gov_vantage", "west": "zone_gov_registry", "north": "zone_gov_assembly", "south": "zone_gov_mezzanine"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -3, -6, 0, 'CB', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_deep', 'The Deep', 'The deepest sounding in the bay, marked on old charts with a number and a warning. Whatever the harbour lurkers grew from, it grew biggest down here, in the dark under the cold.', 'medium', 0, 0, 1, '["A wake broad as a road crosses the deep and sinks without a source.", "The cold off the deep water climbs your spine like a hand."]', '{"east": "zone_bay_floes", "west": "zone_bay_mid", "north": "zone_bay_reach", "south": "zone_bay_fog"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 3, -6, 0, 'DP', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_embassy_floor3', 'Embassy Hotel & Bar — Third Floor Landing', 'Top of the stairwell — the third-floor landing, closer to the roof and colder for it. Water stains bloom brown across the ceiling tiles, one sagging low enough to drip when it rains. Units 3A through 3D ring the landing, their doors heavier up here, the locks newer; people who climb this far want to stay lost. A single emergency light burns a weak red over the stairwell mouth, the only bulb on the floor that still works. The iron railing ends in a broken newel post someone''s wrapped in duct tape.', 'safe', 0, 0, 1, '["The sagging ceiling tile releases a slow, deliberate drip.", "The red emergency light buzzes, dims, and steadies again."]', '{"down": "zone_embassy_floor2", "east": "zone_apt_11", "west": "zone_apt_12", "north": "zone_apt_9", "south": "zone_apt_10"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783112361, 'map_interior_zone_residential_lobby', 'zone_residential_lobby', 0, 0, 2, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_assembly', 'The Assembly', 'The debating chamber of a legislature that meets to ratify decisions the Architect already made. The benches are full of the earnest, the appointed, and the merely loud.', 'safe', 0, 0, 1, '["A vote is called in the chamber and passes unanimously, as they all do.", "Someone at the rostrum speaks with great feeling to a chamber that isn''t listening."]', '{"east": "zone_gov_prefect", "west": "zone_gov_ministry", "south": "zone_gov_cobalt"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -3, -7, 0, 'AS', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_emberwaste', 'Ember Waste', 'A stretch of ground that burned so long ago and so completely that it still, on cold nights, remembers the fire — a faint orange breathing deep in the cracks.', 'low', 0, 0, 1, '["An ember-glow breathes deep in a crack, then fades, then breathes again.", "Warmth rises through the sole of your boot from a fire decades dead."]', '{"east": "zone_waste_cull", "west": "zone_waste_slaghollow", "north": "zone_gov_mezzanine", "south": "zone_civ_commons"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase6-build', 1783123885, 'map_world', NULL, -3, -4, 0, 'EW', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_sootbank', 'Sootbank', 'A long bank of packed soot heaped against a fallen retaining wall, black and greasy and warm in patches where something still smoulders beneath.', 'low', 0, 0, 1, '["A patch of the sootbank glows dull orange, then darkens as you watch.", "Your boots come away black, and stay black, no matter what you do."]', '{"east": "zone_waste_slaghollow", "west": "zone_waste_greymile", "north": "zone_waste_leachfield", "south": "zone_waste_molten"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase6-build', 1783123885, 'map_world', NULL, -5, -4, 0, 'SB', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_civ_meltwater', 'Meltwater Row', 'A municipal water point where a queue forms daily at a bank of hissing taps. The line has its own etiquette, its own enforcers, and a very long memory.', 'low', 0, 0, 1, '["A tap coughs, spits brown, then runs clear to a small ragged cheer.", "Someone loses their place in line and does not make that mistake twice."]', '{"east": "zone_up_aid", "west": "zone_waste_gravel", "north": "zone_civ_commons", "south": "zone_civ_sortation"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase2-build', 1783123885, 'map_world', NULL, -3, -2, 0, 'MT', '#111111', '#4bb36a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_mezzanine', 'The Mezzanine', 'The half-floor between departments where the truly stalled paperwork goes to age. Interdepartmental mail carts trundle through on rails, delivering forms to forms.', 'safe', 0, 0, 1, '["A mail cart trundles across the mezzanine and delivers a form to another form.", "The mezzanine''s paperwork rustles in a draught with a sound like distant applause."]', '{"east": "zone_gov_onyx", "west": "zone_waste_ashensteppe", "north": "zone_gov_cobalt", "south": "zone_waste_emberwaste"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -3, -5, 0, 'MZ', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_ashensteppe', 'Ashen Steppe', 'A wide grey steppe of drifted ash that runs west toward worse. The wind has combed it into long dunes that erase your trail as fast as you make it.', 'low', 0, 0, 1, '["Wind combs the ashen steppe into a new dune-line and erases your last step.", "Far to the west, something red flickers on the horizon, and is gone."]', '{"east": "zone_gov_mezzanine", "west": "zone_waste_leachfield", "north": "zone_gov_registry", "south": "zone_waste_slaghollow"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase6-build', 1783123885, 'map_world', NULL, -4, -5, 0, 'AE', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_onyx', 'Onyx Row', 'The quarter''s lower approach, an onyx-flagged terrace where the government''s marble finally gives way to the working city — and, beyond the western rail, to the wastes.', 'safe', 0, 0, 1, '["A statue of a forgotten administrator watches Onyx Row with stone disapproval.", "From the terrace edge you can see the wastes begin, grey and patient, to the west."]', '{"east": "zone_nc_datum", "west": "zone_gov_mezzanine", "north": "zone_gov_vantage", "south": "zone_waste_cull"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -2, -5, 0, 'OX', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_cull', 'The Cull', 'The government''s unofficial dumping ground for what it would rather forget — records, machinery, and now and then people. The scavengers work it carefully; the government watches it not at all.', 'medium', 0, 0, 1, '["A picker in the cull uncovers a government seal and pockets it, fast.", "A shredded drift of official documents lifts, swirls, and resettles like snow."]', '{"east": "zone_up_vellum", "west": "zone_waste_emberwaste", "north": "zone_gov_onyx", "south": "zone_civ_ledger"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase6-build', 1783123885, 'map_world', NULL, -2, -4, 0, 'CL', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_slaghollow', 'Slaghollow', 'A hollow scooped from the flats where cooled slag was once dumped and forgotten. Rain has pooled in the bottom into something that reflects nothing.', 'low', 0, 0, 1, '["The pool in the hollow''s bottom holds perfectly still, reflecting no sky.", "Slag glass clinks and shifts on the hollow''s slope, resettling."]', '{"east": "zone_waste_emberwaste", "west": "zone_waste_sootbank", "north": "zone_waste_ashensteppe", "south": "zone_waste_windrow"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase6-build', 1783123885, 'map_world', NULL, -4, -4, 0, 'Sw', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_scald', 'The Scald', 'A field of blanched, chemically-burnt hardpan where nothing has grown since before the Handoff. The government pretends this is the edge of its jurisdiction, and the wastes agree.', 'medium', 0, 0, 1, '["Heat-haze rises off the scalded pan though the air itself is cold.", "A brittle crust of bleached salts crunches to powder underfoot."]', '{"east": "zone_gov_registry", "west": "zone_waste_tailings", "north": "zone_waste_rusthollow", "south": "zone_waste_leachfield"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase6-build', 1783123885, 'map_world', NULL, -5, -6, 0, 'SC', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_102', 'Unit 102', 'A studio that still has its original built-in cabinetry, half the doors missing, the rest painted shut. A mattress on a pallet, a chair, a view of the square if you press your face to the glass. Home.', 'safe', 0, 0, 1, '["Pipes knock somewhere in the walls. The building is old but it holds."]', '{"west": "zone_mq_chrome_f1"}', '{"is_apartment": true}', NULL, 1782964408, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 1, 0, 1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_chrome_f1', 'Chrome Court — Floor 1', 'The first-floor hallway of Chrome Court, a tunnel of amber emergency light and doors painted so many times the numbers are just suggestions. The carpet is worn to jute down the center where every tenant walks the identical line. Four units open off the hall. A window at the end looks out over the district''s neon, which from up here almost looks like a city that works.', 'safe', 0, 0, 1, '["A door down the hall closes with the finality of a lock turning.", "The amber emergency light hums and dims by a shade.", "Something is cooking behind one of the doors; the smell almost reaches you.", "The end-of-hall window rattles as the wind leans on it."]', '{"up": "zone_mq_chrome_f2", "down": "zone_mq_chrome_lobby", "east": "zone_mq_chrome_102", "west": "zone_mq_chrome_104", "north": "zone_mq_chrome_101", "south": "zone_mq_chrome_103"}', '{"is_interior": true}', NULL, 1782964408, 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, 1, NULL, NULL, '#e85aa0', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_corp_boardroom', 'Boardroom Row', 'The boardrooms of the consignment houses, glass-walled and climate-perfect, where cargo is bought, insured, and betrayed over water nobody drinks. The Yards'' grime stops precisely at the door.', 'safe', 0, 0, 1, '["A boardroom''s glass wall fogs to opaque mid-meeting, then clears, empty.", "A consignment is agreed with a handshake and a look that promises litigation."]', '{"east": "zone_yard_container", "west": "zone_dock_slip", "north": "zone_nc_manifold", "south": "zone_corp_investor"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase8-build', 1783123885, 'map_world', NULL, 5, -3, 0, 'Br', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_lobby', 'The Meridian - Lobby', 'The ground-floor lobby of The Meridian, a residential tower that survived the Collapse the same way most things survived it: through sheer institutional inertia. Cracked terrazzo floors carry the ghost of a geometric inlay, ground to near-invisibility by foot traffic. A bank of tenant mailboxes lines the east wall — most of them pried open decades ago, doors hanging at odd angles, contents long gone. The security desk sits unmanned, its terminal cycling a screensaver of rolling static. A brass plaque reading THE MERIDIAN — ESTABLISHED 2031 is still bolted above the entrance, which is the most optimistic thing in the building. Emergency lighting casts everything in pale amber. Stairs ascend through a fire door to the upper floors.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_floor_1", "out": "zone_meridian", "down": "zone_util_zone_meridian_lobby"}', '{"is_building": true, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": "apartment", "world_exit_zone": "zone_meridian", "scavenging_table_id": null}', NULL, 1783112116, 'map_int_meridian', NULL, 0, 0, 0, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_roof', 'The Meridian — Roof', 'Cracked tar and gravel, hemmed by a low concrete parapet stenciled with emergency contact numbers no one has answered in years. Rusted antenna masts and conduit runs crowd the edges — relics of broadcast infrastructure nobody maintained long enough to matter. The city stretches out in every direction: an unbroken plane of light pollution and industrial haze that could almost pass for a skyline at night if you let your eyes go soft. Up here the building''s recycled air ends and the real thing begins — it tastes like ozone and diesel particulate and something faintly sulphuric drifting in from the eastern refineries. Wind cuts across the gravel with nothing to stop it. A heavy-duty junction box is mounted to the stairwell housing near the hatch.', 'safe', 0, 0, 0, '[]', '{"down": "zone_meridian_floor_6"}', '{"open_sky": true, "is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783112403, 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 7, NULL, NULL, '#c9a884', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_breakwater', 'The Breakwater', 'A spine of tumbled concrete and rebar thrown out to break the bay''s temper, walkable if you mind your footing. Things nest in the gaps between the blocks.', 'low', 0, 0, 1, '["A wave slaps the breakwater and throws cold spray across the blocks.", "Something withdraws into a gap in the concrete as your shadow falls on it."]', '{"east": "zone_nc_highwater", "west": "zone_bay_fog", "north": "zone_bay_floes", "south": "zone_dock_boatyard"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase3-build', 1783123885, 'map_world', NULL, 4, -5, 0, 'BW', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_datum', 'Datum Court', 'A survey marker set in brass declares this the city''s official datum — the point from which all heights and depths are measured. Someone has scratched YOU ARE HERE beneath it, and it feels like a threat.', 'safe', 0, 0, 1, '["The brass datum marker gleams, recently and pointlessly polished.", "A tour drone recites the court''s significance to an audience of pigeons."]', '{"east": "zone_nc_spindle", "west": "zone_gov_onyx", "north": "zone_nc_skyline", "south": "zone_up_vellum"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase5-build', 1783123885, 'map_world', NULL, -1, -5, 0, 'DT', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_mid', 'Coldwater Deep', 'The middle of the bay, where the water goes from grey to a green-black that gives nothing back. The pontoon-walks end at railings here, and beyond is just cold and down.', 'low', 0, 0, 1, '["The green-black water heaves once, without wind, and stills.", "A railing marks the edge of the safe walk; past it, nothing but cold."]', '{"east": "zone_bay_deep", "west": "zone_bay_wreck", "north": "zone_bay_deadwater", "south": "zone_bay_open"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase5-build', 1783123885, 'map_world', NULL, 2, -6, 0, 'CD', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_cathode', 'Cathode Row', 'A narrow run of frontage where every third storefront sells some flavor of skin, chrome, or forgetting. The signage competes for attention until it all blurs into one continuous migraine of light. A tattoo parlor, two shuttered clinics, and a club with a cherry blinking over the door. The gutter runs with meltwater and the confetti of a hundred torn wristbands.', 'safe', 0, 0, 1, '["A busker''s amp cuts out mid-note and doesn''t come back.", "Someone in a doorway offers you something in a language you almost recognize.", "The cherry sign over the club flickers, blinks, holds.", "A drone the size of a fist buzzes the row, scanning faces, and moves on."]', '{"in": "zone_mq_cherry_floor", "east": "zone_mq_chrome_court", "west": "zone_meridian", "north": "zone_up_skyway", "south": "zone_mq_marquee"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783123885, 'map_world', NULL, 3, -1, 0, 'CT', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_palings', 'The Palings', 'A fence-line of scrap palings marches across the flat, warning off nobody. Rags and older things hang from the pickets, turning slowly in the wind.', 'low', 0, 0, 1, '["A rag on a paling turns to face you, then turns away.", "The palings creak in sequence down the line, as if counting you past."]', '{"east": "zone_waste_slake", "west": "zone_waste_rustmarsh", "north": "zone_waste_dross", "south": "zone_ashway_ashfall"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -6, -1, 0, 'PL', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_slake', 'Slake Pond', 'The only clean-ish water for a mile, and so the only thing out here worth defending. A ragged scavenger camp rings the pond — lean-tos, a cook-fire, and eyes that track every newcomer.', 'low', 0, 0, 1, '["Someone at the camp fire looks up, weighs you, and goes back to the pot.", "A scavenger fills a jug at the pond''s edge and hurries it back to the lean-tos."]', '{"east": "zone_waste_endcut", "west": "zone_waste_palings", "north": "zone_waste_smoulder", "south": "zone_ashway_road"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -5, -1, 0, 'SL', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_leachfield', 'The Leachfield', 'The buried leach-beds of the old city drain here, seeping a slow chemical weep to the surface that kills the ground in bright, geometric patches.', 'medium', 0, 0, 1, '["A patch of ground fizzes gently as something leaches up through it.", "The chemical weep has drawn a perfect dead circle in the ash. You step around it."]', '{"east": "zone_waste_ashensteppe", "west": "zone_waste_scrapmesa", "north": "zone_waste_scald", "south": "zone_waste_sootbank"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase6-build', 1783123885, 'map_world', NULL, -5, -5, 0, 'LF', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_halcyon', 'Halcyon Heights', 'The literal top of the city: a wind-scoured roof-plaza of glass and engineered calm, where the arcology''s owners take the air and look down on everything they own, which is everything.', 'safe', 0, 0, 1, '["A private drone escorts someone important across the plaza and away.", "The wind up here is clean, cold, and somehow billed to your account."]', '{"east": "zone_nc_sable", "west": "zone_gov_prefect", "south": "zone_nc_skyline"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase5-build', 1783123885, 'map_world', NULL, -1, -7, 0, 'HH', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_embassy_floor2', 'Embassy Hotel & Bar — Second Floor Landing', 'The second-floor landing, where the hotel''s old carpet runner gives up entirely — bare concrete underneath, worn pale in a path between the stairs and the doors. Four units open off it, brass numbers screwed to each: 2A through 2D, a couple hanging by a single screw. The stairwell railing is cold iron, sticky where a thousand hands have gripped it. A dead vending machine hulks in the corner, its glass front spider-cracked, the snacks inside fossilised. Somewhere below, the bar''s murmur leaks up through the floor.', 'safe', 0, 0, 1, '["A door slams somewhere down the hall, and a chain rattles into place.", "The dead vending machine emits a single, hopeless click."]', '{"up": "zone_embassy_floor3", "down": "zone_residential_lobby", "east": "zone_apt_7", "west": "zone_apt_8", "north": "zone_apt_5", "south": "zone_apt_6"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null}', NULL, 1783020605, 'map_interior_zone_residential_lobby', 'zone_residential_lobby', 0, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_floor_1', 'The Meridian — Floor 1 Hallway', 'Floor 1 of The Meridian. A narrow corridor stretches between four unit doors — numbers 101, 102, 103, 104 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_floor_2", "down": "zone_meridian_lobby", "east": "zone_meridian_unit_102", "west": "zone_meridian_unit_104", "north": "zone_meridian_unit_101", "south": "zone_meridian_unit_103"}', '{"is_interior": true}', NULL, 1782898109, 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meridian_floor_5', 'The Meridian — Floor 5 Hallway', 'Floor 5 of The Meridian. A narrow corridor stretches between four unit doors — numbers 501, 502, 503, 504 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]', '{"up": "zone_meridian_floor_6", "down": "zone_meridian_floor_4", "east": "zone_meridian_unit_502", "west": "zone_meridian_unit_504", "north": "zone_meridian_unit_501", "south": "zone_meridian_unit_503"}', '{"is_building": false, "is_interior": true, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": null}', NULL, 1783111944, 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 5, NULL, NULL, '#c9a884', 'indoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_gov_vantage', 'Vantage Row', 'A gallery of offices with the best view in the quarter, allotted strictly by seniority to functionaries who no longer look up from their screens to use it.', 'safe', 0, 0, 1, '["A functionary''s blinds are drawn against the finest view in the city.", "Someone important passes down Vantage Row and three doors quietly close."]', '{"east": "zone_nc_skyline", "west": "zone_gov_cobalt", "north": "zone_gov_prefect", "south": "zone_gov_onyx"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase6-build', 1783123885, 'map_world', NULL, -2, -6, 0, 'VN', '#111111', '#ff5ea8', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_threshold', 'The Threshold', 'The fractured boulevard stretches east beneath leaning streetlights and sagging power lines. Rows of shuttered storefronts stare blankly across the cracked pavement, their windows painted over or shattered years ago. Rusted buses sit abandoned where traffic died, their interiors swallowed by dust and creeping vines. Faded evacuation signs still point deeper into the city, while countless layers of graffiti bury whatever messages came before. Every road seems to lead somewhere important, yet every direction feels equally forgotten.', 'safe', 0, 0, 1, '["A drone hums overhead, its chassis stenciled with a faded corporate logo you half-recognize.", "Somewhere in the plaza, a speaker plays a jingle for a fast food chain. Thirty seconds in, it loops.", "A ragged NPC catches your eye and immediately looks away. Everyone here has learned not to be interesting.", "The departure board flickers: COLDWATER → DENVER → SALT LAKE → [SIGNAL LOST]"]', '{"east": "zone_thresholdeast", "west": "zone_city_west", "north": "zone_city_north", "south": "zone_city_south"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123885, 'map_world', NULL, 0, 0, 0, 'TR', '#111111', '#4bb36a', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_marshalling', 'The Marshalling Yard', 'The great marshalling yard where trains are assembled car by car, a slow ballet of shunting and coupling conducted by a lone yard pilot with a flag and a death wish.', 'low', 0, 0, 1, '["Cars couple somewhere down the yard with a crash that rolls along the line.", "The yard pilot waves a flag at a locomotive and, incredibly, is obeyed."]', '{"east": "zone_yard_reefer", "west": "zone_yard_boxcar", "north": "zone_yard_pallet", "south": "zone_yard_dray"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 7, -1, 0, 'Ma', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_dray', 'Dray Street', 'The haulers'' street, lined with idling trucks and the cafes and card games that spring up wherever drivers wait. The engine-fug never lifts and the coffee is, somehow, worse than the fug.', 'low', 0, 0, 1, '["A trucker leans on their horn out of boredom and three others answer.", "A card game folds abruptly as a dispatcher''s voice barks a load number."]', '{"east": "zone_yard_weighbridge", "west": "zone_yard_loadout", "north": "zone_yard_marshalling", "south": "zone_yard_transfer"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 7, 0, 0, 'Dy', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_depot', 'The Depot', 'The Yards'' main depot and muster point, where crews clock on, trucks queue, and the day''s chaos is dispatched from a whiteboard nobody can read. The gateway between the yards and the city proper.', 'low', 0, 0, 1, '["A crew clocks on at the depot, reads the whiteboard, and gives up interpreting it.", "A dispatcher shouts a truck number into the din and something, eventually, moves."]', '{"east": "zone_yard_boxcar", "west": "zone_mq_chrome_court", "north": "zone_corp_investor", "south": "zone_mq_precinct"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 5, -1, 0, 'Dp', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_transfer', 'The Transfer Dock', 'The main transfer dock, where cargo changes hands, trucks, and legality. Forklifts weave between pallet-mountains with a recklessness that is somehow never quite fatal.', 'low', 0, 0, 1, '["A forklift threads a gap it has no business fitting through, horn blaring.", "A pallet-mountain shifts, sheds a crate, and is restacked before it lands."]', '{"east": "zone_yard_forklift", "west": "zone_yard_chassis", "north": "zone_yard_dray", "south": "zone_yard_tare"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 7, 1, 0, 'TD', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_boxcar', 'Boxcar Lane', 'A lane of derelict boxcars long since shunted off the rails and repurposed — into stores, squats, and the occasional very private meeting. Their doors are all differently, deliberately locked.', 'low', 0, 0, 1, '["A boxcar door slides shut from the inside as you pass.", "Cook-smoke rises from a boxcar''s jury-rigged flue and hangs in the still air."]', '{"east": "zone_yard_marshalling", "west": "zone_yard_depot", "north": "zone_yard_sidings", "south": "zone_yard_loadout"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 6, -1, 0, 'Bx', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_crane', 'Crane Alley', 'A narrow service alley threaded between the crane bases, hung with control cables and the occasional operator''s washing. The machinery here is always warm and always listening.', 'low', 0, 0, 1, '["A crane base ticks with heat as its motors idle down.", "A control cable overhead twitches as someone, somewhere, takes the sticks."]', '{"west": "zone_yard_pallet", "north": "zone_yard_gantry", "south": "zone_yard_reefer"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 8, -2, 0, 'Cr', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_loadout', 'The Loadout', 'The southern loadout bays where trucks back up to the docks and freight crosses from rail to road under the eye of a tally clerk who trusts absolutely no one, correctly.', 'low', 0, 0, 1, '["A truck backs to the loadout bay with a warning beep and a grinding stop.", "The tally clerk counts a load twice, frowns, and counts it a third time."]', '{"east": "zone_yard_dray", "west": "zone_mq_precinct", "north": "zone_yard_boxcar", "south": "zone_yard_chassis"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 6, 0, 0, 'Lo', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_reefer', 'Reefer Row', 'A row of refrigerated cars humming on stolen power, breathing fog into the yard. What''s kept cold here ranges from legitimate to the kind of thing you smell before you see.', 'low', 0, 0, 1, '["A reefer car''s compressor kicks in with a shudder and a gout of fog.", "Something in a reefer car has stopped being kept cold enough. The row knows."]', '{"west": "zone_yard_marshalling", "north": "zone_yard_crane", "south": "zone_yard_weighbridge"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 8, -1, 0, 'Rf', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_pallet', 'Pallet Row', 'Wooden pallets stacked into unstable ziggurats, splintered, stained, and endlessly recirculated. The whole row smells of wet timber and the ghost of whatever they last carried.', 'low', 0, 0, 1, '["A pallet ziggurat sheds a plank from its summit and no one flinches.", "The wet-timber smell of Pallet Row gets into the back of your throat."]', '{"east": "zone_yard_crane", "west": "zone_yard_sidings", "north": "zone_yard_freightworks", "south": "zone_yard_marshalling"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 7, -2, 0, 'Pl', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_bourse', 'The Bourse', 'Coldwater''s exchange floor, where cargo, debt, territory, and the occasional person are bought and sold by shouting at screens. The noise is a kind of weather.', 'safe', 0, 0, 1, '["A trader on the Bourse floor screams a number and a fortune changes hands.", "The big board flickers red across the floor and the shouting climbs an octave."]', '{"west": "zone_nc_glass", "south": "zone_nc_tessellate"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 8, -7, 0, 'Bo', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_consulate', 'The Consulate', 'A cluster of corporate consulates flying flags that are really just logos, where the great powers of the city keep missions to one another and pretend at diplomacy between raids.', 'safe', 0, 0, 1, '["A consular flag — a logo, really — is lowered and a subtly different one raised.", "Two rival consuls pass on the steps and exchange smiles like drawn blades."]', '{"east": "zone_nc_ivory", "west": "zone_bay_basin", "north": "zone_nc_meridianheights", "south": "zone_nc_palisade"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 6, -6, 0, 'Cs', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_ivory', 'Ivory Deck', 'An open deck of pale stone where the quarter takes its meetings in the open air, on the theory that it''s harder to bug a conversation held over a two-hundred-metre drop.', 'safe', 0, 0, 1, '["A meeting on the Ivory Deck breaks up the instant you come into earshot.", "The wind off the deck snatches a document from a manicured hand and is thanked for it."]', '{"east": "zone_nc_tessellate", "west": "zone_nc_consulate", "north": "zone_nc_glass", "south": "zone_nc_beacon"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 7, -6, 0, 'Id', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_palisade', 'The Palisade', 'A rampart-walk along the district''s edge, all defensive posturing and excellent sightlines, where private security patrol a wall that keeps out a threat the residents can''t name.', 'safe', 0, 0, 1, '["A security operator paces the palisade, watching the yards below like weather.", "The palisade wall is being raised another course, against nothing in particular."]', '{"east": "zone_nc_beacon", "west": "zone_nc_highwater", "north": "zone_nc_consulate", "south": "zone_waste_oxide"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 6, -5, 0, 'Pa', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_meridianheights', 'Meridian Heights', 'The most expensive address in Coldwater, where the residences have no numbers because everyone who matters already knows where they are. The air is filtered twice and billed once.', 'safe', 0, 0, 1, '["A private lift disgorges someone important into a lobby that closes behind them.", "The filtered air here smells faintly of nothing, aggressively maintained."]', '{"east": "zone_nc_glass", "west": "zone_nc_concordat", "south": "zone_nc_consulate"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 6, -7, 0, 'MH', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_tessellate', 'Tessellate Plaza', 'A plaza floored in a shifting tessellated pattern that is, allegedly, load-bearing corporate art. Standing on it too long gives you the distinct sense of being solved.', 'safe', 0, 0, 1, '["The tessellated floor seems to shift its pattern when you look away from it.", "A tour group is told the plaza''s meaning and quietly declines to believe it."]', '{"west": "zone_nc_ivory", "north": "zone_nc_bourse", "south": "zone_nc_chancery"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 8, -6, 0, 'Te', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_concordat', 'The Concordat', 'The treaty hall where the corporations that own Coldwater sign the accords that carve it up, beneath a mural of a handshake so large and so insincere it loops in the mind for hours.', 'safe', 0, 0, 1, '["A delegation sweeps through the Concordat, flanked by lawyers like an honour guard.", "The great handshake mural is being repainted, slightly, to reflect the new terms."]', '{"east": "zone_nc_meridianheights", "west": "zone_bay_narrows", "south": "zone_bay_basin"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 5, -7, 0, 'Co', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_highwater', 'Highwater Court', 'A residential court set at the district''s high-water mark, named for a flood that the owners have been assured, at great expense, will never reach them. The assurance is framed on a wall.', 'safe', 0, 0, 1, '["A resident of Highwater Court checks the bay''s level and, reassured, checks it again.", "The framed flood-assurance gleams under a light that never goes off."]', '{"east": "zone_nc_palisade", "west": "zone_bay_breakwater", "north": "zone_bay_basin", "south": "zone_nc_manifold"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 5, -5, 0, 'HC', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_glass', 'Glass Terrace', 'A terrace of mirror-glass towers that reflect only each other, so that from any point you see the district endlessly, and the grey city beyond it not at all.', 'safe', 0, 0, 1, '["Your reflection is handed off from one glass face to the next across the terrace.", "A window-drone squeegees a pane that is already, impossibly, perfect."]', '{"east": "zone_nc_bourse", "west": "zone_nc_meridianheights", "south": "zone_nc_ivory"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 7, -7, 0, 'GT', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_ashreach', 'Ash Reach', 'An open reach of drifted ash that the wind sculpts into low dunes and then, bored, flattens again. Old machine-bones surface and submerge in it like the tide has teeth.', 'low', 0, 0, 0, '["The wind reshapes an ash dune and reveals the rusted ribs of a machine.", "Ash lifts off the reach in a long grey sheet and settles a field over."]', '{"east": "zone_waste_rusthollow", "west": "zone_waste_cinderflat", "south": "zone_waste_tailings"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -6, -7, 0, 'AR', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_chancery', 'Chancery Walk', 'The legal spine of the quarter, a colonnade of chanceries and notaries where the accords signed in the Concordat are rendered into language designed never to be read.', 'safe', 0, 0, 1, '["A notary seals a document with a stamp that costs more than a life down in the yards.", "A clerk carries a contract down Chancery Walk with both hands, like a relic."]', '{"west": "zone_nc_beacon", "north": "zone_nc_tessellate", "south": "zone_corp_argent"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 8, -5, 0, 'Cy', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_downwind', 'The Downwind', 'Set deliberately downwind of the heights so its stink never troubles them, this is where the quarter''s waste and worse is quietly let go. Things thrive here that the district denies exist.', 'medium', 0, 0, 1, '["A gust carries the Downwind''s stink briefly uphill, and a dozen windows shut.", "Something feeds in the Downwind''s tip and does not look up as you pass."]', '{"east": "zone_corp_argent", "west": "zone_waste_oxide", "north": "zone_nc_beacon", "south": "zone_yard_freightworks"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase9-build', 1783123886, 'map_world', NULL, 7, -4, 0, 'Dw', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_rusthollow', 'Rust Hollow', 'A shallow hollow where rainwater once pooled and left everything it touched the deep orange-brown of old blood. Nothing drains here; it just sits, and stains, and waits.', 'low', 0, 0, 0, '["Standing water in the hollow holds the grey sky the colour of rust.", "A dropped bolt in the hollow is already, impossibly, half-eaten by rust."]', '{"east": "zone_gov_ministry", "west": "zone_waste_ashreach", "south": "zone_waste_scald"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -5, -7, 0, 'RH', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_freightworks', 'The Freightworks', 'The mechanised heart of the Yards, a shed of conveyors and sorting arms that route freight by a logic no living person fully understands and nobody dares reboot.', 'low', 0, 0, 1, '["A sorting arm swings a crate down a chute chosen by nothing you can see.", "The conveyors change direction all at once, for reasons, and change back."]', '{"east": "zone_yard_gantry", "west": "zone_yard_container", "north": "zone_waste_downwind", "south": "zone_yard_pallet"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 7, -3, 0, 'FW', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_beacon', 'Beacon Row', 'A row crowned by an old harbour beacon, relit as a status symbol, that now warns ships away from a port that no longer wants them. The light sweeps the district all night.', 'safe', 0, 0, 1, '["The beacon sweeps its cold light across Beacon Row and moves on.", "A resident closes their blinds against the beacon they paid extra to live beside."]', '{"east": "zone_nc_chancery", "west": "zone_nc_palisade", "north": "zone_nc_ivory", "south": "zone_waste_downwind"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 7, -5, 0, 'Be', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_oxide', 'Oxide Flats', 'A rust-red flat where the district''s runoff bleeds out onto open ground, staining everything the colour of a wound. The quarter looks the other way; the wastes do not.', 'medium', 0, 0, 1, '["Orange runoff bleeds across the oxide flat in slow, branching deltas.", "Something pale and heavy shifts in the rust-stained mud and goes still."]', '{"east": "zone_waste_downwind", "west": "zone_nc_manifold", "north": "zone_nc_palisade", "south": "zone_yard_container"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase9-build', 1783123886, 'map_world', NULL, 6, -4, 0, 'Ox', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_cinderflat', 'Cinder Flat', 'A flat of grey cinder that crunches underfoot like frozen ground, except it is not frozen — it is the cooled skin over heat that never fully left. In places the crust gives, and glows.', 'medium', 0, 1, 0, '["The cinder crust crunches under you and, somewhere, exhales a curl of heat.", "A patch of the flat glows dull orange for a moment and then thinks better of it."]', '{"east": "zone_waste_ashreach", "west": "zone_waste_slagverge", "south": "zone_waste_clinkerrow"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -7, -7, 0, 'CF', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_nc_manifold', 'The Manifold', 'The junction where the diplomatic quarter''s clean marble finally meets the working city — the boat yard below, the boardrooms beside. A checkpoint here decides, quietly, who ascends.', 'safe', 0, 0, 1, '["A checkpoint at the Manifold turns someone back with a smile and a raised palm.", "From the Manifold you can see the yards'' grime start, one clean step down."]', '{"east": "zone_waste_oxide", "west": "zone_dock_boatyard", "north": "zone_nc_highwater", "south": "zone_corp_boardroom"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_consumer_trash"}', 'phase9-build', 1783123885, 'map_world', NULL, 5, -4, 0, 'Mf', '#eeeeee', '#9b59b6', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_vexhollow', 'Vex Hollow', 'A sunken hollow just inside the Redline where the air sits still and hums, and the few plants are the wrong colours and the wrong sizes. Things den here. They come out changed, and hungry, and toward you.', 'high', 0, 3, 0, '["The air in Vex Hollow hums at a pitch you feel in your fillings.", "Something the wrong size for its shape shifts in a den at the hollow''s edge and fixes on you."]', '{"east": "zone_waste_brokenkiln", "west": "zone_red_slaughterworks", "north": "zone_waste_deadfurnace", "south": "zone_waste_pitnine"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase10-build', 1783123886, 'map_world', NULL, -8, -4, 0, 'VH', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_tailings', 'The Tailings', 'The tailings pile of some long-dead operation, a grey-green mound of what was left after everything worth having was taken out. Whatever''s still in it is what nobody wanted, which is not the same as nothing.', 'low', 0, 0, 0, '["The tailings pile weeps a thin grey-green trickle from somewhere inside itself.", "A scavenger works the tailings with a bent rake and does not acknowledge you."]', '{"east": "zone_waste_scald", "west": "zone_waste_clinkerrow", "north": "zone_waste_ashreach", "south": "zone_waste_scrapmesa"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -6, -6, 0, 'TT', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_brokenkiln', 'Broken Kiln', 'The cracked shell of a brick kiln, split down one side so it gapes like a broken jaw. Inside, out of the wind, is one of the few places in the wastes a person can almost rest. Almost.', 'medium', 0, 1, 0, '["Wind whistles through the split in the broken kiln and dies away inside it.", "Old scorch-marks and newer bootprints share the floor of the kiln; you are not the first to almost rest here."]', '{"east": "zone_waste_greymile", "west": "zone_red_vexhollow", "north": "zone_waste_ferrouswash", "south": "zone_waste_overburden"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -7, -4, 0, 'BK', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_scrapmesa', 'Scrap Mesa', 'A flat-topped mesa built entirely of compacted scrap, layer on crushed layer, that the wastes have folded back into something almost geological. Salvagers mine it like a seam. It bites back.', 'low', 0, 0, 0, '["A slab calves off the scrap mesa''s flank and comes down in a slow avalanche of rust.", "A salvager on the mesa''s rim waves once — warning or greeting, impossible to tell — and goes back to digging."]', '{"east": "zone_waste_leachfield", "west": "zone_waste_ferrouswash", "north": "zone_waste_tailings", "south": "zone_waste_greymile"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -6, -5, 0, 'SM', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_greymile', 'The Grey Mile', 'The featureless grey mile that everyone crosses and nobody remembers, a long flat nothing of ash and grit between the city''s edge and the killing ground beyond. Its only landmark is that it has none.', 'low', 0, 0, 0, '["The grey mile stretches ahead and behind, identical in both directions.", "A bootprint in the grit ahead of you fills slowly with drifting ash and is gone."]', '{"east": "zone_waste_sootbank", "west": "zone_waste_brokenkiln", "north": "zone_waste_scrapmesa", "south": "zone_waste_tarseep"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -6, -4, 0, 'GM', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_clinkerrow', 'Clinker Row', 'A row of heaped clinker — the hard, glassy dregs raked from furnaces that died before anyone here was born — stacked into a wall that someone, at some point, decided to hide behind.', 'medium', 0, 1, 0, '["A heap of clinker shifts and rattles down its own slope with a sound like held breath.", "Behind the clinker wall, briefly, a shape ducks out of sight."]', '{"east": "zone_waste_tailings", "west": "zone_red_meltline", "north": "zone_waste_cinderflat", "south": "zone_waste_ferrouswash"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -7, -6, 0, 'CR', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_deadfurnace', 'Dead Furnace', 'The husk of a smelting furnace big enough to stand inside, cold now for decades, its throat choked with debris. People shelter in its belly and swear the walls are still, very faintly, warm.', 'medium', 0, 1, 0, '["The dead furnace''s iron throat funnels the wind into a low, mournful note.", "Someone''s cold camp sits in the furnace''s belly; the ashes are still warm, but they are gone."]', '{"east": "zone_waste_ferrouswash", "west": "zone_red_cullrow", "north": "zone_red_meltline", "south": "zone_red_vexhollow"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -8, -5, 0, 'DF', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_ferrouswash', 'Ferrous Wash', 'A wash where iron-rich runoff braids across the flat in rust-red rivulets, staining a delta that spreads a little wider each year. Drinking it kills you slowly; standing in it, only slightly faster.', 'medium', 0, 1, 0, '["A ferrous rivulet finds a new path across the wash and stains it in seconds.", "The rust-red delta glistens, and the air above it tastes of blood you didn''t shed."]', '{"east": "zone_waste_scrapmesa", "west": "zone_waste_deadfurnace", "north": "zone_waste_clinkerrow", "south": "zone_waste_brokenkiln"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -7, -5, 0, 'FW', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_fumealley', 'Fume Alley', 'A narrow alley between spoil-banks where the Slagworks'' fumes pool when the wind drops, thick enough to lean on and yellow enough to taste. Nobody lingers in Fume Alley by choice, and few by accident survive it.', 'medium', 0, 1, 0, '["Yellow fume pools in the alley and stirs, reluctantly, as you pass through it.", "The air in Fume Alley thickens; your eyes water and the far end swims and vanishes."]', '{"east": "zone_waste_blight", "west": "zone_waste_cokeyard", "north": "zone_red_marrowrow", "south": "zone_slag_catalyst"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -9, -2, 0, 'FA', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_dreadfurnace', 'Dread Furnace', 'The last hard step of the neck before it meets the Reclaimer below — the cold hulk of a furnace so large it has its own weather inside, a slow red haze that never clears. What dens in it came down from the Redline, and stayed.', 'high', 0, 3, 0, '["The dread furnace breathes its red haze out through a hundred cracks and draws it back in.", "Deep in the furnace''s throat, far up in the dark, something shifts its weight and settles."]', '{"east": "zone_slag_flarestack", "north": "zone_red_flensing", "south": "zone_slag_reclaimer"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase11-build', 1783123886, 'map_world', NULL, -11, -1, 0, 'DF', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_cokeyard', 'Coke Yard', 'A yard heaped with spent coke, the grey-black char raked out of the Slagworks'' furnaces and dumped uphill to cool. It never fully does; deep in the piles a red heart still glows, and breathes.', 'medium', 0, 1, 0, '["A coke pile settles with a soft crunch and exhales a breath of sulphurous heat.", "Deep in the char a red glow pulses once, like something down there is still awake."]', '{"east": "zone_waste_fumealley", "west": "zone_red_flensing", "north": "zone_waste_chargully", "south": "zone_slag_flarestack"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -10, -2, 0, 'CY', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_blight', 'The Blight', 'A blighted flat above the Slagworks Gate where nothing that tries to grow gets past a hand''s height before it blackens and gives up. The salvage here is good; the ground insists you earn it.', 'low', 0, 1, 0, '["A blackened stalk in the Blight crumbles to soot at the touch of the wind.", "Something worth having glints in the dead ground, and the dead ground does not want to give it up."]', '{"east": "zone_waste_cindersteps", "west": "zone_waste_fumealley", "north": "zone_waste_pitnine", "south": "zone_waste_sinter"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_industrial_salvage"}', 'phase11-build', 1783123886, 'map_world', NULL, -8, -2, 0, 'BL', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_overburden', 'The Overburden', 'The overburden heap — the worthless top-layer stripped off to get at whatever was beneath — dumped and forgotten in a ridge that the wastes have claimed. It is, fittingly, the wastes made of the wastes'' leftovers.', 'low', 0, 0, 0, '["The overburden ridge sheds a slow trickle of spoil and settles a little lower.", "Something small bolts across the overburden and vanishes into a gap in the spoil."]', '{"east": "zone_waste_tarseep", "west": "zone_waste_pitnine", "north": "zone_waste_brokenkiln", "south": "zone_waste_cindersteps"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -7, -3, 0, 'TO', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_flensing', 'The Flensing', 'The neck of the Redline — a single hard column of poisoned ground threading down out of the killing floor in the north toward the Slagworks below. It earned its name honestly; things that come through it arrive short of skin.', 'high', 0, 3, 0, '["The wind funnels down the Flensing''s neck, and it carries a fine red grit that stings where it lands.", "Something drags itself down the neck from the north, leaving a wet trail, and does not slow when it sees you."]', '{"east": "zone_waste_cokeyard", "north": "zone_red_gnash", "south": "zone_red_dreadfurnace"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase11-build', 1783123886, 'map_world', NULL, -11, -2, 0, 'FL', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_drossworks', 'The Drossworks', 'The dross-works, where the skimmings off molten metal were once cast into pigs and stacked to sell. The stacks are still here, grown over with rust, a maze of worthless iron that squatters and worse have made a warren of.', 'low', 0, 0, 0, '["A stack of dross pigs shifts in the maze and someone, unseen, curses it quietly.", "The rusted iron of the Drossworks funnels the wind into a low, resentful hum."]', '{"east": "zone_waste_ferro", "west": "zone_waste_ashencut", "north": "zone_waste_reek", "south": "zone_waste_hopper"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_industrial_salvage"}', 'phase11-build', 1783123886, 'map_world', NULL, -8, 2, 0, 'DK', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_feralyard', 'Feral Yard', 'A yard where the packs den — the fast, four-legged, wrong-eyed things the Redline makes of what were once dogs, and of what were once other things. They hunt in the open here because here, at last, they are the ones being avoided.', 'lethal', 0, 4, 0, '["Something paces the Feral Yard''s perimeter just out of sight, patient, unhurried, closing.", "A chorus of wrong-pitched howls goes up across the yard and is answered from every side."]', '{"east": "zone_red_screaminglot", "north": "zone_red_mutiewarren", "south": "zone_red_bonepit"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -11, -5, 0, 'FY', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_ashenverge', 'Ashen Verge', 'The western lip of the flats, where the ash deepens to the knee and the wind never stops working at it. Footprints fill in behind you within a minute.', 'medium', 0, 0, 1, '["The ash swallows your last footprint before you''ve taken three more.", "Wind carves a new dune-line across the verge while you watch."]', '{"east": "zone_waste_deadflat", "west": "zone_waste_reek", "north": "zone_ashway_wash", "south": "zone_waste_ferro"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123886, 'map_world', NULL, -7, 1, 0, 'AV', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_radsink', 'The Rad Sink', 'The lowest point of the Redline, where every poison the frontier produces drains and pools and concentrates into a sump so hot the air above it shimmers. Nothing lives in the Rad Sink. Things merely pass through it, and are lessened.', 'lethal', 0, 5, 0, '["The air over the Rad Sink shimmers and warps the ruin behind it into something molten.", "Your counter, if you carry one, stops ticking and simply screams a single unbroken note."]', '{"east": "zone_red_hazardnine", "west": "zone_red_mutiewarren", "north": "zone_red_glowfield", "south": "zone_red_screaminglot"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -10, -6, 0, 'RS', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_killingfloor', 'The Killing Floor', 'The killing floor — a flat, open expanse swept clear of everything but bones and the things that made them, where whatever apex the Redline has bred holds court over a court of the dead. People come here to prove something. Their proof is usually their absence.', 'lethal', 0, 5, 0, '["The killing floor is silent in the way a held breath is silent, waiting to be let out.", "Bones crunch somewhere out on the floor under a weight far larger than yours, and stop."]', '{"east": "zone_waste_slagverge", "west": "zone_red_glowfield", "south": "zone_red_hazardnine"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -9, -7, 0, 'KF', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_mutiewarren', 'Mutie Warren', 'A warren of tunnels and burrows clawed into the poisoned ground by generations of the changed, who breed here in the dark faster than anything can cull them. To enter the Warren is to be outnumbered by definition and outmatched by the second turning.', 'lethal', 0, 4, 0, '["A pale, wrong-jointed shape watches from a burrow-mouth and then draws silently back in.", "The ground underfoot is undermined by the Warren; it gives a little, and something below resents it."]', '{"east": "zone_red_radsink", "north": "zone_red_redline", "south": "zone_red_feralyard"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -11, -6, 0, 'MW', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_hazardnine', 'Hazard Nine', 'A containment zone from the old world, numbered nine, breached decades ago and never resealed because no one who went to reseal it came back. The signage still insists, politely and in three languages, that you should not be reading it.', 'lethal', 0, 4, 0, '["A breached containment door hangs open on Hazard Nine, and the dark inside it breathes out.", "Faded trefoil signs march away into the ruin, each one more emphatic and less obeyed than the last."]', '{"east": "zone_red_meltline", "west": "zone_red_radsink", "north": "zone_red_killingfloor", "south": "zone_red_cullrow"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -9, -6, 0, 'HN', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_glowfield', 'Glowfield', 'A field where the ground gives off a sick green-white light strong enough to read by, pooling in the low places like luminous water. The salvage here is fabulous and the price for taking it is measured in the years it quietly subtracts.', 'lethal', 0, 5, 0, '["The glowfield casts your shadow in three directions at once, all of them wrong.", "A pool of luminance shifts as something moves through it below the surface, unseen, unhurried."]', '{"east": "zone_red_killingfloor", "west": "zone_red_redline", "south": "zone_red_radsink"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -10, -7, 0, 'GL', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_redline', 'The Redline', 'The Redline itself, the top-left corner of the known world, where a line of rusted stakes and warning-skulls marks the place past which the maps simply stop and the living are simply advised not to. Everything here glows faintly, including, after a while, you.', 'lethal', 0, 5, 0, '["A warning-skull on its stake turns its empty sockets toward you as the wind shifts it.", "The air itself has a red cast here, and your skin prickles with a heat that has no source."]', '{"east": "zone_red_glowfield", "south": "zone_red_mutiewarren"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -11, -7, 0, 'RL', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_gnash', 'The Gnash', 'The southern jaw of the Redline, where the killing floor narrows into the neck that drops toward the Slagworks. Everything the core spits out comes through the Gnash on its way down, and the Gnash takes its toll on the way past.', 'lethal', 0, 4, 0, '["The Gnash funnels a cold, ticking wind down the neck toward the Slagworks far below.", "Something comes down through the Gnash from the killing floor above, and does not stop for you."]', '{"east": "zone_waste_chargully", "north": "zone_red_bonepit", "south": "zone_red_flensing"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -11, -3, 0, 'GN', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_rictusalley', 'Rictus Alley', 'A narrow alley where the dead lie where they fell, dried by the poisoned air into leather and locked, every one of them, into a wide fixed grin. They line the walls like an audience. They have been waiting a long time for the show, and you have just walked on.', 'lethal', 0, 4, 0, '["The grinning dead of Rictus Alley watch you pass with their fixed, patient, leather smiles.", "A dried corpse propped against the wall has, you are almost certain, turned to follow you."]', '{"east": "zone_red_slaughterworks", "west": "zone_red_bonepit", "north": "zone_red_screaminglot", "south": "zone_waste_chargully"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -10, -4, 0, 'RA', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_slaughterworks', 'The Slaughterworks', 'An old automated abattoir whose machines never received the order to stop and so, powered by something that will not die, still run — hooks and blades and conveyors cycling endlessly through an empty line that is not, if you listen, always empty.', 'lethal', 0, 5, 0, '["A meat-hook conveyor cycles past overhead, empty, and then not empty, and then empty again.", "The Slaughterworks'' blades reset with a wet mechanical sigh, ready for a line that never ends."]', '{"east": "zone_red_vexhollow", "west": "zone_red_rictusalley", "north": "zone_red_cullrow", "south": "zone_red_marrowrow"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -9, -4, 0, 'SW', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_cullrow', 'Cull Row', 'A row where, in the early days, they tried to hold the line — to cull the changed as they came, at a barricade of scrap and desperation. The barricade is still here. So, in a sense, are the people who manned it, though they are on the wrong side of it now.', 'lethal', 0, 4, 0, '["The old cull-barricade sags across the row, hung with things best not examined closely.", "Something on the far side of the barricade tests it, gently, methodically, looking for the give."]', '{"east": "zone_waste_deadfurnace", "west": "zone_red_screaminglot", "north": "zone_red_hazardnine", "south": "zone_red_slaughterworks"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -9, -5, 0, 'CR', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_slagverge', 'Slag Verge', 'The western verge of the wastes, where the ground goes from merely poisoned to something worse a few strides further on. A hand-painted sign, riddled and unreadable, still manages to communicate: no further.', 'medium', 0, 1, 0, '["A dry wind off the west carries a taste of hot metal and rot.", "The unreadable warning sign creaks on its post and points, more or less, at nothing good."]', '{"east": "zone_waste_cinderflat", "west": "zone_red_killingfloor", "south": "zone_red_meltline"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -8, -7, 0, 'SV', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_chargully', 'Char Gully', 'A charred gully at the very foot of the Redline, the last scrap of merely-poisoned ground before the lethal core proper. Scavengers work its edges for what the core discards, one eye always uphill, on the red glow that never quite goes out.', 'medium', 0, 1, 0, '["Char crunches underfoot in the gully, and uphill the red glow of the core pulses, slow.", "A scavenger works the gully''s edge with one eye uphill and bolts the moment you appear."]', '{"east": "zone_red_marrowrow", "west": "zone_red_gnash", "north": "zone_red_rictusalley", "south": "zone_waste_cokeyard"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase12-build', 1783123886, 'map_world', NULL, -10, -3, 0, 'CG', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_marrowrow', 'Marrow Row', 'The eastern edge of the core where it presses against the fringe, a row of gnawed and hollowed ruins that the changed use as a larder and a lair both. It is the closest a living person can stand to the Redline''s heart and still, sometimes, walk away.', 'lethal', 0, 4, 0, '["A hollowed ruin along Marrow Row is packed with the clean-gnawed evidence of the Row''s purpose.", "Something in the ruins cracks a bone for the marrow with a sound like a snapping bough."]', '{"east": "zone_waste_pitnine", "west": "zone_waste_chargully", "north": "zone_red_slaughterworks", "south": "zone_waste_fumealley"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -9, -3, 0, 'MR', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_bonepit', 'The Bonepit', 'A pit into which the Redline''s dead have been dragged, or have dragged themselves, for longer than anyone remembers — a slow midden of bone gone grey and soft. Things nest in the Bonepit that find the bones convenient, and the visitors more so.', 'lethal', 0, 4, 0, '["The bone-midden shifts and settles with a dry clatter that goes on too long to be settling.", "Something rises out of the Bonepit wearing the bones it nested in, and turns its head toward you."]', '{"east": "zone_red_rictusalley", "north": "zone_red_feralyard", "south": "zone_red_gnash"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -11, -4, 0, 'BP', '#eeeeee', '#ff0000', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_pitnine', 'Pit Nine', 'A collapsed pit, numbered nine by someone who counted eight others just like it, that goes down into the dark further than a dropped stone will report back on. Its rim is the western edge of the walkable wastes.', 'medium', 0, 1, 0, '["A stone kicked into Pit Nine falls a long time and never lands, or lands too far to hear.", "Cold, still air breathes up out of Pit Nine, smelling of deep earth and something metallic."]', '{"east": "zone_waste_overburden", "west": "zone_red_marrowrow", "north": "zone_red_vexhollow", "south": "zone_waste_blight"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase10-build', 1783123886, 'map_world', NULL, -8, -3, 0, 'PN', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_mq_battery', 'Battery Square', 'The civic heart of the district, such as it is — a paved square built around a dry fountain someone has repurposed as a communal firepit. A grocery holds down one side, a police precinct scowls from another, and a public notice pillar wears a thick scab of flyers: rooms to let, people gone missing, curfews rescinded and reinstated. It is, by local standards, safe. The precinct''s floodlights see to that.', 'safe', 0, 0, 1, '["The precinct floodlights sweep the square in a slow, bored arc.", "Someone feeds a broken chair to the fountain fire and warms their hands.", "A public-address speaker crackles: \"CITIZENS ARE REMINDED—\" then gives up.", "A flyer tears loose from the notice pillar and cartwheels across the paving."]', '{"in": "zone_mq_grocery", "east": "zone_mq_precinct", "west": "zone_mq_marquee", "north": "zone_mq_chrome_court", "south": "zone_mq_overpass"}', '{"scavenging_table_id": null}', NULL, 1783123886, 'map_world', NULL, 4, 0, 0, 'BS', '#eeeeee', '#e85aa0', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_sidings', 'The Sidings', 'A tangle of rail sidings where flatcars wait, loaded and forgotten, for engines that are always about to come. The scavengers know the timetable better than the railway does.', 'low', 0, 0, 1, '["A flatcar creaks as its load settles a little further toward salvage.", "A picker melts between the sidings, one eye on the far signal box."]', '{"east": "zone_yard_pallet", "west": "zone_corp_investor", "north": "zone_yard_container", "south": "zone_yard_boxcar"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase8-build', 1783123886, 'map_world', NULL, 6, -2, 0, 'Sd', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_yard', 'The Cracking Yard', 'The heart of the works: a maze of pipework and catwalks around the base of the great cracking columns, everything furred with rust and dripping something that eats through your soles if you stand too long. Salvage crews got the easy metal years ago. What''s left is buried, or guarded, or both.', 'low', 1, 0, 0, '["A pipe fails somewhere overhead and vents a long, hoarse sigh of stale gas.", "Your boots stick, then peel free of the tar-slicked decking with a wet tear."]', '{"east": "zone_slag_gate", "west": "zone_slag_rail", "north": "zone_slag_catalyst", "south": "zone_slag_sump"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_industrial_salvage"}', NULL, 1783123886, 'map_world', NULL, -9, 0, 0, 'CY', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_meat_slaughter', 'Slaughter Lane', 'The killing lane of the meat market, gutters running to a central drain, hooks swinging empty between the stalls. The butchers here work fast and ask nothing.', 'medium', 1, 0, 1, '["A hook swings empty down the lane, then is loaded and swings heavy.", "A butcher hoses the gutter toward the drain; it runs, briefly, red."]', '{"east": "zone_yard_bonded", "west": "zone_meat_ashpit", "north": "zone_mq_cage", "south": "zone_meat_carrion"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 5, 2, 0, 'Sl', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slums', 'The Sprawl', 'Dense, vertical, and loud. Pre-Handoff apartment complexes have been stacked with improvised floors. The streets below are narrow tunnels of laundry lines and extension cords.', 'medium', 1, 0, 1, '["Something crashes several floors above. Then laughter.", "A wall-mounted screen plays a looping corporate training video on conflict resolution."]', '{"down": "zone_tunnels", "east": "zone_deep_scab", "west": "zone_deep_cardboard", "north": "zone_city_south", "south": "zone_deep_maw"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123886, 'map_world', NULL, 0, 2, 0, 'SP', '#111111', '#cf6a2e', 'outdoors', '{}', 'aud_497cdcea-97e4-4e1a-99da-24e01577a849');
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_bay_basin', 'The Reflecting Basin', 'A formal basin of still bay water set into the diplomatic quarter as a gesture toward serenity. The gesture is undercut by the things that occasionally surface in it.', 'low', 0, 0, 1, '["The reflecting basin holds the towers upside-down, perfectly, until it doesn''t.", "A ripple crosses the still basin, from the middle, where nothing dropped."]', '{"east": "zone_nc_consulate", "west": "zone_bay_floes", "north": "zone_nc_concordat", "south": "zone_nc_highwater"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_harbor"}', 'phase9-build', 1783123886, 'map_world', NULL, 5, -6, 0, 'Bn', '#eeeeee', '#2f86cc', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_yard_railhead', 'The Railhead', 'The Yards'' rail terminus, where a single working locomotive shunts flatcars of scrap and cargo out to wherever rails still run. The yardmaster keeps his office in a dead signal box here.', 'low', 0, 0, 1, '["The shunting loco couples up with a crash and a hiss of ancient brakes.", "A flatcar of scrap rolls past, loaded past any sane limit, and slows to a stop."]', '{"west": "zone_yard_tare", "north": "zone_yard_forklift", "south": "zone_yard_bulk"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase7-build', 1783123886, 'map_world', NULL, 8, 2, 0, 'RH', '#111111', '#007031', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_slag_drums', 'The Drum Yard', 'Ten thousand steel drums, stacked four high and rotting from the bottom up, their contents long since wept into the soil. Most are empty. A few are not, and the labels that would tell you which are gone to rust-lace. A scavenger''s jackpot with a coin-flip attached.', 'low', 1, 0, 0, '["A drum somewhere in the stacks lets go and slumps with a long, corroded sigh.", "Rusty runoff wicks up the side of your boot in a thin brown line."]', '{"east": "zone_slag_sump", "west": "zone_waste_coldslag", "north": "zone_slag_rail", "south": "zone_waste_slagbar"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_industrial_salvage"}', NULL, 1783123886, 'map_world', NULL, -10, 1, 0, 'DY', '#111111', '#e5822a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_meltline', 'The Meltline', 'The line where the wastes end and the Redline begins, marked by a slumped rail of fused slag that runs off north and south as far as the haze allows. On this side, the counter ticks. On that side, it screams.', 'high', 0, 3, 0, '["Your teeth ache faintly, the way they do near the Meltline, and you understand it as a warning.", "Beyond the fused-slag rail the ground has a wrong, glassy sheen, and something moves on it."]', '{"east": "zone_waste_clinkerrow", "west": "zone_red_hazardnine", "north": "zone_waste_slagverge", "south": "zone_waste_deadfurnace"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase10-build', 1783123886, 'map_world', NULL, -8, -6, 0, 'TM', '#eeeeee', '#e05555', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_deep_waste', 'The Falloff', 'This is where the city simply gives up. The last blocks of Old Coldwater sag into their own flooded basements, streets dead-ending in dust, rebar, and drifts of shattered glass. Nobody has lived out here in a very long time — you can read it in every caved roofline and every door left standing open on nothing.', 'medium', 1, 0, 0, '["A section of roofing lets go somewhere nearby and comes down with a long, tired crash.", "Wind moves through a hundred empty window-frames at once, one low toneless moan.", "Dust drifts across the dead street in slow, aimless curls.", "Deep in a collapsed building, something shifts its weight and settles again."]', '{"east": "zone_badland_sw_outer", "west": "zone_waste_grit", "north": "zone_badland_w_gate", "south": "zone_deep_tarpit"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "BL", "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123847, 'map_world', NULL, -3, 1, 0, 'BL', '#111111', '#cf6a2e', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_velk_exterior', 'Castoff Walk', 'A cramped walk wedged between two facades in slow structural surrender, close enough to touch both walls at once. What isn''t rented out is stacked with other people''s abandoned lives — chair legs, dead lamps, a wardrobe with no doors — chained together against the inevitable. Velk''s Pre-Owned holds the middle of the walk, its window a chaos of salvaged furniture arranged with a curator''s inexplicable pride. Everything smells of damp upholstery and someone else''s cigarettes.', 'low', 0, 0, 1, '[]', '{"in": "zone_velk_shop", "east": "zone_mq_marquee", "west": "zone_thresholdeast", "north": "zone_meridian", "south": "zone_drum_exterior"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": "zone_deep_waste", "scavenging_table_id": null}', NULL, 1783123848, 'map_world', NULL, 2, 0, 0, 'Fu', '#eeeeee', '#347b49', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_dock_slip', 'Smuggler''s Slip', 'A crooked finger-pier the harbourmaster''s charts pretend doesn''t exist. Boats come in dark and leave lighter. Ask no questions; you won''t like being answered.', 'medium', 1, 0, 1, '["A shuttered boat rocks at the slip, its cargo very deliberately covered.", "Someone at the slip''s end watches you the entire time, and says nothing."]', '{"east": "zone_corp_boardroom", "west": "zone_dock_fishmarket", "north": "zone_dock_boatyard", "south": "zone_up_chrome"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_roadside_junk"}', 'phase3-build', 1783123885, 'map_world', NULL, 4, -3, 0, 'SS', '#111111', '#1fb5aa', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_tarseep', 'Tar Seep', 'A slow black seep wells up through the ash here, patient and bottomless. Things that wander in do not wander out; the surface just closes over with an oily wink.', 'medium', 0, 0, 1, '["A bubble the size of a skull rises through the tar and pops, releasing a sigh.", "Something white and half-dissolved surfaces in the seep, then is drawn back under."]', '{"east": "zone_waste_molten", "west": "zone_waste_overburden", "north": "zone_waste_greymile", "south": "zone_waste_dross"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase4-build', 1783123885, 'map_world', NULL, -6, -3, 0, 'TS', '#eeeeee', '#7c6a4a', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_powerplantnew', 'Coolant Flats', 'A flat apron of stained concrete where the ground still runs warm underfoot, waste heat bleeding up from whatever''s left alive below. Fat coolant mains arc overhead on their gantries, weeping rust-orange at every joint, and the air tastes of hot metal and pond scum. The Coldwater Power Plant looms at the apron''s edge behind chain-link and faded RADIATION placards, a turbine somewhere inside grinding on out of sheer habit. Steam ghosts up from a grate and refuses to disperse.', 'safe', 0, 0, 1, '["The hum changes pitch for a moment, then settles back.", "Somewhere inside, something massive and patient keeps turning."]', '{"in": "zone_coldwater_turbine_hall", "east": "zone_ext_1782953094650", "west": "zone_up_aid", "north": "zone_civ_steps", "south": "zone_city_east"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": null, "building_type": null, "world_exit_zone": null, "scavenging_table_id": "scav_roadside_junk"}', NULL, 1783123885, 'map_world', NULL, -1, -2, 0, 'CP', '#eeeeee', '#347b49', 'city', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_sinter', 'The Sinter', 'The sinter beds beside the Slagworks Gate, where fines were once fused into clinker in long shallow trays now cracked and cold. Salvagers work the trays for the metal the process left behind, and the Gate watches them do it.', 'low', 0, 1, 0, '["A sinter tray cracks a little wider under its own dead weight.", "A Slagworks hand leans in the Gate''s shadow and watches you work the trays, and says nothing."]', '{"east": "zone_waste_rustmarsh", "west": "zone_slag_catalyst", "north": "zone_waste_blight", "south": "zone_slag_gate"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_industrial_salvage"}', 'phase11-build', 1783123886, 'map_world', NULL, -8, -1, 0, 'SI', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_reek', 'The Reek', 'The reek is exactly that — the low ground below the Slagworks where every runoff and effluent the works produces finally collects and stands and stinks. The Effluent Sump drains here. You smell the Reek long before you reach it.', 'low', 0, 1, 0, '["The Reek shifts its skin of scum and lets up a bubble that pops with a sigh.", "Runoff trickles in from the Sump above and the standing filth accepts it without a ripple."]', '{"east": "zone_waste_ashenverge", "west": "zone_slag_sump", "north": "zone_slag_gate", "south": "zone_waste_drossworks"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_industrial_salvage"}', 'phase11-build', 1783123886, 'map_world', NULL, -8, 1, 0, 'RE', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_coldslag', 'Cold Slag', 'A field of slag gone properly cold at last, the western frontier of walkable ground below the neck. Past it the wastes give way to the Redline''s lower reach, and only the desperate and the changed go on.', 'low', 0, 0, 0, '["Cold slag crunches underfoot, dead and grey and finally, entirely done being hot.", "At the field''s western edge the ground takes on a wrong sheen, and you feel watched from it."]', '{"east": "zone_slag_drums", "north": "zone_slag_reclaimer", "south": "zone_waste_culvert"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -11, 1, 0, 'CS', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_slagbar', 'Slag Bar', 'A long bar of fused slag thrown up like a levee across the deep wastes, high enough to climb and walk, a road for those who know it. From its spine you can see the whole grey sweep of the frontier, which is not a comfort.', 'low', 0, 0, 0, '["From the slag bar''s spine the wastes stretch grey and featureless to every horizon.", "A figure walks the far end of the slag bar, silhouetted, and is gone behind the ridge."]', '{"east": "zone_waste_ashencut", "west": "zone_waste_culvert", "north": "zone_slag_drums", "south": "zone_waste_gantry"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -10, 2, 0, 'SB', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_rimeflat', 'Rime Flat', 'The southwestern corner of the walkable world, a flat where a pale chemical rime crusts the ground like frost that never melts. It marks the edge; beyond it the map, and the wastes, and the will to go on, all give out.', 'low', 0, 0, 0, '["The chemical rime crunches like frost and leaves a pale burn where it touches skin.", "At the flat''s edge the ground simply stops mattering, grey into grey into nothing."]', '{"east": "zone_waste_gantry", "north": "zone_waste_culvert"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -11, 3, 0, 'RF', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_dustreach', 'Dust Reach', 'The last reach before the built wastes give out entirely, a plain of fine grey dust that the wind lifts into standing walls and marches across the frontier. Crossing it, you are always inside weather, and the weather is made of this place.', 'low', 0, 0, 0, '["A wall of grey dust marches across the reach and swallows the horizon whole.", "The dust settles for a moment and shows a trail of prints leading west, and no one on it."]', '{"east": "zone_waste_hopper", "west": "zone_waste_gantry", "north": "zone_waste_ashencut"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -9, 3, 0, 'DR', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_red_screaminglot', 'The Screaming Lot', 'A lot where a trick of the ruined structures turns the wind into a sound exactly like a great many people screaming, all the time, forever. Newcomers run toward it to help. There is no one to help. There is only the lot, and the wind, and what the sound draws in.', 'lethal', 0, 4, 0, '["The Screaming Lot rises to a crescendo of voices that are only ever the wind, you are almost sure.", "For one moment the screaming stops dead, which is far, far worse, and then it starts again."]', '{"east": "zone_red_cullrow", "west": "zone_red_feralyard", "north": "zone_red_radsink", "south": "zone_red_rictusalley"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_irradiated_salvage"}', 'phase12-build', 1783123886, 'map_world', NULL, -10, -5, 0, 'SL', '#eeeeee', '#450d0d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_culvert', 'The Culvert', 'A great cracked concrete culvert that once carried the works'' floodwater away and now carries nothing but wind and the occasional person with nowhere better to shelter. Its mouth gapes westward, into the dark under the wastes.', 'low', 0, 0, 0, '["Wind moans down the length of the culvert and dies somewhere in its western dark.", "A shape shelters deep in the culvert''s mouth and pulls back further as you approach."]', '{"east": "zone_waste_slagbar", "north": "zone_waste_coldslag", "south": "zone_waste_rimeflat"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -11, 2, 0, 'CV', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_ashencut', 'Ashen Cut', 'A cutting sliced through the spoil where a rail line once ran out to the Slagworks and was torn up for scrap decades back. The cut is sheltered from the wind, which is why the things that shelter here resent visitors.', 'low', 0, 0, 0, '["The ashen cut holds still air and the ghost of creosote from a railway long gone.", "Bootprints and other prints share the floor of the cut; some of the others are not shaped right."]', '{"east": "zone_waste_drossworks", "west": "zone_waste_slagbar", "north": "zone_slag_sump", "south": "zone_waste_dustreach"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -9, 2, 0, 'AC', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
INSERT INTO public.zones (id, name, description, danger_rating, pvp_enabled, radiation_level, is_safe_zone, ambient_events, exits, flags, created_by, updated_at, map_id, parent_zone, grid_x, grid_y, grid_z, marker, color, bg_color, ambient_theme, stains, audio_theme_id) VALUES ('zone_waste_gantry', 'The Gantry', 'The skeleton of a loading gantry that once straddled the torn-up rail, now a rusted arch over nothing, straddling the deep wastes like a monument to the work that killed this place. Scavengers use its height to spot trouble coming.', 'low', 0, 0, 0, '["The gantry''s rusted arch groans in the wind and drops a rain of scale.", "A lookout perched high on the gantry whistles a warning down and points, west."]', '{"east": "zone_waste_dustreach", "west": "zone_waste_rimeflat", "north": "zone_waste_slagbar"}', '{"is_building": false, "is_interior": false, "is_apartment": false, "building_name": "", "building_type": null, "scavenging_table_id": "scav_west_wastes"}', 'phase11-build', 1783123886, 'map_world', NULL, -10, 3, 0, 'GA', '#eeeeee', '#816e4d', 'outdoors', '{}', NULL);
