INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_medkit', 'trauma kit', 'Real medical supplies. Increasingly rare, increasingly suspicious about why someone is selling them.', 'consumable', 'medicine', 1200, 55, 1, 0, 0, '{"hp_over_time": {"amount": 50, "duration_seconds": 300}}', '{}', '{}', '{}', '{"stackable": true, "consumable": true, "description": "Real medical supplies. Increasingly rare, increasingly suspicious about why someone is selling them.", "heal_over_time": {"amount": 50, "duration_seconds": 300}}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_thermex_top', 'thermex underlayer top', NULL, 'clothing', 'torso', 300, 220, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "layer": "outerwear", "bulkiness": 1, "insulation": 2, "description": "A skin-tight base layer of thermex mesh that traps a thin cushion of warm air against the body. Cheap, reactive, and worn under everything by anyone who''s spent one night outdoors and learned the lesson."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_nyra_hair_fiberoptic', 'asymmetrical fiber-optic hair', NULL, 'clothing', NULL, 1000, 900, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "head", "layer": "outerwear", "bulkiness": 1, "insulation": 0, "description": "A sharp asymmetrical haircut, dark at the roots fading into synthetic violet ends. Threaded through sections are ultra-thin fiber-optic strands that pulse faintly with shifting ambient signals, giving it a low, electronic shimmer in neon light."}');
