INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cobalt_scarf', 'cobalt alpaca scarf', NULL, 'clothing', NULL, 200, 180, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "accessory", "armor": 1, "gets_wet": true, "bulkiness": 2, "insulation": 3, "description": "A long cobalt-blue alpaca scarf that drapes almost to the knees, its thick, soft weave standing out against darker outfits. The luxurious fibers soften an otherwise hardened look, and the frayed ends sway with every step."}');
