INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_nyra_jacket_synthleather', 'fitted synth-leather jacket', NULL, 'clothing', NULL, 1400, 1200, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 2, "layer": "outerwear", "bulkiness": 3, "insulation": 5, "description": "A close-cut black synthetic leather jacket designed for mobility and protection. Lightweight but durable, with reinforced seams and a matte finish that absorbs light rather than reflecting it."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_nyra_gloves_interface', 'split-finger interface gloves', NULL, 'clothing', NULL, 140, 620, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "hands", "armor": 1, "layer": "outerwear", "bulkiness": 1, "insulation": 1, "description": "Black tactical gloves with reinforced palms and exposed fingertips. Subdermal interface contacts along the knuckles allow direct device interaction without removing them."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_onyx_malachite_bracelets', 'onyx and malachite bracelets', NULL, 'clothing', NULL, 180, 220, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "accessory", "armor": 0, "bulkiness": 1, "insulation": 0, "description": "Several bracelets of polished black onyx and richly banded malachite beads wrapped around one wrist. The deep black stones contrast sharply with the swirling emerald-green patterns of the malachite, creating a rugged, eye-catching combination that blends natural materials with a futuristic aesthetic."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_nyra_top_compression', 'compression interface top', NULL, 'clothing', NULL, 280, 380, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "layer": "outerwear", "bulkiness": 1, "insulation": 1.5, "description": "A tight, matte compression top woven with micro-cooling filaments. It regulates body temperature and subtly supports muscular movement, almost like second skin. Minimal seams, built for performance."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_blacktar', 'blacktar', 'Heavy tar opioid, cut with whatever was nearby. The deepest nod there is.', 'consumable', 'drug', 20, 210, 1, 0, 0, '{}', '{}', '{}', '{}', '{"drug": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_nyra_iris_implant', 'augmented iris interface ring', NULL, 'implant', NULL, 0, 3500, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "head", "layer": "outerwear", "bulkiness": 0, "insulation": 0, "description": "A subtle cybernetic enhancement embedded in one eye. A thin golden ring floats within the iris, dynamically shifting as it tracks data — a quiet HUD embedded directly into vision."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_nyra_harness_utility', 'modular utility harness', NULL, 'clothing', NULL, 580, 1600, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "accessory", "bulkiness": 2, "insulation": 0, "description": "A sleek shoulder-and-chest harness with configurable attachment points for compact tools and data modules. Clean, expensive-looking hardware designed for quick swaps and silent operation."}');
