INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cat_boxers', 'cat-print boxer briefs', NULL, 'clothing', NULL, 120, 25, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0.5, "description": "Black boxer briefs patterned with playful cats in contrasting colors, hidden beneath outer layers except for the occasional glimpse of the waistband."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_finger_rings_set', 'a set of elaborate rings', NULL, 'clothing', NULL, 120, 350, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "hands", "armor": 1, "layer": "outerwear", "bulkiness": 0, "insulation": 0, "description": "Every finger bears a distinctive ring, forming a complete collection of symbolic jewelry: a colorful candy skull ring with intricate enamel detailing; a Tree of Life ring with engraved roots and branches; a bold eagle ring with outstretched wings; a wolf ring featuring a snarling profile; a regal lion-head ring with a sculpted mane; and a black-and-gold signet ring displaying a winged skull emblem, its gold design standing out sharply against the dark face."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cyber_track_pants', 'cyber track pants', NULL, 'clothing', NULL, 120, 25, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 1.5, "description": "Black athletic track pants with bold vertical Japanese lettering running down one leg in crisp white, accented by subtle reflective piping. The relaxed fit and tapered ankles give them a sleek cyberpunk streetwear silhouette."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_watch_cap', 'heat-wick watch cap', NULL, 'clothing', 'head', 150, 90, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "head", "layer": "outerwear", "bulkiness": 1, "insulation": 2, "description": "A snug knit cap threaded with heat-wick filament that pulls warmth up from your collar and pins it to your scalp — where, the packaging insists, forty percent of it was getting away."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_thermex_leggings', 'thermex underlayer leggings', NULL, 'clothing', 'legs', 300, 200, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "layer": "outerwear", "bulkiness": 1, "insulation": 2, "description": "Matching thermex base-layer leggings. Seamless, static-clingy, and frequently the only thing standing between your legs and a hypothermic diagnosis."}');
