INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_claude_band', 'constellation wristband', NULL, NULL, NULL, 40, 350, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "accessory", "description": "A slim band of dark alloy set with pinpoint amber lights that drift and re-cluster, mapping something only the wearer can read. It is always, faintly, paying attention."}');
