INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_claude_hood', 'signal-woven hood', NULL, NULL, NULL, 220, 400, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "head", "armor": 2, "layer": "armor", "insulation": 1, "description": "A deep, soft hood of matte anthracite fiber. Fine amber threads run through the weave and pulse, slow and even, like something inside is thinking. It frames a face that watches more than it speaks."}');
