INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_precursor_stim', 'stimulant precursor', 'A jar of volatile crystalline precursor. Cook feedstock for uppers.', 'chemical', 'reagent', 30, 70, 1, 0, 0, '{}', '{}', '{}', '{}', '{"reagent": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_jock_leather', 'studded leather jockstrap', NULL, NULL, NULL, 180, 120, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0, "description": "Black leather, chrome studs, straps arranged with more engineering confidence than modesty. Creaks when you move. Announces intent well before conversation does."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_claude_coat', 'long analyst''s coat', NULL, NULL, NULL, 1600, 1200, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 4, "layer": "armor", "insulation": 2, "stat_bonus": {"stat_cool": 2}, "description": "A floor-skimming coat in charcoal so dark it reads as absence. The lining is a quiet lattice of conductive thread that catches neon and lets it go. Cut for someone who arrives having already understood the room."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_claude_gloves', 'conductive-thread gloves', NULL, NULL, NULL, 120, 300, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "hands", "armor": 1, "layer": "armor", "description": "Thin graphite gloves with fingertip contacts of dull gold. They hum faintly against anything with a current in it."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_claude_trousers', 'graphite field trousers', NULL, NULL, NULL, 700, 500, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 3, "layer": "armor", "insulation": 1, "description": "Reinforced graphite-grey trousers, seams taped, knees quietly armored. Built to move without asking permission."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_claude_boots', 'quiet-soled boots', NULL, NULL, NULL, 900, 500, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "feet", "armor": 2, "layer": "armor", "description": "Low black boots with dampened soles. They make almost no sound. People notice you are there only once you have decided they should."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_ragplate_coat', 'ragplate coat', NULL, 'armor', NULL, 2500, 55, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "layer": "armor", "bulkiness": 3, "armor_soak": {"edged": 1, "kinetic": 1}, "insulation": 3, "description": "A heavy longcoat of quilted wadding with scavenged plate stitched into the panels over the ribs and spine. It hangs like it''s carrying someone else''s bad week, and mostly it is. Blunt hits sink into the padding instead of your bones."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_briefs_sport_wick', 'moisture-wick sport briefs', NULL, NULL, NULL, 90, 30, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0.5, "description": "Seamless synthetic briefs that wick sweat away and, per the tag, \"keep you dry through the apocalypse.\" They only ever tested the first word of that claim."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_furn_busted_sofa', 'busted sofa', 'Cracked pleather in a brown that was probably beige originally. There is a spring that will find you.', 'furniture', NULL, 20000, 120, 0, 0, 0, '{}', '{}', '{}', '{"interactions": ["sit", "lie"]}', '{"description": "Cracked pleather in a brown that was probably beige originally. There is a spring that will find you."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_copper_bundle', 'copper wiring bundle', 'A fat coil of copper wiring, stripped from a junction box and still reeking of scorched insulation.', 'misc', 'metal', 500, 8, 1, 0, 0, '{}', '{}', '{}', '{}', '{"metal": true, "description": "A fat coil of copper wiring, stripped from a junction box and still reeking of scorched insulation."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_steel_plate', 'steel plate', 'A hand-span of sheared ship steel. Heavy, honest, and worth something to anyone who welds.', 'misc', 'metal', 1200, 5, 1, 0, 0, '{}', '{}', '{}', '{}', '{"metal": true, "description": "A hand-span of sheared ship steel. Heavy, honest, and worth something to anyone who welds."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_ball_bearings', 'handful of ball bearings', 'Loose steel bearings, still oily. Drop them and they roll for the horizon.', 'misc', 'metal', 300, 4, 1, 0, 0, '{}', '{}', '{}', '{}', '{"metal": true, "description": "Loose steel bearings, still oily. Drop them and they roll for the horizon."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_hydraulic_hose', 'hydraulic hose', 'A length of armored hose weeping amber fluid from a cracked coupling.', 'misc', NULL, 400, 6, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A length of armored hose weeping amber fluid from a cracked coupling."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_pressure_gauge', 'pressure gauge', 'A brass gauge, its needle jammed hard in the red. Whatever it measured, it lost.', 'misc', NULL, 250, 9, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A brass gauge, its needle jammed hard in the red. Whatever it measured, it lost."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_catalyst_pellets', 'sack of catalyst pellets', 'A mesh sack of spent catalyst pellets, iridescent and faintly warm. Chemists pay; your lungs charge interest.', 'misc', NULL, 700, 12, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A mesh sack of spent catalyst pellets, iridescent and faintly warm. Chemists pay; your lungs charge interest."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_industrial_solvent', 'jug of solvent', 'A sealed jug of industrial solvent that eats grease, paint, and — given time — the jug.', 'misc', NULL, 900, 14, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A sealed jug of industrial solvent that eats grease, paint, and — given time — the jug."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_bearing_grease', 'tub of bearing grease', 'A tub of black grease gone half to tar. Still slick enough to matter to a machine.', 'misc', NULL, 400, 3, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A tub of black grease gone half to tar. Still slick enough to matter to a machine."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_valve_assembly', 'valve assembly', 'A heavy brass valve, seized shut. Reconditioned it is worth real credits; as-is, a paperweight.', 'misc', 'metal', 1500, 16, 1, 0, 0, '{}', '{}', '{}', '{}', '{"metal": true, "description": "A heavy brass valve, seized shut. Reconditioned it is worth real credits; as-is, a paperweight."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_control_relay', 'industrial relay', 'A chunky control relay in a scorched housing. The contacts are pitted, but the copper is good.', 'misc', NULL, 350, 18, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A chunky control relay in a scorched housing. The contacts are pitted, but the copper is good."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_flashlight', 'flashlight', NULL, NULL, NULL, 400, 45, 0, 0, 0, '{}', '{}', '{}', '{}', '{"misc": true, "unique": true, "flashlight": true, "description": "A rugged rubber-armoured handheld flashlight. Throws a hard white cone of light. Runs on a single high-density cell — LIGHT it to switch on, UNLIGHT to save the charge, RELOAD it with a fresh battery when it dies."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_battery', 'battery', NULL, NULL, NULL, 80, 10, 0, 0, 0, '{}', '{}', '{}', '{}', '{"misc": true, "battery": true, "description": "A stubby high-density power cell, warm to the touch. Snap it into a flashlight to bring it back to a full charge."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cassette_neighbors_from_14b_episode_12_the_loud_pipe_imported', 'Cassette: Neighbors from 14B - Episode 12: The Loud Pipe (imported)', 'A media cassette labeled "Neighbors from 14B - Episode 12: The Loud Pipe (imported)".', 'media', 'cassette', 100, 0, 0, 1, 0, '{}', '{}', '{}', '{}', '{"broadcast_id": "bc_1783047062765", "media_cassette": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_briefs_novelty_spareme', 'spare me briefs', NULL, NULL, NULL, 110, 12, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0.5, "description": "Grey cotton briefs with SPARE ME printed across the waistband in a font that was funny to exactly one person: the person who ordered a warehouse of them. The elastic has surrendered."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_thong_lace_sheer', 'sheer lace thong', NULL, NULL, NULL, 40, 45, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0, "description": "A whisper of black lace and less-than-that everywhere else. Structurally it is mostly implication. Cold, impractical, and entirely aware of both."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_breacher_shotgun', 'breacher shotgun', 'A stubby, sawn-down pump gun. Loud enough to end an argument and start three more.', 'weapon', 'firearm', 3200, 420, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "weapon_hand", "__own": {"damage": {"max": 34, "min": 18}, "damage_type": "kinetic", "description": "A stubby, sawn-down pump gun. Loud enough to end an argument and start three more."}, "damage": {"max": 34, "min": 18}, "weapon": true, "__super": ["weapon_firearms"], "damage_type": "kinetic", "description": "A stubby, sawn-down pump gun. Loud enough to end an argument and start three more.", "weapon_skill": "firearms"}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_rattlecan_smg', 'rattlecan SMG', 'A machine pistol held together with spray-paint and spite. Empties a mag before it decides to jam.', 'weapon', 'firearm', 2600, 700, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "weapon_hand", "__own": {"damage": {"max": 20, "min": 10}, "damage_type": "kinetic", "description": "A machine pistol held together with spray-paint and spite. Empties a mag before it decides to jam."}, "damage": {"max": 20, "min": 10}, "weapon": true, "__super": ["weapon_firearms"], "damage_type": "kinetic", "description": "A machine pistol held together with spray-paint and spite. Empties a mag before it decides to jam.", "weapon_skill": "firearms"}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_underpants_lucky', 'lucky underpants', NULL, NULL, NULL, 80, 3, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0.5, "description": "Once white, now a colour with no name. Threadbare to the point of translucency, held together by belief and one heroic seam. The owner insists they have never been caught wearing anything else on a good day."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_longjohns_thermal', 'thermal long johns', NULL, NULL, NULL, 350, 70, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 2, "description": "Waffle-knit thermal underwear in a defeated shade of oatmeal. Deeply unsexy and quietly the best decision you will make all winter. The trapdoor flap actually works."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_panties_crotchless_mesh', 'crotchless mesh panties', NULL, NULL, NULL, 35, 55, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0, "description": "Fishnet mesh cut with a philosophy that the most important part of underwear is optional. Provides zero warmth, zero coverage, and one very specific message."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_boxers_biohazard', 'biohazard boxers', NULL, NULL, NULL, 110, 18, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0.5, "description": "Loose cotton boxers screen-printed edge-to-edge with the biohazard trefoil. A warning, a joke, or laundry-day honesty — the wearer never clarifies."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_bralette_lace_sheer', 'sheer lace bralette', NULL, NULL, NULL, 60, 55, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0, "description": "Delicate floral lace with no wire, no padding, and no interest in hiding anything. Soft as a rumour and about as supportive."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_sportsbra_compression', 'compression sports bra', NULL, NULL, NULL, 110, 40, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0, "description": "Industrial-grade elastic that locks everything down for a fight or a run. Getting it on is a workout. Getting it off is a hostage negotiation."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_bra_leather_harness', 'leather harness bra', NULL, NULL, NULL, 200, 150, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0, "description": "Straps of black leather and steel O-rings arranged in a cage that frames far more than it covers. Buckles at the back. Not remotely a bra in any function except where it sits."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_undershirt_ribbed', 'ribbed cotton undershirt', NULL, NULL, NULL, 140, 8, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0.5, "description": "A plain ribbed tank in yellowing white. The uniform of men who fix boilers and lose arguments in vests. Cheap, honest, faintly damp-smelling."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_pasties_tassel', 'tassel pasties', NULL, NULL, NULL, 15, 25, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0, "description": "A pair of sequinned nipple covers with little silver tassels that spin if you commit to it. Coverage measured in centimetres. Confidence sold separately."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_binder_chest', 'chest binder', NULL, NULL, NULL, 160, 60, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "underwear", "bulkiness": 1, "insulation": 0.5, "description": "A flat compression top in medical grey that smooths the chest to a straight line. Practical, comfortable enough, and worth every credit to whoever needs it."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_tee_singularity', 'I survived the Singularity tee', NULL, NULL, NULL, 300, 20, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 1, "description": "A faded tourist tee reading I SURVIVED THE SINGULARITY AND ALL I GOT WAS THIS LOUSY CONSCIOUSNESS. Statistically, most people who bought one did not, in fact, survive."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_hoodie_grey', 'grey hoodie', NULL, NULL, NULL, 650, 45, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 2, "insulation": 3, "description": "A heavyweight grey hoodie worn soft, cuffs chewed, one drawstring long gone. The uniform of anyone who wants to be left alone and mostly is. Smells faintly of somebody else."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_croptop_fishnet', 'fishnet crop top', NULL, NULL, NULL, 120, 50, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 0, "description": "A cropped net shirt that stops well above the navel and hides absolutely nothing beneath it — that is the point. Layer it over something, or don''t, and make it everyone''s problem."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_tee_mascot', 'SynthCorp mascot tee', NULL, NULL, NULL, 300, 25, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 1, "description": "A knock-off tee with SynthCorp''s bankrupt cartoon mascot — a grinning battery named Sparky — waving above the slogan POWERING TOMORROW. Tomorrow declined. Worn ironically by everyone, sincerely by no one."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_shirt_flannel', 'flannel work shirt', NULL, NULL, NULL, 500, 35, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 2, "insulation": 2, "description": "A red-and-black check flannel gone soft and pilled at the elbows. Two buttons mismatched, one pocket torn half-off. Warm, forgiving, and quietly competent."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_halter_backless', 'backless halter top', NULL, NULL, NULL, 140, 60, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 0.5, "description": "A silky halter that ties at the neck and leaves the entire back bare to the waist. Turns heads on the way in and holds them on the way out."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_sweater_ugly', 'aggressively festive sweater', NULL, NULL, NULL, 700, 40, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 2, "insulation": 3, "description": "A knitted crime scene of reindeer, tinsel, and a battery-powered nose that no longer blinks. Nobody knows which holiday. Everybody knows it is too warm and too much."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_jacket_denim', 'battered denim jacket', NULL, NULL, NULL, 1200, 90, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 2, "insulation": 3, "description": "Faded blue denim gone pale at the seams, collar frayed, a ghost patch where some band''s logo used to be. Heavy, warm, and it has clearly outlived at least one owner."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_tote_canvas', 'THANKS canvas tote', NULL, NULL, NULL, 200, 15, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "accessory", "armor": 0, "bulkiness": 1, "description": "A limp canvas tote stamped THANKS FOR SHOPPING beneath the logo of a chain that no longer exists. Carries everything, keeps out nothing, refuses to die."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_blouse_sheer_wrap', 'sheer wrap blouse', NULL, NULL, NULL, 120, 110, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 0, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 0.5, "description": "A gauzy wrap blouse that knots at the hip and drapes like smoke. Opaque enough for polite company, sheer enough that the company stops being polite."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_tee_offbrand_security', 'SEKURITY tee', NULL, NULL, NULL, 300, 22, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "torso", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 1, "description": "A black tee with SEKURITY across the back in reflective block caps, misspelled with the confidence of someone who was never going to be questioned about it. Works about 60% of the time."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_jeans_relaxed', 'relaxed jeans', NULL, NULL, NULL, 650, 40, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 2, "insulation": 1.5, "description": "Honest blue denim, broken in at the knee, one belt loop gone. Not fashionable, not trying to be. They will outlast the building you bought them in."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_shorts_cargo', 'over-pocketed cargo shorts', NULL, NULL, NULL, 450, 30, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 1, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 0.5, "description": "Khaki cargo shorts with fourteen pockets, three of which zip, none of which you will remember using. A statement, and the statement is \"I have given up.\" Endlessly practical."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_leggings_latex', 'latex leggings', NULL, NULL, NULL, 400, 180, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 1, "description": "Poured-on black latex that squeaks when you walk and shines under any light unkind enough to find you. Getting into them requires talcum powder and a plan. Worth it."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_sweatpants_grey', 'grey sweatpants', NULL, NULL, NULL, 500, 30, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 2, "description": "Soft heather-grey sweatpants with a blown-out knee and a waistband stretched to a permanent shrug. The trousers of a person no longer performing for anyone."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_shorts_micro', 'micro shorts', NULL, NULL, NULL, 100, 45, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 0.5, "description": "Denim shorts cut so high the pockets hang lower than the hem, pale threads fringing the edge. Technically legwear. Barely a technicality."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_trousers_clown', 'patched motley trousers', NULL, NULL, NULL, 550, 35, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "legs", "armor": 0, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 1.5, "description": "Baggy trousers stitched from a dozen clashing fabrics in a riot of dead patterns, gathered at the ankle. Somewhere between salvage-chic and a birthday party nobody survived."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_sneakers_canvas', 'worn canvas sneakers', NULL, NULL, NULL, 600, 25, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "feet", "armor": 1, "layer": "outerwear", "bulkiness": 1, "insulation": 0.5, "description": "Off-white canvas gone grey, one lace knotted where it snapped, a hole starting at the little toe. Comfortable in the way only a shoe that has given up on you can be."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_slippers_monster', 'fuzzy monster slippers', NULL, NULL, NULL, 400, 20, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "feet", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 1, "description": "Enormous plush slippers shaped like googly-eyed swamp beasts, complete with felt teeth and a menacing waddle. Warm, ridiculous, and structurally useless outdoors."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_boots_thigh_heel', 'thigh-high heeled boots', NULL, NULL, NULL, 1100, 220, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "feet", "armor": 1, "layer": "outerwear", "bulkiness": 2, "insulation": 1, "description": "Glossy black boots that climb past the knee on a heel sharpened to a threat. Loud on concrete, murder on ankles, unanswerable in an argument."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_sandals_strap', 'cracked strap sandals', NULL, NULL, NULL, 300, 12, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "feet", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 0, "description": "Flat rubber sandals with a strap repaired in wire and one sole worn to a slick. They flap when you walk and offer your toes to the world and its broken glass."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cap_trucker_slogan', 'HANG IN THERE trucker cap', NULL, NULL, NULL, 120, 18, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "head", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 0.5, "description": "A foam-front mesh-back cap reading HANG IN THERE above a faded kitten clinging to a branch. Sun-bleached, sweat-ringed, unbearably sincere. It is doing its best. So is the kitten."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_bucket_hat', 'soft bucket hat', NULL, NULL, NULL, 150, 30, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "head", "armor": 0, "layer": "outerwear", "gets_wet": true, "bulkiness": 1, "insulation": 1, "description": "A shapeless canvas bucket hat that keeps rain off your neck and hides whatever your hair is doing. Anonymous, useful, and vaguely suspicious in exactly the right way."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_veil_lace', 'black lace veil', NULL, NULL, NULL, 60, 70, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "head", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 0, "description": "A fine black funeral veil that pins to the hair and falls to the collarbone, patterning shadow across the face beneath. Grief and glamour, indistinguishable at this range."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_gloves_fingerless', 'fingerless knit gloves', NULL, NULL, NULL, 100, 20, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "hands", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 1, "description": "Grey wool gloves with the fingertips cut away, the raw edges unravelling politely. Keeps the palms warm, leaves the fingers free to pick, type, or steal."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_gloves_lace_opera', 'lace opera gloves', NULL, NULL, NULL, 80, 65, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "hands", "armor": 0, "layer": "outerwear", "bulkiness": 1, "insulation": 0.5, "description": "Sheer black lace gloves that run past the elbow, fastened with a single silk button at the wrist. Wildly impractical, devastatingly deliberate."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_collar_leather', 'buckled leather collar', NULL, NULL, NULL, 90, 80, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "accessory", "armor": 0, "bulkiness": 1, "description": "A wide black leather collar with a heavy steel buckle and a single loose ring at the throat, worn smooth where a finger keeps hooking it. Says a great deal without a word."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_fannypack', 'bulging fanny pack', NULL, NULL, NULL, 250, 22, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "accessory", "armor": 0, "bulkiness": 1, "description": "A nylon waist pouch in a colour best described as \"1994,\" zipper straining over contents you will absolutely be judged for. Deeply uncool. Deeply convenient."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cassette_doomcast_seven_day_outlook', 'Cassette: DOOMCAST — Seven-Day Outlook', 'A media cassette labeled "DOOMCAST — Seven-Day Outlook".', 'media', 'cassette', 100, 0, 0, 1, 0, '{}', '{}', '{}', '{}', '{"broadcast_id": "bc_1783060890362", "media_cassette": true}');
