INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_hack_deck', 'Nexus IX Infiltrator', 'A Nexis Systems ''IX'' Breacher — mass-produced grey-market intrusion hardware, the housing stamped with a serial number someone filed half off. Clipped leads, a cracked case, a status LED that never quite goes dark.', 'misc', NULL, 800, 450, 0, 0, 0, '{}', '{}', '{}', '{}', '{"misc": true, "description": "A Nexis Systems ''IX'' Breacher — mass-produced grey-market intrusion hardware, the housing stamped with a serial number someone filed half off. Clipped leads, a cracked case, a status LED that never quite goes dark.", "hack_device": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_joint', 'joint', 'A hand-rolled joint, a little crooked, twisted off at the end. Smells like a greenhouse and bad decisions.', 'consumable', 'drug', 5, 20, 1, 0, 0, '{}', '{}', '{}', '{}', '{"drug": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cigarettes', 'cigarettes', 'A soft pack of cheap cigarettes. Each one shaves a little off your lungs and hands it to your image.', 'consumable', 'drug', 20, 15, 1, 0, 0, '{}', '{}', '{}', '{}', '{"drug": true}');
