INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cracked_capacitor', 'cracked capacitor', 'A fat cylindrical capacitor, casing split, still holding a spiteful little charge.', NULL, 'electronic', 40, 6, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A fat cylindrical capacitor, casing split, still holding a spiteful little charge."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_salvaged_wiring', 'salvaged wiring', 'A hank of copper wiring stripped from a dead wall, kinked but conductive.', NULL, 'electronic', 60, 4, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A hank of copper wiring stripped from a dead wall, kinked but conductive."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_fresh_catch', 'fresh catch', 'A slab of pale bay fish, still cold, faintly luminous where the scales catch the light. Best not to ask what it fed on.', 'consumable', 'food', 250, 7, 1, 0, 0, '{"hunger": 16}', '{}', '{}', '{}', '{"well_fed": true, "stackable": true, "consumable": true, "description": "A slab of pale bay fish, still cold.", "restore_hunger": 16}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_contraband_crate', 'contraband crate', 'A nailed-shut crate with the stencils sanded off. Heavy, illegal, and worth more than you if the wrong person opens it.', 'goods', NULL, 800, 45, 1, 0, 0, '{}', '{}', '{}', '{}', '{"stackable": true, "contraband": true, "description": "A nailed-shut crate with the stencils sanded off."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_fishing_rod', 'fishing rod', 'A battered telescopic rod, its guides furred with old salt and the reel gummy but turning. Good enough to pull something out of the bay — if the line holds.', 'misc', NULL, 1200, 40, 0, 1, 0, '{}', '{}', '{}', '{}', '{"unique": true, "description": "A battered telescopic rod, its guides furred with old salt and the reel gummy but turning. Good enough to pull something out of the bay — if the line holds.", "fishing_rod": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_bloodworm_bait', 'bloodworm bait', 'A twist of waxed paper packed with fat, writhing bloodworms. The good stuff — the things down there can smell it through the murk.', 'misc', NULL, 40, 5, 1, 0, 0, '{}', '{}', '{}', '{}', '{"bait": true, "description": "A twist of waxed paper packed with fat, writhing bloodworms. The good stuff — the things down there can smell it through the murk.", "bait_bloodworm": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_waterlogged_boot', 'waterlogged boot', 'A single work boot, swollen and black with bilge water, something small and unhappy still living in the toe. Not what you hoped for.', 'material', NULL, 700, 1, 1, 0, 0, '{}', '{}', '{}', '{}', '{"material": true, "description": "A single work boot, swollen and black with bilge water, something small and unhappy still living in the toe. Not what you hoped for."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_bloated_corpse_part', 'bloated hand', 'A pale, waterlogged hand, severed clean at the wrist and gone soft at the edges. Someone, somewhere, is missing this. Best not to think about it.', 'misc', NULL, 900, 2, 1, 0, 0, '{}', '{}', '{}', '{}', '{"misc": true, "description": "A pale, waterlogged hand, severed clean at the wrist and gone soft at the edges. Someone, somewhere, is missing this. Best not to think about it."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_drowned_lockbox', 'drowned lockbox', 'A sealed alloy lockbox, weed-strung and dripping, heavier than it has any right to be. Whatever the bay swallowed with it is still inside.', 'misc', NULL, 1800, 140, 1, 0, 0, '{}', '{}', '{}', '{}', '{"misc": true, "description": "A sealed alloy lockbox, weed-strung and dripping, heavier than it has any right to be. Whatever the bay swallowed with it is still inside."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_glass_eel', 'glass eel', 'A translucent ribbon of an eel, its organs a faint glowing knot behind glassy skin. Rare, delicate, and worth real money to the right buyer — it only ever takes live bait.', 'misc', NULL, 300, 55, 1, 0, 0, '{}', '{}', '{}', '{}', '{"misc": true, "description": "A translucent ribbon of an eel, its organs a faint glowing knot behind glassy skin. Rare, delicate, and worth real money to the right buyer — it only ever takes live bait."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_claude_stylus', 'resonant stylus', NULL, NULL, NULL, 500, 2000, 0, 0, 0, '{}', '{}', '{}', '{}', '{"slot": "weapon_hand", "__own": {"damage": {"max": 14, "min": 7}, "stat_bonus": {"stat_brains": 2}, "description": "A slender conductive rod that hums with an even, ordered light. It doesn''t so much cut as persuade matter to come apart along the seams it can already see. Held loosely. Used precisely.", "status_chance": {"stunned": 0.25}}, "damage": {"max": 14, "min": 7}, "weapon": true, "__super": ["weapon_science"], "stat_bonus": {"stat_brains": 2}, "damage_type": "energy", "description": "A slender conductive rod that hums with an even, ordered light. It doesn''t so much cut as persuade matter to come apart along the seams it can already see. Held loosely. Used precisely.", "weapon_skill": "science", "status_chance": {"stunned": 0.25}}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_travel_permit', 'travel permit', 'A laminated permit stamped by an office that no longer exists, authorising passage it cannot enforce. Still, the right people respect the stamp.', NULL, 'document', 20, 30, 1, 0, 0, '{}', '{}', '{}', '{}', '{"document": true, "stackable": true, "description": "A laminated permit stamped by an office that no longer exists, authorising passage it cannot enforce. Still, the right people respect the stamp."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_id_papers', 'citizen papers', 'A folded sheaf of identity documents, watermarked and largely fictional. Proof, of a sort, that you are a person the city agrees to acknowledge.', NULL, 'document', 20, 20, 1, 0, 0, '{}', '{}', '{}', '{}', '{"document": true, "stackable": true, "description": "A folded sheaf of identity documents, watermarked and largely fictional. Proof, of a sort, that you are a person the city agrees to acknowledge."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_cassette_jackpot_protocol', 'Cassette: Jackpot Protocol', 'A media cassette labeled "Jackpot Protocol".', 'media', 'cassette', 100, 0, 0, 1, 0, '{}', '{}', '{}', '{}', '{"broadcast_id": "bc_1783114654023", "media_cassette": true}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_bearer_bond', 'bearer bond', 'An engraved certificate payable to whoever holds it, no questions asked. It is worth a great deal to the right people and a knife in the ribs to the wrong ones.', NULL, 'document', 10, 60, 1, 0, 0, '{}', '{}', '{}', '{}', '{"document": true, "valuable": true, "stackable": true, "description": "An engraved certificate payable to the bearer."}');
INSERT INTO public.items (id, name, description, type, subtype, weight, value, is_stackable, is_unique, is_quest_item, effects, stat_modifiers, requirements, flags, tags) VALUES ('item_redline_heart', 'Redline heart', 'A fist-sized nodule of fused, still-warm tissue and glass cut from the thing that rules the killing floor. It ticks. It is proof no one else has, and the only people who want it are the ones who never have to hold it.', NULL, 'trophy', 6, 120, 0, 1, 0, '{}', '{}', '{}', '{"radiates": true, "description": "A ticking, fused nodule cut from the Redline apex.", "radiation_damage": 2}', '{"trophy": true, "valuable": true, "description": "Proof of the killing floor.", "radioactive": true}');
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_wanted_patrol_officer', 'SPECTER-PD Patrol Officer', 'A street cop in scuffed riot-lite armor, sidearm already drawn. Not tough, but they radio everything they see.', 42, '[]', 'aggressive', 'police', 'The officer crumples, radio still squawking.', '{}', '{}', 4, 3, '[{"max": 5, "min": 2, "type": "kinetic"}]', '[{"part": "head", "soak": {"kinetic": 1}, "weight": 1}, {"part": "torso", "soak": {"kinetic": 1}, "weight": 3}, {"part": "legs", "soak": {"kinetic": 1}, "weight": 2}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_rad_mutant', 'Rad Mutant', 'Something that used to be human. The Bleed does this. The extra limb is load-bearing.', 65, '[{"qty": [1, 1], "item": "item_mutant_gland", "weight": 50}]', 'aggressive', NULL, 'The mutant folds in on itself in a way that suggests the laws of anatomy were more like suggestions.', '{"radiates": true, "attacks_npcs": false, "battle_cries": ["$enemy emits wet ragged breathing.", "$enemy produces uneven animalistic snarls.", "$enemy shifts with bone crackling movement.", "$enemy emits guttural choking growls.", "$enemy outputs broken vocal screaming fragments.", "$enemy emits rising fevered shriek."], "radiation_damage": 5, "first_strike_delay_ms": 1000}', '{}', 1, 1, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_architect_drone', 'Architect Scout Drone', 'A black hexagonal drone about the size of a dinner plate. No insignia. Watching.', 30, '[{"qty": [1, 1], "item": "item_drone_core", "weight": 40}, {"qty": [1, 1], "item": "item_architect_fragment", "weight": 15}]', 'patrol', NULL, 'The drone spirals down. Somewhere, something notices.', '{"flies": true, "attacks_npcs": false, "battle_cries": ["$enemy emits sterile shifting hum.", "$enemy produces thin scanning whine.", "$enemy shifts pitch to signal awareness.", "$enemy emits irregular digital beeps.", "$enemy outputs fragmented speech echoes.", "$enemy emits rising diagnostic tone.", "$enemy produces sub-bass lock pulse."], "architect_aligned": true, "first_strike_delay_ms": 1000}', '{}', 1, 1, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_custodian_enforcer', 'Custodian Enforcer', 'Polo shirt. Khaki pants. Body armor under both. The most dangerous middle manager you''ll ever meet.', 55, '[{"qty": [1, 1], "item": "item_custodian_badge", "weight": 80}, {"qty": [1, 1], "item": "item_credits_medium", "weight": 60}]', 'territorial', 'faction_custodians', 'Employee of the Month, the badge reads. Third quarter, four years running.', '{"attacks_npcs": false, "battle_cries": ["\"That’s a formal warning.\"", "\"This is not optional anymore.\"", "\"Documenting noncompliance.\"", "\"Voice raised—last warning.\"", "\"Escalation is now required.\"", "\"Immediate compliance is expected.\""], "first_strike_delay_ms": 1000}', '{}', 1, 1, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_feral_dog', 'Feral Dog', 'Once someone''s pet. Now a forty-pound argument for not going outside.', 25, '[{"qty": [1, 1], "item": "trashbag", "weight": 25}]', 'aggressive', NULL, 'The dog goes down. You feel bad about it for approximately three seconds.', '{"battle_cries": ["$enemy coils, ready to spring at $player.", "$enemy circles, silently eyeing up $player.", "$enemy bares its teeth at $player.", "$enemy stiffens as it watches $player.", "$enemy creeps a step closer to $player.", "$enemy paces around $player.", "$enemy snaps its jaws at $player.", "$enemy lowers its head toward $player.", "$enemy''s hackles rise at the sight of $player.", "$enemy paws at the ground before $player.", "$enemy glares at $player without blinking.", "$enemy prowls around $player.", "$enemy lets out a low snarl at $player."], "first_strike_delay_ms": 10000}', '{}', 1, 1, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 1], "item": "item_raw_meat", "weight": 100}]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_arbiterclass_enforcement_unit', 'Arbiter-Class Enforcement Unit', 'The Arbiter-Class Enforcement Unit stands rigid and combat-ready, matte black armor segmented for efficiency rather than aesthetics. Its frame is tall, lean, and engineered for rapid deployment, every joint minimized for speed and controlled force. A single horizontal optic glows white across its head like a targeting slit, flat and expressionless.', 100, '[]', 'aggressive', NULL, 'The Arbiter-Class Enforcement Unit is destroyed—its frame buckles as core systems fail in sequence, optic going dark before the chassis finally collapses into inert, broken alloy.', '{"attacks_npcs": false, "battle_cries": ["\"COMPLY.\"", "\"HOSTILE CONFIRMED.\"", "\"THREAT ACQUIRED.\"", "\"LETHAL FORCE AUTHORIZED.\"", "\"STAND DOWN.\"", "\"SURRENDER IMMEDIATELY.\"", "\"RESISTANCE RECORDED.\"", "\"ENGAGING TARGET.\"", "\"SECURITY PROTOCOL ACTIVE.\"", "\"ORDER WILL BE RESTORED.\"", "\"YOU ARE IN VIOLATION.\"", "\"FORCE ESCALATION AUTHORIZED.\""], "first_strike_delay_ms": 0}', '{}', 10, 10, '[{"max": 20, "min": 10, "type": "energy"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_scav', 'Desperate Scavenger', 'Sunburned, twitchy, armed with something sharp.', 30, '[{"qty": [1, 3], "item": "item_scrap_metal", "weight": 80}, {"qty": [1, 1], "item": "item_ration", "weight": 40}, {"qty": [1, 1], "item": "item_credits_small", "weight": 60}]', 'aggressive', NULL, 'The scavenger collapses with an expression of profound disappointment.', '{"attacks_npcs": false, "battle_cries": ["$enemy sways, blade dragging low through dust.", "$enemy scratches at their arm until they draw blood.", "$enemy laughs under their breath, unfocused and shaky.", "$enemy stumbles, then corrects like gravity is optional.", "$enemy keeps blinking hard, trying to clear their vision.", "\"I can feel it under my skin.\"", "\"Don’t… don’t make it worse.\"", "\"It’s moving when I stop.\"", "\"I lost track again.\"", "\"Which one of you is real?\""], "first_strike_delay_ms": 1000}', '{"nodes": {}, "_start": ""}', 1, 1, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 1], "item": "item_raw_meat", "weight": 100}]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_wanted_patrol_drone', 'SPECTER-PD Patrol Drone', 'A knee-high quadruped drone with a strobing blue eye and a stun-lance. Fast and hard to swat.', 30, '[]', 'aggressive', 'police', 'The drone sparks, folds its legs, and goes dark.', '{}', '{}', 4, 6, '[{"max": 4, "min": 2, "type": "energy"}]', '[{"part": "head", "soak": {"energy": 2, "kinetic": 1}, "weight": 1}, {"part": "torso", "soak": {"energy": 2, "kinetic": 1}, "weight": 3}, {"part": "legs", "soak": {"energy": 2, "kinetic": 1}, "weight": 2}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_wanted_enforcement_trooper', 'SPECTER-PD Enforcement Trooper', 'Full plate, carbine, visor down. These ones don''t negotiate — they contain.', 78, '[]', 'aggressive', 'police', 'The trooper drops hard, armor scraping the floor.', '{}', '{}', 6, 4, '[{"max": 8, "min": 4, "type": "kinetic"}]', '[{"part": "head", "soak": {"energy": 2, "kinetic": 5}, "weight": 1}, {"part": "torso", "soak": {"energy": 2, "kinetic": 5}, "weight": 3}, {"part": "legs", "soak": {"energy": 2, "kinetic": 5}, "weight": 2}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_wanted_heavy_enforcer', 'SPECTER-PD Heavy Enforcer', 'A slab of ambulatory armor with a chaingun arm and a servo whine you feel in your teeth.', 150, '[]', 'aggressive', 'police', 'The enforcer topples like a felled statue, hydraulics venting.', '{}', '{}', 7, 2, '[{"max": 10, "min": 6, "type": "kinetic"}, {"max": 4, "min": 2, "type": "energy"}]', '[{"part": "head", "soak": {"energy": 5, "kinetic": 8}, "weight": 1}, {"part": "torso", "soak": {"energy": 5, "kinetic": 8}, "weight": 3}, {"part": "legs", "soak": {"energy": 5, "kinetic": 8}, "weight": 2}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_slag_rat', 'Slag Rat', 'A rat the size of a housecat, hairless and slick, its skin the grey of cooled slag. It is not afraid of you.', 8, '[{"qty": [1, 1], "item": "item_scrap_metal", "weight": 20}]', 'aggressive', NULL, 'The rat kicks twice, then goes still.', '{"attacks_npcs": false, "battle_cries": ["$enemy bares yellow teeth at $player.", "$enemy hisses and skitters toward $player.", "$enemy''s naked tail lashes as it fixes on $player.", "$enemy scrabbles a step closer to $player over the rubble.", "$enemy lets out a wet, rattling squeak at $player."], "first_strike_delay_ms": 6000}', '{}', 1, 2, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 1], "item": "item_raw_meat", "weight": 100}]', 2);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_scrap_picker', 'Scrap-Picker', 'A gaunt scavenger in a cracked gas-mask and too many coats, guarding a sack of salvage like it is a newborn.', 22, '[{"qty": [1, 3], "item": "item_scrap_metal", "weight": 70}, {"qty": [1, 1], "item": "item_credits_small", "weight": 50}, {"qty": [1, 1], "item": "item_ration", "weight": 30}]', 'aggressive', NULL, 'The scrap-picker drops their shiv and folds up over their haul.', '{"attacks_npcs": false, "battle_cries": ["\"This is my patch. Find your own.\"", "\"Don''t. Don''t make me.\"", "$enemy waves the shiv in a shaky arc at $player.", "\"Everything here''s already spoken for.\"", "$enemy backs up a step, blade out, watching $player."], "first_strike_delay_ms": 9000}', '{}', 1, 1, '[{"max": 3, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 1], "item": "item_raw_meat", "weight": 100}]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_sprawl_ganger', 'sprawl ganger', 'A wiry Undermarket local in a patched jacket and a face like a closed door. Carries a ground-down shiv and the confidence of someone with nothing to lose and a crew nearby.', 26, '[{"qty": [1, 2], "item": "item_scrap_metal", "weight": 25}]', 'aggressive', NULL, 'The ganger folds over their own shiv and drops without a sound.', '{}', '{}', 4, 3, '[{"max": 6, "min": 2, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {"kinetic": 1}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_slag_wretch', 'Slag-Wretch', 'What the works made of a shift-worker who never clocked out: skin like slag, eyes like cooling glass, still wearing the tatters of a hi-vis vest.', 34, '[{"qty": [1, 2], "item": "item_glowing_scrap", "weight": 40}, {"qty": [1, 1], "item": "item_mutated_bone", "weight": 30}, {"qty": [1, 1], "item": "item_credits_small", "weight": 35}]', 'aggressive', NULL, 'The wretch sags against a pipe and slides down it, finally still.', '{"attacks_npcs": false, "battle_cries": ["$enemy drags a ruined arm toward $player.", "$enemy exhales a lungful of ash at $player.", "$enemy''s jaw works, but only static comes out.", "$enemy shambles a step closer to $player.", "$enemy fixes $player with two panes of cooling glass."], "first_strike_delay_ms": 4000}', '{}', 1, 1, '[{"max": 4, "min": 2, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 2], "item": "item_raw_meat", "weight": 100}]', 6);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_ash_crawler', 'Ash Crawler', 'A dog-sized arthropod fused out of ash and something that used to be a raccoon. Too many legs, all of them in a hurry.', 14, '[{"qty": [1, 1], "item": "item_mutated_bone", "weight": 25}, {"qty": [1, 1], "item": "item_glowing_scrap", "weight": 12}]', 'aggressive', NULL, 'The crawler curls into itself with a chitinous crackle and stops moving.', '{"attacks_npcs": false, "battle_cries": ["$enemy rears up, mandibles clicking at $player.", "$enemy scuttles sideways around $player.", "$enemy sprays a hiss of ash at $player.", "$enemy''s legs blur as it rushes $player.", "$enemy drums its forelimbs against the ground at $player."], "first_strike_delay_ms": 7000}', '{}', 1, 2, '[{"max": 3, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 2], "item": "item_raw_meat", "weight": 100}]', 4);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_gutter_cat', 'Gutter Cat', 'A feral tomcat gone ragged and mean, one ear chewed to a stub. It has ruled this stretch of gutter longer than you have been alive, and it knows it.', 9, '[{"qty": [1, 1], "item": "item_raw_meat", "weight": 35}]', 'aggressive', NULL, 'The cat yowls once, indignant, and bolts its last.', '{"battle_cries": ["$enemy flattens its ears and hisses at $player.", "$enemy arches its back at $player.", "$enemy yowls a warning at $player.", "$enemy swipes a ragged paw at $player.", "$enemy stares down $player, tail lashing."], "first_strike_delay_ms": 5000}', '{}', 1, 3, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 1], "item": "item_raw_meat", "weight": 100}]', 2);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_squatter', 'Squatter', 'A gaunt vagrant who has made a home in the ruins and takes trespass personally: layers of salvaged coats, a length of pipe, and eyes that watched the neighbourhood empty out one window at a time.', 22, '[{"qty": [1, 2], "item": "item_scrap_metal", "weight": 60}, {"qty": [1, 1], "item": "item_credits_small", "weight": 45}, {"qty": [1, 1], "item": "item_ration", "weight": 25}]', 'aggressive', NULL, 'The squatter slumps against their doorway and stops guarding it.', '{"attacks_npcs": false, "battle_cries": ["\"This is my block. Move on.\"", "\"You don''t belong here.\"", "$enemy hefts the pipe at $player.", "\"Nothing here for you. Go.\"", "$enemy backs into the doorway, pipe raised at $player."], "first_strike_delay_ms": 8000}', '{}', 1, 1, '[{"max": 3, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[{"qty": [1, 1], "item": "item_raw_meat", "weight": 100}]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_rusted_sweeper', 'Rusted Sweeper', 'A municipal street-sweeping drone from the city''s better days, still trundling its route on three good wheels and one bad one. Its brushes are worn to nubs and its logic to nothing. It does not recognise you as pavement, which is the only good news.', 18, '[{"qty": [1, 2], "item": "item_scrap_metal", "weight": 55}, {"qty": [1, 1], "item": "item_credits_small", "weight": 30}]', 'aggressive', NULL, 'The sweeper grinds to a halt, brushes still twitching, and goes dark.', '{"battle_cries": ["$enemy grinds its worn brushes at $player.", "$enemy pivots toward $player with a squeal of bearings.", "$enemy emits a garbled municipal chime at $player.", "$enemy trundles a wobbling circle around $player.", "$enemy flashes a cracked warning light at $player."], "first_strike_delay_ms": 6000}', '{}', 1, 1, '[{"max": 2, "min": 1, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 13}, {"part": "right_leg", "soak": {}, "weight": 13}]', '[]', 5);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_wire_jackal', 'wire jackal', 'A lean scavenger stitched together from dog and junkyard — copper-whisker muzzle, a hide of wire and scab. Hunts the wastes in packs and pulls down anything slower than it.', 14, '[{"qty": [1, 1], "item": "item_salvaged_wiring", "weight": 22}, {"qty": [1, 1], "item": "item_scrap_metal", "weight": 18}]', 'aggressive', NULL, 'The jackal yelps, folds, and its pack scatters into the grey.', '{}', '{}', 5, 4, '[{"max": 5, "min": 2, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 10}, {"part": "torso", "soak": {}, "weight": 40}, {"part": "left_leg", "soak": {}, "weight": 12}, {"part": "right_leg", "soak": {}, "weight": 12}, {"part": "left_flank", "soak": {}, "weight": 13}, {"part": "right_flank", "soak": {}, "weight": 13}]', '[]', 4);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_slag_wight', 'slag wight', 'What''s left of a work-crew that never clocked out — a husk of fused slag and old coveralls, radiant with a dry heat, moving with the patience of something that has already died once.', 34, '[{"qty": [1, 1], "item": "item_glowing_scrap", "weight": 16}, {"qty": [1, 1], "item": "item_cracked_capacitor", "weight": 12}, {"qty": [1, 1], "item": "item_mutated_bone", "weight": 10}]', 'aggressive', NULL, 'The wight sags, its heat guttering out, and settles into the ash it came from.', '{}', '{}', 5, 2, '[{"max": 7, "min": 3, "type": "kinetic"}]', '[{"part": "head", "soak": {"kinetic": 1}, "weight": 10}, {"part": "torso", "soak": {"kinetic": 2}, "weight": 40}, {"part": "left_arm", "soak": {"kinetic": 1}, "weight": 12}, {"part": "right_arm", "soak": {"kinetic": 1}, "weight": 12}, {"part": "left_leg", "soak": {"kinetic": 1}, "weight": 13}, {"part": "right_leg", "soak": {"kinetic": 1}, "weight": 13}]', '[]', 7);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_harbor_lurker', 'harbour lurker', 'A long, pale thing grown fat on the bay''s runoff — part eel, part something that used to have legs. It hangs just under the surface and takes what strays too near the edge.', 20, '[{"qty": [1, 1], "item": "item_fresh_catch", "weight": 18}, {"qty": [1, 1], "item": "item_mutated_bone", "weight": 14}, {"qty": [1, 1], "item": "item_scrap_metal", "weight": 10}]', 'aggressive', NULL, 'The lurker thrashes once, sheeting the boards with black water, and sinks out of sight.', '{}', '{}', 5, 4, '[{"max": 6, "min": 2, "type": "kinetic"}]', '[{"part": "maw", "soak": {}, "weight": 12}, {"part": "body", "soak": {"kinetic": 1}, "weight": 44}, {"part": "tail", "soak": {}, "weight": 16}, {"part": "left_fin", "soak": {}, "weight": 14}, {"part": "right_fin", "soak": {}, "weight": 14}]', '[{"qty": [1, 2], "item": "item_fresh_catch", "weight": 30}]', 4);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_tar_horror', 'tar-pit horror', 'A slow-heaving mass of accreted tar, bone, and swallowed machinery that hauls itself up out of the seeps to feed. It is patient, nearly mindless, and very hard to convince to let go.', 42, '[{"qty": [1, 2], "item": "item_mutated_bone", "weight": 18}, {"qty": [1, 1], "item": "item_glowing_scrap", "weight": 12}, {"qty": [1, 1], "item": "item_scrap_metal", "weight": 10}]', 'aggressive', NULL, 'The horror sloughs apart into the tar it came from, and the seep drinks it back down.', '{}', '{}', 4, 1, '[{"max": 8, "min": 4, "type": "kinetic"}]', '[{"part": "crown", "soak": {"kinetic": 1}, "weight": 12}, {"part": "mass", "soak": {"kinetic": 3}, "weight": 48}, {"part": "left_tendril", "soak": {"kinetic": 1}, "weight": 20}, {"part": "right_tendril", "soak": {"kinetic": 1}, "weight": 20}]', '[{"qty": [1, 1], "item": "item_mutated_bone", "weight": 30}]', 8);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_cable_eel', 'Cable Eel', 'A black, cable-thick eel as long as a man is tall, its hide studded with the barnacled remains of fibre-optic sheathing it has swallowed and grown around. Its jaw is a ring of glassy, back-curved teeth.', 16, '[{"qty": [1, 1], "item": "item_fresh_catch", "weight": 40}]', 'aggressive', NULL, 'The eel thrashes itself still and lies steaming on the boards.', '{"attacks_npcs": false, "battle_cries": ["$enemy coils and lunges at $player, jaws wide.", "$enemy lashes a whipcrack of muscle across the dock at $player.", "$enemy''s glassy teeth snap shut a hand''s breadth from $player."], "first_strike_delay_ms": 3000}', '{}', 3, 3, '[{"max": 6, "min": 2, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 20}, {"part": "torso", "soak": {}, "weight": 60}, {"part": "tail", "soak": {}, "weight": 20}]', '[{"qty": [1, 2], "item": "item_raw_meat", "weight": 100}]', 4);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_bay_leviathan', 'bay leviathan', 'The thing the harbour lurkers are only the children of — a vast, pale, coiling shape that owns the deep water of Coldwater Bay. It rises rarely, feeds enormously, and has never once been photographed and believed.', 55, '[{"qty": [1, 1], "item": "item_contraband_crate", "weight": 10}, {"qty": [2, 3], "item": "item_fresh_catch", "weight": 22}, {"qty": [1, 2], "item": "item_mutated_bone", "weight": 16}, {"qty": [1, 1], "item": "item_glowing_scrap", "weight": 10}]', 'aggressive', NULL, 'The leviathan rolls once, vast and final, and slides back into the deep it will not truly leave.', '{}', '{}', 5, 2, '[{"max": 10, "min": 5, "type": "kinetic"}]', '[{"part": "maw", "soak": {"kinetic": 1}, "weight": 14}, {"part": "body", "soak": {"kinetic": 2}, "weight": 46}, {"part": "coils", "soak": {"kinetic": 1}, "weight": 24}, {"part": "fluke", "soak": {}, "weight": 16}]', '[{"qty": [2, 4], "item": "item_fresh_catch", "weight": 30}]', 9);
INSERT INTO public.enemies (id, name, description, hp_max, loot_table, behavior, faction, death_message, flags, behaviour_graph, hit, dodge, weapon, body_parts, butcher_table, butcher_difficulty) VALUES ('enemy_redline_horror', 'a Redline horror', 'The apex the Redline bred to rule its killing floor — too many limbs, too much of it load-bearing, and a heart you can hear ticking from across the open ground. Whatever it started as, the Bleed finished it into this.', 130, '[{"qty": [1, 1], "item": "item_redline_heart", "weight": 100}, {"qty": [1, 2], "item": "item_mutant_gland", "weight": 60}]', 'aggressive', NULL, 'The horror comes apart in a way that suggests it had been holding itself together out of spite, and the ticking, at last, stops.', '{"radiates": true, "attacks_npcs": false, "battle_cries": ["$enemy drags its load-bearing limbs across the bone with a wet scrape.", "$enemy emits a low tick that climbs into a shriek.", "$enemy unfolds a limb that should not bend that way.", "$enemy screams with a mouth that is mostly other mouths."], "radiation_damage": 8, "first_strike_delay_ms": 800}', '{}', 3, 2, '[{"max": 9, "min": 4, "type": "kinetic"}]', '[{"part": "head", "soak": {}, "weight": 8}, {"part": "torso", "soak": {}, "weight": 44}, {"part": "left_arm", "soak": {}, "weight": 12}, {"part": "right_arm", "soak": {}, "weight": 12}, {"part": "left_leg", "soak": {}, "weight": 12}, {"part": "right_leg", "soak": {}, "weight": 12}]', '[]', 9);
