INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_the_fixer', 'a hooded figure', 'A lean figure in a hood who keeps to the edges of the light, hands in pockets, eyes everywhere. Nothing about them invites conversation. They could be gone the moment you look away.', 'zone_tunnels', NULL, '{}', '[{"price": 70, "item_id": "item_dreamsmoke", "min_trust": 0}, {"price": 60, "item_id": "item_buzz", "min_trust": 0}, {"price": 100, "item_id": "item_lull", "min_trust": 0}, {"price": 45, "item_id": "item_ether", "min_trust": 0}, {"price": 140, "item_id": "item_static", "min_trust": 25}, {"price": 120, "item_id": "item_laughers", "min_trust": 25}, {"price": 90, "item_id": "item_psilocybin", "min_trust": 25}, {"price": 40, "item_id": "item_amyls", "min_trust": 25}, {"price": 175, "item_id": "item_redline", "min_trust": 45}, {"price": 210, "item_id": "item_grey", "min_trust": 45}, {"price": 150, "item_id": "item_mescaline", "min_trust": 45}, {"price": 185, "item_id": "item_blotter", "min_trust": 45}, {"price": 145, "item_id": "item_screamers", "min_trust": 45}, {"price": 360, "item_id": "item_coldfire", "min_trust": 70}, {"price": 300, "item_id": "item_blacktar", "min_trust": 70}, {"price": 250, "item_id": "item_khole", "min_trust": 70}, {"price": 300, "item_id": "item_memhack", "min_trust": 70}, {"price": 550, "item_id": "item_threshold", "min_trust": 90}, {"price": 480, "item_id": "item_voidwalk", "min_trust": 90}, {"price": 500, "item_id": "item_overclock", "min_trust": 90}]', 0, '{"covert": true, "deal_to": 5, "deal_from": 21, "trust_max": 100, "trust_flag": "dealer_trust", "passphrases": ["the static''s bad tonight", "you holding", "ask the shadows"], "trust_per_buy": 8, "inner_circle_flag": "dealer_inner_circle"}', '{"nodes": {"prowl": {"next": "night_check", "type": "action", "params": {"loop": true, "mode": "walk", "waypoints": ["zone_tunnels", "zone_city_sw", "zone_thresholdeast"]}, "action_type": "PATROL"}, "vanish": {"next": "night_check", "type": "action", "action_type": "GO_HOME"}, "night_check": {"type": "condition", "ifTrue": "prowl", "params": {"to": 5, "from": 21}, "ifFalse": "vanish", "condition_type": "HOUR_RANGE"}}, "_start": "night_check"}', 'zone_tunnels', NULL, NULL, '["doesn''t look up.", "keeps to the shadows, watching the exits.", "\"Wrong guy. Keep moving.\"", "says nothing, but you feel watched.", "melts a little further into the dark."]', 40, 40, 'male', '[]', 0, 1, 0, 'dealer', '{"fri": [{"to": 4, "from": 0}, {"to": 24, "from": 20}], "mon": [{"to": 4, "from": 0}, {"to": 24, "from": 20}], "sat": [{"to": 4, "from": 0}, {"to": 24, "from": 20}], "sun": [{"to": 4, "from": 0}, {"to": 24, "from": 20}], "thu": [{"to": 4, "from": 0}, {"to": 24, "from": 20}], "tue": [{"to": 4, "from": 0}, {"to": 24, "from": 20}], "wed": [{"to": 4, "from": 0}, {"to": 24, "from": 20}]}', 0, NULL, '[]', '[]', '["zone_tunnels", "zone_city_sw", "zone_thresholdeast"]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_yardmaster', 'Voss', 'The Yards'' yardmaster, a barrel of a man who runs freight, salvage, and the occasional quiet cargo out of a dead signal box. He knows where everything is, whose it is, and what it would cost you to disagree.', 'zone_yard_railhead', NULL, '{"bye": {"text": "\"Mind the forklifts on your way out.\"", "options": []}, "root": {"text": "Voss looks up from a manifest he plainly wrote himself. \"Freight, salvage, or a favour? I do all three, and only one of them''s on the books.\"", "options": [{"next": "quest_offer", "label": "What kind of favour?"}, {"next": "__shop__", "label": "Show me your salvage."}, {"next": "bye", "label": "Nothing."}]}, "accepted": {"text": "\"Good. They den in the wet freight down the south end. Mind the grab-crane; it doesn''t stop for anyone, including me.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_sidings_cleared"}], "options": [{"next": "bye", "label": "Understood."}]}, "reported": {"text": "\"...Sidings are quiet. My flatcars still have their fittings. Here — your coin, and a crate that fell off the back of a truck I definitely logged. We''re square.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_sidings_cleared"}], "options": [{"next": "bye", "label": "Obliged."}]}, "quest_offer": {"text": "\"Scavengers. Coming up off the sidings and stripping my parked flatcars to the rivets. Clear three of them out of the yards — Skid Row, the bulk heaps, the bonded cage — and there''s coin and a no-questions crate in it for you.\"", "options": [{"next": "accepted", "label": "I''ll clear the sidings."}, {"next": "reported", "label": "It''s done. (report back)"}, {"next": "bye", "label": "Pass."}]}}', '[{"price": 4, "item_id": "item_scrap_metal"}, {"price": 8, "item_id": "item_salvaged_wiring"}, {"price": 14, "item_id": "item_cracked_capacitor"}, {"price": 90, "item_id": "item_contraband_crate"}, {"price": 15, "item_id": "canteen"}]', 0, '{"personality": "vendor", "clothing_layers": ["a hi-vis yardmaster''s vest", "a grease-grey work shirt", "a heavy freight-hauler''s belt"]}', '{}', 'zone_yard_railhead', NULL, 'zone_yard_railhead', '[]', 24, 24, 'male', '[{"item_id": "item_scrap_metal"}, {"item_id": "item_salvaged_wiring"}, {"item_id": "item_cracked_capacitor"}, {"item_id": "item_contraband_crate"}, {"item_id": "canteen"}]', 10, 1, 340, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'The Railhead Office', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_butcher', 'the Butcher', 'A vast, unhurried man in an apron you try not to look at too closely, working the killing lane with a cleaver worn thin from sharpening. He sells meat, buys meat, and does not clarify the difference.', 'zone_meat_slaughter', NULL, '{"bye": {"text": "\"Everyone comes back hungry.\"", "options": []}, "root": {"text": "The Butcher sets down his cleaver with unsettling gentleness. \"Meat. Fresh, mostly. Cheap, always. You bring me something with meat on it, I''ll pay, and I won''t ask what it was.\"", "options": [{"next": "__shop__", "label": "What''s fresh?"}, {"next": "bye", "label": "Lost my appetite."}]}}', '[{"price": 6, "item_id": "item_raw_meat"}, {"price": 6, "item_id": "item_bar_jerky"}, {"price": 10, "item_id": "item_ration"}]', 0, '{"personality": "vendor", "clothing_layers": ["a rubber apron best left undescribed", "a blood-stiff undershirt", "waders and nothing to discuss"]}', '{}', 'zone_meat_slaughter', NULL, 'zone_meat_slaughter', '[]', 22, 22, 'male', '[{"item_id": "item_raw_meat"}, {"item_id": "item_bar_jerky"}, {"item_id": "item_ration"}]', 8, 1, 120, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'Slaughter Lane', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_yard_teamster', 'a teamster', 'A rope-armed teamster with a manifest board and no patience, directing forklifts by bellowed insult and pointing with whatever''s in her hand.', 'zone_yard_transfer', NULL, '{"bye": {"text": "\"Then pass faster.\"", "options": []}, "root": {"text": "The teamster doesn''t stop marking her board. \"If you''re not freight and you''re not crew, you''re an obstacle. Which is it?\"", "options": [{"next": "bye", "label": "Just passing."}]}}', 'null', 0, '{"personality": "labourer", "clothing_layers": ["a hi-vis vest over a thermal", "cargo trousers with too many pockets", "steel-caps worn to the steel"]}', '{}', 'zone_yard_transfer', NULL, 'zone_yard_transfer', '["The teamster bellows a forklift into a gap and it obeys.", "\"You''re standing in a load lane. Don''t.\"", "\"Everything in this yard is going somewhere. Are you?\""]', 18, 18, 'female', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_john_akerson', 'John Akerson', 'A broadcast studio host.', 'zone_studio_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_w0": {"next": "n_ww0", "type": "action", "params": {"message": "enters the frame."}, "action_type": "EMOTE"}, "n_w1": {"next": "n_ww1", "type": "action", "params": {"message": "The camera follows John Akerson as he jogs onto the stage, shaking hands with audience members before stopping behind his desk with a broad smile."}, "action_type": "SAY"}, "n_w2": {"next": "n_ww2", "type": "action", "params": {"message": "waves to the crowd."}, "action_type": "EMOTE"}, "n_w3": {"next": "n_ww3", "type": "action", "params": {"message": "Thank you!"}, "action_type": "SAY"}, "n_w4": {"next": "n_ww4", "type": "action", "params": {"message": "Thank you!"}, "action_type": "SAY"}, "n_w5": {"next": "n_ww5", "type": "action", "params": {"message": "Sit down! We''ve got a fantastic show tonight!"}, "action_type": "SAY"}, "n_w6": {"next": "n_ww6", "type": "action", "params": {"message": "Did everyone survive the commute?"}, "action_type": "SAY"}, "n_w7": {"next": "n_ww7", "type": "action", "params": {"message": "Traffic was backed up six blocks after somebody hacked the crossing lights to advertise noodles."}, "action_type": "SAY"}, "n_w8": {"next": "n_ww8", "type": "action", "params": {"message": "Corporate Security says crime is down."}, "action_type": "SAY"}, "n_w9": {"next": "n_ww9", "type": "action", "params": {"message": "Apparently they stopped counting anything outside corporate property."}, "action_type": "SAY"}, "n_w10": {"next": "n_ww10", "type": "action", "params": {"message": "I stopped by a pharmacy today."}, "action_type": "SAY"}, "n_w11": {"next": "n_ww11", "type": "action", "params": {"message": "They''ve started locking up bottled water."}, "action_type": "SAY"}, "n_w12": {"next": "n_ww12", "type": "action", "params": {"message": "The cybernetic organs are still self-service though."}, "action_type": "SAY"}, "n_w13": {"next": "n_ww13", "type": "action", "params": {"message": "You know times are tough when the mugger accepts store credit."}, "action_type": "SAY"}, "n_w14": {"next": "n_ww14", "type": "action", "params": {"message": "Good news though..."}, "action_type": "SAY"}, "n_w15": {"next": "n_ww15", "type": "action", "params": {"message": "My landlord says the building is structurally sound."}, "action_type": "SAY"}, "n_w16": {"next": "n_ww16", "type": "action", "params": {"message": "Apparently that''s a completely different thing than \"safe.\""}, "action_type": "SAY"}, "n_w17": {"next": "n_ww17", "type": "action", "params": {"message": "Lenny, welcome to the show."}, "action_type": "SAY"}, "n_w18": {"next": "n_ww18", "type": "action", "params": {"message": "You won the city lottery seven times."}, "action_type": "SAY"}, "n_w19": {"next": "n_ww19", "type": "action", "params": {"message": "Eight?"}, "action_type": "SAY"}, "n_w20": {"next": "n_ww20", "type": "action", "params": {"message": "What''s your secret?"}, "action_type": "SAY"}, "n_w21": {"next": "n_ww21", "type": "action", "params": {"message": "That''s oddly specific."}, "action_type": "SAY"}, "n_w22": {"next": "n_ww22", "type": "action", "params": {"message": "What''s the first thing you bought?"}, "action_type": "SAY"}, "n_w23": {"next": "n_ww23", "type": "action", "params": {"message": "Nice!"}, "action_type": "SAY"}, "n_w24": {"next": "n_ww24", "type": "action", "params": {"message": "That''s all the time we''ve got tonight."}, "action_type": "SAY"}, "n_w25": {"next": "n_ww25", "type": "action", "params": {"message": "Thanks to Lenny for joining us."}, "action_type": "SAY"}, "n_w26": {"next": "n_ww26", "type": "action", "params": {"message": "Remember..."}, "action_type": "SAY"}, "n_w27": {"next": "n_ww27", "type": "action", "params": {"message": "If somebody offers you free cyberware in an alley.."}, "action_type": "SAY"}, "n_w28": {"next": "n_ww28", "type": "action", "params": {"message": "...at least ask if it comes with a warranty."}, "action_type": "SAY"}, "n_w29": {"next": "n_ww29", "type": "action", "params": {"message": "Good night, everybody!"}, "action_type": "SAY"}, "n_w30": {"next": "n_ww30", "type": "action", "params": {"message": "The camera slowly pulls back as John waves to the audience. The Tonight Show band reprises the theme while the audience rises for a standing ovation beneath glowing neon studio lights."}, "action_type": "SAY"}, "n_ww0": {"next": "n_w1", "type": "wait", "seconds": 5}, "n_ww1": {"next": "n_w2", "type": "wait", "seconds": 3}, "n_ww2": {"next": "n_w3", "type": "wait", "seconds": 5}, "n_ww3": {"next": "n_w4", "type": "wait", "seconds": 3}, "n_ww4": {"next": "n_w5", "type": "wait", "seconds": 5}, "n_ww5": {"next": "n_w6", "type": "wait", "seconds": 5}, "n_ww6": {"next": "n_w7", "type": "wait", "seconds": 5}, "n_ww7": {"next": "n_w8", "type": "wait", "seconds": 5}, "n_ww8": {"next": "n_w9", "type": "wait", "seconds": 5}, "n_ww9": {"next": "n_w10", "type": "wait", "seconds": 5}, "n_life": {"next": "n_work", "type": "action", "action_type": "HAVE_LIFE"}, "n_loop": {"next": "n_start", "type": "loop"}, "n_work": {"next": "n_w0", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_ww10": {"next": "n_w11", "type": "wait", "seconds": 5}, "n_ww11": {"next": "n_w12", "type": "wait", "seconds": 5}, "n_ww12": {"next": "n_w13", "type": "wait", "seconds": 5}, "n_ww13": {"next": "n_w14", "type": "wait", "seconds": 5}, "n_ww14": {"next": "n_w15", "type": "wait", "seconds": 5}, "n_ww15": {"next": "n_w16", "type": "wait", "seconds": 5}, "n_ww16": {"next": "n_w17", "type": "wait", "seconds": 5}, "n_ww17": {"next": "n_w18", "type": "wait", "seconds": 5}, "n_ww18": {"next": "n_w19", "type": "wait", "seconds": 5}, "n_ww19": {"next": "n_w20", "type": "wait", "seconds": 5}, "n_ww20": {"next": "n_w21", "type": "wait", "seconds": 5}, "n_ww21": {"next": "n_w22", "type": "wait", "seconds": 5}, "n_ww22": {"next": "n_w23", "type": "wait", "seconds": 5}, "n_ww23": {"next": "n_w24", "type": "wait", "seconds": 5}, "n_ww24": {"next": "n_w25", "type": "wait", "seconds": 5}, "n_ww25": {"next": "n_w26", "type": "wait", "seconds": 5}, "n_ww26": {"next": "n_w27", "type": "wait", "seconds": 5}, "n_ww27": {"next": "n_w28", "type": "wait", "seconds": 5}, "n_ww28": {"next": "n_w29", "type": "wait", "seconds": 5}, "n_ww29": {"next": "n_w30", "type": "wait", "seconds": 5}, "n_ww30": {"next": "n_loop", "type": "wait", "seconds": 5}, "n_start": {"next": "n_life", "type": "start"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, 'zone_studio_1782953094650', '[]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_captain_nguyen', 'Captain Nguyen', 'A broadcast studio host.', 'zone_studio_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_w0": {"next": "n_ww0", "type": "action", "params": {"message": "[Extended Vietnamese at considerable volume, followed by a long and deliberate nod.]"}, "action_type": "SAY"}, "n_w1": {"next": "n_ww1", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w2": {"next": "n_ww2", "type": "action", "params": {"message": "Im gonna be this guys sponsor im bringing him on the crew we can hire him for half wage do you believe this guy is from fuckin ''Nam hey nguyen tell this guy you''re from ''nam!"}, "action_type": "EMOTE"}, "n_w3": {"next": "n_ww3", "type": "action", "params": {"message": "reaches into frame and yanks Camera 1 back in the other direction."}, "action_type": "EMOTE"}, "n_w4": {"next": "n_ww4", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w5": {"next": "n_ww5", "type": "action", "params": {"message": "NEIL WE HAVE TO THANK THE SPONSORS SAY AND NOW A WORD FROM OUR SPONSORS!"}, "action_type": "EMOTE"}, "n_w6": {"next": "n_ww6", "type": "action", "params": {"message": "The Captain Nguyen shouts this at a volume that could be heard in the laundromat upstairs."}, "action_type": "SAY"}, "n_w7": {"next": "n_ww7", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w8": {"next": "n_ww8", "type": "action", "params": {"message": "And now a word from our sponsors."}, "action_type": "EMOTE"}, "n_w9": {"next": "n_ww9", "type": "action", "params": {"message": "The basement drops away. We cut to a commercial. A sad man sits alone at a kitchen table, staring at a wall."}, "action_type": "SAY"}, "n_w10": {"next": "n_ww10", "type": "action", "params": {"message": "A dream blooms into colour. The man pushes his child on a playground swing. Nearby, his partner holds a new baby and smiles at him — warm, full, genuine. This is everything. This is his whole life."}, "action_type": "SAY"}, "n_w11": {"next": "n_ww11", "type": "action", "params": {"message": "A thundercrack. A man on a Harley-Davidson roars up onto the grass, dismounts, kicks the baby, and begins making out with the man''s wife. The kid on the swing jumps off, turns to face the camera, and speaks."}, "action_type": "SAY"}, "n_w12": {"next": "n_ww12", "type": "action", "params": {"message": "Loser."}, "action_type": "SAY"}, "n_w13": {"next": "n_ww13", "type": "action", "params": {"message": "The whole family piles onto the Harley and rides away without a backward glance. The man sinks to his knees. He begins to weep."}, "action_type": "SAY"}, "n_w14": {"next": "n_ww14", "type": "action", "params": {"message": "A figure approaches from the right: a large man in a foam rubber Salisbury steak costume. He sits beside the crying man and places an arm around him in silence.\r\n\r\nA second figure approaches from the left: a rectangular man in a chicken patty costume, carrying a glass of whiskey. He hands it over.\r\n\r\nA third figure lumbers in from the rear — shaped like a rib patty, boombox on one shoulder. Creed is playing. He reaches a thick slab-like arm forward and passes the crying man a lit joint."}, "action_type": "SAY"}, "n_w15": {"next": "n_ww15", "type": "action", "params": {"message": "The man is back in his kitchen. He is cleaned up. Shaved. Wearing a pressed shirt. On the table before him sits a Hungry Man dinner tray — wall to wall meat. Not a vegetable in sight. He looks at it the way a man looks at his oldest friend."}, "action_type": "SAY"}, "n_w16": {"next": "n_ww16", "type": "action", "params": {"message": "It''s just the meats."}, "action_type": "SAY"}, "n_w17": {"next": "n_ww17", "type": "action", "params": {"message": "She can''t control you anymore, king."}, "action_type": "SAY"}, "n_w18": {"next": "n_ww18", "type": "action", "params": {"message": "The camera fades back to the basement. Neil is at the table. There are three more cigarette butts in the ashtray than there were before the break. He does not acknowledge this. The pendulum bulb has slowed to a gentle sway."}, "action_type": "SAY"}, "n_w19": {"next": "n_ww19", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w20": {"next": "n_ww20", "type": "action", "params": {"message": "Where was I..."}, "action_type": "EMOTE"}, "n_w21": {"next": "n_ww21", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w22": {"next": "n_ww22", "type": "action", "params": {"message": "Maybe we should move on."}, "action_type": "EMOTE"}, "n_w23": {"next": "n_ww23", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w24": {"next": "n_ww24", "type": "action", "params": {"message": "MAYBE YOU SHOULD MOVE ON!"}, "action_type": "EMOTE"}, "n_w25": {"next": "n_ww25", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w26": {"next": "n_ww26", "type": "action", "params": {"message": "You know that''s not what I meant. Let''s get to the top 10."}, "action_type": "EMOTE"}, "n_w27": {"next": "n_ww27", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w28": {"next": "n_ww28", "type": "action", "params": {"message": "OK here''s my top ten conspiracy theories of the week, as always I will be fielding calls but only at the end of the programme please, I know our phone lines are already lighting up, our operators are standing by..."}, "action_type": "EMOTE"}, "n_w29": {"next": "n_ww29", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w30": {"next": "n_ww30", "type": "action", "params": {"message": "No one calls this show. This phone isn''t even that type of phone. It''s a payphone. You have a basement payphone. I didn''t even think that was possible."}, "action_type": "EMOTE"}, "n_w31": {"next": "n_ww31", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w32": {"next": "n_ww32", "type": "action", "params": {"message": "She fuckin took everything man..."}, "action_type": "EMOTE"}, "n_w33": {"next": "n_ww33", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w34": {"next": "n_ww34", "type": "action", "params": {"message": "Let''s try and move on."}, "action_type": "EMOTE"}, "n_w35": {"next": "n_ww35", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w36": {"next": "n_ww36", "type": "action", "params": {"message": "That''s what Barb told my kids and my dog."}, "action_type": "EMOTE"}, "n_w37": {"next": "n_ww37", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w38": {"next": "n_ww38", "type": "action", "params": {"message": "For christ sake."}, "action_type": "EMOTE"}, "n_w39": {"next": "n_ww39", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w40": {"next": "n_ww40", "type": "action", "params": {"message": "Just put the fuckin number up man, put up my number so my fans can call in."}, "action_type": "EMOTE"}, "n_w41": {"next": "n_ww41", "type": "action", "params": {"message": "The number crawls across the bottom of the screen. It is the suicide hotline. It is being towed by a centaur playing electric guitar. Behind the centaur, a graphic element features Hulk Hogan pointing directly at the audience with one finger. He appears to be saying something encouraging."}, "action_type": "SAY"}, "n_w42": {"next": "n_ww42", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w43": {"next": "n_ww43", "type": "action", "params": {"message": "WHAT THE FUCK WAS THAT MAN?! WAS THAT THE SUICIDE HOTLINE NUMBER?!"}, "action_type": "EMOTE"}, "n_w44": {"next": "n_ww44", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w45": {"next": "n_ww45", "type": "action", "params": {"message": "And why was Hulk Hogan involved?"}, "action_type": "EMOTE"}, "n_w46": {"next": "n_ww46", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w47": {"next": "n_ww47", "type": "action", "params": {"message": "The Hulkster was your idea."}, "action_type": "EMOTE"}, "n_w48": {"next": "n_ww48", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w49": {"next": "n_ww49", "type": "action", "params": {"message": "Why the hell was it my idea when was that ever my idea to have Hulk Hogan telling my audience not to kill themselves?!"}, "action_type": "EMOTE"}, "n_w50": {"next": "n_ww50", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w51": {"next": "n_ww51", "type": "action", "params": {"message": "I got a voicemail at 3 am. It sounded like you were drunk but you were quite insistent that we should use the Hulkster in a graphic for the show."}, "action_type": "EMOTE"}, "n_w52": {"next": "n_ww52", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w53": {"next": "n_ww53", "type": "action", "params": {"message": "Since when did that mean get the Hulkster to tell my fans not to kill themselves after the divorce?! I was watching the Netflix documentary!"}, "action_type": "EMOTE"}, "n_w54": {"next": "n_ww54", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w55": {"next": "n_ww55", "type": "action", "params": {"message": "That''s on me. I thought you''d appreciate the levity."}, "action_type": "EMOTE"}, "n_w56": {"next": "n_ww56", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w57": {"next": "n_ww57", "type": "action", "params": {"message": "The Hulkster wouldn''t stand for this. It was all a smear anyways, and we all know why..."}, "action_type": "EMOTE"}, "n_w58": {"next": "n_ww58", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w59": {"next": "n_ww59", "type": "action", "params": {"message": "What are you talking about man?"}, "action_type": "EMOTE"}, "n_w60": {"next": "n_ww60", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w61": {"next": "n_ww61", "type": "action", "params": {"message": "These Hollywood jews hate to see a blonde haired blue eyed macho friend of Jesus win."}, "action_type": "EMOTE"}, "n_w62": {"next": "n_ww62", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w63": {"next": "n_ww63", "type": "action", "params": {"message": "You can''t keep saying jews!"}, "action_type": "EMOTE"}, "n_w64": {"next": "n_ww64", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w65": {"next": "n_ww65", "type": "action", "params": {"message": "Why is Barb gonna go get her big jew lawyer to come after me, you know they love to litigate —"}, "action_type": "EMOTE"}, "n_w66": {"next": "n_ww66", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w67": {"next": "n_ww67", "type": "action", "params": {"message": "Jesus!"}, "action_type": "EMOTE"}, "n_w68": {"next": "n_ww68", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w69": {"next": "n_ww69", "type": "action", "params": {"message": "YOU CANT SQUEEZE BLOOD FROM A STONE BARBRA I KNOW WHO DROVE US APART AND I HEARS THE TRUTH IS REALLY BAD!"}, "action_type": "EMOTE"}, "n_w70": {"next": "n_ww70", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w71": {"next": "n_ww71", "type": "action", "params": {"message": "IS REALLY BAD."}, "action_type": "EMOTE"}, "n_w72": {"next": "n_ww72", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w73": {"next": "n_ww73", "type": "action", "params": {"message": "ISRAELI BAD!"}, "action_type": "EMOTE"}, "n_w74": {"next": "n_ww74", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w75": {"next": "n_ww75", "type": "action", "params": {"message": "PRESS THE RED BUTTON NGUYEN!"}, "action_type": "EMOTE"}, "n_w76": {"next": "n_ww76", "type": "action", "params": {"message": "grabs Camera 1 from the other side and hauls it back."}, "action_type": "EMOTE"}, "n_w77": {"next": "n_ww77", "type": "action", "params": {"message": "The camera swings wildly between the two men, catching ceiling, floor, the laundromat pipes, and half-illuminated faces in roughly equal measure."}, "action_type": "SAY"}, "n_w78": {"next": "n_ww78", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w79": {"next": "n_ww79", "type": "action", "params": {"message": "DO YOU HAVE TROUBLE GETTING IT UP CUZ YOUR WIFE WAS AN UGLY PIG?!"}, "action_type": "EMOTE"}, "n_w80": {"next": "n_ww80", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w81": {"next": "n_ww81", "type": "action", "params": {"message": "Give me that!"}, "action_type": "EMOTE"}, "n_w82": {"next": "n_ww82", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w83": {"next": "n_ww83", "type": "action", "params": {"message": "WELL LOOK NO FURTHER THAN Captain Nguyen''S MAGIC ROOT! AVAILABLE VIA PAYPAL —"}, "action_type": "EMOTE"}, "n_w84": {"next": "n_ww84", "type": "action", "params": {"message": "releases Camera 1 and it drops to the concrete floor."}, "action_type": "EMOTE"}, "n_w85": {"next": "n_ww85", "type": "action", "params": {"message": "The camera hits the floor and settles at a forty-five-degree angle. The image holds there. In the background, the argument continues to dissolve into ambient noise."}, "action_type": "SAY"}, "n_w86": {"next": "n_ww86", "type": "action", "params": {"message": "Cut to exterior. California. The sun is aggressively bright. A convertible sports car rolls up a coastal road to the sound of smooth jazz."}, "action_type": "SAY"}, "n_w87": {"next": "n_ww87", "type": "action", "params": {"message": "The camera pans to the beach. An attractive woman and her handsome personal trainer are doing Pilates together. They are very in sync. They are having a genuinely lovely time."}, "action_type": "SAY"}, "n_w88": {"next": "n_ww88", "type": "action", "params": {"message": "A man in a crisp linen suit steps into frame. He has the easy confidence of someone who has never once paid his own parking tickets."}, "action_type": "SAY"}, "n_ww0": {"next": "n_w1", "type": "wait", "seconds": 5}, "n_ww1": {"next": "n_w2", "type": "wait", "seconds": 5}, "n_ww2": {"next": "n_w3", "type": "wait", "seconds": 3}, "n_ww3": {"next": "n_w4", "type": "wait", "seconds": 3}, "n_ww4": {"next": "n_w5", "type": "wait", "seconds": 3}, "n_ww5": {"next": "n_w6", "type": "wait", "seconds": 3}, "n_ww6": {"next": "n_w7", "type": "wait", "seconds": 3}, "n_ww7": {"next": "n_w8", "type": "wait", "seconds": 5}, "n_ww8": {"next": "n_w9", "type": "wait", "seconds": 3}, "n_ww9": {"next": "n_w10", "type": "wait", "seconds": 3}, "n_life": {"next": "n_work", "type": "action", "action_type": "HAVE_LIFE"}, "n_loop": {"next": "n_start", "type": "loop"}, "n_work": {"next": "n_w0", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_ww10": {"next": "n_w11", "type": "wait", "seconds": 5}, "n_ww11": {"next": "n_w12", "type": "wait", "seconds": 5}, "n_ww12": {"next": "n_w13", "type": "wait", "seconds": 5}, "n_ww13": {"next": "