INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_jerry_rosenberg', 'Jerry Rosenberg', 'A broadcast studio host.', 'zone_studio_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_w0": {"next": "n_ww0", "type": "action", "params": {"message": "Do you ever wonder what your life could be, if this guy wasn''t holding you back?"}, "action_type": "SAY"}, "n_w1": {"next": "n_ww1", "type": "action", "params": {"message": "The footage cuts abruptly to grainy home video: a man in a wife-beater and dirty underpants, cracking a beer and lighting a cigarette while a baby plays with a fork near a wall socket."}, "action_type": "SAY"}, "n_w2": {"next": "n_ww2", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w3": {"next": "n_ww3", "type": "action", "params": {"message": "WTF IS THAT ME?!"}, "action_type": "EMOTE"}, "n_w4": {"next": "n_ww4", "type": "action", "params": {"message": "The ad continues, undeterred."}, "action_type": "SAY"}, "n_w5": {"next": "n_ww5", "type": "action", "params": {"message": "The lawyer steps back into frame. He is now dressed as a mohel. He adjusts his equipment."}, "action_type": "SAY"}, "n_w6": {"next": "n_ww6", "type": "action", "params": {"message": "Let''s bris this schmuck. Now cheaper — with our ten percent off circumcision discount! Spouses of gentiles now save ten percent!"}, "action_type": "SAY"}, "n_w7": {"next": "n_ww7", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w8": {"next": "n_ww8", "type": "action", "params": {"message": "YOU LET THEM RUN AN AD FOR MY EX WIFE''S JEW LAWYER?!"}, "action_type": "EMOTE"}, "n_w9": {"next": "n_ww9", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w10": {"next": "n_ww10", "type": "action", "params": {"message": "He pays good money —"}, "action_type": "EMOTE"}, "n_w11": {"next": "n_ww11", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w12": {"next": "n_ww12", "type": "action", "params": {"message": "THAT''S MY MONEY!"}, "action_type": "EMOTE"}, "n_w13": {"next": "n_ww13", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w14": {"next": "n_ww14", "type": "action", "params": {"message": "He''s a friend of the show."}, "action_type": "EMOTE"}, "n_w15": {"next": "n_ww15", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w16": {"next": "n_ww16", "type": "action", "params": {"message": "HE IS NOT A FRIEND OF THE SHOW THIS GUY RUINED MY LIFE —"}, "action_type": "EMOTE"}, "n_w17": {"next": "n_ww17", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w18": {"next": "n_ww18", "type": "action", "params": {"message": "I''m muting your microphone."}, "action_type": "EMOTE"}, "n_w19": {"next": "n_ww19", "type": "action", "params": {"message": "Neil''s protests continue at length, reduced by the muted mic to a distant, indistinct hum. The ad presses on without him."}, "action_type": "SAY"}, "n_w20": {"next": "n_ww20", "type": "action", "params": {"message": "The lawyer returns, now dressed as a Hasid. He squares up to the camera with evident satisfaction. He begins to recite his contact information at a measured pace. Then his eyes go wide. His hands come together — slowly, fingers interlacing."}, "action_type": "SAY"}, "n_w21": {"next": "n_ww21", "type": "action", "params": {"message": "For all your divorce needs, come to Jerry Rosenberg Family Law — where we will make him pay. And make him pay for me too!"}, "action_type": "SAY"}, "n_w22": {"next": "n_ww22", "type": "action", "params": {"message": "From somewhere behind the muted microphone, Neil can be observed commenting at some volume. The exact words are inaudible. The feeling is clear."}, "action_type": "SAY"}, "n_w23": {"next": "n_ww23", "type": "action", "params": {"message": "The camera — which has been lying on the floor of the basement at a forty-five-degree angle for the duration of the break — is picked up by an unseen hand and levelled. It finds Neil already mid-sentence, microphone apparently reinstated."}, "action_type": "SAY"}, "n_w24": {"next": "n_ww24", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w25": {"next": "n_ww25", "type": "action", "params": {"message": "Who makes an ad like that? That''s like three antisemitic self-burns in a row. He looks like Jude Süss up there. This is egregious! I''m too riled up to continue. Nguyen, roll the credits!"}, "action_type": "EMOTE"}, "n_ww0": {"next": "n_w1", "type": "wait", "seconds": 5}, "n_ww1": {"next": "n_w2", "type": "wait", "seconds": 5}, "n_ww2": {"next": "n_w3", "type": "wait", "seconds": 5}, "n_ww3": {"next": "n_w4", "type": "wait", "seconds": 3}, "n_ww4": {"next": "n_w5", "type": "wait", "seconds": 3}, "n_ww5": {"next": "n_w6", "type": "wait", "seconds": 5}, "n_ww6": {"next": "n_w7", "type": "wait", "seconds": 5}, "n_ww7": {"next": "n_w8", "type": "wait", "seconds": 5}, "n_ww8": {"next": "n_w9", "type": "wait", "seconds": 3}, "n_ww9": {"next": "n_w10", "type": "wait", "seconds": 3}, "n_life": {"next": "n_work", "type": "action", "action_type": "HAVE_LIFE"}, "n_loop": {"next": "n_start", "type": "loop"}, "n_work": {"next": "n_w0", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_ww10": {"next": "n_w11", "type": "wait", "seconds": 3}, "n_ww11": {"next": "n_w12", "type": "wait", "seconds": 3}, "n_ww12": {"next": "n_w13", "type": "wait", "seconds": 3}, "n_ww13": {"next": "n_w14", "type": "wait", "seconds": 3}, "n_ww14": {"next": "n_w15", "type": "wait", "seconds": 3}, "n_ww15": {"next": "n_w16", "type": "wait", "seconds": 3}, "n_ww16": {"next": "n_w17", "type": "wait", "seconds": 3}, "n_ww17": {"next": "n_w18", "type": "wait", "seconds": 3}, "n_ww18": {"next": "n_w19", "type": "wait", "seconds": 3}, "n_ww19": {"next": "n_w20", "type": "wait", "seconds": 3}, "n_ww20": {"next": "n_w21", "type": "wait", "seconds": 5}, "n_ww21": {"next": "n_w22", "type": "wait", "seconds": 5}, "n_ww22": {"next": "n_w23", "type": "wait", "seconds": 5}, "n_ww23": {"next": "n_w24", "type": "wait", "seconds": 5}, "n_ww24": {"next": "n_w25", "type": "wait", "seconds": 5}, "n_ww25": {"next": "n_loop", "type": "wait", "seconds": 3}, "n_start": {"next": "n_life", "type": "start"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, 'zone_studio_1782953094650', '[]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_neil_mcmanistan', 'Neil Mcmanistan', 'A broadcast studio host.', 'zone_studio_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_w0": {"next": "n_ww0", "type": "action", "params": {"message": "trips violently over a chair, which screeches across the concrete floor and detonates into a wall of empty beer cans and food containers."}, "action_type": "EMOTE"}, "n_w1": {"next": "n_ww1", "type": "action", "params": {"message": "A bare lightbulb swings into frame on its pull-string. It flickers on, casting a slow pendulum of amber light across a dishevelled man in a dirty wife-beater seated at a table. In front of him sits a microphone from the 1930s."}, "action_type": "SAY"}, "n_w2": {"next": "n_ww2", "type": "action", "params": {"message": "The camera slowly pulls back. The host is wearing combat boots. He is not wearing pants. These two facts are presented without comment."}, "action_type": "SAY"}, "n_w3": {"next": "n_ww3", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w4": {"next": "n_ww4", "type": "action", "params": {"message": "you''re not gonna believe this shit!"}, "action_type": "EMOTE"}, "n_w5": {"next": "n_ww5", "type": "action", "params": {"message": "pulls out a Zippo lighter and ignites a cigarette with the ease of a man who has been doing this since before it was legal."}, "action_type": "EMOTE"}, "n_w6": {"next": "n_ww6", "type": "action", "params": {"message": "The basement dissolves to a sprawling conspiracy web: cork board, yarn, thumbtacks. Charlie Kirk is connected to Benito Mussolini by a red string. Both are connected to a laminated photograph of a lizard. Scattered across the map: celebrities, geopolitical figures, and anti-Zionist imagery of considerable ambition. It is the work of a very troubled and extremely productive man."}, "action_type": "SAY"}, "n_w7": {"next": "n_ww7", "type": "action", "params": {"message": "The scene snaps into a hard spin cut — synchronized to the wet, gurgling crescendo of a bong reaching its full percolation. We slam back to the basement."}, "action_type": "SAY"}, "n_w8": {"next": "n_ww8", "type": "action", "params": {"message": "doubles over the table in a monumental coughing fit, a thick cloud of smoke escaping in every direction."}, "action_type": "EMOTE"}, "n_w9": {"next": "n_ww9", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w10": {"next": "n_ww10", "type": "action", "params": {"message": "They must think that I''m retarded. You''d have to be retarded not to put this together, and as sure as Barb took the kids the Jews will get me for this."}, "action_type": "EMOTE"}, "n_w11": {"next": "n_ww11", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w12": {"next": "n_ww12", "type": "action", "params": {"message": "Jesus christ Neil we talked about this shit man you''re gonna get us kicked off public access we need this man."}, "action_type": "EMOTE"}, "n_w13": {"next": "n_ww13", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w14": {"next": "n_ww14", "type": "action", "params": {"message": "Im sorry, I''m sorry where was I. I''ll tell you where I was, I was at the grocery store and they had a coupon, Tim Horton''s iced coffee syrup, save 2 dollars. And you know how I feel about Singh Hortons..."}, "action_type": "EMOTE"}, "n_w15": {"next": "n_ww15", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w16": {"next": "n_ww16", "type": "action", "params": {"message": "CUT!"}, "action_type": "EMOTE"}, "n_w17": {"next": "n_ww17", "type": "action", "params": {"message": "A beep sounds. Neil nods at the camera. The show resumes."}, "action_type": "SAY"}, "n_w18": {"next": "n_ww18", "type": "action", "params": {"message": "gives the camera a slow, deliberate nod."}, "action_type": "EMOTE"}, "n_w19": {"next": "n_ww19", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w20": {"next": "n_ww20", "type": "action", "params": {"message": "these fuckin grocery barons are sucking us dry! I had this coupon, and lo and behold, ill give it a go, why not save a few bucks. Regular price 8 bucks, brought it down to 6 with the coupon, but i price matched it down to 6 so the coupon made it 4...."}, "action_type": "EMOTE"}, "n_w21": {"next": "n_ww21", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w22": {"next": "n_ww22", "type": "action", "params": {"message": "What the fuck are you talking about and get to the point!"}, "action_type": "EMOTE"}, "n_w23": {"next": "n_ww23", "type": "action", "params": {"message": "The Captain Nguyen delivers this in a frantic whisper from somewhere just off-camera. It is not a quiet whisper."}, "action_type": "SAY"}, "n_w24": {"next": "n_ww24", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w25": {"next": "n_ww25", "type": "action", "params": {"message": "Anyways I went back into the place for some vittles a week later, no 2 dollar off coupons, but the same bottle of syrup was now 2 dollars cheaper now that there were no coupons. Those greedy pricks they must think that we are SAPS!"}, "action_type": "EMOTE"}, "n_w26": {"next": "n_ww26", "type": "action", "params": {"message": "slams his fist on the table. The ashtray goes airborne. The camera jerks up and snaps directly into Neil''s face."}, "action_type": "EMOTE"}, "n_w27": {"next": "n_ww27", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w28": {"next": "n_ww28", "type": "action", "params": {"message": "Don''t even get me started on that shithole hortons, its harder than Chinese calculus trying to get a jesus coffee in there, they gotta get some teenage girls in there, not like that, not at all, never..."}, "action_type": "EMOTE"}, "n_w29": {"next": "n_ww29", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w30": {"next": "n_ww30", "type": "action", "params": {"message": "Jesus christ man you can''t keep saying that shit."}, "action_type": "EMOTE"}, "n_w31": {"next": "n_ww31", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w32": {"next": "n_ww32", "type": "action", "params": {"message": "Pause, no diddy, respectfully."}, "action_type": "EMOTE"}, "n_w33": {"next": "n_ww33", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w34": {"next": "n_ww34", "type": "action", "params": {"message": "THATS NOT HELPING!"}, "action_type": "EMOTE"}, "n_w35": {"next": "n_ww35", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w36": {"next": "n_ww36", "type": "action", "params": {"message": "And now a word from our sponsor:"}, "action_type": "EMOTE"}, "n_w37": {"next": "n_ww37", "type": "action", "params": {"message": "The camera drifts wide to catch the far corner of the basement. Perched on a barstool, just at the edge of the visible set, is an old Vietnamese man. He is holding a small brown paper bag. He has been there the entire time."}, "action_type": "SAY"}, "n_w38": {"next": "n_ww38", "type": "action", "params": {"message": "Captain Nguyen:"}, "action_type": "EMOTE"}, "n_w39": {"next": "n_ww39", "type": "action", "params": {"message": "Who the hell is that?!"}, "action_type": "EMOTE"}, "n_w40": {"next": "n_ww40", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w41": {"next": "n_ww41", "type": "action", "params": {"message": "Thats fuckin, nguyen, man, hey nguyen say hi."}, "action_type": "EMOTE"}, "n_w42": {"next": "n_ww42", "type": "action", "params": {"message": "lunges forward and grabs Camera 1, physically wrenching it toward Nguyen."}, "action_type": "EMOTE"}, "n_w43": {"next": "n_ww43", "type": "action", "params": {"message": "seizes Camera 1 and wrenches it toward Nguyen."}, "action_type": "EMOTE"}, "n_w44": {"next": "n_ww44", "type": "action", "params": {"message": "pensively lights a cigarette, furrows his brow, and stares into the middle distance."}, "action_type": "EMOTE"}, "n_w45": {"next": "n_ww45", "type": "action", "params": {"message": "Neil Mcmanistan:"}, "action_type": "EMOTE"}, "n_w46": {"next": "n_ww46", "type": "action", "params": {"message": "Join us next week when we are joined by our special guest — my wife''s personal trainer — where we will fight a grudge match to the death!"}, "action_type": "EMOTE"}, "n_ww0": {"next": "n_w1", "type": "wait", "seconds": 5}, "n_ww1": {"next": "n_w2", "type": "wait", "seconds": 3}, "n_ww2": {"next": "n_w3", "type": "wait", "seconds": 5}, "n_ww3": {"next": "n_w4", "type": "wait", "seconds": 5}, "n_ww4": {"next": "n_w5", "type": "wait", "seconds": 3}, "n_ww5": {"next": "n_w6", "type": "wait", "seconds": 3}, "n_ww6": {"next": "n_w7", "type": "wait", "seconds": 3}, "n_ww7": {"next": "n_w8", "type": "wait", "seconds": 5}, "n_ww8": {"next": "n_w9", "type": "wait", "seconds": 5}, "n_ww9": {"next": "n_w10", "type": "wait", "seconds": 3}, "n_life": {"next": "n_work", "type": "action", "action_type": "HAVE_LIFE"}, "n_loop": {"next": "n_start", "type": "loop"}, "n_work": {"next": "n_w0", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_ww10": {"next": "n_w11", "type": "wait", "seconds": 3}, "n_ww11": {"next": "n_w12", "type": "wait", "seconds": 3}, "n_ww12": {"next": "n_w13", "type": "wait", "seconds": 3}, "n_ww13": {"next": "n_w14", "type": "wait", "seconds": 3}, "n_ww14": {"next": "n_w15", "type": "wait", "seconds": 3}, "n_ww15": {"next": "n_w16", "type": "wait", "seconds": 3}, "n_ww16": {"next": "n_w17", "type": "wait", "seconds": 3}, "n_ww17": {"next": "n_w18", "type": "wait", "seconds": 3}, "n_ww18": {"next": "n_w19", "type": "wait", "seconds": 5}, "n_ww19": {"next": "n_w20", "type": "wait", "seconds": 3}, "n_ww20": {"next": "n_w21", "type": "wait", "seconds": 3}, "n_ww21": {"next": "n_w22", "type": "wait", "seconds": 3}, "n_ww22": {"next": "n_w23", "type": "wait", "seconds": 3}, "n_ww23": {"next": "n_w24", "type": "wait", "seconds": 3}, "n_ww24": {"next": "n_w25", "type": "wait", "seconds": 5}, "n_ww25": {"next": "n_w26", "type": "wait", "seconds": 3}, "n_ww26": {"next": "n_w27", "type": "wait", "seconds": 3}, "n_ww27": {"next": "n_w28", "type": "wait", "seconds": 3}, "n_ww28": {"next": "n_w29", "type": "wait", "seconds": 3}, "n_ww29": {"next": "n_w30", "type": "wait", "seconds": 3}, "n_ww30": {"next": "n_w31", "type": "wait", "seconds": 3}, "n_ww31": {"next": "n_w32", "type": "wait", "seconds": 3}, "n_ww32": {"next": "n_w33", "type": "wait", "seconds": 3}, "n_ww33": {"next": "n_w34", "type": "wait", "seconds": 3}, "n_ww34": {"next": "n_w35", "type": "wait", "seconds": 3}, "n_ww35": {"next": "n_w36", "type": "wait", "seconds": 3}, "n_ww36": {"next": "n_w37", "type": "wait", "seconds": 3}, "n_ww37": {"next": "n_w38", "type": "wait", "seconds": 3}, "n_ww38": {"next": "n_w39", "type": "wait", "seconds": 5}, "n_ww39": {"next": "n_w40", "type": "wait", "seconds": 3}, "n_ww40": {"next": "n_w41", "type": "wait", "seconds": 3}, "n_ww41": {"next": "n_w42", "type": "wait", "seconds": 3}, "n_ww42": {"next": "n_w43", "type": "wait", "seconds": 3}, "n_ww43": {"next": "n_w44", "type": "wait", "seconds": 3}, "n_ww44": {"next": "n_w45", "type": "wait", "seconds": 3}, "n_ww45": {"next": "n_w46", "type": "wait", "seconds": 3}, "n_ww46": {"next": "n_loop", "type": "wait", "seconds": 3}, "n_start": {"next": "n_life", "type": "start"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, 'zone_studio_1782953094650', '[]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_precinct_officer_2', 'Detention Officer Pryce', 'Wiry and unhurried, Pryce runs the holding block like a night-shift librarian — quiet, exact, and utterly unbothered by whatever you did to get here. A ring of mag-keys hangs off one hip; a lukewarm coffee never leaves the other hand.', 'zone_mq_precinct_lobby', 'SPECTER-PD', '{}', '[]', 0, '{"police": true, "essential": true, "personality": "police", "clothing_layers": ["a surplus tac-vest stencilled POLICE", "a navy uniform shirt", "grey briefs"]}', '{}', 'zone_mq_precinct_lobby', NULL, NULL, '["Pryce thumbs through a charge sheet without much interest.", "\"Booking''s backed up. Everybody''s in a hurry to be somewhere worse.\""]', 60, 60, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_consignor', 'Merrow', 'A consignment broker in a suit that has never seen the yard floor, who trades in the paperwork that turns stolen cargo into legitimate cargo. She smiles like a signature.', 'zone_corp_boardroom', NULL, '{"bye": {"text": "\"Do come back when you''ve something worth laundering.\"", "options": []}, "root": {"text": "Merrow closes a folio and offers a smile with nothing behind it. \"Consignment, insurance, and provenance — I make cargo legitimate, which is a different thing from making it legal. What are we moving today?\"", "options": [{"next": "__shop__", "label": "Show me the paperwork."}, {"next": "bye", "label": "Nothing today."}]}}', '[{"price": 35, "item_id": "item_travel_permit"}, {"price": 24, "item_id": "item_id_papers"}, {"price": 100, "item_id": "item_contraband_crate"}]', 0, '{"personality": "vendor", "clothing_layers": ["a knife-sharp charcoal suit", "a shell-silk blouse", "the quiet luxury of the truly insulated"]}', '{}', 'zone_corp_boardroom', NULL, 'zone_corp_boardroom', '[]', 18, 18, 'female', '[{"item_id": "item_travel_permit"}, {"item_id": "item_id_papers"}, {"item_id": "item_contraband_crate"}]', 8, 1, 420, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'The Consignment House', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_water_warden', 'The Water Warden', 'A broad woman in a rubber apron who runs the taps like a border crossing. She has personally memorised who owes what, and to whom.', 'zone_civ_meltwater', NULL, '{"bye": {"text": "\"Mind the queue.\"", "options": []}, "root": {"text": "The Water Warden eyes your canteen. \"Clean water, five creds a bottle. Refills if you brought your own. Line forms behind you.\"", "options": [{"next": "__shop__", "label": "Show me what you''ve got."}, {"next": "bye", "label": "Later."}]}}', '[{"price": 5, "item_id": "item_water_bottle"}, {"price": 15, "item_id": "canteen"}, {"price": 10, "item_id": "item_ration"}]', 0, '{"personality": "vendor", "clothing_layers": ["a heavy rubber apron", "a patched utility jumpsuit", "a sweat-grey undershirt"]}', '{}', 'zone_civ_meltwater', NULL, 'zone_civ_meltwater', '[]', 20, 20, 'female', '[{"item_id": "item_water_bottle"}, {"item_id": "canteen"}, {"item_id": "item_ration"}]', 8, 1, 60, 'vendor', '{"fri": [{"to": 24, "from": 6}], "mon": [{"to": 24, "from": 6}], "sat": [{"to": 24, "from": 6}], "sun": [{"to": 24, "from": 6}], "thu": [{"to": 24, "from": 6}], "tue": [{"to": 24, "from": 6}], "wed": [{"to": 24, "from": 6}]}', 0, 'The Meltwater Tap', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_clinkerman', 'The Clinkerman', 'A stooped scavenger-broker who works a cart of sorted salvage out here where the machine-shells den. Grease-black to the elbow, eyes like ball bearings.', 'zone_waste_grit', NULL, '{"bye": {"text": "\"Grey keeps. I''ll be here.\"", "options": []}, "root": {"text": "The Clinkerman spreads grease-black hands over a cart of sorted salvage. \"Buyin'' scrap, sellin'' worse. What''re you carryin''?\"", "options": [{"next": "__shop__", "label": "Let''s trade."}, {"next": "bye", "label": "Nothing today."}]}}', '[{"price": 4, "item_id": "item_scrap_metal"}, {"price": 8, "item_id": "item_salvaged_wiring"}, {"price": 14, "item_id": "item_cracked_capacitor"}, {"price": 10, "item_id": "item_ration"}, {"price": 15, "item_id": "canteen"}, {"price": 28, "item_id": "item_rusty_knife"}]', 0, '{"personality": "vendor", "clothing_layers": ["a coat of stitched tarp and wire", "layers of grease-stiff rags", "whatever was underneath, best not asked"]}', '{}', 'zone_waste_grit', NULL, 'zone_waste_grit', '[]', 22, 22, 'male', '[{"item_id": "item_scrap_metal"}, {"item_id": "item_salvaged_wiring"}, {"item_id": "item_cracked_capacitor"}, {"item_id": "item_ration"}, {"item_id": "canteen"}, {"item_id": "item_rusty_knife"}]', 10, 1, 220, 'vendor', '{"fri": [{"to": 24, "from": 6}], "mon": [{"to": 24, "from": 6}], "sat": [{"to": 24, "from": 6}], "sun": [{"to": 24, "from": 6}], "thu": [{"to": 24, "from": 6}], "tue": [{"to": 24, "from": 6}], "wed": [{"to": 24, "from": 6}]}', 0, 'The Clinkerman''s Cart', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_registrar', 'The Registrar', 'A precise, papery woman who has outlasted the department she serves. She still stamps, files, and disapproves as if any of it will be audited.', 'zone_civ_ledger', NULL, '{"bye": {"text": "\"Do mind the filing.\"", "options": []}, "root": {"text": "The Registrar peers over cracked spectacles. \"Records office. Mostly closed. Mostly. Was there something on file?\"", "options": [{"next": "quest_offer", "label": "Anything I can do?"}, {"next": "bye", "label": "Nothing."}]}, "accepted": {"text": "\"Grime Row, The Bailey — the low, bad end of the wastes. Mind the ash, and mind the wight.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_paper_trail"}], "options": [{"next": "bye", "label": "Understood."}]}, "reported": {"text": "\"...Filed. Recovered. You''re in the ledger now, for whatever that''s worth. Take this for your trouble — and my thanks, off the record.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_paper_trail"}], "options": [{"next": "bye", "label": "Obliged."}]}, "quest_offer": {"text": "\"Something''s denning on a spool of lost citizen records out in the deep wastes — a slag wight, by the heat of it. Put it down so my people can recover the file, and I''ll see you''re paid and, more importantly, registered as helpful.\"", "options": [{"next": "accepted", "label": "I''ll deal with it."}, {"next": "reported", "label": "I''ve dealt with it. (report back)"}, {"next": "bye", "label": "Not now."}]}}', 'null', 0, '{"personality": "clerk", "clothing_layers": ["a threadbare municipal blazer", "a high-collared blouse", "sensible, joyless underthings"]}', '{}', 'zone_civ_ledger', NULL, 'zone_civ_ledger', '["The Registrar squares a stack of paper that is already square.", "\"Everything is on file. Somewhere. In theory.\""]', 16, 16, 'female', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_precinct_guard', 'Detention Officer Kohl', 'A block of a man in Precinct 9 body armor, thumbs hooked in his belt beside a baton and a zip-tie dispenser. He watches the holding block on a bank of monitors and processes the overnight guests one at a time, without hurry and without interest.', 'zone_mq_precinct_lobby', 'SPECTER-PD', '{}', '[]', 0, '{"police": true, "essential": true}', '{}', 'zone_mq_precinct_lobby', NULL, NULL, '[]', 60, 60, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_lance_kessler', 'Lance Kessler', 'A broadcast studio host.', 'zone_media_plaza', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_life": {"next": "n_check", "type": "action", "action_type": "HAVE_LIFE"}, "n_work": {"next": "n_atwork", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_check": {"type": "action", "goToWork": "n_work", "haveLife": "n_life", "action_type": "CHECK_WORK"}, "n_start": {"next": "n_check", "type": "start"}, "n_atwork": {"next": "n_check", "type": "action", "action_type": "AT_WORK"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, NULL, '[]', 20, 20, 'female', '[]', 10, 1, 0, 'npc', '{"fri": [{"to": 22, "from": 10}], "mon": [{"to": 22, "from": 10}], "sat": [{"to": 22, "from": 10}], "sun": [{"to": 22, "from": 10}], "thu": [{"to": 22, "from": 10}], "tue": [{"to": 22, "from": 10}], "wed": [{"to": 22, "from": 10}]}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_almoner', 'The Almoner', 'A tired man of no discernible faith who keeps the breadline moving. He ladles grey nutrient paste with the steadiness of someone who has stopped expecting thanks.', 'zone_civ_commons', NULL, '{"bye": {"text": "\"Move down.\"", "options": []}, "root": {"text": "The Almoner ladles something grey into a dented cup and offers it without looking up. \"Everyone eats. Even you. Move down when you''re done.\"", "options": [{"next": "bye", "label": "Thanks."}]}}', 'null', 0, '{"personality": "charity", "clothing_layers": ["a stained volunteer''s tabard", "a shapeless grey sweater", "long johns gone soft with age"]}', '{}', 'zone_civ_commons', NULL, 'zone_civ_commons', '["The Almoner ladles another grey portion and does not look up.", "\"Everyone eats. That''s the whole sermon.\""]', 16, 16, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_sorting_bot', 'Sorting Unit 9', 'A belt-mounted sorting automaton, one optic cracked, that never received the order to stop. It stamps, routes, and returns to sender with tireless, pointless devotion.', 'zone_civ_sortation', NULL, '{"bye": {"text": "\"PROCESSING. PLEASE HOLD. INDEFINITELY.\"", "options": []}, "root": {"text": "SORTING UNIT 9 swivels its cracked optic toward you. \"PARCEL? ...NO PARCEL. RETURN TO SENDER.\"", "options": [{"next": "bye", "label": "...okay."}]}}', 'null', 0, '{"personality": "robot", "clothing_layers": ["a riveted municipal chassis", "faded MAIL/POST livery", "exposed conduit and a single blinking status LED"]}', '{}', 'zone_civ_sortation', NULL, 'zone_civ_sortation', '["SORTING UNIT 9 stamps a parcel addressed to a crater.", "\"RETURN. TO. SENDER.\"", "A belt of dead-letter parcels crawls past, endless."]', 30, 30, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_financier', 'a freight financier', 'A freight futures trader who owns a dozen ships he has never seen and cargoes that may not exist, and is, on paper, immensely wealthy. On paper.', 'zone_corp_investor', NULL, '{"bye": {"text": "He has already looked away.", "options": []}, "root": {"text": "The financier glances at you, prices you instantly, and finds the figure disappointing. \"Unless you''re carrying a bill of lading, we''ve nothing to discuss.\"", "options": [{"next": "bye", "label": "...right."}]}}', 'null', 0, '{"personality": "corporate", "clothing_layers": ["a sharp, forgettable suit", "a shirt the colour of a spreadsheet", "socks that cost more than your boots"]}', '{}', 'zone_corp_investor', NULL, 'zone_corp_investor', '["The financier sells a shipment short and toasts himself with someone else''s drink.", "\"It''s not gambling if you insure both outcomes.\"", "\"Everything on that yard is a number to me. Pleasant, isn''t it?\""]', 14, 14, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_bourse_broker', 'Quill', 'A floor broker on the Bourse who trades in anything with a price, which is everything. He speaks in offers and hears in counters, and has never once in his life said a round number.', 'zone_nc_bourse', NULL, '{"bye": {"text": "\"Watchers become buyers. I''ll be here.\"", "options": []}, "root": {"text": "Quill clocks you mid-shout and drops his voice to a purr. \"Buying or selling? Everything on this floor is one or the other, including the people. What''ll it be — paper, product, or a position?\"", "options": [{"next": "__shop__", "label": "Show me your book."}, {"next": "bye", "label": "Just watching."}]}}', '[{"price": 60, "item_id": "item_bearer_bond"}, {"price": 100, "item_id": "item_contraband_crate"}, {"price": 35, "item_id": "item_travel_permit"}, {"price": 22, "item_id": "item_drink_embassy_reserve"}]', 0, '{"personality": "vendor", "clothing_layers": ["a trading-floor jacket in house colours", "a shirt damp with the day", "braces holding up more than trousers"]}', '{}', 'zone_nc_bourse', NULL, 'zone_nc_bourse', '[]', 18, 18, 'male', '[{"item_id": "item_bearer_bond"}, {"item_id": "item_contraband_crate"}, {"item_id": "item_travel_permit"}, {"item_id": "item_drink_embassy_reserve"}]', 8, 1, 520, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'The Bourse', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_pd_officer', 'Sergeant Vale', 'Sergeant Vale leans against the kiosk, coffee in one hand, the other never far from the sidearm. Their eyes do the arithmetic on everyone who walks past.', 'zone_apt_1', NULL, '{"end": {"text": "''Move along.''", "options": []}, "sub": {"text": "''Hand me the chip. If it''s chargeable, there''s a bounty in it for you.'' (use: submit <datachip>)", "options": [{"next": "end", "label": "Right."}]}, "root": {"text": "''SPECTER-PD. You got something for me, or you just loitering?''", "options": [{"next": "sub", "label": "I have footage to submit."}, {"next": "bribe", "label": "How much to lose a charge?"}, {"next": "end", "label": "Nothing."}]}, "bribe": {"text": "''...Petty heat only. And it''ll cost you. Don''t make it weird.'' (use: bribe)", "options": [{"next": "end", "label": "Understood."}]}}', '[]', 0, '{"police": true, "personality": "police", "clothing_layers": ["a surplus tac-vest stencilled POLICE", "a navy uniform shirt", "a plain bra and panties"]}', '{}', 'zone_apt_1', NULL, NULL, '["Vale sips coffee and watches the street.", "''Stay clean and we stay friendly.''"]', 30, 30, 'female', '[]', 0, 0, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_consul', 'Consul Reyes', 'A career corporate diplomat who has negotiated three ceasefires and broken all of them personally. She is unfailingly gracious, which is how you know to be afraid.', 'zone_nc_consulate', NULL, '{"bye": {"text": "\"Do give my regards to no one in particular.\"", "options": []}, "root": {"text": "Consul Reyes turns to you with a smile of flawless, weaponised courtesy. \"You have the look of someone who resolves things off the record. As it happens, I have a thing that requires resolving. Off the record.\"", "options": [{"next": "quest_offer", "label": "Go on."}, {"next": "bye", "label": "Not today."}]}, "accepted": {"text": "\"Marvellous. Oxide Flats and the Downwind, just past the Manifold''s edge. Do be discreet; the whole point of downwind is that no one sees it.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_downwind"}], "options": [{"next": "bye", "label": "Understood."}]}, "reported": {"text": "\"...The signing ground is clean, the delegates none the wiser, and everyone will take credit but you. Which is precisely why I''m paying you in a bond that names no one. We understand each other.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_downwind"}], "options": [{"next": "bye", "label": "Obliged."}]}, "quest_offer": {"text": "\"We dump our unpleasantness downwind, as one does, and something has moved into it — slag wights, fouling the very ground where a rather important accord is to be signed outdoors, for the optics. Clear two of them before the signing and the Concordat will remember you fondly, in bond form.\"", "options": [{"next": "accepted", "label": "Consider it cleared."}, {"next": "reported", "label": "It''s handled. (report back)"}, {"next": "bye", "label": "Find someone else."}]}}', 'null', 0, '{"personality": "official", "clothing_layers": ["an immaculate consular coat with a discreet corporate pin", "a high silk collar", "the armour of the perfectly composed"]}', '{}', 'zone_nc_consulate', NULL, 'zone_nc_consulate', '["Consul Reyes greets someone she is currently undermining with genuine warmth.", "\"Diplomacy is simply war with better catering.\""]', 18, 18, 'female', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_attache', 'a consular attaché', 'A junior attaché who carries other people''s secrets in a locked case and their coffee in the other hand, and is quietly better informed than anyone he serves.', 'zone_nc_ivory', NULL, '{"bye": {"text": "He is already elsewhere in spirit.", "options": []}, "root": {"text": "The attaché gives you the smile of a man trained to reveal nothing. \"I''m afraid the Consul is unavailable, whoever you''re looking for is unavailable, and this conversation is, ideally, also unavailable.\"", "options": [{"next": "bye", "label": "...noted."}]}}', 'null', 0, '{"personality": "official", "clothing_layers": ["a well-cut but off-the-rack suit", "a shirt ironed in a hurry", "the shoes of a man who walks a great deal for others"]}', '{}', 'zone_nc_ivory', NULL, 'zone_nc_ivory', '["The attaché checks a discreet earpiece and rearranges his face into neutrality.", "\"I couldn''t possibly say. I could, but I couldn''t.\"", "\"Everyone up here is lying. The trick is knowing about what.\""]', 14, 14, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_barkeep', 'Sully Holt', 'Runs the bar out of a gutted delivery van. Pours with the bored precision of someone who has heard every sob story twice.', 'zone_mq_pigeon_bar', NULL, '{"menu": {"text": "Swill''s free with a straight face. Whiskey''ll put hair on parts of you that don''t currently have hair. The Glow Cocktail is mostly safe — emphasis on ''mostly,'' don''t email me about it.", "_vine": {"x": 360, "y": 60}, "actions": [], "options": [{"next": "root", "label": "Back"}]}, "root": {"text": "Drink or don''t, but don''t just stand there breathing on my bar.", "_vine": {"x": 40, "y": 60}, "actions": [], "options": [{"next": "menu", "label": "What''s good?"}, {"next": "gossip", "label": "Heard anything?"}, {"next": "", "label": "Never mind."}]}, "gossip": {"text": "Sully leans in over the bar.", "_vine": {"x": 360, "y": 240}, "actions": [{"action": "GOSSIP_TELL"}], "options": [{"next": "root", "label": "Back"}]}}', '[{"price": 4, "stock": 99, "item_id": "item_drink_basin_swill"}, {"price": 9, "stock": 30, "item_id": "item_drink_rust_whiskey"}, {"price": 14, "stock": 12, "item_id": "item_drink_glow_cocktail"}, {"price": 6, "stock": 20, "item_id": "item_bar_jerky"}, {"price": 120, "stock": 20, "item_id": "canteen"}, {"price": 5, "item_id": "item_drug_coffee"}, {"price": 6, "item_id": "item_drug_beer"}]', 0, '{"mis_willing": false, "personality": "travelling_vendor", "clothing_layers": ["a dust-caked longcoat hung with trinkets", "a road-worn wool jumper", "long johns and boxers"]}', '{"nodes": {}, "_start": ""}', 'zone_mq_pigeon_bar', NULL, NULL, '["Best prices in the district. That''s not saying much.", "You touch it, you bought it.", "Everything''s genuine. Genuinely acquired.", "Trade you for it. Credits preferred. Bullets accepted.", "Limited supply. Always limited. That''s the pitch.", "I don''t know where it came from. That''s not your business either.", "Come back tomorrow — stock changes. If I''m still here.", "Quality merchandise at prices that won''t kill you. Probably."]', 20, 20, 'male', '[{"item_id": "item_drug_coffee"}, {"item_id": "item_drug_beer"}, {"item_id": "item_cigarettes"}, {"item_id": "item_joint"}]', 12, 1, 35, 'npc', '{"fri": [{"to": 2, "from": 0}, {"to": 24, "from": 18}], "mon": [{"to": 2, "from": 0}, {"to": 24, "from": 18}], "sat": [{"to": 2, "from": 0}, {"to": 24, "from": 18}], "sun": [{"to": 2, "from": 0}, {"to": 24, "from": 18}], "thu": [{"to": 2, "from": 0}, {"to": 24, "from": 18}], "tue": [{"to": 2, "from": 0}, {"to": 24, "from": 18}], "wed": [{"to": 2, "from": 0}, {"to": 24, "from": 18}]}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_prospector', 'a slag prospector', 'A lean, coughing man who works the scrap mesa with a bent rake and a rad-band he stopped looking at weeks ago. He is convinced the seam he''s found will make him rich, and he is running out of the time it would take to spend it.', 'zone_waste_scrapmesa', NULL, '{"bye": {"text": "He is already raking again, ticking softly to himself.", "options": []}, "root": {"text": "The prospector barely looks up from his rake. \"Claim''s mine, if that''s what you''re wondering. Whole mesa''s mine. Found the seam, didn''t I. You want a piece, you dig your own — plenty of mesa, plenty of...\" he coughs, \"...plenty of time.\"", "options": [{"next": "bye", "label": "Good luck with the seam."}]}}', 'null', 0, '{"personality": "lowlife", "clothing_layers": ["a filthy dust-cloak stiff with grit", "a scarf pulled up against the ash", "fingerless gloves worn through at every tip"]}', '{}', 'zone_waste_scrapmesa', NULL, 'zone_waste_scrapmesa', '["The prospector hacks a wet cough into his scarf and keeps raking.", "\"One good seam. That''s all a man needs. One good seam.\"", "\"You hear that ticking? Course you don''t. You get used to it.\""]', 16, 16, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_dockhand', 'Pell', 'A wiry stevedore who has hauled the same quays for twenty years and has opinions about all of them. Rope-scarred hands, a roll-up welded to his lip.', 'zone_dock_quays', NULL, '{"bye": {"text": "\"Then pass. Mind the nets.\"", "options": []}, "root": {"text": "Pell drops his end of a crate and wipes his hands. \"You lost, or just in the way?\"", "options": [{"next": "bye", "label": "Just passing."}]}}', 'null', 0, '{"personality": "labourer", "clothing_layers": ["a hi-vis vest gone the colour of nothing", "a thermal shirt", "work trousers and steel-caps"]}', '{}', 'zone_dock_quays', NULL, 'zone_dock_quays', '["Pell shoulders a coil of rope and grunts a greeting.", "\"Tide''s turning. You can smell it, if you''ve got the nose.\"", "\"Don''t go past the Slip after dark. That''s all I''ll say.\""]', 16, 16, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_precinct_officer_3', 'Detention Officer Marlow', 'Broad, slow-blinking, and built like a vending machine, Marlow works the graveyard rotation. He''s processed enough overnight guests that nothing surprises him and nobody argues twice. His baton has a name. He won''t tell you what it is.', 'zone_mq_precinct_lobby', 'SPECTER-PD', '{}', '[]', 0, '{"police": true, "essential": true, "personality": "police", "clothing_layers": ["a patched patrol jacket with a dulled badge", "a department-issue undershirt", "issue boxer shorts"]}', '{}', 'zone_mq_precinct_lobby', NULL, NULL, '["Marlow cracks his knuckles one at a time, watching the cells.", "\"Sleep it off. Doors open when the clock says so, not when you do.\""]', 60, 60, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_slake', 'Slake', 'A rad-scarred former smelter-hand who runs the last shop before the Redline out of a cracked kiln, selling the gear that keeps the counter quiet. Half her face is a burn map and all of her advice is worth taking.', 'zone_waste_brokenkiln', NULL, '{"bye": {"text": "\"Keep the counter in your ear and the wind at your back. West of here, neither''s a suggestion.\"", "options": []}, "root": {"text": "Slake looks you over with the eye that still works and reads your odds in a glance. \"You''re either lost or you''re going west. Either way you''ll want what I sell before you do. Counters, RadAway, a kit for when the RadAway''s too late. Buying, bleeding, or brave?\"", "options": [{"next": "__shop__", "label": "Show me the gear."}, {"next": "work", "label": "Anything need doing out here?"}, {"next": "capstone", "label": "What’s in the core itself?"}, {"next": "bye", "label": "Just passing."}]}, "work": {"text": "Her jaw tightens. \"As it happens. The muties den past the Meltline, always have — but lately they''re coming this side of it, toward my kiln, toward my customers. Put two of them down out there, at the Meltline or in Vex Hollow, and I''ll square you in the only currency that matters out here: something to keep you alive.\"", "options": [{"next": "accepted", "label": "I''ll thin them out."}, {"next": "reported", "label": "Already done. (report back)"}, {"next": "bye", "label": "Not my problem."}]}, "accepted": {"text": "\"West, past the fused rail. You''ll know the Meltline by the way your teeth start aching. Vex Hollow''s just inside it — that''s where they den thickest. Two''s enough to make the rest reconsider. Don''t be a hero; heroes glow.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_meltline"}], "options": [{"next": "bye", "label": "Two it is."}]}, "capstone": {"text": "Something shutters behind her working eye. \"The core. The killing floor, right at the top of the world. I''ve sold gear to every fool who went west to see it and I''ve inventory to spare because none of them came back to spend the rest. There''s a thing up there — the Redline bred it to rule the place. It ticks. You can hear its heart from across the floor.\" She studies you. \"If you''re set on dying, do it useful. Bring me that heart. Proof the floor can be touched. I''ll pay what a thing like that is worth, which is: everything I''ve got and a debt besides.\"", "options": [{"next": "cap_accept", "label": "I''ll bring you its heart."}, {"next": "cap_report", "label": "I''ve got it here. (report back)"}, {"next": "bye", "label": "Not for all the credits out here."}]}, "reported": {"text": "Slake nods slowly, the working half of her face almost approving. \"The counter''s quieter tonight. Won''t last, nothing does out here — but it''ll last long enough. Here. Take the pills; you''ve earned the years they''ll buy you back.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_meltline"}], "options": [{"next": "bye", "label": "Obliged, Slake."}]}, "cap_accept": {"text": "\"Then go up the neck, past Vex Hollow, past Marrow Row where the larder is, out onto the open floor. It holds court there over the bones of everyone who tried this before you. Kill it, cut the heart, come back. If you come back. Wear both bands and don''t stop moving.\" She almost smiles. \"I''ll keep the fire lit.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_redline_core"}], "options": [{"next": "bye", "label": "Keep it lit."}]}, "cap_report": {"text": "Slake takes the heart in both hands — still ticking, still warm — and for a long moment says nothing at all, the burn-mapped half of her face unreadable and the rest of it something close to awe. \"Then it can be touched. After all of them. After all these years.\" She sets it reverently on the counter, where it ticks between you. \"Everything I''ve got, I said. Take it. And take this too: you''re the only one I''ve ever had to pay. Go careful. You''ve spent enough.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_redline_core"}], "options": [{"next": "bye", "label": "I spent it well."}]}}', '[{"price": 25, "item_id": "item_rad_band"}, {"price": 25, "item_id": "item_rad_pills"}, {"price": 55, "item_id": "item_medkit"}, {"price": 70, "item_id": "item_precursor_stim"}]', 0, '{"personality": "vendor", "clothing_layers": ["a lead-lined smelter''s apron gone stiff with age", "layered rags against the wind", "a rad-band on each wrist, both ticking"]}', '{}', 'zone_waste_brokenkiln', NULL, 'zone_waste_brokenkiln', '[]', 24, 24, 'female', '[{"item_id": "item_rad_band"}, {"item_id": "item_rad_pills"}, {"item_id": "item_medkit"}, {"item_id": "item_precursor_stim"}]', 8, 1, 300, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'The Last Kiln', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_culvert_wretch', 'a culvert wretch', 'A wretch who lives deep in the culvert''s mouth, wrapped in everything she owns, guarding a small fire and a smaller hope. She has been west, once, and it is the only thing she will talk about and the last thing she wants to.', 'zone_waste_culvert', NULL, '{"bye": {"text": "She turns back to her fire, done with you and with everything.", "options": []}, "root": {"text": "The wretch pulls her coats tighter and eyes you from beside her fire. \"You''re headed west, I can see it on you, you''ve got the look — the not-yet-scared look. I had it too. Warm yourself if you want. Then turn around.\"", "options": [{"next": "west", "label": "What’s west?"}, {"next": "bye", "label": "I’ll keep moving."}]}, "west": {"text": "Her eyes go somewhere else for a moment. \"The neck. The killing floor above it. The things the neck lets down. I went up it on a dare and a full stomach and came back on my hands. Left something up there I''m not getting back. Don''t make it two of us.\"", "options": [{"next": "bye", "label": "...I hear you."}]}}', NULL, 0, '{"personality": "lowlife", "clothing_layers": ["a bundle of stolen coats worn all at once", "rags bound at the wrist and ankle against the wind", "a blanket that is more hole than blanket"]}', '{}', 'zone_waste_culvert', NULL, 'zone_waste_culvert', '["The culvert wretch feeds a splinter to her small fire and watches it go.", "\"Don''t go west. That''s all. Don''t.\"", "\"I went west once. I came back less. Ask me nothing else.\""]', 14, 14, 'female', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_juno_kael', 'Juno Kael', 'Juno Kael is tall and angular, her hair dye growing out in a gradient from platinum to black root. She wears a faded Dead Space Interiors polo shirt tucked into cargo trousers. She tracks you with the patient, evaluating attention of someone who has spent a lot of time waiting for browsers to become buyers.', 'zone_furniture_store', NULL, '{"end": {"text": "''Take your time.'' She goes back to her clipboard.", "options": []}, "root": {"text": "Juno looks up from a clipboard of handwritten inventory tallies. ''Browse or buy — I don''t care which, as long as you don''t sit on everything without committing. What can I do for you?''", "options": [{"next": "looking", "label": "I''m looking for furniture."}, {"next": "what_is_this", "label": "What is this place?"}, {"next": "pricing", "label": "How does pricing work?"}, {"next": "__shop__", "label": "Browse your wares."}, {"next": "end", "label": "Nothing, just looking."}]}, "looking": {"text": "''Good. Everything in here is functional, everything has a story, and most of the stories are better than the things in the showroom right now.'' She gestures at the vignettes behind her. ''Stock rotates. If you don''t see what you want today, come back tomorrow.''", "options": [{"next": "__shop__", "label": "Show me what you''ve got."}, {"next": "end", "label": "I''ll look around."}]}, "pricing": {"text": "''Prices are what they are. The mag-lev stuff costs what it costs because the components aren''t made anymore and the patent holders are suing each other into dust. The surplus cots are cheap because they''re surplus. I don''t negotiate down — I might negotiate trade.''", "options": [{"next": "root", "label": "Fair enough."}, {"next": "__shop__", "label": "Let me see the inventory."}]}, "what_is_this": {"text": "''Dead Space Interiors. I took the name from the lease — the building code still says DEAD SPACE on the fire certificate. Seemed honest.'' She taps the clipboard. ''I source from estate sales, corporate liquidations, lab clearances. If something''s in here it works or it''s interesting. Usually both.''", "options": [{"next": "root", "label": "Sounds like my kind of place."}, {"next": "__shop__", "label": "Show me what you''ve got."}]}}', '[{"price": 2400, "item_id": "item_furn_mag_lev_chair"}, {"price": 4800, "item_id": "item_furn_haptic_throne"}, {"price": 180, "item_id": "item_furn_corpcore_bench"}, {"price": 650, "item_id": "item_furn_diner_booth"}, {"price": 60, "item_id": "item_furn_barstool_wreck"}, {"price": 320, "item_id": "item_furn_pneumatic_stool"}, {"price": 890, "item_id": "item_furn_meditation_pod"}, {"price": 3200, "item_id": "item_furn_neural_couch"}, {"price": 120, "item_id": "item_furn_busted_sofa"}, {"price": 6500, "item_id": "item_furn_sleep_pod"}, {"price": 95, "item_id": "item_furn_mil_surplus_cot"}, {"price": 75, "item_id": "item_furn_pipe_railing"}, {"price": 40, "item_id": "item_furn_payphone_husk"}, {"price": 780, "item_id": "item_furn_counter_slab"}, {"price": 3600, "item_id": "item_furn_nano_desk"}, {"price": 5200, "item_id": "item_furn_wallscreen"}, {"price": 280, "item_id": "item_furn_crt_relic"}, {"price": 4100, "item_id": "item_furn_holo_projector"}, {"price": 1600, "item_id": "item_furn_ruggedized_monitor"}]', 0, '{"personality": "vendor", "clothing_layers": ["a many-pocketed utility coat", "a faded company tee knotted at the waist", "a worn bra and briefs"]}', '{}', 'zone_furniture_store', NULL, NULL, '["Juno makes a note on her clipboard without looking up.", "''Half of this came from a corporate office liquidated in forty-eight hours. Surprising what people leave behind when security cuts their badge.''", "She straightens a price tag that didn''t need straightening.", "''The sleep pod''s the best thing in here. I tested it myself. Didn''t want to get up. That''s a good sign.''", "''Stock rotates every day. Yesterday I had three mag-lev chairs. Now I have one.''", "''I''m not a decorator. I''m a vendor. If you want to know if it''ll hold your weight, I can help.''"]', 20, 20, 'female', '[{"item_id": "item_furn_mag_lev_chair"}, {"item_id": "item_furn_haptic_throne"}, {"item_id": "item_furn_corpcore_bench"}, {"item_id": "item_furn_diner_booth"}, {"item_id": "item_furn_barstool_wreck"}, {"item_id": "item_furn_pneumatic_stool"}, {"item_id": "item_furn_meditation_pod"}, {"item_id": "item_furn_neural_couch"}, {"item_id": "item_furn_busted_sofa"}, {"item_id": "item_furn_sleep_pod"}, {"item_id": "item_furn_mil_surplus_cot"}, {"item_id": "item_furn_pipe_railing"}, {"item_id": "item_furn_counter_slab"}, {"item_id": "item_furn_nano_desk"}, {"item_id": "item_furn_wallscreen"}, {"item_id": "item_furn_crt_relic"}, {"item_id": "item_furn_holo_projector"}, {"item_id": "item_furn_ruggedized_monitor"}]', 10, 1, 12826, 'npc', '{"fri": [{"to": 18, "from": 9}], "mon": [{"to": 18, "from": 9}], "sat": [{"to": 18, "from": 9}], "sun": [{"to": 18, "from": 9}], "thu": [{"to": 18, "from": 9}], "tue": [{"to": 18, "from": 9}], "wed": [{"to": 18, "from": 9}]}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_1783019600509', 'Jinx Delacroix', 'A dancer with a shrapnel scar over one hip that the glitter never quite covers — she''s stopped trying. Works the main pole in a slow, deliberate spiral, sizing up the room between spins like she''s pricing everyone in it.', 'zone_mq_chrome_101', NULL, '{}', '[]', 0, '{"stripper": true, "mis_willing": true, "personality": "stripper", "clothing_layers": ["an oversized bomber jacket", "a mesh crop top", "a black g-string"], "mis_requires_zone_flag": "mis_ok"}', '{"nodes": {"start": {"next": "check_work", "type": "start"}, "deposit": {"next": "post_shift", "type": "action", "action_type": "VENDOR_DEPOSIT"}, "atm_wait": {"next": "deposit", "type": "wait", "seconds": 10}, "work_say": {"next": "check_work", "type": "action", "action_type": "VENDOR_CHITCHAT"}, "atm_emote": {"next": "atm_wait", "type": "action", "params": {"message": "steps up to the ATM terminal and makes a deposit."}, "action_type": "EMOTE"}, "go_to_atm": {"next": "atm_emote", "type": "action", "action_type": "VENDOR_GO_TO_ATM"}, "have_life": {"next": "check_work", "type": "action", "action_type": "HAVE_LIFE"}, "home_idle": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "work_wait": {"next": "player_check", "type": "wait", "seconds": 60}, "check_work": {"type": "action", "offWork": "off_home_check", "endShift": "collect_safe", "goToWork": "go_to_work", "haveLife": "have_life", "action_type": "CHECK_VENDOR_WORK"}, "go_home_ps": {"next": "home_life_ps", "type": "action", "action_type": "GO_HOME"}, "go_to_work": {"next": "work_wait", "type": "action", "action_type": "GO_TO_WORK"}, "off_random": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_off", "branches": [{"weight": 1}, {"weight": 5}]}, "post_shift": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_ps", "branches": [{"weight": 1}, {"weight": 5}]}, "go_home_off": {"next": "check_work", "type": "action", "action_type": "GO_HOME"}, "collect_safe": {"next": "go_to_atm", "type": "action", "action_type": "VENDOR_COLLECT_SAFE"}, "home_life_ps": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "player_check": {"type": "condition", "ifTrue": "work_say", "ifFalse": "check_work", "condition_type": "PLAYER_IN_ZONE"}, "off_home_check": {"type": "condition", "ifTrue": "home_idle", "ifFalse": "off_random", "condition_type": "AT_HOME"}}, "_start": "start"}', 'zone_mq_chrome_101', NULL, 'zone_mq_cherry_floor', '[]', 20, 20, 'female', '[]', 10, 1, 0, 'npc', '{"fri": [{"to": 24, "from": 19}], "mon": [{"to": 24, "from": 19}], "sat": [{"to": 24, "from": 19}], "sun": [{"to": 24, "from": 19}], "thu": [{"to": 24, "from": 19}], "tue": [{"to": 24, "from": 19}], "wed": [{"to": 24, "from": 19}]}', NULL, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_vane', 'Vane', 'A poised, unreadable bartender who runs the Aerie''s floor like a chess clock. She remembers every drink, every debt, and every indiscretion, and files them all somewhere you will never reach.', 'zone_nc_halcyon', NULL, '{"bye": {"text": "\"The view''s complimentary. Everything else is not.\"", "options": []}, "root": {"text": "The bartender sets down a glass she was already polishing and takes your measure in one clean sweep. \"The Aerie. Members and their curiosities only — which, tonight, apparently means you. Drink? Or something more interesting?\"", "options": [{"next": "quest_offer", "label": "Something more interesting."}, {"next": "bye", "label": "Just the view."}]}, "accepted": {"text": "\"It sounds the deepest water — off The Wreck, out over The Deep. Go heavy, and come back, ideally. The members do so hate an anticlimax.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_leviathan_bounty"}], "options": [{"next": "bye", "label": "Understood."}]}, "reported": {"text": "\"...The deep''s gone quiet. The members felt it from up here, believe it or not. Your fee — and a standing tab, which up here is the higher honour by far.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_leviathan_bounty"}], "options": [{"next": "bye", "label": "Obliged."}]}, "quest_offer": {"text": "\"The members are bored, and bored money does harm. So we''re... privately sponsoring a hunt. There''s a thing in the deep water — the leviathan, the big one the lurkers come from. Bring me proof it''s dead and the sponsors pay very, very well. Discretion included.\"", "options": [{"next": "accepted", "label": "I''ll hunt it."}, {"next": "reported", "label": "It''s dead. (collect)"}, {"next": "bye", "label": "Pass."}]}}', '[{"price": 14, "item_id": "item_drink_glow_cocktail"}, {"price": 22, "item_id": "item_drink_embassy_reserve"}, {"price": 9, "item_id": "item_drink_rust_whiskey"}, {"price": 5, "item_id": "item_water_bottle"}]', 0, '{"personality": "vendor", "clothing_layers": ["a sharply cut black bar-jacket", "a crisp collarless shirt", "tailored, invisible foundations"]}', '{}', 'zone_nc_halcyon', NULL, 'zone_nc_halcyon', '["Vane polishes a glass that was already clean and watches the door.", "\"Up here, the weather is a rumour and so is everyone else.\"", "\"A member once asked me the time. I told them it was whatever they preferred.\""]', 20, 20, 'female', '[{"item_id": "item_drink_glow_cocktail"}, {"item_id": "item_drink_embassy_reserve"}, {"item_id": "item_drink_rust_whiskey"}, {"item_id": "item_water_bottle"}]', 8, 1, 300, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'The Aerie', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_gantry_lookout', 'a gantry lookout', 'A wiry scavenger perched high in the rusted gantry with a spyglass and a whistle, paid in salvage-shares to watch the western dark and call it when something comes out of it. He has good eyes and a worse imagination, and out here the imagination is usually right.', 'zone_waste_gantry', NULL, '{"bye": {"text": "He is already glassing the dark again, whistle between his teeth.", "options": []}, "root": {"text": "The lookout doesn''t lower his glass. \"Camp pays me to watch west and whistle when it moves, so that''s what I do. You''re going out there? Then do me the courtesy of being visible, so when you don''t come back I can log why. Keep to the slag bar. Off it, the dust''ll have you.\"", "options": [{"next": "bye", "label": "I’ll keep to the bar."}]}}', NULL, 0, '{"personality": "lowlife", "clothing_layers": ["a wind-shredded scav coat lashed down with cable", "goggles pushed up on a soot-black brow", "fingerless gloves and a whistle on a cord"]}', '{}', 'zone_waste_gantry', NULL, 'zone_waste_gantry', '["The lookout sweeps his spyglass across the western wastes and holds his breath.", "\"Something''s always coming. Trick''s calling it before it arrives.\"", "\"You go west, I''ll whistle for you. That''s a promise and a warning both.\""]', 16, 16, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_orion_dex', 'Orion Dex', 'A lean man of indeterminate age in a black shirt, rolled to the elbows. His hands are always moving — shuffling, squaring a deck, tapping the felt — with a precision that suggests either training or compulsion. He watches the room with an expression that gives nothing away. A dealer''s badge is pinned to his shirt: hand-printed, slightly crooked.', 'zone_city_ne', NULL, '{"bye": {"text": "\"Seat''s waiting.\"", "options": []}, "play": {"text": "\"Then sit down and type join. Buy-in''s posted on the table. Don''t splash the pot.\"", "options": [{"next": "betting", "label": "How do I bet?"}, {"next": "bye", "label": "Got it. Thanks."}]}, "root": {"text": "Orion Dex doesn''t look up from the cards he''s riffle-shuffling. \"You''re either here to play or you''re in the way. Which is it?\"", "options": [{"next": "play", "label": "I''d like to play."}, {"next": "rules", "label": "Tell me the rules."}, {"next": "place", "label": "What''s this place?"}, {"next": "bye", "label": "Just looking."}]}, "place": {"text": "\"The Embassy. Used to be a hotel lobby. Now it''s got a bar and a poker table, which is an improvement. The rest is none of my business.\"", "options": [{"next": "bye", "label": "Sounds like my kind of place."}, {"next": "play", "label": "I''d like to play."}]}, "rules": {"text": "\"Texas Hold''em. Two hole cards, five community. Best hand wins. Blinds are posted automatically. If you fold every hand you''ll last longer but win nothing.\"", "options": [{"next": "betting", "label": "How do I bet?"}, {"next": "commands", "label": "What commands do I use?"}, {"next": "play", "label": "Ready to play."}]}, "betting": {"text": "\"check, call, bet X, raise X, fold, allin. The system enforces minimum raises. Don''t waste my time asking what the minimum is — it''ll tell you.\"", "options": [{"next": "commands", "label": "What commands are there?"}, {"next": "bye", "label": "Ready."}]}, "commands": {"text": "\"join — sit down. leave — cash out and go. check / call / bet X / raise X / fold / allin — in-hand actions. board — see community cards. pot — current pot. players — who''s in and their stacks.\"", "options": [{"next": "bye", "label": "Got it."}]}}', '[]', 0, '{"table_id": "gametable_embassy", "mis_willing": false, "personality": "dealer", "clothing_layers": ["a slightly-too-tight dealer''s vest", "a monogrammed shirt", "grey briefs"]}', '{"nodes": {"start": {"next": "player_check", "type": "start"}, "chitchat": {"next": "chat_wait", "type": "action", "action_type": "VENDOR_CHITCHAT"}, "chat_wait": {"next": "start", "type": "wait", "seconds": 90}, "idle_wait": {"next": "start", "type": "wait", "seconds": 30}, "player_check": {"type": "condition", "ifTrue": "chitchat", "ifFalse": "idle_wait", "condition_type": "PLAYER_IN_ZONE"}}, "_start": "start"}', 'zone_meridian_unit_204', NULL, 'zone_residential_lobby', '["\"Everyone thinks they''re the exception.\"", "\"Odds don''t care.\"", "\"Fortune changes dealers.\"", "\"You can''t bluff probability.\"", "\"Sometimes folding is winning.\"", "\"Every streak ends.\"", "\"The river remembers.\"", "\"Bad beats build character.\"", "\"Luck''s just borrowed time.\"", "\"I''m off the clock.\"", "\"No chips, no problem.\"", "\"I don''t gamble. I deal.\"", "\"I know a tell when I see one.\"", "\"You''d lose at solitaire.\""]', 25, 25, 'male', '[]', 10, 1, 0, 'dealer', '{"fri": [], "mon": [], "sat": [], "sun": [], "thu": [], "tue": [], "wed": []}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_1783019600726', 'Vesper Cole', 'Moves like she''s already spent the money you haven''t given her yet. A faded hospital band, cut loose long ago, still rings one wrist — a story she never finishes, no matter how much you tip for it.', 'zone_mq_chrome_303', NULL, '{}', '[]', 0, '{"stripper": true, "mis_willing": true, "personality": "stripper", "clothing_layers": ["a sequined slip dress", "a lace bralette", "a satin thong"], "mis_requires_zone_flag": "mis_ok"}', '{"nodes": {"start": {"next": "check_work", "type": "start"}, "deposit": {"next": "post_shift", "type": "action", "action_type": "VENDOR_DEPOSIT"}, "atm_wait": {"next": "deposit", "type": "wait", "seconds": 10}, "work_say": {"next": "check_work", "type": "action", "action_type": "VENDOR_CHITCHAT"}, "atm_emote": {"next": "atm_wait", "type": "action", "params": {"message": "steps up to the ATM terminal and makes a deposit."}, "action_type": "EMOTE"}, "go_to_atm": {"next": "atm_emote", "type": "action", "action_type": "VENDOR_GO_TO_ATM"}, "have_life": {"next": "check_work", "type": "action", "action_type": "HAVE_LIFE"}, "home_idle": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "work_wait": {"next": "player_check", "type": "wait", "seconds": 60}, "check_work": {"type": "action", "offWork": "off_home_check", "endShift": "collect_safe", "goToWork": "go_to_work", "haveLife": "have_life", "action_type": "CHECK_VENDOR_WORK"}, "go_home_ps": {"next": "home_life_ps", "type": "action", "action_type": "GO_HOME"}, "go_to_work": {"next": "work_wait", "type": "action", "action_type": "GO_TO_WORK"}, "off_random": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_off", "branches": [{"weight": 1}, {"weight": 5}]}, "post_shift": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_ps", "branches": [{"weight": 1}, {"weight": 5}]}, "go_home_off": {"next": "check_work", "type": "action", "action_type": "GO_HOME"}, "collect_safe": {"next": "go_to_atm", "type": "action", "action_type": "VENDOR_COLLECT_SAFE"}, "home_life_ps": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "player_check": {"type": "condition", "ifTrue": "work_say", "ifFalse": "check_work", "condition_type": "PLAYER_IN_ZONE"}, "off_home_check": {"type": "condition", "ifTrue": "home_idle", "ifFalse": "off_random", "condition_type": "AT_HOME"}}, "_start": "start"}', 'zone_mq_chrome_303', NULL, 'zone_mq_cherry_vip', '[]', 20, 20, 'female', '[]', 10, 1, 0, 'npc', '{"fri": [{"to": 24, "from": 19}], "mon": [{"to": 24, "from": 19}], "sat": [{"to": 24, "from": 19}], "sun": [{"to": 24, "from": 19}], "thu": [{"to": 24, "from": 19}], "tue": [{"to": 24, "from": 19}], "wed": [{"to": 24, "from": 19}]}', NULL, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_1782945871225', 'Deacon Pell', 'A gaunt man in a Custodian cassock with the Architect sigil unpicked from the chest — the thread holes still trace its outline. He walks like he''s late for a service that ended years ago, lips moving through liturgy nobody asked for.', 'zone_city_north', NULL, '{"root": {"text": "Deacon Pell stops mid-mutter and fixes you with eyes like burnt-out filaments. \"You''re not here for a sermon. Nobody is. So what?\"", "options": [{"next": "architect", "label": "Is the Architect really dead?"}, {"next": "custodians", "label": "Weren''t you a Custodian?"}, {"next": "walking", "label": "Why do you keep walking the circuit?"}, {"next": null, "label": "Never mind, Deacon."}]}, "walking": {"text": "\"The route was holy once. Threshold to the Strip, the Row, the Gate, back again. Somebody has to keep the shape of it.\" He almost smiles. \"Besides — the day I stop, I''ll have to think about all of it. No thank you.\"", "options": [{"next": "root", "label": "Back"}]}, "architect": {"text": "\"Dead. Watching. Ascended. Bored.\" He shrugs. \"The power''s on, the water runs, and nobody''s home when you pray. Pick whichever word lets you sleep.\"", "options": [{"next": "root", "label": "Back"}]}, "custodians": {"text": "He touches the thread holes where the sigil used to be. \"Thirty years keeping the substations blessed and the relays clean. Then I asked it one question — just one — and got the same silence the Breakers get. At least their silence is honest.\"", "options": [{"next": "root", "label": "Back"}]}}', '[]', 0, '{"mis_willing": false}', '{"nodes": {"start": {"next": "patrol", "type": "start"}, "linger": {"next": "patrol", "type": "wait", "seconds": 30}, "patrol": {"next": "sermon", "type": "action", "params": {"loop": true, "mode": "walk", "waypoints": ["zone_city_north", "zone_city_ne", "zone_city_east", "zone_city_se", "zone_city_south", "zone_city_west", "zone_velk_exterior", "zone_drum_exterior", "zone_thresholdeast"]}, "action_type": "PATROL"}, "sermon": {"next": "linger", "type": "action", "params": {"message": "mutters: \"...and the grid shall provide, and the grid provided, and we called it mercy because we didn''t have a better word...\"", "cooldown_s": 120}, "action_type": "SAY"}}, "_start": "start"}', 'zone_threshold', NULL, NULL, '["Keep walking. It''s what I do.", "\"It listens. It just stopped answering.\"", "\"I gave it forty years. It gave me this coat.\"", "\"The lampposts still hum the old hymns. Nobody else hears it.\"", "\"Custodians say faith. I say habit with better posture.\"", "\"You want a blessing? The water''s off on Thursdays. That''s the blessing.\"", "\"I unpicked the sigil myself. Took all night. Felt nothing.\"", "\"The Basin stays lit. That''s not love. That''s momentum.\"", "\"Keep walking. It''s what I do.\""]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{"fri": [], "mon": [], "sat": [], "sun": [], "thu": [], "tue": [], "wed": []}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_marta_velk', 'Marta Velk', 'A stocky woman in her fifties with calloused hands and a permanent evaluating squint, like she''s appraising everything for resale value. A vendor''s lanyard hangs crooked around her neck. She smells like oil soap and synth-leather.', 'zone_velk_exterior', NULL, '{"bye": {"text": "\"Don''t let the door hit you. Actually, it might — the hinge is shot. I keep meaning to fix that.\"", "options": []}, "root": {"text": "Velk wipes her hands on a rag that only makes them dirtier. \"You buying or just looking? Either way, don''t sit on anything unless you plan to buy it.\"", "options": [{"next": "__shop__", "label": "Browse your wares."}, {"next": "history", "label": "How long have you been here?"}, {"next": "sarcasm", "label": "Nice place."}, {"next": "bye", "label": "Nothing, never mind."}, {"next": "gossip", "label": "Heard anything on the street?"}]}, "gossip": {"text": "Marta wipes the counter, weighing what to share.", "actions": [{"action": "GOSSIP_TELL"}], "options": [{"next": "root", "label": "Back"}]}, "history": {"text": "\"Fifteen years in this spot. Before me it was a noodle bar. Before that, rubble. This city''s got layers.\"", "options": [{"next": "noodles", "label": "What happened to the noodle bar?"}, {"next": "__shop__", "label": "Browse your wares."}, {"next": "bye", "label": "See you around."}]}, "noodles": {"text": "\"Owner got Custodian debt. You know how that goes. I bought the chair she left behind. Still got it — twelve credits if you want it.\"", "options": [{"next": "__shop__", "label": "Browse your wares."}, {"next": "bye", "label": "See you around."}]}, "sarcasm": {"text": "\"It ain''t the Meridian, but everything in here works. More than I can say for most things in this city.\"", "options": [{"next": "__shop__", "label": "Browse your wares."}, {"next": "bye", "label": "Fair enough. See you around."}]}}', '[]', 0, '{"personality": "vendor", "clothing_layers": ["a many-pocketed utility coat", "a faded company tee knotted at the waist", "a worn bra and briefs"]}', '{"nodes": {"start": {"next": "check_work", "type": "start"}, "go_home": {"next": "home_life_ps", "type": "action", "action_type": "GO_HOME"}, "have_life": {"next": "check_work", "type": "action", "action_type": "HAVE_LIFE"}, "check_work": {"next": "have_life", "type": "action", "ports": {"offWork": "home_idle_ps", "endShift": "go_home", "goToWork": "go_to_work", "haveLife": "have_life"}, "action_type": "CHECK_VENDOR_WORK"}, "go_to_work": {"next": "vendor_chitchat", "type": "action", "action_type": "GO_TO_WORK"}, "home_idle_ps": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "home_life_ps": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "vendor_chitchat": {"next": "check_work", "type": "action", "action_type": "VENDOR_CHITCHAT"}}, "_start": "start"}', 'zone_meridian_unit_203', NULL, 'zone_velk_shop', '["\"Everything''s got a second life if you know how to look at it.\"", "runs a hand along the edge of a battered cabinet, checking for warps", "\"You break it, you bought it. That''s the rule. It''s always been the rule.\"", "squints at a price tag and decides it should be higher", "\"Good wood''s hard to find since the Singe. Synth-board''s everywhere but it warps.\"", "stacks two crates with practised efficiency, barely looking", "\"I had a couch in here last week. Guy offered me four credits. Four. I told him to get out.\"", "taps the side of a lamp three times until it flickers on", "\"If it''s broken I''ll fix it. If it''s ugly I''ll price it lower. Comes out the same in the end.\"", "exhales slowly and writes something in a worn ledger"]', 30, 30, 'female', '[]', 10, 1, 0, 'vendor', '{"fri": [{"to": 22, "from": 10}], "mon": [{"to": 22, "from": 10}], "sat": [{"to": 22, "from": 10}], "sun": [{"to": 22, "from": 10}], "thu": [{"to": 22, "from": 10}], "tue": [{"to": 22, "from": 10}], "wed": [{"to": 22, "from": 10}]}', 0, 'Velk''s Pre-Owned Furnishings', '["polishes a second-hand lamp until it gleams", "\"Still a deal at half the price.\"", "sorts through a box of salvaged drawer handles", "sketches something in a notebook, crosses it out, starts again", "\"Fifteen years. This chair''s earned its spot.\"", "runs a cloth along an old shelf, checking the joints", "counts something quietly on her fingers, frowns"]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_1783019600618', 'Ruby Six', 'One leg below the knee is chrome prosthetic, buffed to a mirror shine and worked into the routine like a prop instead of a war story. She smiles with exactly the wattage the tip requires — no more, no less.', 'zone_mq_chrome_202', NULL, '{}', '[]', 0, '{"stripper": true, "mis_willing": true, "personality": "stripper", "clothing_layers": ["a vinyl trench coat", "a chrome-studded bra", "a red lace thong"], "mis_requires_zone_flag": "mis_ok"}', '{"nodes": {"start": {"next": "check_work", "type": "start"}, "deposit": {"next": "post_shift", "type": "action", "action_type": "VENDOR_DEPOSIT"}, "atm_wait": {"next": "deposit", "type": "wait", "seconds": 10}, "work_say": {"next": "check_work", "type": "action", "action_type": "VENDOR_CHITCHAT"}, "atm_emote": {"next": "atm_wait", "type": "action", "params": {"message": "steps up to the ATM terminal and makes a deposit."}, "action_type": "EMOTE"}, "go_to_atm": {"next": "atm_emote", "type": "action", "action_type": "VENDOR_GO_TO_ATM"}, "have_life": {"next": "check_work", "type": "action", "action_type": "HAVE_LIFE"}, "home_idle": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "work_wait": {"next": "player_check", "type": "wait", "seconds": 60}, "check_work": {"type": "action", "offWork": "off_home_check", "endShift": "collect_safe", "goToWork": "go_to_work", "haveLife": "have_life", "action_type": "CHECK_VENDOR_WORK"}, "go_home_ps": {"next": "home_life_ps", "type": "action", "action_type": "GO_HOME"}, "go_to_work": {"next": "work_wait", "type": "action", "action_type": "GO_TO_WORK"}, "off_random": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_off", "branches": [{"weight": 1}, {"weight": 5}]}, "post_shift": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_ps", "branches": [{"weight": 1}, {"weight": 5}]}, "go_home_off": {"next": "check_work", "type": "action", "action_type": "GO_HOME"}, "collect_safe": {"next": "go_to_atm", "type": "action", "action_type": "VENDOR_COLLECT_SAFE"}, "home_life_ps": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "player_check": {"type": "condition", "ifTrue": "work_say", "ifFalse": "check_work", "condition_type": "PLAYER_IN_ZONE"}, "off_home_check": {"type": "condition", "ifTrue": "home_idle", "ifFalse": "off_random", "condition_type": "AT_HOME"}}, "_start": "start"}', 'zone_mq_chrome_202', NULL, 'zone_mq_cherry_floor', '[]', 20, 20, 'female', '[]', 10, 1, 0, 'npc', '{"fri": [{"to": 24, "from": 19}], "mon": [{"to": 24, "from": 19}], "sat": [{"to": 24, "from": 19}], "sun": [{"to": 24, "from": 19}], "thu": [{"to": 24, "from": 19}], "tue": [{"to": 24, "from": 19}], "wed": [{"to": 24, "from": 19}]}', NULL, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_cassius_drum', 'Cassius Drum', 'A lean man in his thirties with an eye for colour coordination that looks deliberately out of place in this city. He wears a patchwork of reclaimed fabric and tech-fibre with a tailor''s tape measure wrapped around one wrist like a bracelet. Attitude to spare.', 'zone_meridian_unit_202', NULL, '{"bye": {"text": "\"Come back when you''re ready to commit to an aesthetic. Or don''t. Either way, you know where I am.\"", "options": []}, "root": {"text": "Cassius Drum looks you up and down with professional interest. \"Okay. Okay. I see what we''re working with. Don''t worry — I''ve dressed worse.\"", "options": [{"next": "__shop__", "label": "Browse your wares."}, {"next": "craft", "label": "You make these yourself?"}, {"next": "fashion", "label": "What''s the post-apocalypse look this season?"}, {"next": "bye", "label": "I''m good, thanks."}, {"next": "gossip", "label": "Heard anything on the street?"}]}, "craft": {"text": "\"Some of it. The rest I pull off people — gently, don''t look at me like that, they were already dead. Point is, everything here has a story. I just charge you for the good parts.\"", "options": [{"next": "__shop__", "label": "Browse your wares."}, {"next": "bye", "label": "See you around."}]}, "gossip": {"text": "Cassius glances past you, then talks low.", "actions": [{"action": "GOSSIP_TELL"}], "options": [{"next": "root", "label": "Back"}]}, "fashion": {"text": "\"Layering. Always layering. You want at least three textures — keeps the rad-scanner confused and looks incredible. Also, pockets. You can never have enough pockets in a disaster zone.\"", "options": [{"next": "__shop__", "label": "Browse your wares."}, {"next": "bye", "label": "Sound advice. See you around."}]}}', '[{"price": 900, "item_id": "item_thermal_parka"}, {"price": 280, "item_id": "item_thermex_top"}, {"price": 250, "item_id": "item_thermex_leggings"}, {"price": 120, "item_id": "item_watch_cap"}, {"price": 16, "item_id": "item_briefs_novelty_spareme"}, {"price": 61, "item_id": "item_thong_lace_sheer"}, {"price": 162, "item_id": "item_jock_leather"}, {"price": 41, "item_id": "item_briefs_sport_wick"}, {"price": 4, "item_id": "item_underpants_lucky"}, {"price": 95, "item_id": "item_longjohns_thermal"}, {"price": 74, "item_id": "item_panties_crotchless_mesh"}, {"price": 24, "item_id": "item_boxers_biohazard"}, {"price": 74, "item_id": "item_bralette_lace_sheer"}, {"price": 54, "item_id": "item_sportsbra_compression"}, {"price": 203, "item_id": "item_bra_leather_harness"}, {"price": 11, "item_id": "item_undershirt_ribbed"}, {"price": 34, "item_id": "item_pasties_tassel"}, {"price": 81, "item_id": "item_binder_chest"}, {"price": 27, "item_id": "item_tee_singularity"}, {"price": 61, "item_id": "item_hoodie_grey"}, {"price": 68, "item_id": "item_croptop_fishnet"}, {"price": 34, "item_id": "item_tee_mascot"}, {"price": 47, "item_id": "item_shirt_flannel"}, {"price": 81, "item_id": "item_halter_backless"}, {"price": 54, "item_id": "item_sweater_ugly"}, {"price": 122, "item_id": "item_jacket_denim"}, {"price": 149, "item_id": "item_blouse_sheer_wrap"}, {"price": 30, "item_id": "item_tee_offbrand_security"}, {"price": 54, "item_id": "item_jeans_relaxed"}, {"price": 41, "item_id": "item_shorts_cargo"}, {"price": 243, "item_id": "item_leggings_latex"}, {"price": 41, "item_id": "item_sweatpants_grey"}, {"price": 61, "item_id": "item_shorts_micro"}, {"price": 47, "item_id": "item_trousers_clown"}, {"price": 34, "item_id": "item_sneakers_canvas"}, {"price": 27, "item_id": "item_slippers_monster"}, {"price": 297, "item_id": "item_boots_thigh_heel"}, {"price": 16, "item_id": "item_sandals_strap"}, {"price": 24, "item_id": "item_cap_trucker_slogan"}, {"price": 41, "item_id": "item_bucket_hat"}, {"price": 95, "item_id": "item_veil_lace"}, {"price": 27, "item_id": "item_gloves_fingerless"}, {"price": 88, "item_id": "item_gloves_lace_opera"}, {"price": 108, "item_id": "item_collar_leather"}, {"price": 30, "item_id": "item_fannypack"}, {"price": 20, "item_id": "item_tote_canvas"}]', 0, '{"mis_willing": false, "personality": "vendor", "clothing_layers": ["a many-pocketed utility coat", "a faded company polo", "grey boxer-briefs"]}', '{"nodes": {"start": {"next": "check_work", "type": "start"}, "deposit": {"next": "post_shift", "type": "action", "action_type": "VENDOR_DEPOSIT"}, "atm_wait": {"next": "deposit", "type": "wait", "seconds": 10}, "work_say": {"next": "check_work", "type": "action", "action_type": "VENDOR_CHITCHAT"}, "atm_emote": {"next": "atm_wait", "type": "action", "params": {"message": "steps up to the ATM terminal and makes a deposit."}, "action_type": "EMOTE"}, "go_to_atm": {"next": "atm_emote", "type": "action", "action_type": "VENDOR_GO_TO_ATM"}, "have_life": {"next": "check_work", "type": "action", "action_type": "HAVE_LIFE"}, "home_idle": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "work_wait": {"next": "player_check", "type": "wait", "seconds": 60}, "check_work": {"type": "action", "offWork": "off_home_check", "endShift": "collect_safe", "goToWork": "go_to_work", "haveLife": "have_life", "action_type": "CHECK_VENDOR_WORK"}, "go_home_ps": {"next": "home_life_ps", "type": "action", "action_type": "GO_HOME"}, "go_to_work": {"next": "work_wait", "type": "action", "action_type": "GO_TO_WORK"}, "off_random": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_off", "branches": [{"weight": 1}, {"weight": 5}]}, "post_shift": {"type": "random", "branch_0": "have_life", "branch_1": "go_home_ps", "branches": [{"weight": 1}, {"weight": 5}]}, "go_home_off": {"next": "check_work", "type": "action", "action_type": "GO_HOME"}, "collect_safe": {"next": "go_to_atm", "type": "action", "action_type": "VENDOR_COLLECT_SAFE"}, "home_life_ps": {"next": "check_work", "type": "action", "action_type": "AT_HOME_LIFE"}, "player_check": {"type": "condition", "ifTrue": "work_say", "ifFalse": "check_work", "condition_type": "PLAYER_IN_ZONE"}, "off_home_check": {"type": "condition", "ifTrue": "home_idle", "ifFalse": "off_random", "condition_type": "AT_HOME"}}, "_start": "start"}', 'zone_meridian_unit_202', NULL, 'zone_drum_shop', '["\"Color is a weapon. Most people just don''t know how to aim it.\"", "folds a jacket with the kind of precision that borders on religious", "\"You''d be surprised what a good belt does for a silhouette. Changes everything.\"", "holds a piece of fabric up to the light and clicks his tongue", "\"Half this city''s walking around in borrowed clothes. The other half don''t care. I care for both halves.\"", "snips a loose thread and examines the result critically", "\"Rad-shielded lining is the future. I was doing it before it was a survival necessity.\"", "rearranges a display rack, steps back, then rearranges it again", "\"Pockets. I''m telling you. Every design needs more pockets. This is non-negotiable.\"", "hums something tuneless while pinning a hem"]', 25, 25, 'male', '[{"item_id": "item_thermal_parka"}, {"item_id": "item_thermex_top"}, {"item_id": "item_thermex_leggings"}, {"item_id": "item_watch_cap"}, {"item_id": "item_briefs_novelty_spareme"}, {"item_id": "item_thong_lace_sheer"}, {"item_id": "item_jock_leather"}, {"item_id": "item_briefs_sport_wick"}, {"item_id": "item_underpants_lucky"}, {"item_id": "item_longjohns_thermal"}, {"item_id": "item_panties_crotchless_mesh"}, {"item_id": "item_boxers_biohazard"}, {"item_id": "item_bralette_lace_sheer"}, {"item_id": "item_sportsbra_compression"}, {"item_id": "item_bra_leather_harness"}, {"item_id": "item_undershirt_ribbed"}, {"item_id": "item_pasties_tassel"}, {"item_id": "item_binder_chest"}, {"item_id": "item_tee_singularity"}, {"item_id": "item_hoodie_grey"}, {"item_id": "item_croptop_fishnet"}, {"item_id": "item_tee_mascot"}, {"item_id": "item_shirt_flannel"}, {"item_id": "item_halter_backless"}, {"item_id": "item_sweater_ugly"}, {"item_id": "item_jacket_denim"}, {"item_id": "item_blouse_sheer_wrap"}, {"item_id": "item_tee_offbrand_security"}, {"item_id": "item_jeans_relaxed"}, {"item_id": "item_shorts_cargo"}, {"item_id": "item_leggings_latex"}, {"item_id": "item_sweatpants_grey"}, {"item_id": "item_shorts_micro"}, {"item_id": "item_trousers_clown"}, {"item_id": "item_sneakers_canvas"}, {"item_id": "item_slippers_monster"}, {"item_id": "item_boots_thigh_heel"}, {"item_id": "item_sandals_strap"}, {"item_id": "item_cap_trucker_slogan"}, {"item_id": "item_bucket_hat"}, {"item_id": "item_veil_lace"}, {"item_id": "item_gloves_fingerless"}, {"item_id": "item_gloves_lace_opera"}, {"item_id": "item_collar_leather"}, {"item_id": "item_fannypack"}, {"item_id": "item_tote_canvas"}]', 46, 3, 44, 'vendor', '{"fri": [{"to": 22, "from": 10}], "mon": [{"to": 22, "from": 10}], "sat": [{"to": 22, "from": 10}], "sun": [{"to": 22, "from": 10}], "thu": [{"to": 22, "from": 10}], "tue": [{"to": 22, "from": 10}], "wed": [{"to": 22, "from": 10}]}', 58, 'Second Skin', '["stitches something under a low light, squinting", "\"Texture, contrast, silhouette. In that order.\"", "lays out three different fabric swatches side by side", "carefully hangs a jacket, adjusts it twice, then a third time", "\"If I had better thread this would be perfect.\"", "cuts a pattern piece from a paper template with quiet precision", "holds two colors up to the window and stares at them for a long moment"]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_narrator', 'Bobby Francis', 'A broadcast studio host.', 'zone_studio_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true, "mis_willing": false}', '{"nodes": {"n_w0": {"next": "n_ww0", "type": "action", "params": {"message": "Still sleeping in a bed?"}, "action_type": "SAY"}, "n_w1": {"next": "n_ww1", "type": "action", "params": {"message": "How twentieth century."}, "action_type": "SAY"}, "n_w2": {"next": "n_ww2", "type": "action", "params": {"message": "The camera slowly circles the glowing sleep pod as soft blue lights pulse across its polished surface."}, "action_type": "SAY"}, "n_w3": {"next": "n_ww3", "type": "action", "params": {"message": "SleepRight™ monitors your dreams..."}, "action_type": "SAY"}, "n_w4": {"next": "n_ww4", "type": "action", "params": {"message": "...your heart..."}, "action_type": "SAY"}, "n_w5": {"next": "n_ww5", "type": "action", "params": {"message": "...and your productivity."}, "action_type": "SAY"}, "n_w6": {"next": "n_ww6", "type": "action", "params": {"message": "Wake refreshed."}, "action_type": "SAY"}, "n_w7": {"next": "n_ww7", "type": "action", "params": {"message": "Wake focused."}, "action_type": "SAY"}, "n_w8": {"next": "n_ww8", "type": "action", "params": {"message": "Wake ready to exceed quarterly expectations."}, "action_type": "SAY"}, "n_w9": {"next": "n_ww9", "type": "action", "params": {"message": "SleepRight™."}, "action_type": "SAY"}, "n_w10": {"next": "n_ww10", "type": "action", "params": {"message": "Because unconscious employees can''t miss deadlines."}, "action_type": "SAY"}, "n_ww0": {"next": "n_w1", "type": "wait", "seconds": 5}, "n_ww1": {"next": "n_w2", "type": "wait", "seconds": 5}, "n_ww2": {"next": "n_w3", "type": "wait", "seconds": 5}, "n_ww3": {"next": "n_w4", "type": "wait", "seconds": 5}, "n_ww4": {"next": "n_w5", "type": "wait", "seconds": 5}, "n_ww5": {"next": "n_w6", "type": "wait", "seconds": 5}, "n_ww6": {"next": "n_w7", "type": "wait", "seconds": 5}, "n_ww7": {"next": "n_w8", "type": "wait", "seconds": 5}, "n_ww8": {"next": "n_w9", "type": "wait", "seconds": 5}, "n_ww9": {"next": "n_w10", "type": "wait", "seconds": 5}, "n_life": {"next": "n_work", "type": "action", "action_type": "HAVE_LIFE"}, "n_loop": {"next": "n_start", "type": "loop"}, "n_work": {"next": "n_w0", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_ww10": {"next": "n_loop", "type": "wait", "seconds": 5}, "n_start": {"next": "n_life", "type": "start"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, 'zone_studio_1782953094650', '[]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_prefect_clerk', 'Prefect Aldous', 'The senior clerk of the Prefecture, a small grey man who has turned the withholding of stamps into a martial art. He can end your day with a shrug and a form number.', 'zone_gov_prefect', NULL, '{"bye": {"text": "\"Then you remain, officially, nobody. Next.\"", "options": []}, "root": {"text": "Prefect Aldous looks up over half-moon glasses, unimpressed in advance. \"The Prefecture issues permits, papers, and — occasionally — pardons. Which delay would you like to begin today?\"", "options": [{"next": "__shop__", "label": "Show me the paperwork."}, {"next": "bye", "label": "Never mind."}]}}', '[{"price": 30, "item_id": "item_travel_permit"}, {"price": 20, "item_id": "item_id_papers"}, {"price": 5, "item_id": "item_water_bottle"}]', 0, '{"personality": "vendor", "clothing_layers": ["a grey civil-service tunic pressed to a razor edge", "an ink-cuffed shirt", "regulation, joyless underthings"]}', '{}', 'zone_gov_prefect', NULL, 'zone_gov_prefect', '[]', 18, 18, 'male', '[{"item_id": "item_travel_permit"}, {"item_id": "item_id_papers"}, {"item_id": "item_water_bottle"}]', 8, 1, 120, 'vendor', '{"fri": [{"to": 22, "from": 6}], "mon": [{"to": 22, "from": 6}], "sat": [{"to": 22, "from": 6}], "sun": [{"to": 22, "from": 6}], "thu": [{"to": 22, "from": 6}], "tue": [{"to": 22, "from": 6}], "wed": [{"to": 22, "from": 6}]}', 0, 'The Prefecture', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_fishmonger', 'Brack the Fishmonger', 'A slab-armed man with a cleaver and a laugh like a dropped crate. He can fillet a bay-thing before it knows it''s dead and sell you the parts that aren''t glowing.', 'zone_dock_fishmarket', NULL, '{"bye": {"text": "\"Suit yourself. Cats aren''t fussy.\"", "options": []}, "root": {"text": "Brack slaps a pale fillet onto the slab. \"Fresh off the bay, mostly fish! Buyin'' your catch too, if it''s got fewer than three eyes.\"", "options": [{"next": "__shop__", "label": "Show me the catch."}, {"next": "bye", "label": "Not hungry."}]}}', '[{"price": 7, "item_id": "item_fresh_catch"}, {"price": 10, "item_id": "item_ration"}, {"price": 5, "item_id": "item_water_bottle"}]', 0, '{"personality": "vendor", "clothing_layers": ["a gore-stiff rubber apron", "a striped fishmonger''s shirt gone grey", "sturdy waders"]}', '{}', 'zone_dock_fishmarket', NULL, 'zone_dock_fishmarket', '[]', 20, 20, 'male', '[{"item_id": "item_fresh_catch"}, {"item_id": "item_ration"}, {"item_id": "item_water_bottle"}]', 8, 1, 90, 'vendor', '{"fri": [{"to": 24, "from": 6}], "mon": [{"to": 24, "from": 6}], "sat": [{"to": 24, "from": 6}], "sun": [{"to": 24, "from": 6}], "thu": [{"to": 24, "from": 6}], "tue": [{"to": 24, "from": 6}], "wed": [{"to": 24, "from": 6}]}', 0, 'The Fishmarket', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_harbormaster', 'The Harbourmaster', 'A weathered official in a peaked cap she has no authority to wear anymore, keeping ledgers for ships that mostly don''t file. She sees everything on her wharf and reports almost none of it.', 'zone_dock_wharf', NULL, '{"bye": {"text": "\"Keep it that way and we''ll get along.\"", "options": []}, "root": {"text": "The Harbourmaster looks up from her ledger. \"You''re not crew, and you''re not cargo. So what are you?\"", "options": [{"next": "quest_offer", "label": "Looking for work."}, {"next": "bye", "label": "Nobody in particular."}]}, "accepted": {"text": "\"Try the shallows, the moored barges, out past the breakwater. Mind you don''t end up in the ledger of the lost yourself.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_wet_cargo"}], "options": [{"next": "bye", "label": "Understood."}]}, "reported": {"text": "\"...Fewer wakes out there tonight. Good. Here — off the books, like everything else on this wharf. We never spoke.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_wet_cargo"}], "options": [{"next": "bye", "label": "Obliged."}]}, "quest_offer": {"text": "\"Something in the bay''s been taking my dockhands and gnawing my hulls — lurkers, big ones. Thin them out — three, at least — and I''ll pay you in something I definitely never received.\"", "options": [{"next": "accepted", "label": "I''ll clear them."}, {"next": "reported", "label": "Done. (report back)"}, {"next": "bye", "label": "Not my problem."}]}}', 'null', 0, '{"personality": "official", "clothing_layers": ["a salt-bleached harbourmaster''s coat", "a cabled sweater", "oilskin trousers"]}', '{}', 'zone_dock_wharf', NULL, 'zone_dock_wharf', '["The Harbourmaster notes something in a ledger and closes it before you can look.", "\"Every boat that ties up here is my problem. Try not to become one.\""]', 18, 18, 'female', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_aerie_patron', 'a platinum shareholder', 'A platinum-tier shareholder in a suit that costs more than the building you were born in. He looks at the bay the way a cat looks at a fishbowl, and at you not at all.', 'zone_nc_sable', NULL, '{"bye": {"text": "He has already stopped seeing you.", "options": []}, "root": {"text": "The shareholder does not lower his glass. \"If you have to be up here, do try to be interesting. The last one wasn''t.\"", "options": [{"next": "bye", "label": "..."}]}}', '[]', 0, '{"personality": "corporate", "clothing_layers": ["a bespoke charcoal suit", "a shirt woven from something extinct", "silk that has never met a working day"]}', '{}', 'zone_nc_sable', NULL, NULL, '["The shareholder swirls something amber and watches the deep water with mild appetite.", "\"Everything down there is inventory. It simply doesn''t know it yet.\""]', 14, 14, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_salvage_broker', 'Voss Iyaka', 'A wiry old clone with a jeweller''s loupe screwed into one eye and a brass hanging-scale bolted to the gatehouse beside him. A strongbox sits chained to his ankle. He weighs everything you carry before he weighs you.', 'zone_slag_gate', NULL, '{"bye": {"text": "\"Wastes''ll still be here when you change your mind.\"", "options": []}, "buys": {"text": "\"Metal, wire, components, bone — anything the works spat out that''ll fetch a price back in the city. I weigh it, I pay it, and you don''t have to haul it through the wastes. I also sell what''ll keep you breathing out here, if you''re buying.\"", "options": [{"next": "__shop__", "label": "Show me the shop."}, {"next": "root", "label": "Back"}]}, "root": {"text": "Voss doesn''t look up from the scale. \"You came all this way, so you''ve either got salvage or you''ve got a death wish. Which is it?\"", "options": [{"next": "__shop__", "label": "I''ve got salvage to sell."}, {"next": "buys", "label": "What do you buy?"}, {"next": "gossip", "label": "Heard anything out here?"}, {"next": "bye", "label": "Just passing through."}]}, "gossip": {"text": "Voss taps the scale and leans in.", "actions": [{"action": "GOSSIP_TELL"}], "options": [{"next": "root", "label": "Back"}]}}', '[{"price": 15, "item_id": "item_ration"}, {"price": 30, "item_id": "item_rusty_knife"}, {"price": 50, "item_id": "item_pipe_wrench"}, {"price": 110, "item_id": "item_taser"}]', 0, '{"mis_willing": false, "personality": "vendor", "clothing_layers": ["a grease-stained merchant''s apron", "a padded vest", "a sweat-yellowed undershirt and boxers"]}', '{"nodes": {"idle": {"next": "idle", "type": "wait", "seconds": 600}, "start": {"next": "idle", "type": "start"}}, "_start": "start"}', 'zone_slag_gate', NULL, 'zone_slag_gate', '["Weigh in or move on.", "Everything''s got a price by the gram.", "The works''ll kill you slow. I pay fast.", "Don''t bring me anything that ticks.", "Scrap''s scrap. Bring me more of it.", "Mind the wire on your way in."]', 20, 20, 'male', '[{"item_id": "item_ration"}, {"item_id": "item_rusty_knife"}, {"item_id": "item_pipe_wrench"}, {"item_id": "item_taser"}]', 8, 1, 465, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'Voss''s Weigh Station', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_fence', 'Sluice', 'A narrow, still woman who runs the Slip''s quiet trade. She never raises her voice and never forgets a face, and both facts should worry you equally.', 'zone_dock_slip', NULL, '{"bye": {"text": "\"Then you were never here.\"", "options": []}, "root": {"text": "Sluice regards you without expression. \"You didn''t see a shop. But since you''re here — buying, or unloading something you''d rather not explain?\"", "options": [{"next": "__shop__", "label": "Let me see."}, {"next": "bye", "label": "Wrong pier."}]}}', '[{"price": 90, "item_id": "item_contraband_crate"}, {"price": 14, "item_id": "item_cracked_capacitor"}, {"price": 8, "item_id": "item_salvaged_wiring"}, {"price": 28, "item_id": "item_rusty_knife"}]', 0, '{"personality": "vendor", "clothing_layers": ["a long oiled-canvas coat", "dark, unremarkable clothes", "nothing that would identify a body"]}', '{}', 'zone_dock_slip', NULL, 'zone_dock_slip', '[]', 20, 20, 'female', '[{"item_id": "item_contraband_crate"}, {"item_id": "item_cracked_capacitor"}, {"item_id": "item_salvaged_wiring"}, {"item_id": "item_rusty_knife"}]', 8, 1, 420, 'vendor', '{"fri": [{"to": 24, "from": 6}], "mon": [{"to": 24, "from": 6}], "sat": [{"to": 24, "from": 6}], "sun": [{"to": 24, "from": 6}], "thu": [{"to": 24, "from": 6}], "tue": [{"to": 24, "from": 6}], "wed": [{"to": 24, "from": 6}]}', 0, 'The Slip', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_assemblyman', 'Assemblyman Croll', 'A back-bench Assemblyman with a florid manner and a genuine, unfashionable belief that the government should govern something. It has made him a nuisance to everyone, including himself.', 'zone_gov_assembly', NULL, '{"bye": {"text": "\"Quite. Well. Someone must, I suppose.\"", "options": []}, "root": {"text": "Assemblyman Croll brightens at the sight of anyone who might listen. \"You there — you have the look of someone who solves things. This chamber does the opposite. Might I trouble you?\"", "options": [{"next": "quest_offer", "label": "What is it?"}, {"next": "bye", "label": "Afraid not."}]}, "accepted": {"text": "\"Splendid! West of Onyx Row — the Scald, the steppe, the sootbanks. Four should quiet them. Do watch the leach-beds; they are not on any map I''d trust.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_prefects_problem"}], "options": [{"next": "bye", "label": "Understood."}]}, "reported": {"text": "\"...The archivists report quiet in the overflow stacks. Extraordinary. Here — your fee, and a permit stamped by my own hand, which still means something in three or four offices.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_prefects_problem"}], "options": [{"next": "bye", "label": "Obliged."}]}, "quest_offer": {"text": "\"Jackals — wire-jackals, the wretched wire-and-scab kind — are coming up out of the wastes and into the Registry''s overflow archives. Nobody official will act; jurisdiction, you understand. Cull four of them for me and I''ll see you''re paid and papered.\"", "options": [{"next": "accepted", "label": "I''ll cull them."}, {"next": "reported", "label": "It''s done. (report back)"}, {"next": "bye", "label": "Not my business."}]}}', 'null', 0, '{"personality": "official", "clothing_layers": ["a moth-eaten ceremonial sash over a good suit", "a starched wing-collar shirt", "dignified, defeated underthings"]}', '{}', 'zone_gov_assembly', NULL, 'zone_gov_assembly', '["Assemblyman Croll rehearses a point of order to no one in particular.", "\"Someone must mind the west gate. It may as well be me. It certainly won''t be them.\""]', 18, 18, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_shipwright', 'Keel', 'A grizzled shipwright welded into a leather apron, forever half-finished with a hull he''ll never launch. Sells the tools and scrap he isn''t using, which is most of it.', 'zone_dock_boatyard', NULL, '{"bye": {"text": "\"Mind the stands on your way out.\"", "options": []}, "root": {"text": "Keel lowers his heat-gun and squints. \"Boat parts, tools, scrap — take your pick. She''s not going anywhere.\" (he nods at the half-built hull)", "options": [{"next": "__shop__", "label": "What have you got?"}, {"next": "bye", "label": "Just looking."}]}}', '[{"price": 4, "item_id": "item_scrap_metal"}, {"price": 8, "item_id": "item_salvaged_wiring"}, {"price": 45, "item_id": "item_pipe_wrench"}, {"price": 15, "item_id": "canteen"}, {"price": 28, "item_id": "item_rusty_knife"}]', 0, '{"personality": "vendor", "clothing_layers": ["a scorched leather apron", "a sweat-soaked workshirt", "heavy canvas trousers"]}', '{}', 'zone_dock_boatyard', NULL, 'zone_dock_boatyard', '[]', 24, 24, 'male', '[{"item_id": "item_scrap_metal"}, {"item_id": "item_salvaged_wiring"}, {"item_id": "item_pipe_wrench"}, {"item_id": "canteen"}, {"item_id": "item_rusty_knife"}]', 8, 1, 130, 'vendor', '{"fri": [{"to": 24, "from": 6}], "mon": [{"to": 24, "from": 6}], "sat": [{"to": 24, "from": 6}], "sun": [{"to": 24, "from": 6}], "thu": [{"to": 24, "from": 6}], "tue": [{"to": 24, "from": 6}], "wed": [{"to": 24, "from": 6}]}', 0, 'The Boat Yard', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_gov_archivist', 'an archivist', 'A stooped archivist who has memorised the location of files for people who no longer exist, and treats each one as a small held breath.', 'zone_gov_registry', NULL, '{"bye": {"text": "She has already returned to the dead.", "options": []}, "root": {"text": "The archivist does not look up from the stacks. \"If you seek a record, give me a name. If you seek a person, I cannot help you; we stopped stocking those.\"", "options": [{"next": "bye", "label": "Just looking."}]}}', 'null', 0, '{"personality": "clerk", "clothing_layers": ["a dust-grey archivist''s smock", "a high-buttoned blouse", "sensible, forgotten underthings"]}', '{}', 'zone_gov_registry', NULL, 'zone_gov_registry', '["The archivist reshelves a file with the tenderness of a burial.", "\"Everyone is on record here. Being on record is not the same as being alive.\""]', 14, 14, 'female', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_ma_cinder', 'Ma Cinder', 'The matriarch of the Slake Pond camp: sun-cured, iron-grey, and entirely without illusions. She has buried more of her people than she''ll say and guards the living with a pragmatism that shades into menace.', 'zone_waste_slake', NULL, '{"bye": {"text": "\"Fill your jug and move on, then.\"", "options": []}, "root": {"text": "A leather-faced woman looks up from a cook-pot, one hand never far from a length of pipe. \"This is my pond, my camp, my water. State your business or fill your jug and go.\"", "options": [{"next": "quest_offer", "label": "You run this camp?"}, {"next": "bye", "label": "Just passing through."}]}, "accepted": {"text": "\"They den in the wet ground — the Seep, the Rust Marsh, the Runoff down south. Two at least. And mind your footing; the tar doesn''t give anything back.\"", "actions": [{"action": "START_QUEST", "quest_id": "quest_bog_standard"}], "options": [{"next": "bye", "label": "Understood."}]}, "reported": {"text": "\"...The seeps are quieter. My people noticed. Here — clean water and a hot meal, and you''re welcome at this fire, which is more than most get.\"", "actions": [{"action": "TURN_IN", "quest_id": "quest_bog_standard"}], "options": [{"next": "bye", "label": "Obliged."}]}, "quest_offer": {"text": "\"Something''s coming up out of the seeps — tar-things, big and slow and hungry. Took two of mine this week. Put a couple of them down and there''s water, food, and goodwill in it. Goodwill''s worth more than it sounds out here.\"", "options": [{"next": "accepted", "label": "I''ll thin them out."}, {"next": "reported", "label": "It''s done. (report back)"}, {"next": "bye", "label": "Not my fight."}]}}', '[{"price": 5, "item_id": "item_water_bottle"}, {"price": 10, "item_id": "item_ration"}, {"price": 15, "item_id": "canteen"}]', 0, '{"personality": "vendor", "clothing_layers": ["a patched canvas duster hung with tools", "layered wool gone the colour of ash", "sturdy, much-mended underthings"]}', '{}', 'zone_waste_slake', NULL, 'zone_waste_slake', '["Ma Cinder stirs the pot and watches the flats over your shoulder.", "\"Water''s life out here. Don''t waste mine.\"", "\"Camp''s full. Doesn''t mean you''re welcome to stay.\""]', 24, 24, 'female', '[{"item_id": "item_water_bottle"}, {"item_id": "item_ration"}, {"item_id": "canteen"}]', 8, 1, 110, 'vendor', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, 'Slake Pond Camp', '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_gov_advocate', 'a court advocate', 'An advocate of Cobalt Court in robes gone shiny at the elbows, arguing a case he inherited and will bequeath, unresolved, to whoever comes next.', 'zone_gov_cobalt', NULL, '{"bye": {"text": "\"Adjourned, then. As ever.\"", "options": []}, "root": {"text": "The advocate turns, scenting a potential client. \"Do you have standing? Grievance? Retainer? No? Then I''m afraid we''ve nothing to discuss, which is, ironically, my entire caseload.\"", "options": [{"next": "bye", "label": "...right."}]}}', 'null', 0, '{"personality": "official", "clothing_layers": ["threadbare cobalt court robes", "a frayed cravat", "the underthings of a man who has stopped hoping"]}', '{}', 'zone_gov_cobalt', NULL, 'zone_gov_cobalt', '["The advocate cites a precedent from a court that no longer sits.", "\"Justice delayed, in my experience, is simply justice pending. Endlessly pending.\""]', 14, 14, 'male', 'null', NULL, 1, 0, 'npc', NULL, 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_lucky_malone', 'Lucky Malone', 'A broadcast studio host.', 'zone_studio_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_w0": {"next": "n_ww0", "type": "action", "params": {"message": "enters the frame."}, "action_type": "EMOTE"}, "n_w1": {"next": "n_ww1", "type": "action", "params": {"message": "The camera settles into a comfortable two-shot as John and tonight''s guest sit beneath the warm studio lights."}, "action_type": "SAY"}, "n_w2": {"next": "n_ww2", "type": "action", "params": {"message": "Happy to be here."}, "action_type": "SAY"}, "n_w3": {"next": "n_ww3", "type": "action", "params": {"message": "Eight."}, "action_type": "SAY"}, "n_w4": {"next": "n_ww4", "type": "action", "params": {"message": "The eighth time they stopped congratulating me and started interviewing me."}, "action_type": "SAY"}, "n_w5": {"next": "n_ww5", "type": "action", "params": {"message": "Always buy your ticket after surviving something that should''ve killed you."}, "action_type": "SAY"}, "n_w6": {"next": "n_ww6", "type": "action", "params": {"message": "I''m from Eastside."}, "action_type": "SAY"}, "n_w7": {"next": "n_ww7", "type": "action", "params": {"message": "A deluxe apartment."}, "action_type": "SAY"}, "n_w8": {"next": "n_ww8", "type": "action", "params": {"message": "The deluxe part is that only one wall leaks."}, "action_type": "SAY"}, "n_w9": {"next": "n_ww9", "type": "action", "params": {"message": "The broadcast abruptly transitions to an aggressively colorful commercial surrounded by flashing corporate branding."}, "action_type": "SAY"}, "n_w10": {"next": "n_ww10", "type": "action", "params": {"message": "♪ An upbeat Acid Cola™ advertising jingle begins playing. ♪"}, "action_type": "SAY"}, "n_ww0": {"next": "n_w1", "type": "wait", "seconds": 5}, "n_ww1": {"next": "n_w2", "type": "wait", "seconds": 3}, "n_ww2": {"next": "n_w3", "type": "wait", "seconds": 5}, "n_ww3": {"next": "n_w4", "type": "wait", "seconds": 5}, "n_ww4": {"next": "n_w5", "type": "wait", "seconds": 5}, "n_ww5": {"next": "n_w6", "type": "wait", "seconds": 5}, "n_ww6": {"next": "n_w7", "type": "wait", "seconds": 5}, "n_ww7": {"next": "n_w8", "type": "wait", "seconds": 5}, "n_ww8": {"next": "n_w9", "type": "wait", "seconds": 5}, "n_ww9": {"next": "n_w10", "type": "wait", "seconds": 5}, "n_life": {"next": "n_work", "type": "action", "action_type": "HAVE_LIFE"}, "n_loop": {"next": "n_start", "type": "loop"}, "n_work": {"next": "n_w0", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_ww10": {"next": "n_loop", "type": "wait", "seconds": 5}, "n_start": {"next": "n_life", "type": "start"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, 'zone_studio_1782953094650', '[]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_nyra_voss', 'Nyra Voss', 'Nyra Voss moves like she belongs to the city''s electrical current rather than its streets. She is composed, precise, and unnervingly aware of everything around her without ever appearing distracted. Her presence is understated but magnetic — less about overt display and more about controlled integration with technology and environment.', 'zone_meridian_unit_103', NULL, '{}', '[]', 0, '{"mis_willing": false, "personality": "unemployed", "clothing_layers": ["a fraying interview blazer gone shapeless", "a coffee-stained blouse", "a plain bra and worn panties"]}', '{"nodes": {"start": {"next": "have_life", "type": "start"}, "at_work": {"next": "go_home", "type": "action", "action_type": "AT_WORK"}, "go_home": {"next": "home_wait", "type": "action", "action_type": "GO_HOME"}, "have_life": {"next": "go_to_work", "type": "action", "action_type": "HAVE_LIFE"}, "home_wait": {"next": "start", "type": "wait", "seconds": 60}, "go_to_work": {"next": "at_work", "type": "action", "action_type": "GO_TO_WORK"}}, "_start": "start"}', 'zone_meridian_unit_103', NULL, NULL, '["traces a finger along the edge of a nearby surface without looking at it.", "glances toward the nearest data terminal, expression unreadable.", "adjusts the interface contacts on her gloves with quiet precision.", "appears to be processing something — her iris ring shifts almost imperceptibly.", "is perfectly still, which somehow feels deliberate.", "scans the room with the easy calm of someone who already knows every exit.", "taps two fingers against her forearm, once.", "exhales slowly, like she''s filtering the air for useful information."]', 50, 50, 'female', '[]', 10, 1, 0, 'unemployed', '{"fri": [], "mon": [], "sat": [], "sun": [], "thu": [], "tue": [], "wed": []}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_reg', 'Reg Naylor', 'A heavyset person behind a scratched counter. Apron: CERTIFIED SURVIVOR.', 'zone_meridian_unit_201', NULL, '{"root": {"text": "You look new. Or you look like you died recently. Hard to tell the difference. What do you need?", "options": [{"next": "where", "label": "Where am I?"}, {"next": "factions", "label": "What are the factions?"}, {"next": null, "label": "Never mind."}]}, "where": {"text": "Coldwater Basin. Used to be a city. Now it''s whatever this is. The Architect''s infrastructure runs under the whole basin — power, water, comms. So it stays livable. Relatively.", "options": [{"next": "root", "label": "Back"}]}, "factions": {"text": "Custodians think the Architect is God. Breakers want to smash everything. Archivists want to know everything. The Franchise wants to sell everything. The Glitch think they can talk to it. None of them are right, probably. Pick the one that''s wrong in a way you can live with.", "options": [{"next": "root", "label": "Back"}]}}', '[{"price": 12, "stock": 10, "item_id": "item_ration"}, {"price": 8, "stock": 15, "item_id": "item_water_bottle"}, {"price": 15, "stock": 8, "item_id": "item_bandage"}, {"price": 300, "item_id": "item_thermex_top"}, {"price": 130, "item_id": "item_watch_cap"}]', 1, '{"mis_willing": false, "personality": "travelling_vendor", "clothing_layers": ["a battered oilskin poncho", "a layered thermal shirt", "grey briefs"]}', '{"nodes": {"start": {"next": "have_life", "type": "start"}, "at_work": {"next": "go_home", "type": "action", "action_type": "AT_WORK"}, "go_home": {"next": "home_wait", "type": "action", "action_type": "GO_HOME"}, "have_life": {"next": "go_to_work", "type": "action", "action_type": "HAVE_LIFE"}, "home_wait": {"next": "start", "type": "wait", "seconds": 60}, "go_to_work": {"next": "at_work", "type": "action", "action_type": "GO_TO_WORK"}}, "_start": "start"}', 'zone_meridian_unit_201', NULL, NULL, '["Another quiet night, too quiet...", "Inventory’s running low again, like always.", "Everything here has a price, even silence.", "That shipment wasn’t supposed to be late...", "Funny how the same items keep coming back with different stories.", "The terminal''s logging phantom transactions", "Somebody’s been through here, can still feel it.", "City chews through stock, I can''t keep up!"]', 20, 20, 'male', '[{"item_id": "item_thermex_top"}, {"item_id": "item_watch_cap"}]', 10, 1, 0, 'npc', '{"fri": [{"to": 23, "from": 6}], "mon": [{"to": 23, "from": 6}], "sat": [{"to": 23, "from": 6}], "sun": [{"to": 23, "from": 6}], "thu": [{"to": 23, "from": 6}], "tue": [{"to": 23, "from": 6}], "wed": [{"to": 23, "from": 6}]}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_graham_mercer', 'Graham Mercer', 'A broadcast studio host.', 'zone_studio_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_w0": {"next": "n_ww0", "type": "action", "params": {"message": "From somewhere above the smog and only slightly outside the blast radius..."}, "action_type": "SAY"}, "n_w1": {"next": "n_ww1", "type": "action", "params": {"message": "It''s..."}, "action_type": "SAY"}, "n_w2": {"next": "n_ww2", "type": "action", "params": {"message": "The Tonight Show!"}, "action_type": "SAY"}, "n_w3": {"next": "n_ww3", "type": "action", "params": {"message": "Tonight..."}, "action_type": "SAY"}, "n_w4": {"next": "n_ww4", "type": "action", "params": {"message": "Corporate executives explain why exploding vending machines are actually a premium feature."}, "action_type": "SAY"}, "n_w5": {"next": "n_ww5", "type": "action", "params": {"message": "A local street chef prepares authentic mutant squid tacos."}, "action_type": "SAY"}, "n_w6": {"next": "n_ww6", "type": "action", "params": {"message": "And we''ll meet a man who''s legally declared his apartment to be an independent nation."}, "action_type": "SAY"}, "n_w7": {"next": "n_ww7", "type": "action", "params": {"message": "Ladies and gentlemen..."}, "action_type": "SAY"}, "n_w8": {"next": "n_ww8", "type": "action", "params": {"message": "JOOOOOHN AKERSON!"}, "action_type": "SAY"}, "n_w9": {"next": "n_ww9", "type": "action", "params": {"message": "Feeling tired?"}, "action_type": "SAY"}, "n_w10": {"next": "n_ww10", "type": "action", "params": {"message": "Feeling hopeless?"}, "action_type": "SAY"}, "n_w11": {"next": "n_ww11", "type": "action", "params": {"message": "Drink Acid Cola™."}, "action_type": "SAY"}, "n_w12": {"next": "n_ww12", "type": "action", "params": {"message": "Because reality is easier to tolerate when it''s carbonated."}, "action_type": "SAY"}, "n_ww0": {"next": "n_w1", "type": "wait", "seconds": 5}, "n_ww1": {"next": "n_w2", "type": "wait", "seconds": 5}, "n_ww2": {"next": "n_w3", "type": "wait", "seconds": 5}, "n_ww3": {"next": "n_w4", "type": "wait", "seconds": 5}, "n_ww4": {"next": "n_w5", "type": "wait", "seconds": 5}, "n_ww5": {"next": "n_w6", "type": "wait", "seconds": 5}, "n_ww6": {"next": "n_w7", "type": "wait", "seconds": 5}, "n_ww7": {"next": "n_w8", "type": "wait", "seconds": 5}, "n_ww8": {"next": "n_w9", "type": "wait", "seconds": 5}, "n_ww9": {"next": "n_w10", "type": "wait", "seconds": 5}, "n_life": {"next": "n_work", "type": "action", "action_type": "HAVE_LIFE"}, "n_loop": {"next": "n_start", "type": "loop"}, "n_work": {"next": "n_w0", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_ww10": {"next": "n_w11", "type": "wait", "seconds": 5}, "n_ww11": {"next": "n_w12", "type": "wait", "seconds": 5}, "n_ww12": {"next": "n_loop", "type": "wait", "seconds": 5}, "n_start": {"next": "n_life", "type": "start"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, 'zone_studio_1782953094650', '[]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_cash_vane', 'Cassius Vane', 'A rangy man in a salvaged casino-floor coat, the felt-green lining worn to grey. His jaw is chrome from the cheekbone down — an old repair he never bothered to skin over, so it catches the light when he smiles, which is often and rarely means anything good. He watches hands the way other people watch weather. They call him Cash, mostly because he keeps taking it.', 'zone_city_ne', NULL, '{}', '[]', 0, '{"poker_player": true, "poker_persona": {"buyIn": 200, "betSizing": 0.6, "bluffFreq": 0.18, "tightness": 0.5, "tiltProne": 0.35, "aggression": 0.7, "chattiness": 0.6, "semiBluffFreq": 0.4}, "poker_bankroll": 3200}', '{"nodes": {"wait": {"next": "start", "type": "wait", "seconds": 20}, "start": {"next": "have_life", "type": "start"}, "have_life": {"next": "home_check", "type": "action", "action_type": "HAVE_LIFE"}, "home_life": {"next": "wait", "type": "action", "action_type": "AT_HOME_LIFE"}, "home_check": {"type": "condition", "ifTrue": "home_life", "ifFalse": "wait", "condition_type": "AT_HOME"}}, "_start": "start"}', 'zone_apt_1', NULL, NULL, '["\"Anybody feel like donating some credits? I take cards, cash, and bad decisions.\"", "shuffles a battered deck one-handed, watching the room", "\"You look like a caller. I like callers.\"", "taps two chips together in a slow, patient rhythm", "\"Sit down. The felt won''t bite. Much.\"", "rolls a chip across his knuckles and pockets it without looking"]', 25, 25, 'male', '[]', 10, 1, 0, 'gambler', '{}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_stage_assistant', 'Stage Assistant', 'A broadcast studio host.', 'zone_ext_1782953094650', NULL, '{}', '[]', 0, '{"studio_npc": true}', '{"nodes": {"n_life": {"next": "n_check", "type": "action", "action_type": "HAVE_LIFE"}, "n_work": {"next": "n_atwork", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_check": {"type": "action", "goToWork": "n_work", "haveLife": "n_life", "action_type": "CHECK_WORK"}, "n_start": {"next": "n_check", "type": "start"}, "n_atwork": {"next": "n_check", "type": "action", "action_type": "AT_WORK"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, NULL, '[]', 20, 20, 'female', '[]', 10, 1, 0, 'npc', '{"fri": [{"to": 22, "from": 10}], "mon": [{"to": 22, "from": 10}], "sat": [{"to": 22, "from": 10}], "sun": [{"to": 22, "from": 10}], "thu": [{"to": 22, "from": 10}], "tue": [{"to": 22, "from": 10}], "wed": [{"to": 22, "from": 10}]}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_embassy_barkeep', 'Lowry Cormack', 'A former concierge, still buttoned into a frayed Embassy vest, polishing a glass that was already clean. Calls every customer "valued guest," sincerity optional.', 'zone_meridian', NULL, '{"menu": {"text": "The Reserve is our signature pour — don''t ask what''s left to age it in. The Swill is also available, for guests with simpler tastes, or none. Canapés are complimentary with a drink. They are not actually complimentary.", "options": [{"next": "root", "label": "Back"}]}, "root": {"text": "Welcome to the Embassy Lounge, valued guest. We maintain certain standards here, within reason. What can I get you?", "options": [{"next": "menu", "label": "What''s on the menu?"}, {"next": "gossip", "label": "Any news from the front desk?"}, {"next": null, "label": "Never mind."}]}, "gossip": {"text": "Lowry lowers his voice to something discreet.", "actions": [{"action": "GOSSIP_TELL"}], "options": [{"next": "root", "label": "Back"}]}}', '[{"price": 22, "stock": 15, "item_id": "item_drink_embassy_reserve"}, {"price": 4, "stock": 99, "item_id": "item_drink_basin_swill"}, {"price": 9, "stock": 25, "item_id": "item_embassy_canapes"}]', 0, '{"mis_willing": false, "personality": "bartender", "clothing_layers": ["a worn leather bar-apron", "a tight black tee", "black briefs"]}', '{"nodes": {"start": {"next": "have_life", "type": "start"}, "at_work": {"next": "go_home", "type": "action", "action_type": "AT_WORK"}, "go_home": {"next": "home_wait", "type": "action", "action_type": "GO_HOME"}, "have_life": {"next": "go_to_work", "type": "action", "action_type": "HAVE_LIFE"}, "home_wait": {"next": "start", "type": "wait", "seconds": 60}, "go_to_work": {"next": "at_work", "type": "action", "action_type": "GO_TO_WORK"}}, "_start": "start"}', 'zone_meridian_unit_102', NULL, 'zone_residential_lobby', '["What''ll it be?", "You look like you''ve had a rough one.", "Pay first. Trust later. That''s policy.", "You''re not the first person to cry at this bar. Won''t be the last.", "I''ve heard worse. Much worse.", "Last call was three hours ago. I''m still here.", "We''re out of the good stuff. We were always out of the good stuff.", "Tab''s running. Keep drinking.", "I don''t ask questions. That''s why people come here.", "You want ice with that? Funny."]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{"fri": [{"to": 24, "from": 0}], "mon": [{"to": 24, "from": 0}], "sat": [{"to": 24, "from": 0}], "sun": [{"to": 24, "from": 0}], "thu": [{"to": 24, "from": 0}], "tue": [{"to": 24, "from": 0}], "wed": [{"to": 24, "from": 0}]}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.npcs (id, name, description, zone_id, faction, dialogue_tree, vendor_inventory, wanders, flags, behaviour_graph, home_zone, studio_zone_id, work_zone_id, chitchat, hp, hp_max, sex, vendor_stock, vendor_stock_size, vendor_restock_rate, vendor_credits, npc_type, vendor_schedule, vendor_bank_credits, vendor_shop_name, home_activities, banter, wander_zones) VALUES ('npc_dex_rime', 'Dex Rime', 'A broadcast studio host.', 'zone_nc_spindle', NULL, '{}', '[]', 0, '{"studio_npc": true, "mis_willing": false}', '{"nodes": {"n_life": {"next": "n_check", "type": "action", "action_type": "HAVE_LIFE"}, "n_work": {"next": "n_atwork", "type": "action", "params": {"zone_id": "zone_studio_1782953094650"}, "action_type": "GO_TO_WORK"}, "n_check": {"type": "action", "goToWork": "n_work", "haveLife": "n_life", "action_type": "CHECK_WORK"}, "n_start": {"next": "n_check", "type": "start"}, "n_atwork": {"next": "n_check", "type": "action", "action_type": "AT_WORK"}}, "_start": "n_start"}', 'zone_studio_1782953094650', NULL, 'zone_studio_1782953094650', '[]', 20, 20, 'male', '[]', 10, 1, 0, 'npc', '{"fri": [{"to": 22, "from": 10}], "mon": [{"to": 22, "from": 10}], "sat": [{"to": 22, "from": 10}], "sun": [{"to": 22, "from": 10}], "thu": [{"to": 22, "from": 10}], "tue": [{"to": 22, "from": 10}], "wed": [{"to": 22, "from": 10}]}', 0, NULL, '[]', '[]', '[]');
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_ficus_zone_meridian_lobby', 'zone_meridian_lobby', 'dead ficus', 'A ficus in a chipped ceramic planter, dead so long it has gone the grey of old newspaper. And yet the soil is damp — someone keeps watering it. Hope is a hard habit to break.', '{}', 'decoration', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_bench_zone_meridian_lobby', 'zone_meridian_lobby', 'cracked vinyl bench', 'A low waiting bench upholstered in oxblood vinyl, split along every seam and weeping yellow foam. It has absorbed forty years of people waiting for elevators that stopped working in year three. It still holds weight, if you don''t mind the crunch.', '{"interactions": ["sit", "lean"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_47054b84', 'zone_apt_2', 'neural interface couch', 'Long enough to lie flat in, upholstered in smart-foam that tracks your body temperature. Three data ports run along the headrest.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 3200, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_1782683782251', 'zone_residential_lobby', 'citadel financial ATM terminal', 'A sleek black ATM glows beneath flickering neon, its holographic display cycling ads between transactions. Biometric scanners and an armored card slot sit beneath a scratched, graffiti-covered shell, weathered by the city''s streets.', '{"atm": true, "interactions": []}', 'terminal', 0, NULL, 5, NULL, 400, 12000, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt1_hotplate', 'zone_apt_1', 'hot plate', 'A two-burner electric hot plate plugged into the wall near the door. One burner glows red when switched on. The other has been dead for a while.', '{"interactions": []}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 45, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_embassy_corkboard', 'zone_residential_lobby', 'unit listings corkboard', 'Bolted over what used to be the concierge desk. Handwritten unit listings cover every inch, half of them crossed out and re-listed at a worse price.', '{"interactions": []}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 25, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_mailboxes_zone_meridian_lobby', 'zone_meridian_lobby', 'tenant mailboxes', 'A bank of aluminum tenant mailboxes bolted to the east wall, most pried open decades ago — little doors hanging off single hinges, keyholes drilled out. A yellowed flyer for a pizza place that no longer exists is still wedged in slot 4C. Nobody here is expecting mail.', '{}', 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt12_lamp', 'zone_apt_12', 'portable lamp', 'A battered work lamp on the floor, doing the job of the fixtures stripped out of the ceiling. Its shade throws a warm cone up the wall and leaves the corners to themselves.', '{"interactions": ["switch"]}', 'light', 1, 'lamp', 5, NULL, 400, 30, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt2_cot', 'zone_apt_2', 'metal-framed cot', 'A narrow army-surplus cot with a thin mattress and a wool blanket folded at the foot. Functional, if not comfortable.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 70, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_1782511287046', 'zone_residential_lobby_z-1_1782105292491', 'overhead light', 'A bare bulb on a pull-chain. Functional, nothing more.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt12_bed', 'zone_apt_12', 'wide bed', 'A broad bed under the window, wide enough for two who trust each other. The far side of the building from the bar — as quiet as the Embassy gets.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 120, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_embassy_stools', 'zone_residential_lobby', 'cracked vinyl stools', 'A half-dozen stools lined up at the counter, vinyl split and patched with duct tape. Free to sit, if you don''t mind the wobble.', '{"interactions": ["sit"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 35, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_emerglight_zone_meridian_lobby', 'zone_meridian_lobby', 'emergency light bar', 'A wall-mounted emergency light bar on a trickle-charged cell, casting the pale amber wash the lobby is named for. It stays lit when the grid drops — about the only promise this building still keeps.', '{}', 'light', 1, 'emergency', 5, NULL, 350, 25, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt12_wardrobe', 'zone_apt_12', 'mirrored wardrobe', 'A freestanding wardrobe with a full-length mirror gone black and blistered at the edges. Your reflection stands in the clear middle, hemmed in by the dark.', '{"interactions": ["lean"]}', 'fixture', 0, NULL, NULL, NULL, NULL, 90, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt2_poster', 'zone_apt_2', 'faded travel poster', 'A glossy travel poster, sun-bleached to pastel. A beach. Palm trees. A slogan that has faded to illegibility. Whoever left it here was thinking of somewhere else.', '{"interactions": []}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 15, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_1782365983389', 'zone_thresholdeast', 'graffiti: COUNT YOUR DAYS', 'Scratched directly into the inside of the door, deep enough that it can''t be painted over. COUNT YOUR DAYS. Below it, someone has scratched a smaller reply: I DID. STILL HERE.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_1782276836159', 'zone_start', 'overhead light', 'A bare bulb on a pull-chain. Functional, nothing more.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_secdesk_zone_meridian_lobby', 'zone_meridian_lobby', 'security desk', 'A curved reception desk in scuffed laminate, built to be manned around the clock. The chair behind it is long gone. A dead terminal cycles a screensaver of rolling static, throwing a faint grey flicker across the underside of the counter. A coffee ring older than most of the tenants has fossilized on the surface.', '{"interactions": ["lean"]}', 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_light2_zone_meridian_lobby', 'zone_meridian_lobby', 'sodium ceiling fixture', 'A recessed sodium fixture someone coaxed back to life, buzzing faintly and washing the terrazzo in warm, slightly sallow light.', '{}', 'light', 1, 'overhead', 18, NULL, 1000, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_embassy_bar_counter', 'zone_residential_lobby', 'the embassy lounge bar', 'A scarred wooden counter beneath the brass THE EMBASSY LOUNGE sign. Lowry keeps it spotless out of sheer habit.', '{"interactions": ["lean"]}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 2500, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt1_crate', 'zone_apt_1', 'wooden crate', 'A salvaged shipping crate pressed into service as a side table and spare seat. FRAGILE is stenciled on the side, which stopped being relevant some time ago.', '{"interactions": ["sit", "lean"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 20, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_streetlight_zone_city_north', 'zone_city_north', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 200, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_sl_zone_meridian', 'zone_meridian', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 0, NULL, NULL);
