INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_threshold_trashbin', 'zone_threshold', 'trash bin', 'A dented metal waste bin bolted to the wall. Anything you put in it is gone. That''s the point.', '{"trash_bin": true, "interactions": []}', 'container', 0, 'lamp', NULL, NULL, NULL, 15, NULL, NULL);
