INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_basement_chair', 'zone_residential_lobby_z-1_1782105292491', 'broken office chair', 'A wheeled office chair with a cracked backrest and one arm missing. It still rolls, barely, and takes your weight if you sit carefully.', '{"interactions": ["sit"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 20, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_basement_cabinet', 'zone_residential_lobby_z-1_1782105292491', 'utility cabinet', 'A heavy steel cabinet bolted to the wall beside the breaker box. Padlocked. The padlock is old enough that it''s probably more rust than mechanism.', '{"interactions": []}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 90, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt3_shelves', 'zone_apt_3', 'metal shelving unit', 'Floor-to-ceiling metal shelving, everything on it arranged by size. Whatever was here has been taken. The organisation left behind.', '{"interactions": ["lean"]}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 120, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt4_armchair', 'zone_apt_4', 'salvaged armchair', 'A wide, low armchair, upholstery worn smooth at the arms. Something lumpy is stuffed into the left cushion. You decide not to investigate.', '{"interactions": ["sit"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 110, NULL, NULL);
