INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_antenna_zone_meridian_roof', 'zone_meridian_roof', 'rusted antenna mast', 'One of the taller masts still standing, guy-wires sagging, a dish at the top aimed at a satellite that stopped answering during the Collapse. In high wind it hums a single flat note, like it''s trying to remember what it was for.', '{}', 'decoration', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_basement_racks', 'zone_residential_lobby_z-1_1782105292491', 'rusted storage racks', 'Floor-to-ceiling metal shelving bolted to the far wall. Most shelves are empty; the rest hold broken equipment, unmarked boxes, and things that stopped being useful before anyone thought to throw them out.', '{"interactions": ["lean"]}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 60, NULL, NULL);
