INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_hero_poster_bonghitz', '__posters_test_apt__', 'hero poster: BONGHITZ, THE UNCLOUDED MIND', 'A wheat-pasted propaganda poster, two meters tall, gone soft and rippled at the edges. A man is rendered in heroic gold-leaf halftone, chin lifted to a sunburst, a monumental bong cradled in both arms like a martyr''s relic. Sacred smoke coils up to spell one word: PEACE. The caption reads: BONGHITZ — HE INHALED YOUR FEAR SO YOU WOULDN''T HAVE TO. Someone has scrawled "still owes me 40 credits" across his glowing forehead in marker.', '{"poster_key": "bonghitz", "hero_poster": true}', 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_light_zone_mq_chrome_303', 'zone_mq_chrome_303', 'overhead light', 'A bare bulb on a pull-chain, buzzing faintly. Functional, nothing more.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', NULL, NULL, 1200, 40, NULL, NULL);
