INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_bed_zone_meridian_unit_102', 'zone_meridian_unit_102', 'prefab bed', 'A mass-produced sleeping slab: a thin foam mattress sagging on a dented aluminium frame, stamped with a faded ARCOLOGY HOUSING lot number. The foam has long since taken the shape of everyone who slept here before you, and none of them slept well. Cheap, functional, and faintly institutional — but after a day in the sprawl, it might as well be a cloud.', '{"bed": true, "interactions": ["sit", "lie", "lean"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 55, NULL, NULL);
