INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt7_kitchenette', 'zone_apt_7', 'two-burner kitchenette', 'A strip of counter with two working burners and a scorched gap where a third used to be. The yellow paint above it has cooked to brown.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 60, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_chem_lab', 'zone_drum_basement', 'chem lab', 'A scavenged chemistry bench — ring stands, a fume hood that half works, reagent bottles labelled in three languages and a skull. Smells like ambition and poison.', '{"station_quality": "refined", "crafting_station": "chem_lab"}', 'appliance', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt7_tub', 'zone_apt_7', 'cast-iron bathtub', 'A clawfoot tub marooned in the middle of the room, because the plumbing never reached the back wall. People have slept in worse. People have slept in this.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 80, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt6_radiator', 'zone_apt_6', 'clanking radiator', 'A cast-iron radiator that either roars out heat or sits stone cold — never anything between. It announces each change of mood with a bang like a dropped wrench.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt7_table', 'zone_apt_7', 'fold-down table', 'A table hinged to the wall, folded down and propped on a single leg. It wobbles under anything heavier than a bottle.', '{"interactions": ["lean"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt7_light', 'zone_apt_7', 'overhead bulb', 'A bare bulb on a pull-chain. Functional, nothing more.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL);
