INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt5_hotplate', 'zone_apt_5', 'wall hotplate', 'A two-burner hotplate wired straight into the wall socket by someone who didn''t respect electricity. One burner glows. The other waits.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 45, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt8_bed', 'zone_apt_8', 'iron-frame bed', 'A real bed with a real frame — a rarity worth the rent by itself. Made up, even, though the blanket still smells of the last tenant''s cigarettes.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 90, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt11_cot', 'zone_apt_11', 'narrow cot', 'A cot wedged along the one wall long enough to take it. ''Cozy,'' the corkboard called it. It meant small.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 45, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_streetlight_zone_city_south', 'zone_city_south', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 200, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_streetlight_velk_1', 'zone_velk_exterior', 'streetlight', 'A tall sodium-vapor streetlight on a graffiti-tagged pole. It clicks on at dusk and off at dawn, assuming the city power holds.', '{"is_light": true, "light_type": "streetlight"}', 'light', 0, 'streetlight', NULL, NULL, NULL, 200, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_streetlight_drum_2', 'zone_drum_exterior', 'streetlight', 'A second streetlight at the far end of the block. Someone has taped a flyer to the base that has since become illegible.', '{"is_light": true, "light_type": "streetlight"}', 'light', 0, 'streetlight', NULL, NULL, NULL, 200, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt10_light', 'zone_apt_10', 'bare bulb', 'A dim bulb under the sloping ceiling, close enough to the roofline to buzz when the wind gets up.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', 12, NULL, 900, 30, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt10_bed', 'zone_apt_10', 'camp bed', 'A canvas camp bed under the low slope of the ceiling. Sit up too fast in the night and you''ll learn exactly where the cornice cuts in.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 50, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt9_hook', 'zone_apt_9', 'ceiling hook', 'A steel hook screwed into a joist, once home to a fan, now to nothing. It turns a slow quarter-circle in the draft, as if weighing its options.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt11_toilet', 'zone_apt_11', 'curtained toilet', 'A toilet in the corner behind a shower curtain on a sagging wire. The curtain is the only thing in the unit anyone bothered to keep clean.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 30, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt11_light', 'zone_apt_11', 'overhead bulb', 'A bare bulb on a pull-chain. Functional, nothing more.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt9_light', 'zone_apt_9', 'overhead bulb', 'A bare bulb on a pull-chain, brighter than most — someone up here changed it recently.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt8_light', 'zone_apt_8', 'overhead bulb', 'A bare bulb on a pull-chain. Functional, nothing more.', '{"interactions": ["switch"]}', 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt8_chair', 'zone_apt_8', 'overturned chair', 'A wooden chair left on its side by whoever cleared out in a hurry. Set it upright and it''s a seat; leave it and it''s a warning.', '{"interactions": ["sit"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 25, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt9_bed', 'zone_apt_9', 'proper bed', 'An actual bed with an actual headboard, tucked under the window that opens. Clean sheets. The single most civilised object in the Embassy.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 110, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt8_candles', 'zone_apt_8', 'ring of candle stubs', 'A circle of melted candle stubs on the floorboards, wax pooled and hardened. Ritual, blackout, or just cheaper than the meter — no way to tell now.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt10_patch', 'zone_apt_10', 'road-sign patch', 'A hole in the plaster covered by a bent STOP sign screwed over the gap. When it rains you can hear the drip land behind it before it finds the bucket.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt11_sink', 'zone_apt_11', 'rust-run sink', 'A wall sink that coughs rust for a full minute before the water runs anything like clear. The enamel is worn through to black at the drain.', '{"interactions": []}', 'fixture', 0, NULL, NULL, NULL, NULL, 40, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt10_footlocker', 'zone_apt_10', 'steel footlocker', 'An army footlocker at the foot of the bed, the hasp scarred where a lock used to be. Doubles as the room''s only chair.', '{"interactions": ["sit"]}', 'furniture', 0, NULL, NULL, NULL, NULL, 45, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_apt9_desk', 'zone_apt_9', 'wall-bolted desk', 'A slab of desk bolted flush to the wall so nobody can carry it off. Someone did their thinking here — the surface is ringed with coffee and scored with crossed-out sums.', '{"interactions": ["lean"]}', 'fixture', 0, NULL, NULL, NULL, NULL, 70, NULL, NULL);
