INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_generator_coldwater', 'zone_coldwater_turbine_hall', 'coldwater main generator', 'A colossal city-grade turbine generator, its armoured casing streaked with grime and hazard chevrons. Banks of indicator lights stutter across its control face; a heavy sealed hacking port is bolted shut beneath a cracked screen. It ROARS.', '{"destructible": true, "generator_id": "gen_zone_powerplantnew_1782069598190", "requires_demolition": true}', 'generator', 0, 'lamp', NULL, NULL, NULL, 0, 5000, 5000);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_1782698855727', 'zone_warehouse', 'notice board', 'A thick slab of cork bolted to a sheet of armored steel, repaired so many times it''s become sturdier than the wall behind it. Flyers overlap handwritten notes, official-looking forms, faded family photos, and at least three declarations of eternal vengeance. Someone keeps tidying it every morning, which is either comforting or deeply unsettling.', '{"bulletin": true, "interactions": []}', 'furniture', 0, NULL, 5, NULL, 400, 25, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('secdev_pd_zone_residential_lobby_z-1_1782105292491', 'zone_residential_lobby_z-1_1782105292491', 'PD street camera', 'A hardened municipal camera on a tall pole, blue status light steady. A decal reads SPECTER-PD — SMILE.', '{"concealed": false, "device_id": "secdev_pd_zone_residential_lobby_z-1_1782105292491", "security_device": true}', 'security_device', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_vendor_safe_juno', 'zone_furniture_store', 'phantom vault', 'A matte-black security enclosure about the size of a microwave oven, bolted directly into the structural concrete behind the counter. The door has no visible seam, no keyway, no biometric reader. The entire face is a single panel of electrochromic glass that cycles between mirror, opaque, and — briefly — translucent, though there is nothing visibly inside when it clears. A holographic lock interface shimmers above the surface: a rotating key rendered in the 8–14nm band, invisible to the naked eye. The frequency shifts every ninety seconds. Etched in the concrete beside it in small, precise letters: PROPERTY OF VENDOR. MONITORED.', '{"vendor_safe": true, "vendor_npc_id": "npc_juno_kael", "hack_difficulty": 5}', 'fixture', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt2_crate', 'zone_apt_2', 'plastic storage crate', 'A heavy-duty plastic crate — the kind you find in a demolished warehouse — doing duty as a bedside table. A candle stub sits on top of it.', '{"interactions": ["sit", "lean"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 25, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_sl_zone_tunnels', 'zone_tunnels', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 200, NULL, NULL);
