INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_cell_weightbench', 'zone_mq_precinct_holding', 'prison weight bench', 'A slab of a bench welded from scrap rebar and a cracked vinyl pad, bolted to the floor so nobody gets ideas about swinging it. The plates are mismatched chunks of poured concrete on a bent bar, worn smooth by a thousand bored inmates. It is, somehow, the most honest thing in the building.', '{"interactions": ["lie", "lift"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_cell_toilet', 'zone_mq_precinct_holding', 'steel cell toilet', 'A seatless steel toilet-and-basin combo bolted to the cinderblock, scuffed to a dull shine by a decade of reluctant use. No lid, no privacy, no dignity — just cold metal and a slow, resigned trickle.', '{}', 'toilet', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_cell_sink', 'zone_mq_precinct_holding', 'stainless cell sink', 'A knuckle-sized stainless basin jutting from the wall above the toilet. One push-button tap coughs out a thin stream of cold water — enough to drink, or to scrub the worst of the night off your hands.', '{"water_source": true}', 'sink', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_cell_cot', 'zone_mq_precinct_holding', 'bolted steel cot', 'A steel shelf welded to the wall, topped with a vinyl pad the thickness of a sympathy card. It is not comfortable. It is, technically, a place to lie down until the clock lets you out.', '{"interactions": ["sit", "lie"]}', 'furniture', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_sl_zone_mq_marquee', 'zone_mq_marquee', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_apt2_hardcase', 'zone_apt_2', 'Nexis biometric hardcase', 'A matte-black composite case the size of a footlocker, its corners scuffed down to bare alloy. A biometric pad glows a patient amber above the seam — jailbroken, by the look of it, the lock light stuttering between green and red. Heavier than it has any right to be.', '{"container": 40000}', 'container', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_hero_poster_kiyo', 'zone_apt_1', 'hero poster: KIYO, THE GRID-BREAKER', 'A heavy-stock poster, its edges scorched like it was printed too close to something on fire. Kiyo stands hip-deep in a nest of torn cabling and cracked-open server towers, sleeves shoved past the elbow, a soldering iron in one fist and a length of live wire in the other, sparks hanging frozen around a face that hasn''t slept and doesn''t intend to. Behind him a dead machine is grinding back to life at his say-so. KIYO — HE DOESN''T FIX THE MACHINE. HE MAKES IT AFRAID OF HIM. Stencilled below in service-manual type: "give him ten minutes and a junction box and he''ll hand you a weapon, a bomb, or a way out — his call." A real strand of copper wire is threaded through two punched holes, worried bright by passing thumbs.', '{"poster_key": "kiyo", "hero_poster": true}', 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_sl_zone_mq_chrome_roof', 'zone_mq_chrome_roof', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_sl_zone_mq_ember', 'zone_mq_ember', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 0, NULL, NULL);
