INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furniture_1783065860962', 'zone_residential_lobby', 'shoddy television', 'A battered flatscreen bolted to the wall with mismatched screws. The casing is cracked and one corner is held together with duct tape, but the picture still comes through.', '{"tv": true, "interactions": ["watch"], "tv_dial_freq": 7, "broadcast_receiver": true, "broadcast_device_type": "tv"}', 'furniture', 0, NULL, 5, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_hero_poster_ocelot', 'zone_residential_lobby', 'hero poster: OCELOT, THE SHADOW THAT GUARDS', 'A sleek, expensive-looking poster — someone spent real money on this one. A silhouette crouches on a gargoyle of rebar, eyes rendered as two slit-pupil coins of reflective foil that catch you wherever you stand. OCELOT WATCHES THE STREET SO THE STREET NEVER SLEEPS ALONE. Below, in a smaller, warmer font: "sightings unconfirmed. that''s the point." The foil eyes have been half-peeled by someone who wanted the shiny bit.', '{"poster_key": "ocelot", "hero_poster": true}', 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_sl_zone_mq_cathode', 'zone_mq_cathode', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}', 'light', 0, 'streetlight', 200, NULL, 8000, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_schd_npc_salvage_broker', 'zone_slag_gate', 'Voss Iyaka''s Schedule', 'Voss Iyaka''s Schedule
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_hero_poster_alphagunman', 'zone_meridian_lobby', 'hero poster: ALPHAGUNMAN, THE LAST STRAIGHT SHOOTER', 'A high-contrast poster built like a wanted bill turned inside-out — not WANTED but WANTED BACK. A gunfighter stands centred and unhurried against a white noon, coat open, hands empty and loose, because the poster wants you to understand he doesn''t need to reach. ALPHAGUNMAN NEVER FIRED FIRST. HE NEVER HAD TO FIRE SECOND EITHER. The paper is punched clean through by a single old bullet hole, dead centre, which someone has helpfully circled and labelled "exhibit A."', '{"poster_key": "alphagunman", "hero_poster": true}', 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
INSERT INTO public.furniture (id, zone_id, name, description, flags, object_type, light_on, light_type, power_draw_kw, light_on_intended, lumen_output, price, hp, hp_max) VALUES ('furn_hero_poster_stabbz', 'zone_mq_sump_bar', 'hero poster: STABBZ, THE PEOPLE’S SCALPEL', 'A heroic poster in deep arterial reds, the ink already flaking. A lean figure stands astride a heap of the vanquished, a knife raised to a stormbreak sky, its edge catching a light that isn''t in the rest of the picture. THE PEOPLE''S SCALPEL, the banner proclaims, HE CUTS ONLY WHAT NEEDS CUTTING. The fine print at the bottom, tiny and legal, adds: "definition of ''needs'' at the sole discretion of Stabbz." A brown handprint is dried across one corner.', '{"poster_key": "stabbz", "hero_poster": true}', 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL);
