INSERT INTO public.sounds (id, name, category, descriptions, loudness, enabled, propagation) VALUES ('2dc84334-cc04-4908-b328-1031e78ff8dc', 'knock', 'impact', '["Someone knocks on a door nearby.", "A firm knock echoes through the wall.", "Three sharp raps sound from close by.", "A dull thud — someone knocking.", "The hollow knock of knuckles on wood.", "A polite double-knock, close by.", "Knock knock. Whoever it is, they''re persistent.", "A single loud knock reverberates.", "You hear someone rapping on a surface nearby.", "A muffled knock — maybe a door, maybe not."]', 1, 1, 'both');
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('498c7c60-256e-4393-9e61-4bfff9a6d477', 'outdoors', 'Leaves rustle softly nearby.', 1, 0.8, 100);
