INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('b45ab1db-0477-413f-9bd2-b4ad177f0c9d', 'indoors', 'You catch a brief, sharp smell — antiseptic or chemicals.', 1, 0.3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('a69e9a24-0872-49fc-b731-e1fea1a23820', 'indoors', 'Pipes in the wall groan and tick as something moves through them.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('e0423f57-ff4e-4d5f-9514-df5fabc1eb77', 'indoors', 'A phone rings distantly and isn''t answered.', 1, 1, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('bdc3a88f-8628-42c7-8a70-0c6f3a587180', 'indoors', 'Something scurries behind the walls.', 1, 0.8, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('833cd4ad-a568-4196-89bd-04bbb6880481', 'indoors', 'A distant hum that you can feel more than hear.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('64101204-04dd-46ff-8115-711ba0bb3756', 'industrial', 'Heavy machinery drones somewhere beyond the walls.', 1, 2, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('77938a56-23d9-4512-81c2-fb6f157fd304', 'industrial', 'A pressure valve releases with a sharp hiss.', 1, 2.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('dc7f7249-2cd3-4da5-b96b-d82db859ab65', 'industrial', 'Metal impacts metal — a rhythmic hammering from deeper inside.', 1, 2, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('cedf448c-955d-4257-a933-452f6891cf3d', 'industrial', 'Something large shifts overhead. Structural, probably.', 1, 1.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('66866461-9175-48a0-8f98-92793f188f24', 'industrial', 'Sparks cascade briefly from a junction box across the room.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('ab0f9d3a-e949-4fa2-9f67-72d6d2afd51f', 'industrial', 'A conveyor belt squeals and then stops.', 1, 1.5, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('1ccaaa9e-feee-4bde-af3e-f5bc230c1349', 'industrial', 'Coolant or fluid drips from overhead piping into a spreading puddle.', 1, 0.8, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('674eca47-8abe-434d-a022-18adc1dce301', 'industrial', 'Warning lights pulse orange through a distant corridor.', 1, 0.5, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('a49e49d0-db68-49b7-8f6e-8c024730d7fb', 'industrial', 'An alarm sounds briefly, three notes, then cuts off.', 1, 3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('088c335c-c5e9-4b9b-ac05-f82fdf1d47f1', 'industrial', 'You can feel vibration in the floor from something enormous running below.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('812fa6cf-59e4-401d-abee-55dcf837fc2a', 'underground', 'Water drips in the darkness ahead.', 1, 0.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('9699f206-2093-4c4e-9596-f1dea26df84b', 'underground', 'The walls carry a low rumble — the surface world, distant.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('783dab7c-4e12-49cf-925b-224cc7bc2220', 'underground', 'Something shifts in the rock above. The ceiling holds.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('49906fd3-8f2c-4e53-92a9-86100c7ab2b5', 'underground', 'A colony of insects moves somewhere nearby, just out of sight.', 1, 0.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('70fb3f89-c427-4120-a4df-021f372283d3', 'underground', 'Your own breathing sounds too loud down here.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('7c516251-3bfa-4553-9d36-c34b8cda282c', 'underground', 'The air pressure shifts, as if something large moved far away.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('7f33c3e0-5ee3-4fbd-b0b5-0db50a31d014', 'underground', 'A slow grinding noise rolls through the stone, then fades.', 1, 1.5, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('d78a6c96-1d0b-4210-9485-1b951eb25d06', 'underground', 'The darkness ahead seems to shift, though you can''t tell why.', 1, 0.3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('126bb65b-9e87-454b-b395-8689824032e7', 'underground', 'Something brushes past overhead in the dark — wings, maybe.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('20912278-dceb-41e1-b8bc-7f509f84838f', 'underground', 'The smell changes: mineral, damp, old.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('979ab383-ac02-4d08-ba64-edc06b1a0c31', 'waterfront', 'Waves lap against something nearby.', 1, 0.8, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('67108fc4-b569-42b4-968c-44be261f517c', 'waterfront', 'A buoy bell clanks irregularly with the water.', 1, 1.2, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('241aadd2-3e78-4b21-af56-4f39a59bde3b', 'waterfront', 'Seabirds argue somewhere overhead.', 1, 1.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('11f0c392-33bd-43e6-97a6-a30e4d83f60e', 'waterfront', 'A foghorn sounds in the distance — long and hollow.', 1, 3, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('8e7b4017-b221-4c6b-8a24-6a5fd19729a4', 'waterfront', 'The smell of salt and diesel drifts past.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('538b4098-abc8-48af-bb60-e593422fcd73', 'waterfront', 'A chain drags across concrete somewhere nearby.', 1, 1.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('461c128f-baee-428f-97b7-db9ee45d75f7', 'waterfront', 'A boat engine starts up and idles, then throttles away.', 1, 2.5, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('eb4f88c6-5433-4fab-83e9-8e899b96aa14', 'waterfront', 'Something large surfaces briefly in the water nearby and sinks.', 1, 1, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('b2a241ff-2322-4f1e-969b-524b4269f2e5', 'waterfront', 'Cargo shifts in a container somewhere close with a dull boom.', 1, 2, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('42bb960a-af1d-404f-9a7c-c483a16311ad', 'forest', 'A branch snaps somewhere in the treeline.', 1, 1.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('765ea4fe-2f31-4d0f-b1f4-afa2a48b17a6', 'forest', 'Birds fall quiet all at once. Then, slowly, start again.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('24b3ca46-6347-4459-a24b-8f1c1d55a3b8', 'forest', 'The undergrowth moves nearby. Too large for a small animal.', 1, 1.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('4647f69a-f171-4eee-8f56-eb6776b8e50a', 'forest', 'Wind moves through the canopy above like a long exhale.', 1, 0.8, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('c1d5d4c6-b010-4fcb-9d70-57b92aeb267c', 'forest', 'Something calls from deeper in — it doesn''t sound like any animal you know.', 1, 1.5, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('ff887318-73c3-45c3-ab00-151041a160bb', 'forest', 'An insect lands on you and is gone before you can look.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('7a772b9b-554e-4345-9e46-a8143a9bbc72', 'forest', 'Leaves overhead filter the light into shifting patterns.', 1, 0.3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('9441bf38-04de-4cd9-acee-aea6655ff8bd', 'forest', 'The forest has a smell here: rot and growth, inseparable.', 1, 0.3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('a1c61cf6-7e21-40c9-af64-8c8f6496fc11', 'forest', 'Something large watches from the treeline. You can''t prove it.', 1, 0.5, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('7c51b45e-b398-45ba-a0fc-c8b76e7258d4', 'ruins', 'A section of ceiling crumbles nearby, raining dust.', 1, 1.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('fc08c11a-c3d9-48a1-8750-727459e96b0f', 'ruins', 'Wind moves through collapsed walls with a low moan.', 1, 1, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('a8383382-cc2d-46ce-9a46-07b3b4b7f13c', 'ruins', 'Old newspaper or debris skitters across the floor.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('4e0346fe-6c19-475e-aac8-396688c8aba7', 'ruins', 'A structure somewhere close shifts and settles.', 1, 2, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('001f9968-ae1e-43ac-90b3-70f0f7cb22f6', 'ruins', 'The floor is uneven here — evidence of something that happened below.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('d3365b4c-4bb2-48f2-ad1d-2fea713fc9fa', 'ruins', 'Broken glass grinds underfoot somewhere nearby.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('1e235821-71e4-40e2-b48f-df114fe810c0', 'ruins', 'Exposed rebar has rusted into the color of dried blood.', 1, 0.3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('90be81b6-1ba2-4dbe-8103-dedba6835d2e', 'ruins', 'Something has been nesting here. Whatever it was, it left recently.', 1, 0.5, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('70adcef6-39da-4557-b59c-699b87ea8c67', 'ruins', 'Graffiti covers the walls in multiple layers. The oldest is illegible.', 1, 0.3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('0535f377-1acb-4f5a-8e9f-9f790cb00d2b', 'commercial', 'A PA system crackles somewhere — no words, just static.', 1, 1.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('effc7441-8c84-40a2-9295-9a64b769b242', 'commercial', 'Muzak leaks from a vent above. The song is unidentifiable and wrong.', 1, 0.8, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('c0fb6a5c-8d3e-4de7-99f2-a113d2d05c96', 'commercial', 'A security camera tracks slowly across the space.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('2cc944ad-4903-44f1-8ad4-ed9799af5be3', 'commercial', 'Automatic doors open and close for no one somewhere nearby.', 1, 1.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('ea15e959-1440-4591-8406-0aed1fa251e2', 'commercial', 'A cash register drawer slides open and shut.', 1, 1, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('cd75997b-34cc-4c1c-beb8-08e69d1c68ea', 'commercial', 'Refrigeration units hum behind locked staff doors.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('f4f46b17-7e86-42bb-ae31-10ddb76593cf', 'commercial', 'Something on a shelf falls over. Nothing else moves.', 1, 1.2, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('f88c0c68-9255-4323-864d-62c3af8889f1', 'commercial', 'The floor wax is cracked here. No one has maintained this in a while.', 1, 0.3, 60);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('935b19fa-f3af-432c-9a37-8202a91f0b92', 'residential', 'Someone coughs in a nearby unit.', 1, 0.8, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('bd43d0f4-013b-4f4d-befb-1479e2cc4fdb', 'residential', 'A TV plays through a wall — voices, then laughter, then silence.', 1, 1, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('addfc51c-b385-4cfa-a438-ddb3ac8770f6', 'residential', 'A baby cries briefly and is hushed.', 1, 1.2, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('42d0e012-095c-46aa-a560-2f526e4e42ae', 'residential', 'Cooking smells drift under a door somewhere close.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('298af276-4540-4b09-960f-07c64b4e1ce0', 'residential', 'Upstairs, someone paces back and forth.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('ce590a20-74ce-4990-bb61-422bc63b1800', 'residential', 'A toilet flushes in a nearby unit.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('37e4248b-8b0a-4eae-80f3-01c216a97979', 'residential', 'An argument bleeds through the walls — low, tense, unresolved.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('0edaabd0-8abd-4f8b-95cc-943d09118191', 'residential', 'A dog scratches at a door and whines quietly.', 1, 0.8, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('7835a784-752c-46d6-8b10-847cb59f6fed', 'residential', 'Keys jangle outside. Whoever it was, they moved on.', 1, 1, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('2fba62f9-69ac-4380-94d7-285c949274c9', 'residential', 'The building''s heating ticks and pops as temperature shifts.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('37451184-fa7a-40cc-a249-6f26c055ab54', 'city', 'A burst of static from a radio or speaker crackles nearby.', 1, 1.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('15521f00-ed1f-4cfd-9734-c2223b1c5954', 'weather_rain', 'Rain hammers the street in shifting curtains.', 1, 1.2, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('6109045b-25ec-4490-803a-5318a37dd5b4', 'weather_rain', 'Water rushes through a clogged gutter somewhere nearby.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('64d066ef-583d-42c2-9c48-a6204cd5fff7', 'weather_rain', 'The rain intensifies briefly, then eases back.', 1, 1, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('56fd50bf-50ec-4254-b219-e5bccad9e4b2', 'weather_rain', 'Rainwater streams off an overhang in a heavy silver sheet.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('9ebec46a-1cce-408e-bfde-94b5664bd982', 'weather_rain', 'Puddles spread across the pavement, joining and dividing.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('2807b5fe-801d-41e4-a7dd-c9c199843d14', 'weather_rain', 'A drain somewhere gurgles as it struggles to keep up.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('956ffcb5-76f9-447f-a287-7f6ddad36218', 'weather_rain', 'The smell of wet concrete and rust hangs in the air.', 1, 0.3, 70);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('0c9b333c-a2e4-41b4-86af-a4c7cfff046e', 'weather_sleet', 'Ice pellets ping off metal surfaces in erratic bursts.', 1, 1, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('78326399-aeae-4c99-901b-c391a2ab0326', 'weather_sleet', 'Sleet hisses against every hard surface.', 1, 1, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('5c401b71-1103-421a-ab39-b0a8af9a32b9', 'weather_sleet', 'The ground is treacherous — a thin skim of ice over everything.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('95ead6cc-645f-47ac-bdb6-5fc28d903a04', 'weather_sleet', 'A bitter wind drives the sleet sideways.', 1, 1.2, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('863c9d2e-7935-454b-9d43-3b9a3613b293', 'weather_sleet', 'Sleet taps against every surface like bad static.', 1, 0.8, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('0b484848-0183-4573-976f-6a10feaf359f', 'weather_thunderstorm', 'Thunder rolls across the sky, close enough to feel.', 1, 3, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('a0bd6fae-da8b-49eb-bbd2-f37df750a575', 'weather_thunderstorm', 'Lightning strobes through the clouds, throwing everything into sharp relief.', 1, 1.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('f76081b0-71d9-4e74-bb12-f5594ba84868', 'weather_thunderstorm', 'A crack of thunder shakes the air — that one was close.', 1, 3.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('32f678c8-9ee2-4912-9164-093c520aabc2', 'weather_thunderstorm', 'Rain hammers everything flat.', 1, 2, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('fbf4efb0-a27d-4f14-a675-3ac0f77ac98e', 'weather_thunderstorm', 'Lightning hits something nearby with a sharp crack and a flash.', 1, 3, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('d49237f5-650c-44d9-94c1-9680fccf1eb8', 'weather_thunderstorm', 'Thunder rolls through in a long, grinding wave.', 1, 3, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('b7940578-4d67-442d-beb5-9e0479416ba0', 'weather_thunderstorm', 'The storm flares white for a second, and for a moment everything casts a shadow.', 1, 1.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('c341828d-8a42-4a63-8f40-8edc66c9c407', 'weather_storm', 'Wind screams between the buildings, finding every gap.', 1, 2.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('3ddee0ba-47f6-48bb-a3ae-81d2c5760334', 'weather_storm', 'Something large gets picked up by the wind and slams into a wall.', 1, 3, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('a3941767-461d-46e6-b399-e076af3247d5', 'weather_storm', 'A sheet of corrugated metal tears loose somewhere and clatters away.', 1, 2.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('df77394e-5a4d-494a-8cfb-6f03ea60428f', 'weather_storm', 'The wind drops for a second, then slams back twice as hard.', 1, 2, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('2fa6bd50-05db-4931-adb6-347b13340354', 'weather_storm', 'Debris skitters across the ground in sudden, sharp rushes.', 1, 1.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('94864f9a-4bee-48d4-a9e1-1cc5cf3a5fcc', 'weather_storm', 'A sign rips free overhead and vanishes into the dark.', 1, 2, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('9190327e-6d36-4c44-8db8-273c8fb4f64d', 'weather_storm', 'The wind makes the structures groan.', 1, 1.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('4fc0de03-bebd-4d19-b1c7-19dda167baeb', 'weather_snow', 'Snow falls in thick, slow flakes. Everything goes quiet.', 1, 0.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('97283b80-58d6-4e8e-8db8-dcb87b0e7684', 'weather_snow', 'A heavy drift slides off a roof somewhere above and hits the ground.', 1, 1.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('0b0a655d-35e3-461a-b4fb-05f936ebd646', 'weather_snow', 'Snow muffles the city into something almost peaceful. Almost.', 1, 0.3, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('25598cbd-5dd5-4b84-b87c-43b62a934e75', 'weather_snow', 'Footprints in the snow nearby, filling in fast.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('89a14897-d7a3-4931-92ce-fd29a188dbe7', 'weather_snow', 'Somewhere, a structure groans under the weight of accumulation.', 1, 1.2, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('e2d2756d-8c89-4820-9013-1888c874d7c6', 'weather_snow', 'Snow hisses softly against every surface.', 1, 0.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('faf8629f-e1ee-4d8f-8f80-d3ea05dedbd9', 'weather_blizzard', 'The blizzard whips snow into a horizontal wall of white.', 1, 2.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('77902823-f8c8-4e55-b19d-dfaa7459b6b9', 'weather_blizzard', 'Wind howls through every gap and crevice.', 1, 2.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('264c6a7b-b692-45fc-a2b8-3bebd842edfe', 'weather_blizzard', 'Visibility is nearly nothing. You''re navigating by feel.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('151eedf2-df0a-4f8d-8ccb-f33284647f0f', 'weather_blizzard', 'The cold cuts straight through everything.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('22c67c1e-6aed-404f-8fd3-29ec9f514270', 'weather_blizzard', 'Drifts are forming fast — in an hour this will be impassable.', 1, 0.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('76aaffe6-c3f1-4e15-882f-7c613c770a78', 'weather_blizzard', 'A gust hits like a wall. It takes effort to stay upright.', 1, 2, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('787a8384-a6f7-4af9-a4d0-add715cec4f4', 'weather_fog', 'Sound carries strangely in the fog — distant things seem close.', 1, 0.8, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('87004140-ebe6-4f23-abec-903e6a963596', 'weather_fog', 'The fog is thick enough to taste.', 1, 0.3, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('f153cf0f-3241-42a0-bc26-e1d40c7eb7bf', 'weather_fog', 'Shapes in the fog resolve into buildings only when you''re almost on top of them.', 1, 0.3, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('9a9374f5-7ee3-4100-9aa2-6a61691d6e5b', 'weather_fog', 'A foghorn sounds somewhere in the grey — direction impossible to pin.', 1, 2.5, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('84da183e-b2b3-4cd7-9f46-386588e04692', 'weather_fog', 'Moisture condenses on every surface. Everything drips slowly.', 1, 0.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('958f96fc-3c82-43c8-a168-ae66b5664973', 'weather_fog', 'Footsteps you can''t see echo from somewhere in the fog.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('7762f2e4-6824-492b-8058-3673375d7a9c', 'weather_haze', 'The air tastes like metal and chemicals.', 1, 0.3, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('38c761c7-320c-49b7-adf2-62eb1a69aadd', 'weather_haze', 'Your eyes water. It''s been worse before, but not by much.', 1, 0.3, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('2617c5e6-5959-42e1-bb00-d131f5e8ebc8', 'weather_haze', 'The haze gives everything a sickly orange tint.', 1, 0.3, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('512259c0-0e89-4c35-b0c6-0272cbe80524', 'weather_haze', 'Breathing feels faintly wrong, like the air is slightly off.', 1, 0.3, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('bbff51ff-35ba-4cd0-ad29-ffb04f89977b', 'weather_haze', 'The horizon has vanished into a flat brown smear.', 1, 0.3, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('d58668a7-667f-491e-84dd-29ec42e807e1', 'weather_ash', 'Ash drifts down like grey snow, coating every surface.', 1, 0.5, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('d75501e4-4a02-4272-92ae-9d76bfed0163', 'weather_ash', 'The air smells of sulfur and something burnt — organic, maybe.', 1, 0.3, 100);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('2f7350cc-3594-4f88-b58d-79dea3a7bbf2', 'weather_ash', 'Ash settles on your skin. It''s fine and dry and smells wrong.', 1, 0.3, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('86cc3d4c-6f5b-4eb6-9a40-a76c8d029e40', 'weather_ash', 'A thick layer of ash muffles footsteps, coats the ground grey.', 1, 0.5, 90);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('c128756c-cb82-4362-a0c9-eba2fe2eb496', 'weather_ash', 'Something is still burning, somewhere upwind.', 1, 1, 80);
INSERT INTO public.global_ambient_events (id, theme, message, enabled, loudness, weight) VALUES ('bbd3cdf7-9426-49e6-b864-66a3240845a1', 'weather_ash', 'The sky is the color of a dead monitor.', 1, 0.3, 80);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('recipe_pipe_weapon', 'Pipe Wrench', 'Combine scrap metal into a crude but effective blunt weapon.', 'weapons', NULL, '{"fabrication": 0}', '[{"item_id": "item_scrap_metal", "quantity": 3, "min_quality": "scrap"}]', '{"item_id": "item_pipe_wrench", "quantity": 1}', 'fabrication', 3);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('recipe_bandage', 'Field Bandage', 'Tear cloth into bandages. Requires nothing but desperation.', 'medicine', NULL, '{"medicine": 0}', '[{"item_id": "item_scrap_metal", "quantity": 0}]', '{"item_id": "item_bandage", "quantity": 2}', 'medicine', 2);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('recipe_rad_pills_crude', 'Crude RadAway', 'Improvised radiation treatment. Effective. Unpleasant.', 'medicine', 'chemistry_set', '{"medicine": 3, "fabrication": 1}', '[{"item_id": "item_mutant_gland", "quantity": 1, "min_quality": "common"}]', '{"item_id": "item_rad_pills", "quantity": 2}', 'medicine', 6);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('recipe_scrap_armor', 'Scrap Vest', 'Layer metal sheeting over salvaged clothing. Crude but it absorbs hits.', 'armor', NULL, '{"fabrication": 1}', '[{"item_id": "item_scrap_metal", "quantity": 5, "min_quality": "scrap"}]', '{"item_id": "item_scrap_armor", "quantity": 1}', 'fabrication', 4);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('recipe_glitch_decoder', 'Architect Signal Decoder', 'Assembles a device that can interpret Architect data fragments. Requires high skill and rare parts.', 'tech', 'architect_terminal', '{"hacking": 5, "electronics": 4}', '[{"item_id": "item_drone_core", "quantity": 1, "min_quality": "common"}, {"item_id": "item_architect_fragment", "quantity": 1, "min_quality": "common"}]', '{"item_id": "item_signal_decoder", "quantity": 1}', 'hacking', 10);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('recipe_ragplate_coat', 'Ragplate Coat', 'Quilt salvaged wadding into a longcoat and stitch scrap plate over the vitals. Crude, warm, and it''ll take a swing so your ribs don''t have to.', 'armor', NULL, '{"fabrication": 1}', '[{"item_id": "item_salvaged_wadding", "quantity": 3, "min_quality": "scrap"}, {"item_id": "item_scrap_metal", "quantity": 2, "min_quality": "scrap"}]', '{"item_id": "item_ragplate_coat", "quantity": 1}', 'fabrication', 3);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('synth_redline', 'Cook Redline', 'A fast, dirty stimulant cook. Entry-level chemistry.', 'synthesis', 'chem_lab', '{"chemistry": 1}', '[{"item_id": "item_precursor_stim", "quantity": 2}, {"item_id": "item_solvent", "quantity": 1}]', '{"item_id": "item_redline", "quantity": 1}', 'chemistry', 5);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('synth_grey', 'Cook Grey', 'Rendering opioid base into a usable dose.', 'synthesis', 'chem_lab', '{"chemistry": 1}', '[{"item_id": "item_precursor_opioid", "quantity": 2}, {"item_id": "item_solvent", "quantity": 1}]', '{"item_id": "item_grey", "quantity": 1}', 'chemistry', 5);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('synth_blotter', 'Distill Blotter', 'Fixing psychoactive extract onto blotter. Delicate work.', 'synthesis', 'chem_lab', '{"chemistry": 2}', '[{"item_id": "item_reagent_psycho", "quantity": 2}, {"item_id": "item_solvent", "quantity": 1}]', '{"item_id": "item_blotter", "quantity": 1}', 'chemistry', 6);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('synth_coldfire', 'Cook Coldfire', 'A dangerous combat-stim synthesis. One slip and it runs away from you.', 'synthesis', 'chem_lab', '{"chemistry": 3}', '[{"item_id": "item_precursor_stim", "quantity": 3}, {"item_id": "item_catalyst", "quantity": 1}, {"item_id": "item_solvent", "quantity": 1}]', '{"item_id": "item_coldfire", "quantity": 1}', 'chemistry', 7);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('synth_blacktar', 'Cook Blacktar', 'Deep, heavy opioid cook. Not for the squeamish or the shaky-handed.', 'synthesis', 'chem_lab', '{"chemistry": 3}', '[{"item_id": "item_precursor_opioid", "quantity": 3}, {"item_id": "item_catalyst", "quantity": 1}]', '{"item_id": "item_blacktar", "quantity": 1}', 'chemistry', 7);
INSERT INTO public.recipes (id, name, description, category, requires_station, skill_req, ingredients, base_output, skill_id, base_difficulty) VALUES ('synth_threshold', 'Synthesize the Threshold', 'Vaporised dissociative synthesis at the edge of what a home lab can do.', 'synthesis', 'chem_lab', '{"chemistry": 5}', '[{"item_id": "item_reagent_psycho", "quantity": 3}, {"item_id": "item_catalyst", "quantity": 2}]', '{"item_id": "item_threshold", "quantity": 1}', 'chemistry', 9);
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_buzz', 'Buzz', 'A jittery, short-lived stimulant. Common in the Franchise Strip.', 'item_drug_buzz', 240, '{"hunger": -5, "stat_agi_temp": 2}', 0.04, 3, '{"overdose": {"hp": -10, "sanity": -5}}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_slow', 'Slow', 'Dulls pain and panic. Popular with people who have seen too much.', 'item_drug_slow', 600, '{"hp": 5, "sanity": 15}', 0.12, 2, '{"overdose": {"hp": -20, "sanity": -15}}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_glasshollow', 'Glasshollow', 'Architect-adjacent. Reality gets thin and strange. Sanity damage is real; so is whatever you see.', 'item_drug_glasshollow', 180, '{"sanity": -10, "radiation": 5}', 0.2, 2, '{"overdose": {"hp": -25, "sanity": -30}}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_redline', 'Redline', 'Military-grade cyber-amphetamine. The label is mostly warnings.', 'item_redline', 300, '{"phases": {"peak_mods": {"hp_max": 15, "stat_brawn": 3, "stat_reflexes": 3, "stamina_regen_per_sec": 2}, "end_message": "<span class=\"msg-system\">The crash lands on you like a dropped ceiling.</span>", "comeup_scale": 0.4, "peak_message": "<span class=\"msg-system\">You are made of wire and lightning. Nothing can touch you.</span>", "peak_seconds": 150, "comedown_scale": 0.5, "comeup_message": "<span class=\"msg-system\">Your pulse redlines. The world drops into slow motion.</span>", "comeup_seconds": 20, "comedown_message": "<span class=\"msg-system\">The wire goes slack. Your hands start to shake.</span>", "comedown_seconds": 90}, "instant": {"hunger": -8, "sanity": 12, "thirst": -6}, "overdose": {"lethal": true, "message": "Your heart is a fist clenching until it cannot open again."}, "tolerance": {"gain_per_dose": 0.12, "max_reduction": 0.7, "recovery_per_sec": 0.0002}, "withdrawal": {"mods": {"stat_cool": -2, "stat_reflexes": -2}, "message": "Your teeth won''t stop grinding. You need another hit.", "onset_seconds": 900}}', 0.28, 3, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_coldfire', 'Coldfire', 'A combat stim that turns fear into fuel. Frontline mercs swear by it, and at it.', 'item_coldfire', 240, '{"phases": {"peak_mods": {"hp_max": 30, "stat_brawn": 5, "stat_endurance": 3, "hp_regen_per_sec": 1}, "end_message": "<span class=\"msg-system\">The fire gutters out. Every wound you ignored is suddenly very loud.</span>", "comeup_scale": 0.6, "peak_message": "<span class=\"msg-system\">Cold fire floods your veins. Pain becomes a distant rumour.</span>", "peak_seconds": 140, "comedown_scale": 0.6, "comeup_seconds": 10, "comedown_seconds": 90}, "instant": {"hunger": -12, "sanity": 6}, "overdose": {"lethal": true, "message": "Your body cannot tell it is dying. It sprints straight past the edge."}, "tolerance": {"gain_per_dose": 0.15, "max_reduction": 0.7}, "withdrawal": {"mods": {"stat_brawn": -3, "stat_endurance": -2}, "message": "Everything aches. Coldfire fixes that. Coldfire fixes everything.", "onset_seconds": 1200}}', 0.35, 3, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_static', 'Static', 'A nootropic mist for the overclocked mind. Clarity in a can, with interest.', 'item_static', 360, '{"phases": {"peak_mods": {"stat_brains": 4, "sanity_regen_per_sec": 1}, "end_message": "<span class=\"msg-system\">The signal degrades. Thoughts go grainy again.</span>", "comeup_scale": 0.5, "peak_message": "<span class=\"msg-system\">The static clears. You can see the shape of every problem at once.</span>", "peak_seconds": 240, "comedown_scale": 0.5, "comeup_seconds": 30, "comedown_seconds": 90}, "instant": {"sanity": 10}, "overdose": {"lethal": true, "message": "Too much signal, no more silence. Your mind whites out and does not come back."}, "tolerance": {"gain_per_dose": 0.1, "max_reduction": 0.6}}', 0.18, 4, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_grey', 'Grey', 'Synthetic morphine in a grey gelcap. The pain goes away. So does everything else.', 'item_grey', 420, '{"phases": {"peak_mods": {"stat_cool": 2, "stat_reflexes": -3, "hp_regen_per_sec": 2}, "end_message": "<span class=\"msg-system\">The warmth recedes and leaves you cold and small on the shore.</span>", "comeup_scale": 0.5, "peak_message": "<span class=\"msg-system\">You are floating in warm water in a dark, kind room.</span>", "peak_seconds": 240, "comedown_scale": 0.5, "comeup_message": "<span class=\"msg-system\">A warm grey tide rolls up from your feet. Nothing hurts.</span>", "comeup_seconds": 25, "comedown_seconds": 150}, "instant": {"sanity": 14}, "overdose": {"lethal": true, "message": "Your breathing slows, and slows, and forgets how."}, "tolerance": {"gain_per_dose": 0.14, "max_reduction": 0.75, "recovery_per_sec": 0.00015}, "withdrawal": {"mods": {"hp_max": -15, "stat_cool": -3, "stat_endurance": -3}, "message": "Your skin crawls, your bones ache, and the whole world is a hand held out for more grey.", "onset_seconds": 600}}', 0.45, 3, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_blacktar', 'Blacktar', 'Heavy tar opioid, cut with whatever was nearby. The deepest nod there is.', 'item_blacktar', 480, '{"phases": {"peak_mods": {"stat_brains": -3, "stat_reflexes": -5, "hp_regen_per_sec": 3}, "end_message": "<span class=\"msg-system\">You surface, gasping, into a world that got worse while you were gone.</span>", "comeup_scale": 0.6, "peak_message": "<span class=\"msg-system\">You go under. The tar closes over your head, black and total and perfect.</span>", "peak_seconds": 300, "comedown_scale": 0.6, "comeup_seconds": 20, "comedown_seconds": 160}, "instant": {"hunger": -6, "sanity": 18}, "overdose": {"lethal": true, "message": "The nod goes all the way down and does not turn around."}, "tolerance": {"gain_per_dose": 0.18, "max_reduction": 0.8, "recovery_per_sec": 0.0001}, "withdrawal": {"mods": {"hp_max": -25, "stat_cool": -4, "stat_brawn": -3, "stat_endurance": -4}, "message": "Withdrawal has you by the spine. You would trade almost anything to make it stop.", "onset_seconds": 480}}', 0.6, 2, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_lull', 'Lull', 'A blue benzo tab that files the sharp edges off a bad night.', 'item_lull', 360, '{"phases": {"peak_mods": {"stat_cool": 3, "stat_reflexes": -2, "sanity_regen_per_sec": 1}, "end_message": "<span class=\"msg-system\">The calm wears thin and the worries file back in.</span>", "comeup_scale": 0.5, "peak_message": "<span class=\"msg-system\">The panic unclenches. Whatever it was, it can wait.</span>", "peak_seconds": 240, "comedown_scale": 0.5, "comeup_seconds": 30, "comedown_seconds": 90}, "instant": {"sanity": 16}, "overdose": {"lethal": true, "message": "You lie down to rest your eyes for just a second, and never open them."}, "tolerance": {"gain_per_dose": 0.12, "max_reduction": 0.7}, "withdrawal": {"mods": {"stat_cool": -3, "sanity_regen_per_sec": -1}, "message": "Your nerves are live wires again. You remember exactly what fixes that.", "onset_seconds": 900}}', 0.3, 3, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_psilocybin', 'Psilocybin', 'A handful of wrinkled grey mushrooms grown in somebody''s ventilation duct.', 'item_psilocybin', 240, '{"instant": {"sanity": -4}, "tolerance": {"gain_per_dose": 0.3, "max_reduction": 0.9, "recovery_per_sec": 0.0003}, "hallucination": {"mode": "overlay", "palette": "purple", "eventPool": ["[trip]The walls take a slow, deliberate breath.[/trip]", "[trip]The floor is a carpet of soft breathing moss now. It doesn''t mind you standing on it.[/trip]", "[trip]Every surface is faintly patterned with eyes, all of them kind.[/trip]", "[trip]You can hear the colour green. It sounds like your grandmother''s kitchen.[/trip]", "[trip]Time pools in the corners of the room like warm honey.[/trip]", "[trip]A shaft of light bends toward you and asks, without words, if you are okay.[/trip]"], "intensity": 0.5, "eventEverySec": 12, "duration_seconds": 240}}', 0.02, 6, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_blotter', 'Blotter', 'A single square of high-powered blotter acid, printed with a grinning sun.', 'item_blotter', 600, '{"instant": {"sanity": -8}, "tolerance": {"gain_per_dose": 0.4, "max_reduction": 0.95, "recovery_per_sec": 0.0002}, "hallucination": {"mode": "overlay", "palette": "magenta", "eventPool": ["[trip]The room inhales and the walls flow outward into cathedral vaults of liquid light.[/trip]", "[trip]Fractal vines of every impossible colour crawl up from the floor and flower midair.[/trip]", "[trip]Your own hands leave glowing trails, a hundred hands fanning out from your wrists.[/trip]", "[trip]Sound has texture. A distant machine hum is velvet dragged across your teeth.[/trip]", "[trip]The grinning sun from the tab is on the ceiling now, and it winks at you.[/trip]", "[trip]You are absolutely certain, for one perfect second, that you understand it all.[/trip]", "[trip]A stranger who is also you steps out of the wall, waves, and folds back in.[/trip]"], "intensity": 0.8, "eventEverySec": 14, "duration_seconds": 600}}', 0.01, 8, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_mescaline', 'Mescaline', 'Seventy-five pellets rattle in a little tin. You only need a few.', 'item_mescaline', 480, '{"instant": {"hunger": -6, "sanity": -6}, "tolerance": {"gain_per_dose": 0.3, "max_reduction": 0.9}, "hallucination": {"mode": "overlay", "palette": "gold", "eventPool": ["[trip]Everything is edged in shimmering gold, as if the world were a coin held to the light.[/trip]", "[trip]Geometric patterns bloom across every wall, precise and ancient and alive.[/trip]", "[trip]Your stomach rolls, but the nausea is just the door you have to walk through.[/trip]", "[trip]A desert wind you cannot feel moves the shadows in long slow waves.[/trip]", "[trip]An old voice, patient as stone, tells you a story in a language you were born knowing.[/trip]"], "intensity": 0.7, "eventEverySec": 13, "duration_seconds": 480}}', 0.02, 6, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_screamers', 'Screamers', 'A designer psychedelic that does not do gentle. Roll the dice.', 'item_screamers', 300, '{"instant": {"sanity": -18}, "tolerance": {"gain_per_dose": 0.25, "max_reduction": 0.85}, "hallucination": {"mode": "overlay", "palette": "red", "eventPool": ["[trip]The walls are the wrong colour. They know they are the wrong colour. They are furious about it.[/trip]", "[trip]Something enormous is screaming just below the range of hearing and it is getting closer.[/trip]", "[trip]Your reflection in every surface is a half-second behind you, and grinning.[/trip]", "[trip]The floor tilts. The ceiling drips. None of it is trying to help you.[/trip]", "[trip]You are being watched by the architecture and it does not like what it sees.[/trip]", "[trip]For a moment you are certain you have always been here and will never leave.[/trip]"], "intensity": 1, "eventEverySec": 10, "duration_seconds": 300}}', 0.08, 5, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_laughers', 'Laughers', 'Little yellow tabs that turn the apocalypse into the funniest thing you have ever seen.', 'item_laughers', 240, '{"instant": {"sanity": 20}, "tolerance": {"gain_per_dose": 0.2, "max_reduction": 0.8}, "hallucination": {"mode": "overlay", "palette": "gold", "eventPool": ["[trip]The sheer absurdity of everything hits you and you have to lean on a wall, wheezing.[/trip]", "[trip]That grim little machine in the corner looks, on reflection, deeply and hilariously stupid.[/trip]", "[trip]Someone somewhere is taking all of this seriously and that is the funniest part.[/trip]", "[trip]You catch your own reflection making a face and completely lose it.[/trip]", "[trip]Even the dread feels like a joke with a punchline you already know.[/trip]"], "intensity": 0.5, "eventEverySec": 12, "duration_seconds": 240}}', 0.1, 5, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_dreamsmoke', 'Dreamsmoke', 'Two bags of engineered grass. Mellow, hungry, harmless-ish.', 'item_dreamsmoke', 300, '{"phases": {"peak_mods": {"stat_cool": 2, "stat_reflexes": -1}, "end_message": "<span class=\"msg-system\">The mellow lifts. You are mostly just hungry now.</span>", "comeup_scale": 0.5, "peak_message": "<span class=\"msg-system\">A soft heaviness settles over you. The edges of the room go plush.</span>", "peak_seconds": 200, "comedown_scale": 0.5, "comeup_seconds": 20, "comedown_seconds": 80}, "instant": {"hunger": 15, "sanity": 12, "thirst": 6}, "tolerance": {"gain_per_dose": 0.15, "max_reduction": 0.7}, "hallucination": {"mode": "overlay", "palette": "green", "eventPool": ["[trip]Time slows to a comfortable crawl. There is nowhere you need to be.[/trip]", "[trip]You become deeply, urgently aware that you would demolish an entire vending machine of snacks.[/trip]", "[trip]A thought drifts by, profound and important, and you completely fail to catch it.[/trip]"], "intensity": 0.3, "eventEverySec": 20, "duration_seconds": 300}}', 0.08, 8, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_ether', 'Ether', 'A pint of raw ether and a rag. Not the smart choice, but here we are.', 'item_ether', 120, '{"instant": {"sanity": -10}, "overdose": {"lethal": true, "message": "You breathe in one rag too many. The lights go out mid-thought."}, "hallucination": {"mode": "overlay", "palette": "cyan", "eventPool": ["[trip]The floor lurches sideways and the room smears into long cold streaks.[/trip]", "[trip]Your thoughts arrive out of order, each one wrapped in cotton wool.[/trip]", "[trip]You are extremely far away from your own hands.[/trip]", "[trip]A chemical wind blows straight through your skull and out the other side.[/trip]"], "intensity": 0.6, "eventEverySec": 10, "duration_seconds": 120}}', 0.15, 3, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_threshold', 'The Threshold', 'A single breath of vaporised DMT-analog. Ten thousand years in four hundred seconds.', 'item_threshold', 200, '{"instant": {"sanity": -12}, "tolerance": {"gain_per_dose": 0.2, "max_reduction": 0.6}, "hallucination": {"mode": "dreamzone", "events": [{"text": "[trip]The room peels away like wet paper and you fall UP through it.[/trip]", "atSec": 4}, {"text": "[trip]The machine-elves are showing you something. It is the most important thing there is.[/trip]", "atSec": 30}, {"text": "[trip]You have been here before. You have always been here. You live here.[/trip]", "atSec": 80}, {"text": "[trip]The cathedral begins, very gently, to fold you back up and post you home.[/trip]", "atSec": 140}], "palette": "magenta", "intensity": 1, "dreamzone_id": "zone_dream_threshold", "eventEverySec": 20, "duration_seconds": 180}}', 0.01, 6, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_khole', 'K-Hole', 'A dissociative dust that unplugs you from your own body for a while.', 'item_khole', 240, '{"instant": {"sanity": -8}, "overdose": {"lethal": true, "message": "You go so far down the hole that you forget the way back, and your body forgets to breathe."}, "tolerance": {"gain_per_dose": 0.2, "max_reduction": 0.8}, "withdrawal": {"mods": {"stat_brains": -2}, "message": "The grey funnel calls. You keep glancing toward the door that isn''t there.", "onset_seconds": 1800}, "hallucination": {"mode": "dreamzone", "palette": "blue", "eventPool": ["[trip]You slide a little further down the smooth grey funnel.[/trip]", "[trip]Your body is somewhere behind you now, waving. You wave back, or think about it.[/trip]", "[trip]Continents of thought drift past, too large and too slow to be afraid of.[/trip]", "[trip]Someone is speaking. It might be you. It was a long time ago.[/trip]"], "intensity": 0.7, "dreamzone_id": "zone_dream_khole", "eventEverySec": 18, "duration_seconds": 200}}', 0.12, 4, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_voidwalk', 'Voidwalk', 'A designer dissociative that drops you into the static between channels.', 'item_voidwalk', 300, '{"instant": {"sanity": -14}, "overdose": {"lethal": true, "message": "The static pulls you all the way under and keeps the channel dark."}, "tolerance": {"gain_per_dose": 0.2, "max_reduction": 0.8}, "hallucination": {"mode": "dreamzone", "palette": "cyan", "eventPool": ["[trip]The static sea hums your name and you feel it in your back teeth.[/trip]", "[trip]A memory swims past wearing someone else''s face. It nods at you.[/trip]", "[trip]An advertisement for a product that does not exist plays across the whole sky.[/trip]", "[trip]You wade deeper. The blue closes over your knees, your chest, your reasons for leaving.[/trip]"], "intensity": 0.9, "dreamzone_id": "zone_dream_void", "eventEverySec": 20, "duration_seconds": 260}}', 0.1, 4, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_overclock', 'Neural Overclock', 'A lace-booster that runs your wetware past the red line. Smoke may be metaphorical.', 'item_overclock', 240, '{"phases": {"peak_mods": {"hp_max": 10, "stat_brains": 5, "stat_reflexes": 4, "sanity_regen_per_sec": -1}, "end_message": "<span class=\"msg-system\">The clock drops back to baseline. Your skull throbs where the heat pooled.</span>", "comeup_scale": 0.5, "peak_message": "<span class=\"msg-system\">You are thinking in parallel now, a dozen threads, all of them screaming.</span>", "peak_seconds": 150, "comedown_scale": 0.6, "comeup_message": "<span class=\"msg-system\">Your lace spins up with a whine only you can hear. The world turns to data.</span>", "comeup_seconds": 12, "comedown_seconds": 78}, "instant": {"sanity": -6}, "overdose": {"lethal": true, "message": "Your wetware runs too hot for too long and something delicate inside simply melts."}, "tolerance": {"gain_per_dose": 0.14, "max_reduction": 0.7}, "withdrawal": {"mods": {"stat_brains": -3, "stat_reflexes": -2}, "message": "Baseline feels like wading through mud. You want the clock back up.", "onset_seconds": 900}}', 0.3, 3, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_memhack', 'Memhack', 'A memory-editing synth. Sands the barbs off your worst recollections. Mostly.', 'item_memhack', 360, '{"phases": {"peak_mods": {"stat_cool": 3, "sanity_regen_per_sec": 1}, "end_message": "<span class=\"msg-system\">The edits settle. A few of the barbs quietly grow back.</span>", "comeup_scale": 0.5, "peak_message": "<span class=\"msg-system\">Old wounds you carry go soft and distant, like they happened to someone else.</span>", "peak_seconds": 240, "comedown_scale": 0.5, "comeup_seconds": 30, "comedown_seconds": 90}, "instant": {"sanity": 24}, "overdose": {"lethal": true, "message": "It edits one memory too many — the one where your heart remembers to beat."}, "tolerance": {"gain_per_dose": 0.12, "max_reduction": 0.7}, "withdrawal": {"mods": {"stat_cool": -2, "sanity_regen_per_sec": -1}, "message": "The memories come back sharp and all at once. Only memhack files them down.", "onset_seconds": 1200}}', 0.2, 4, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_amyls', 'Amyls', 'Two dozen amyls in a rattling little box. A brief, roaring rush.', 'item_amyls', 60, '{"phases": {"peak_mods": {"stat_brawn": 2, "stat_reflexes": 2}, "end_message": "<span class=\"msg-system\">The rush drops out from under you as fast as it came.</span>", "comeup_scale": 0.8, "peak_seconds": 30, "comedown_scale": 0.5, "comeup_message": "<span class=\"msg-system\">A hot rush slams up the back of your neck and the room goes bright and loud.</span>", "comeup_seconds": 4, "comedown_seconds": 26}, "instant": {"sanity": 6, "horniness_increase": 25}, "overdose": {"lethal": true, "message": "One popper too many and your blood pressure bottoms out. You fold like a chair."}, "tolerance": {"gain_per_dose": 0.2, "max_reduction": 0.7}}', 0.1, 4, '{}', '{}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_coffee', 'Coffee', 'A jolt of caffeine — sharpens you up for a while.', 'item_drug_coffee', 180, '{"instant": {"sanity": 4, "thirst": 15}}', 0, 12, '{}', '{"legal": true}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_beer', 'Beer', 'A mild buzz. Takes the edge off.', 'item_drug_beer', 240, '{"instant": {"hunger": 3, "sanity": 3, "thirst": 12}}', 0, 12, '{}', '{"legal": true}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_joint', 'joint', 'A hand-rolled joint, a little crooked, twisted off at the end. Smells like a greenhouse and bad decisions.', 'item_joint', 300, '{"phases": {"peak_mods": {"stat_reflexes": -1}, "end_message": "<span class=\"msg-system\">The high tapers off. The colours go back to normal and you are suddenly, urgently thinking about a sandwich.</span>", "comeup_scale": 0.5, "peak_message": "<span class=\"msg-system\">You are extremely stoned. Everything is faintly hilarious and the music is <em>unbelievable</em>.</span>", "peak_seconds": 240, "comedown_scale": 0.4, "comeup_message": "<span class=\"msg-system\">You spark it up and draw slow. The room exhales with you; the edges go soft and warm.</span>", "comeup_seconds": 8, "comedown_seconds": 60}, "instant": {"sanity": 6, "thirst": -10}, "overdose": {"mods": {"hp": -4, "sanity": -12}, "message": "You have smoked far too much. The room tilts, your heart hammers, and a cold wave of paranoid nausea rolls over you. You green out."}}', 0, 5, '{}', '{"legal": true, "cannabis": true, "high_seconds": 300}');
INSERT INTO public.drugs (id, name, description, item_id, duration_seconds, effects, addiction_chance, overdose_threshold, withdrawal_effects, flags) VALUES ('drug_cigarettes', 'cigarettes', 'A soft pack of cheap cigarettes. Each one shaves a little off your lungs and hands it to your image.', 'item_cigarettes', 300, '{"phases": {"peak_mods": {"stat_cool": 2, "stamina_max": -15}, "end_message": "<span class=\"msg-system\">The cigarette burns down to the filter. The cool goes with it; the craving stays.</span>", "comeup_scale": 0.6, "peak_message": "<span class=\"msg-system\">Nicotine hums through you. You feel, briefly, extremely cool and very slightly winded.</span>", "peak_seconds": 90, "comedown_scale": 0.5, "comeup_message": "<span class=\"msg-system\">You light up and draw deep. Your shoulders drop; the edge comes off your hunger.</span>", "comeup_seconds": 4, "comedown_seconds": 40}, "instant": {"sanity": 3}, "overdose": {"mods": {"hp": -5, "sanity": -8}}, "tolerance": {"gain_per_dose": 0.1, "max_reduction": 0.5}, "withdrawal": {"mods": {"stat_cool": -2, "stamina_max": -10}, "message": "Your hands are restless and your mood is fraying. You would kill for a cigarette.", "onset_seconds": 600}}', 0.4, 12, '{}', '{"legal": true, "smokeable": true, "appetite_suppress_seconds": 900}');
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_extra_eye', 'Extra Eye', 'A third eye has opened on the back of your skull. You see things people don''t.', 'mixed', 1, '{"stat_agi": 1}', '{"perception_bonus": 2}', '["NPCs find you unsettling"]', 60);
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_necrotic_hand', 'Necrotic Hand', 'One hand has darkened and hardened. Melee attacks cause bleeding. You can''t wear gloves.', 'mixed', 1, '{}', '{"chance": 0.3, "status_on_hit": "bleeding"}', '["Cannot equip gloves"]', 50);
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_static_mind', 'Static Mind', 'Your thoughts are a white noise channel. Partial immunity to sanity loss. Architect signals are louder.', 'positive', 0, '{"stat_wil": 2}', '{"sanity_drain_reduction": 0.5}', '["Occasional intrusive Architect messages"]', 70);
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_iron_stomach', 'Iron Stomach', 'You can eat almost anything. Food poisoning is no longer a concern. What is a concern is what you now find appetizing.', 'positive', 0, '{"stat_end": 1}', '{"food_poison_immunity": true}', '[]', 40);
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_rad_absorption', 'Rad Absorption', 'Your body has learned to metabolize radiation instead of being destroyed by it. Slowly.', 'positive', 1, '{"stat_end": 2}', '{"rad_resistance": 0.3}', '["You glow faintly in the dark — stealth is harder"]', 80);
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_bone_spurs', 'Bone Spurs', 'Calcified projections have erupted through your knuckles. Unarmed attacks deal more damage and cause bleeding.', 'mixed', 1, '{"stat_str": 1}', '{"unarmed_bleed_chance": 0.25, "unarmed_damage_bonus": 3}', '["Gloves don''t fit"]', 55);
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_weeping_sores', 'Weeping Sores', 'Open lesions that never quite heal. Purely cosmetic. Purely awful.', 'negative', 1, '{"stat_cha": -2}', '{}', '["Visibly diseased — NPCs react poorly"]', 45);
INSERT INTO public.mutations (id, name, description, polarity, visible, stat_modifiers, effects, drawbacks, radiation_threshold) VALUES ('mut_tremor_hands', 'Tremor Hands', 'Your hands shake constantly now. Fine motor tasks are a struggle.', 'negative', 0, '{"stat_agi": -1}', '{}', '["Crafting and lockpicking rolls take a penalty"]', 40);
