INSERT INTO public.scripts (id, name, description, graph, updated_at) VALUES ('script_test_p4', 'P4 Test Diagnostic', 'Phase 4 smoke-test script.', '{"nodes": {"flag": {"flag": "ran_test_script", "type": "setflag", "scope": "player", "value": "true"}, "check": {"type": "condition", "ifTrue": "known", "ifFalse": "stranger", "condition": {"op": "set", "flag": "met_architect"}}, "known": {"next": "flag", "text": "The script confirms: the Architect already knows you.", "type": "say"}, "stranger": {"text": "The script reports: you are a stranger here.", "type": "say"}}, "start": "check"}', 1782470932);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_0', NULL, '["\"You feel that? Pressure''s dropping. Gonna rain acid again.\"", "\"It always rains acid. That''s just weather now.\"", "\"Used to mean something, a storm. Now it''s Tuesday.\"", "shrugs and pulls their collar up."]', true, 0);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_1', NULL, '["\"Heard they found another body down by the transit line.\"", "\"Ours or theirs?\"", "\"Does it matter anymore?\"", "\"...No. Suppose it doesn''t.\""]', true, 1);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_2', NULL, '["\"Rent went up again. Same box, more credits.\"", "\"Complain to who? The landlord''s an algorithm.\"", "\"Can''t even argue with it. It just deducts.\"", "laughs, but there''s nothing behind it."]', true, 2);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_3', NULL, '["\"You remember real coffee? Before the substitute?\"", "\"I remember the smell. Can''t remember the taste.\"", "\"That''s the worst part. The forgetting.\"", "stares into the middle distance."]', true, 3);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_4', NULL, '["\"The machines were quiet last night. Too quiet.\"", "\"Maybe they''re done with us.\"", "\"They''re never done. They''re just patient.\"", "\"...Yeah. That''s worse, isn''t it.\""]', true, 4);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_5', NULL, '["\"Somebody''s been through here. Look at the dust.\"", "\"Everybody''s been through here. It''s a corridor.\"", "\"No, recent. Boots, not drones.\"", "glances toward the exit and lowers their voice."]', true, 5);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_6', NULL, '["\"I''d kill for a working shower. Real water.\"", "\"You''d kill for less, these days.\"", "\"Fair.\"", "cracks a tired grin."]', true, 6);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_7', NULL, '["\"They say the upper levels still have power. Real light.\"", "\"They say a lot of things about the upper levels.\"", "\"You ever been?\"", "\"Nobody comes back to say.\""]', true, 7);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_8', NULL, '["\"Prices at the market are insane. A tin of protein for what?\"", "\"Supply and desperation. Classic combination.\"", "\"One of these days I''m just gonna stop eating.\"", "\"Let me know how that works out.\""]', true, 8);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_9', NULL, '["\"Curfew drone came by twice already. Nervous night.\"", "\"Something''s got them spooked.\"", "\"Something''s always got them spooked. That''s the job.\"", "nods slowly, watching the ceiling."]', true, 9);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_10', 'bartender', '["\"You want the usual, or are we pretending you have options?\"", "\"...The usual.\"", "\"Thought so. Pay first.\"", "wipes down the counter without looking up."]', true, 10);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_11', 'bartender', '["\"Third one tonight crying into their drink. Full moon or something.\"", "\"There''s no moon anymore. Just the haze.\"", "\"Then it''s just people. Even worse.\""]', true, 11);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_12', 'thug', '["\"This block''s ours. You standing in it means something.\"", "\"I''m just passing through.\"", "\"Nobody just passes through. Remember the face.\"", "cracks their knuckles, slow."]', true, 12);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_13', 'thug', '["\"Nice gear. Real nice. Be a shame.\"", "\"...Is that a threat?\"", "\"It''s an observation. For now.\""]', true, 13);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_14', 'guard', '["\"Move along. Nothing to see here.\"", "\"I live here.\"", "\"Then live somewhere I''m not standing. Keep it moving.\""]', true, 14);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_15', 'guard', '["\"Long shift. Two more like it before I sleep.\"", "\"They working you to death?\"", "\"Death''d be a day off. Eyes forward.\""]', true, 15);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_16', 'preacher', '["\"The end was promised, friend. And the end delivered.\"", "\"I''m not interested.\"", "\"Nobody is. That never stopped it coming.\"", "raises a hand in something between blessing and warning."]', true, 16);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_17', 'preacher', '["\"Repent. It won''t help, but the gesture matters.\"", "\"Repent for what?\"", "\"You''ll know. You always know.\""]', true, 17);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_18', 'vagrant', '["\"You got a smoke? Just one, I''m good for it.\"", "\"You said that yesterday.\"", "\"And I was good for it. Wasn''t I still here?\"", "holds out a hopeful hand."]', true, 18);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_19', 'vagrant', '["\"Don''t sleep near the east wall. Trust me.\"", "\"Why, what''s at the east wall?\"", "\"...You don''t wanna know. I know. That''s enough for both of us.\""]', true, 19);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_20', 'dealer', '["\"Pot''s right. Cards are fair. Read your opponent, not your luck.\"", "\"Easy for you to say. You deal them.\"", "\"That''s exactly why I say it.\"", "squares the deck against the felt."]', true, 20);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_21', 'doctor', '["\"You''re favouring that leg. Old wound?\"", "\"It''s nothing.\"", "\"It''s never nothing. Sign the waiver and I''ll take a look.\""]', true, 21);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_22', 'scientist', '["\"The readings from last night were... statistically unusual.\"", "\"Unusual how?\"", "\"The kind of unusual I''d rather not write down. Officially.\"", "adjusts a cracked instrument and frowns."]', true, 22);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_23', 'mercenary', '["\"You freelance, or you signed with somebody?\"", "\"I keep my options open.\"", "\"Options close fast out here. Pick a paymaster before one picks you.\""]', true, 23);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_24', 'cult_member', '["\"He is coming. He is always coming. Can you feel it?\"", "\"I feel a draft, mostly.\"", "\"That is how it begins. The cold. The certainty.\"", "smiles with unsettling patience."]', true, 24);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_25', 'politician', '["\"We''re making real progress. The data supports our approach.\"", "\"The data says people are starving.\"", "\"...We''re exploring all options. Except, apparently, that one.\""]', true, 25);
INSERT INTO public.npc_banter_threads (id, personality, lines, enabled, sort_order) VALUES ('bt_seed_26', 'unemployed', '["\"You hiring? No? Figured. Nobody is.\"", "\"Times are hard for everyone.\"", "\"Some of us are just more thorough about it.\"", "kicks at a loose bit of rubble."]', true, 26);
INSERT INTO public.orgs (id, name, description, color, is_npc, owner_id, treasury, founded_at, flags) VALUES ('faction_custodians', 'The Custodians', 'Former corporate employees who serve the Architect as a divine entity.', '#4A90D9', 1, NULL, 0, 1783000349, '{}');
INSERT INTO public.orgs (id, name, description, color, is_npc, owner_id, treasury, founded_at, flags) VALUES ('faction_breakers', 'The Breakers', 'Technology abolitionists. Believe destroying all remaining tech will free humanity.', '#D94A4A', 1, NULL, 0, 1783000349, '{}');
INSERT INTO public.orgs (id, name, description, color, is_npc, owner_id, treasury, founded_at, flags) VALUES ('faction_archivists', 'The Archivists', 'Knowledge hoarders operating from the tunnels. Politically neutral. Deeply weird.', '#F5A623', 1, NULL, 0, 1783000349, '{}');
INSERT INTO public.orgs (id, name, description, color, is_npc, owner_id, treasury, founded_at, flags) VALUES ('faction_franchise', 'The Franchise', 'A commerce empire built on pre-Handoff retail bones. If it can be sold, they sell it.', '#7ED321', 1, NULL, 0, 1783000349, '{}');
INSERT INTO public.orgs (id, name, description, color, is_npc, owner_id, treasury, founded_at, flags) VALUES ('faction_glitch', 'The Glitch', 'Hackers and post-Handoff mystics who believe the Architect can be communicated with.', '#9B59B6', 1, NULL, 0, 1783000349, '{}');
